const _propertyAnnexLabels = [
  'ممرات',
  'درج',
  'سطح',
  'بلكونات',
  'غرفة الاتصالات',
  'غرفة الكهرباء',
  'غرفة الدفاع المدني',
];

/// فلتر العقارات / الأنشطة التجارية / المركبات ووسائل النقل — لفلتر الصفحة
/// الرئيسية. [label] اسم الفئة كما يظهر (العقارات...).
AppFilterModuleConfig assetsFilterModuleConfig(String label) {
  const keys = {
    'العقارات': 'real_estate',
    'الأنشطة التجارية': 'activity',
    'المركبات ووسائل النقل': 'equipment',
  };
  final key = keys[label] ?? 'all';
  return AppFilterModuleConfig(
    fixedMainCategory: label,
    subCategoriesFor: (_) =>
        _ProjectsActivitiesScreenState._assetSubCategories(key),
    sectionsFor: _ProjectsActivitiesScreenState._assetFilterSections,
    selectStatuses: const [
      ...kAppFilterSelectStatuses,
      // «ملغاة» تخص هذا القسم وحده (إلغاء العقار/النشاط/المركبة).
      'ملغاة',
      'مسودة',
      'تنتهي قريبًا',
      'منتهية',
    ],
    currencies: [
      ...kAppFilterCurrencies,
      if (!kAppFilterCurrencies.contains(AppSettings.currencySuffix))
        AppSettings.currencySuffix,
    ],
    delegatesLabel: 'التفويض',
    placeLabel: 'مواقع وأماكن',
    placeHint: 'اكتب اسم الموقع أو المكان',
  );
}

class ProjectsActivitiesScreen extends StatefulWidget {
  /// الفئة المفتوحة عند الدخول: تسمح لاختصارات الصفحة الرئيسية بفتح
  /// العقارات أو الأنشطة مباشرةً بدل فتح "الكل" ثم البحث يدويًا.
  final String initialFilter;

  /// قيم الفلتر الكبير عند الفتح (من فلتر الصفحة الرئيسية).
  final AppFilterValues? initialValues;

  /// فتح تفاصيل أصل بعينه مباشرة (من المثبّت في الرئيسية) ثم الرجوع.
  final String? openAssetId;

  const ProjectsActivitiesScreen({
    super.key,
    this.initialFilter = 'all',
    this.initialValues,
    this.openAssetId,
  });

  @override
  State<ProjectsActivitiesScreen> createState() =>
      _ProjectsActivitiesScreenState();
}

class _ProjectsActivitiesScreenState extends State<ProjectsActivitiesScreen> {
  final TextEditingController _searchController = TextEditingController();
  final ProjectAssetsRepository _repository = SupabaseProjectAssetsRepository();
  // تفتح الصفحة بلا فئة مختارة: جانب العناصر يعرض «اختر إحدى الفئات»
  // حتى يضغط المستخدم فئة، فتُطوى القائمة وتتوسع الصفحة لعناصرها.
  // قسم غير متاح في الباقة لا يُفتح (تظهر نافذة الترقية).
  late String _selectedFilter =
      widget.initialFilter == 'all' ||
          PlanAccess.blocksView(widget.initialFilter)
      ? ''
      : widget.initialFilter;

  String _selectedSort = 'الأحدث أولاً';
  bool _isLoadingRemote = true;

  /// نص خطأ التحميل — يبقى معروضًا حتى ينجح تحميل جديد، بدل شريط سفلي
  /// يختفي قبل أن يُقرأ.
  String _loadError = '';

  /// خروج ودخول نظيف بالحساب المشترك ثم إعادة التحميل.
  Future<void> _reloginAndReload() async {
    setState(() {
      _isLoadingRemote = true;
      _loadError = 'جارٍ إعادة تسجيل الدخول...';
    });
    try {
      await AppSession.forceSignIn();
    } catch (error) {
      if (!mounted) return;
      debugPrint('Projects relogin failed: $error');
      setState(() {
        _isLoadingRemote = false;
        _loadError =
            'تعذّر تجديد الدخول — سجّل الخروج ثم ادخل بحسابك من جديد.';
      });
      return;
    }
    if (!mounted) return;
    await _loadAssetsFromRemote();
  }

  /// طيّ عمود الفئات لتوسيع جانب العناصر (سهم على الخط الفاصل).

  final List<_TopFilter> _filters = const [
    _TopFilter('all', 'الكل', Color(0xFF022E2A)),
    _TopFilter('real_estate', 'العقارات', Color(0xFF0A5A50)),
    _TopFilter('equipment', 'المركبات ووسائل النقل', Color(0xFF0E7161)),
    _TopFilter('activity', 'الأنشطة التجارية', Color(0xFFCE8422)),
    // «أخرى» لا تُعرض إلا إن وُجد فيها سجل — انظر [_visibleFilters].
    _TopFilter('other', 'أخرى', Color(0xFF5C6B68)),
  ];

  /// الفئات المعروضة: الثلاث الأساسية دائمًا، و«أخرى» متى وُجد فيها سجل.
  /// بلا هذا الشرط يبقى أي أصل مخزَّن بتصنيف خارج الثلاثة غير قابل للوصول
  /// إليه من الواجهة أبدًا — موجود في الخادم ولا تعرضه أي فئة.
  List<_TopFilter> _visibleFilters() => [
    for (final filter in _filters)
      if (filter.key != 'all' &&
          !_assetCategoryHidden(filter.key) &&
          (filter.key != 'other' || _categoryCount('other') > 0))
        filter,
  ];

  /// الأصول كما يرويها الخادم — لا بذور تجريبية.
  ///
  /// كانت هنا ثلاثة أصول مكتوبة يدويًا تظهر قبل وصول ردّ الخادم ثم تُمسح
  /// به، فتُقرأ كأنها بيانات المستخدم وقد ضاعت. القائمة تبدأ فارغة الآن،
  /// وما يملؤها هو [_loadAssetsFromRemote] وحده.
  final List<_AssetItem> _items = <_AssetItem>[];

  @override
  void initState() {
    super.initState();
    openPaymentChequeManager = openEntryChequeManager;
    DelegatedAssets.changed.addListener(_loadAssetsFromRemote);
    final initial = widget.initialValues;
    if (initial != null) _filter.assignFrom(initial);
    final openId = widget.openAssetId?.trim() ?? '';
    if (openId.isEmpty) {
      _loadAssetsFromRemote();
    } else {
      _loadAssetsFromRemote().then((_) async {
        if (!mounted) return;
        final index = _items.indexWhere(
          (e) => e.id == openId || (e.id == null && e.title == openId),
        );
        // غير موجود: تبقى القائمة ظاهرة.
        if (index < 0) return;
        await _openDetails(_items[index]);
        if (mounted) Navigator.of(context).pop();
      });
    }
    if (widget.initialFilter != 'all' &&
        !PlanAccess.canView(widget.initialFilter)) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) PlanGate.canView(context, widget.initialFilter);
      });
    }
  }

  /// عقود الوحدات مفهرسة بمعرّف الأصل. هذه هي الحلقة التي كانت مقطوعة:
  /// العقود في جدول مستقل لا تقرأه القائمة، فتبقى حالة العقار وتاريخ
  /// انتهاء عقده ونوعه حقولًا ثابتة لا يكتبها شيء.
  final Map<String, List<PropertyUnitContractRecord>> _contractsByAsset = {};

  Future<void> _loadAssetsFromRemote() async {
    // الضيف بلا حساب: لا طلب للخادم ولا رسالة خطأ — القائمة فارغة.
    if (FundlyAuth.isGuest) {
      setState(() {
        _isLoadingRemote = false;
        _loadError = '';
      });
      return;
    }
    setState(() {
      _isLoadingRemote = true;
      _loadError = '';
    });
    try {
      final records = [...await _repository.fetchAssets()];
      // ما فوّضني أصحابه بإدارته: يظهر مع أصولي بوسم «مفوَّض بإدارته».
      final repo = _repository;
      if (repo is SupabaseProjectAssetsRepository) {
        try {
          records.addAll(await repo.fetchDelegatedAssets());
        } catch (_) {
          // تعذّر جلب المفوَّض لا يمنع عرض أصولي.
        }
      }
      // تُبنى القائمة الجديدة كاملة قبل المساس بالقديمة، وكل سجل على حدة:
      // سجل واحد لا يُقرأ لا يُسقط البقية ولا يُفرغ الشاشة.
      final built = <_AssetItem>[];
      final skipped = <String>[];
      for (final record in records) {
        // المحذوف في سلة المهملات لا يظهر هنا (يُستعاد أو يُحذف من السلة).
        if (record.status == _kAssetTrashStatus) continue;
        try {
          built.add(_assetFromRecord(record));
        } catch (error) {
          skipped.add('${record.title}: $error');
        }
      }
      if (!mounted) return;
      setState(() {
        _items
          ..clear()
          ..addAll(built);
        _isLoadingRemote = false;
        // تفاصيل الخطأ للمطوّر فقط (debugPrint)، والمستخدم يرى رسالة مفهومة.
        if (skipped.isNotEmpty) {
          debugPrint('Projects skipped records: $skipped');
          _loadError = 'تعذّر عرض بعض السجلات.';
        } else {
          _loadError = '';
        }
      });
      await _loadContracts();
      await _loadOutgoingDelegations();
    } catch (error) {
      if (!mounted) return;
      // القائمة القديمة تبقى كما هي: خطأ الشبكة لا يمحو ما كان معروضًا.
      debugPrint(
        'Projects load failed: $error · ${AppSession.describeSession()}',
      );
      setState(() {
        _isLoadingRemote = false;
        _loadError =
            'تعذّر تحميل البيانات — تحقّق من الإنترنت ثم اضغط «إعادة المحاولة».';
      });
    }
  }

  /// دفعات كل عقد (إيجار + رسوم + تأمين) — مصدر «مالية» في مركز المتابعة.
  final Map<String, List<PropertyUnitPaymentRecord>> _paymentsByContract = {};

  /// سجلات كل أصل (مستندات، عقود...) — مصدر «المستندات» و«المتابعة».
  final Map<String, List<ProjectAssetEntryRecord>> _entriesByAsset = {};

  /// استعلام واحد لكل العقود، ثم فهرستها بالأصل.
  Future<void> _loadContracts() async {
    try {
      final rows = await _repository.fetchAllUnitContracts();
      if (!mounted) return;
      setState(() {
        _contractsByAsset.clear();
        for (final row in rows) {
          _contractsByAsset.putIfAbsent(row.assetId, () => []).add(row);
        }
      });
      await _loadFollowUpSources(rows);
      await _loadDelegatedSources();
    } catch (_) {
      // تعذّر جلب العقود لا يمنع عرض العقارات؛ تبقى بلا حالة عقد.
    }
  }

  /// عقود ودفعات وسجلات ما فُوِّضتُ بإدارته — تُضاف إلى فهارس القائمة
  /// (حالة العقار، المستحقات، المستندات).
  Future<void> _loadDelegatedSources() async {
    final repo = _repository;
    final ids = DelegatedAssets.ids;
    if (ids.isEmpty || repo is! SupabaseProjectAssetsRepository) return;
    try {
      final contracts = await repo.fetchContractsOfAssets(ids);
      final payments = await repo.fetchPaymentsOfContracts([
        for (final contract in contracts)
          if (contract.id != null) contract.id!,
      ]);
      final entries = await repo.fetchEntriesOfAssets(ids);
      if (!mounted) return;
      setState(() {
        for (final contract in contracts) {
          _contractsByAsset.putIfAbsent(contract.assetId, () => []).add(contract);
        }
        for (final payment in payments) {
          _paymentsByContract
              .putIfAbsent(payment.contractId, () => [])
              .add(payment);
        }
        for (final entry in entries) {
          _entriesByAsset.putIfAbsent(entry.assetId, () => []).add(entry);
        }
      });
    } catch (_) {
      // بلا بيانات المفوَّض يبقى العنصر ظاهرًا بلا حالة عقد.
    }
  }

  /// ما فوّضتُه لغيري (مقبول وساري) — علامة على العقار أو الوحدة عندي.
  Future<void> _loadOutgoingDelegations() async {
    try {
      final list = await SupabaseDelegationsRepository().fetchDelegations();
      final map = <String, List<OutgoingDelegation>>{};
      void add(String id, OutgoingDelegation d) =>
          map.putIfAbsent(id, () => []).add(d);
      for (final d in list) {
        if (!d.isActive) continue;
        // المقبول، أو المسجَّل بلا رقم تعريفي (لا ينتظر قبولًا: نشط مباشرة).
        final answer = DelegationRecord.acceptOf(d.permissions);
        if (answer != 'accepted' && answer.isNotEmpty) continue;
        final main = DelegationRecord.mainScopeOf(d.scope);
        if (main != 'كل الأقسام' && main != 'العقارات والأنشطة والمركبات') {
          continue;
        }
        final name = d.delegateName.trim().isNotEmpty
            ? d.delegateName.trim()
            : DelegationRecord.delegateFndOf(d.permissions);
        final perms = DelegationRecord.plainPermissions(d.permissions);
        final targets = [
          for (final p in d.permissions)
            if (DelegationTarget.decode(p) case final target?) target,
        ];
        if (targets.isNotEmpty) {
          final units = <String, Set<String>>{};
          for (final t in targets) {
            if (t.kind == 'asset') {
              add(
                t.id,
                OutgoingDelegation(
                  delegateName: name,
                  wholeAsset: true,
                  unitRefs: const {},
                  permissions: perms,
                ),
              );
            } else if (t.kind == 'unit') {
              final cut = t.id.indexOf('#');
              if (cut <= 0) continue;
              units
                  .putIfAbsent(t.id.substring(0, cut), () => <String>{})
                  .add(t.id.substring(cut + 1));
            }
          }
          units.forEach(
            (id, refs) => add(
              id,
              OutgoingDelegation(
                delegateName: name,
                wholeAsset: false,
                unitRefs: refs,
                permissions: perms,
              ),
            ),
          );
          continue;
        }
        // القسم كاملًا أو فئة منه: كل عناصري في تلك الفئة.
        final subs = DelegationRecord.subScopesOf(d.scope);
        for (final item in _items) {
          final id = item.id;
          if (id == null || DelegatedAssets.isDelegated(id)) continue;
          if (main == 'كل الأقسام' ||
              subs.isEmpty ||
              subs.contains(DelegationTargets.subOfCategory(item.category))) {
            add(
              id,
              OutgoingDelegation(
                delegateName: name,
                wholeAsset: true,
                unitRefs: const {},
                permissions: perms,
              ),
            );
          }
        }
      }
      OutgoingDelegations.replace(map);
      if (mounted) setState(() {});
    } catch (_) {
      // بلا تفويضاتي تبقى البطاقات بلا علامة «فوّضته».
    }
  }

  /// الدفعات والسجلات لمركز المتابعة — كلٌّ في محاولة مستقلة، ففشل
  /// أحدهما لا يُفرغ الآخر.
  Future<void> _loadFollowUpSources(
    List<PropertyUnitContractRecord> contracts,
  ) async {
    try {
      var payments = await _repository.fetchAllUnitPayments();
      // عقود كُتبت قبل ربط الدفعات بالجدول: تُولَّد سجلاتها مرة واحدة هنا
      // أيضًا، فلا ينتظر مركز المتابعة فتح كل وحدة على حدة.
      final byContract = <String, List<PropertyUnitPaymentRecord>>{};
      for (final payment in payments) {
        byContract.putIfAbsent(payment.contractId, () => []).add(payment);
      }
      var wrote = false;
      for (final contract in contracts) {
        final id = contract.id;
        if (id == null) continue;
        final lease = LeaseContractData.decode(contract.notes);
        final hasRows = lease.payments.isNotEmpty ||
            lease.adminFees.isNotEmpty ||
            lease.deposits.isNotEmpty;
        if (!hasRows) continue;
        final linked = (byContract[id] ?? const <PropertyUnitPaymentRecord>[])
            .any((p) => (decodePayExtra(p.notes)[kPayRowId] ?? '').isNotEmpty);
        if (linked) continue;
        if (await syncLeasePaymentRecords(
          repository: _repository,
          contract: contract,
          existing: byContract[id] ?? const [],
        )) {
          wrote = true;
        }
      }
      if (wrote) payments = await _repository.fetchAllUnitPayments();
      if (!mounted) return;
      setState(() {
        _paymentsByContract.clear();
        for (final payment in payments) {
          _paymentsByContract
              .putIfAbsent(payment.contractId, () => [])
              .add(payment);
        }
      });
    } catch (_) {
      // بلا دفعات يبقى قسم «مالية» أصفارًا، ولا تتعطّل القائمة.
    }
    try {
      final entries = await _repository.fetchAllEntries();
      if (!mounted) return;
      setState(() {
        _entriesByAsset.clear();
        for (final entry in entries) {
          _entriesByAsset.putIfAbsent(entry.assetId, () => []).add(entry);
        }
      });
    } catch (_) {
      // بلا سجلات يبقى «المستندات» و«المتابعة» أصفارًا.
    }
  }

  List<PropertyUnitContractRecord> _contractsOf(_AssetItem item) =>
      _contractsByAsset[item.id ?? ''] ?? const [];

  /// العقد الساري: لم ينتهِ بعد. وأقربها انتهاءً هو الذي يُعرض، لأنه أول
  /// ما يحتاج تجديدًا.
  PropertyUnitContractRecord? _activeContractOf(_AssetItem item) {
    PropertyUnitContractRecord? best;
    for (final contract in _contractsOf(item)) {
      final end = contract.endDate;
      // يوم الانتهاء نفسه ما زال ساريًا.
      if (_contractEndedByDate(contract)) continue;
      if (best == null) {
        best = contract;
        continue;
      }
      final bestEnd = best.endDate;
      if (bestEnd == null) {
        best = contract;
      } else if (end != null && end.isBefore(bestEnd)) {
        best = contract;
      }
    }
    return best;
  }

  /// عليه عقد محفوظ كمسودة (لم يكتمل بعد).
  bool _hasDraftContract(_AssetItem item) => _contractsOf(item).any(
    (contract) =>
        contract.status == PropertyUnitContractRecord.statusPending &&
        !_contractClosed(contract),
  );

  /// مفاتيح الوحدات التي عليها عقد سارٍ (المسودة لا تجعل الوحدة مؤجرة).
  Set<String> _leasedUnitKeysOf(_AssetItem item) {
    // يوم انتهاء العقد نفسه ما زال مؤجرًا (مقارنة بالتاريخ لا بالساعة).
    return {
      for (final contract in _contractsOf(item))
        if (_contractHolds(contract)) contract.unitKey,
    };
  }

  /// يُنشئ الأصل في قاعدة البيانات ويُعيد معرّفه (null عند الفشل).
  Future<String?> _createAssetRemote(_AssetItem item) async {
    try {
      final created = await _repository.createAsset(_assetToRecord(item));
      if (!mounted) return created.id;
      setState(() {
        final createdItem = _assetFromRecord(created);
        _items.insert(0, createdItem);
        // الانتقال لفئة العنصر المُنشأ نفسها مع طيّ القائمة كالمعتاد.
        _selectedFilter = createdItem.category;
        // نجح الحفظ بعد استبعاد أعمدة غير موجودة في الجدول: السجل محفوظ
        // لكن هذه الحقول لم تُكتب. يُقال صراحة بدل أن تُفقد بصمت.
        final dropped = SupabaseProjectAssetsRepository.droppedColumns();
        _loadError = dropped.isEmpty
            ? ''
            : 'حُفظ السجل، لكن هذه الحقول لا توجد لها أعمدة في قاعدة '
                  'البيانات ولم تُحفظ: ${dropped.join('، ')}';
      });
      return created.id;
    } catch (error) {
      if (!mounted) return null;
      // شريط سفلي يعيش أربع ثوانٍ ويموت مع رجوع شاشة الإضافة: المستخدم
      // يرى القائمة بلا عقاره ولا يعرف أن الحفظ فشل أصلًا. الخطأ يبقى
      // مكتوبًا على الشاشة حتى ينجح حفظ أو تحميل جديد.
      setState(() {
        _loadError =
            'تعذّر حفظ «${item.title}» في قاعدة البيانات.\n$error'
            '\n${AppSession.describeSession()}';
      });
      return null;
    }
  }

  Future<void> _updateAssetRemote(_AssetItem item) async {
    if (item.id == null || item.id!.isEmpty) return;
    try {
      final updated = await _repository.updateAsset(
        _assetToRecord(item, id: item.id),
      );
      if (!mounted) return;
      final index = _items.indexWhere((e) => e.id == updated.id);
      if (index == -1) return;
      setState(() => _items[index] = _assetFromRecord(updated));
    } catch (error) {
      if (!mounted) return;
      setState(() {
        _loadError =
            'تعذّر تحديث «${item.title}» في قاعدة البيانات.\n$error';
      });
    }
  }

  Future<void> _deleteAssetRemote(_AssetItem item) async {
    if (item.id == null || item.id!.isEmpty) return;
    try {
      await _repository.deleteAsset(item.id!);
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('تعذر حذف الأصل من قاعدة البيانات: $error'),
          behavior: SnackBarBehavior.floating,
        ),
      );
    }
  }

  _AssetItem _assetFromRecord(ProjectAssetRecord record) {
    final displayDate = record.endDate?.replaceAll('-', '/') ?? 'غير محدد';
    final mappedCategory = _fromDatabaseCategory(record.category);
    final status = record.status.isEmpty ? 'نشط' : record.status;
    return _AssetItem(
      id: record.id,
      title: record.title,
      subType: record.subType,
      category: mappedCategory,
      locationOrType: record.locationOrType ?? 'غير محدد',
      status: status,
      amountLabel: record.amountLabel ?? '0 ${AppSettings.currencySuffix}',
      followupNote: record.followupNote ?? 'لا توجد ملاحظات متابعة',
      owner: record.owner ?? 'غير محدد',
      tenant: record.tenant ?? 'غير محدد',
      rentValue: record.rentValue ?? 'غير محدد',
      endDate: displayDate,
      annualYield: record.annualYield ?? 'غير محدد',
      occupancyRate: record.occupancyRate,
      contractProgress: record.contractProgress,
      paymentProgress: record.paymentProgress,
      documentsProgress: record.documentsProgress,
      needsAttention: record.needsAttention,
      documents: const [],
      contracts: const [],
      tasks: const [],
      alerts: const [],
      logs: _stripPropertyMeta(_decodeStringList(record.logsJson)),
      propertyMeta: _decodePropertyMeta(_decodeStringList(record.logsJson)),
      createdAt: DateTime.now(),
      description: record.description,
      annexes: record.annexes,
      iconColor: record.iconColor == null ? null : Color(record.iconColor!),
      mapLink: record.mapLink ?? '',
      quickAddEnabled: record.quickAddEnabled,
      units: _decodeUnits(record.unitsJson).where(_unitIsLive).toList(),
      shelvedUnits: _decodeUnits(
        record.unitsJson,
      ).where((u) => !_unitIsLive(u)).toList(),
      employees: _decodeStringMaps(record.employeesJson),
      serialNumber: record.serialNumber ?? '',
      isFrozen: record.isFrozen,
      isPinned: record.isPinned,
      isSublease: record.isSublease,
      latitude: record.latitude,
      longitude: record.longitude,
    );
  }

  List<_PropertyUnit> _decodeUnits(String? unitsJson) {
    if (unitsJson == null || unitsJson.trim().isEmpty) return const [];
    try {
      final decoded = jsonDecode(unitsJson);
      if (decoded is! List) return const [];
      return decoded
          .whereType<Map>()
          .map((m) => _PropertyUnit.fromMap(Map<String, dynamic>.from(m)))
          .toList();
    } catch (_) {
      return const [];
    }
  }

  List<String> _decodeStringList(String? json) {
    if (json == null || json.trim().isEmpty) return const [];
    try {
      final decoded = jsonDecode(json);
      if (decoded is! List) return const [];
      return decoded.map((e) => e.toString()).toList();
    } catch (_) {
      return const [];
    }
  }

  List<Map<String, String>> _decodeStringMaps(String? json) {
    if (json == null || json.trim().isEmpty) return const [];
    try {
      final decoded = jsonDecode(json);
      if (decoded is! List) return const [];
      return decoded
          .whereType<Map>()
          .map(
            (m) => m.map(
              (key, value) => MapEntry(key.toString(), value?.toString() ?? ''),
            ),
          )
          .toList();
    } catch (_) {
      return const [];
    }
  }

  ProjectAssetRecord _assetToRecord(_AssetItem item, {String? id}) {
    return ProjectAssetRecord(
      id: id,
      title: item.title,
      subType: item.subType,
      category: _toDatabaseCategory(item.category),
      status: item.status,
      locationOrType: item.locationOrType,
      amountLabel: item.amountLabel,
      followupNote: item.followupNote,
      owner: item.owner,
      tenant: item.tenant,
      rentValue: item.rentValue,
      // سنة-شهر-يوم دائمًا: التاريخ بصيغة يوم/شهر/سنة (رخصة النشاط، ملكية
      // المركبة) كان يُرفض فيُحفظ فارغًا.
      endDate: item.endDate == 'غير محدد'
          ? null
          : () {
              final d = _parseAssetDate(item.endDate.trim());
              if (d == null) return item.endDate.replaceAll('/', '-');
              String two(int v) => v.toString().padLeft(2, '0');
              return '${d.year}-${two(d.month)}-${two(d.day)}';
            }(),
      annualYield: item.annualYield,
      occupancyRate: item.occupancyRate,
      contractProgress: item.contractProgress,
      paymentProgress: item.paymentProgress,
      documentsProgress: item.documentsProgress,
      needsAttention: item.needsAttention,
      iconColor: item.iconColor?.toARGB32(),
      description: item.description,
      annexes: item.annexes,
      mapLink: item.mapLink,
      quickAddEnabled: item.quickAddEnabled,
      unitsJson: jsonEncode(
        [...item.units, ...item.shelvedUnits].map((u) => u.toMap()).toList(),
      ),
      employeesJson: jsonEncode(item.employees),
      serialNumber: item.serialNumber,
      isFrozen: item.isFrozen,
      isPinned: item.isPinned,
      isSublease: item.isSublease,
      latitude: item.latitude,
      longitude: item.longitude,
      logsJson: jsonEncode(_logsWithPropertyMeta(item.propertyMeta, item.logs)),
    );
  }

  String _toDatabaseCategory(String uiCategory) {
    if (uiCategory == 'activity') return 'business';
    // للمعدات فئة قاعدة بيانات مستقلة عن "الأنشطة التجارية"؛ كانت سابقًا
    // تُخزَّن بنفس قيمة النشاط التجاري ('business') فتتحول كل معدة إلى نشاط
    // تجاري بشكل دائم بمجرد إعادة تحميل البيانات من الخادم (خطأ تصنيف غير
    // قابل للتراجع كان يفقد نوع الأصل الحقيقي).
    if (uiCategory == 'equipment') return 'equipment';
    // «أخرى» ليست فئة يُنشئها المستخدم — لا زر إضافة لها — بل وعاء لقيمة
    // تصنيف قديمة أو غير معروفة. فأول حفظ يسوّيها إلى «عقار».
    return 'real_estate';
  }

  String _fromDatabaseCategory(String dbCategory) {
    if (dbCategory == 'business') return 'activity';
    if (dbCategory == 'equipment') return 'equipment';
    // 'project': تصنيف من نسخة سابقة كانت تعدّ المشروع العقاري فئة مستقلة.
    // المشروع اليوم عقار نوعه الفرعي «مشروع سكني»، فيُقرأ عقارًا.
    if (dbCategory == 'real_estate' || dbCategory == 'project') {
      return 'real_estate';
    }
    // أي قيمة أخرى تُعرض في «أخرى» — مرئية ويمكن فتحها وتصحيحها — بدل أن
    // تُحسب عقارًا بلا إشعار فيضيع أثر الخلل.
    return 'other';
  }

  @override
  void dispose() {
    DelegatedAssets.changed.removeListener(_loadAssetsFromRemote);
    _searchController.dispose();
    super.dispose();
  }

  /// حالة العقار كما يفهمها صاحبه: مؤجر أو شاغر أو تحت الصيانة.
  ///
  /// تُقرأ من العقود أولًا: وحدة عليها عقد سارٍ مؤجرة ولو بقيت حالتها
  /// المخزَّنة «شاغرة»، ووحدة انتهى عقدها شاغرة ولو بقيت «مؤجرة». كانت
  /// تُقرأ من حالة الوحدة المخزَّنة وحدها، فيبقى العقار «مؤجرًا» سنوات
  /// بعد انتهاء عقده.
  String _assetStatusLabel(_AssetItem item) {
    // العقار والمركبة: شاغر أو مؤجر أو صيانة («ملغي» للعقد، في السجل
    // التاريخي). النشاط التجاري يبقى كما كان.
    if ((item.category == 'activity' ||
            item.category == 'real_estate' ||
            item.category == 'equipment') &&
        _isCancelledAsset(item)) {
      return 'ملغي';
    }
    if (item.status == 'مؤرشف') return 'مؤرشف';
    final openMaintenance =
        (_entriesByAsset[item.id ?? ''] ?? const <ProjectAssetEntryRecord>[])
            .any(
              (e) =>
                  e.kind == ProjectAssetEntryRecord.kindMaintenance &&
                  (e.data[_kMaintStateKey] ?? '') == _kMaintOpen,
            );
    // الصيانة تُضاف إلى حالة الإيجار ولا تحلّ محلها: «شاغر / صيانة».
    String withMaint(String s) => openMaintenance ? '$s / صيانة' : s;
    if (item.category == 'equipment') {
      final contracts = _contractsOf(item);
      return withMaint(
        contracts.any(_contractHolds)
            ? 'مؤجر'
            // انتهت مدة العقد ولم يُلغَ / يُجدَّد بعد.
            : contracts.any(_contractEndedOpen)
            ? 'منتهي العقد'
            : 'شاغر',
      );
    }
    if (item.category != 'real_estate') {
      return item.needsAttention ? 'متابعة' : item.status;
    }
    final inMaint =
        item.needsAttention || item.status == 'صيانة' || openMaintenance;
    String withPropMaint(String s) => inMaint ? '$s / صيانة' : s;
    final leasedKeys = _leasedUnitKeysOf(item);
    if (item.units.isNotEmpty) {
      // الحالة المحفوظة في الوحدة لا تُعتمد إلا لعقار بلا عقود مسجّلة
      // (بيانات قديمة)، و«مؤجرة» وحدها تعني مؤجرة — المسودة والمنتهي لا.
      final noContracts = _contractsOf(item).isEmpty;
      final leased = item.units
          .where(
            (unit) =>
                leasedKeys.contains(unit.unitKey) ||
                (noContracts && unit.status == 'مؤجرة'),
          )
          .length;
      if (leased == 0) return withPropMaint('شاغر');
      return withPropMaint(
        leased == item.units.length ? 'مؤجر' : 'مؤجر جزئيًا',
      );
    }
    if (leasedKeys.isNotEmpty) return withPropMaint('مؤجر');
    return withPropMaint(item.tenant.trim().isEmpty ? 'شاغر' : 'مؤجر');
  }

  Color _assetStatusColor(_AssetItem item) {
    final label = _assetStatusLabel(item);
    if (label.endsWith('صيانة')) return const Color(0xFFC4392E);
    return switch (label) {
      'ملغي' => const Color(0xFF8C3A32),
      'مجمّد' || 'مؤرشف' => const Color(0xFF5C6B68),
      'صيانة' || 'متابعة' || 'منتهي العقد' => const Color(0xFFC4392E),
      'شاغر' => _kVacantColor,
      'مؤجر جزئيًا' => _kPartlyLeasedColor,
      _ => const Color(0xFF34A894),
    };
  }

  /// نوع العقد كما هو مسجَّل فعلًا في جدول العقود.
  String _assetContractLabel(_AssetItem item) {
    final contract = _activeContractOf(item);
    if (contract == null) {
      // بلا عقد = شاغر (مكتوبة في السطر الثاني)، فلا سطر «بلا عقد».
      return _contractsOf(item).isEmpty ? '' : 'عقد منتهٍ — يحتاج تجديدًا';
    }
    return switch (contract.leaseType) {
      PropertyUnitContractRecord.leaseTypeMultiUnit => 'عقد متعدد الوحدات',
      PropertyUnitContractRecord.leaseTypeSublease => 'عقد من الباطن',
      _ => 'عقد إيجار',
    };
  }

  /// تاريخ انتهاء العقد الساري — لا حقل endDate الميت في سجل الأصل.
  ///
  /// بلا عقد مسجَّل يعود فارغًا لا «غير محدد»: البطاقة تُسقط صف التاريخ
  /// كلّه عندها، فلا تبقى أيقونة تقويم تحرس كلمة لا تقول شيئًا.
  String _assetEndDateLabel(_AssetItem item) {
    final contract = _activeContractOf(item);
    final end = contract?.endDate;
    if (end != null) return formatDayMonthYear(end);
    final contracts = _contractsOf(item);
    if (contracts.isNotEmpty) {
      final last = contracts
          .map((c) => c.endDate)
          .whereType<DateTime>()
          .fold<DateTime?>(
            null,
            (a, b) => a == null || b.isAfter(a) ? b : a,
          );
      if (last != null) return 'منتهي ${formatDayMonthYear(last)}';
    }
    return '';
  }

  String _assetSubtitle(_AssetItem item) {
    final parts = <String>[
      if (item.subType.trim().isNotEmpty) item.subType.trim(),
      if (item.category == 'real_estate' && item.units.isNotEmpty)
        item.units.length == 1
            ? 'وحدة واحدة'
            : item.units.length == 2
            ? 'وحدتان'
            : '${item.units.length} وحدات',
    ];
    return parts.join(' · ');
  }

  /// تحت حالة النشاط في بطاقته: تاريخ الإلغاء للملغى، وإلا تاريخ انتهاء
  /// الرخصة (أو نهاية عقد الإيجار إن لم تُسجَّل الرخصة).
  String? _activityCardDate(_AssetItem item) {
    String of(String key) => (item.propertyMeta[key] ?? '').trim();
    final text = _isCancelledAsset(item)
        ? of(_ActKeys.cancelledAt)
        : (of(_ActKeys.licenseEnd).isNotEmpty
              ? of(_ActKeys.licenseEnd)
              : of(_ActKeys.leaseEnd));
    return text.isEmpty ? null : text;
  }

  bool _matchesFilter(_AssetItem item, String filter) {
    // الفرع يظهر داخل نشاطه الرئيسي (قسم «الفروع») كالوحدة داخل عقارها.
    if (item.serialNumber.startsWith('branch:')) return false;
    // المخفي من «تخصيص الصفحات» (فئته أو نوعه) لا يظهر ولا يُعدّ.
    if (_assetTypeHidden(
      item.category,
      item.category == 'equipment'
          ? (item.propertyMeta[_EquipKeys.vehicleClass] ?? _kVehicleLand)
          : _assetSubTypeOf(item),
    )) {
      return false;
    }
    if (filter == 'all') return true;
    return item.category == filter;
  }

  /// قيم الفلتر الرئيسي — نفس البنية في الشاشات الأربع.
  final AppFilterValues _filter = AppFilterValues();

  /// مرحلة الاستحقاق — نفس مراحل مركز المتابعة: متأخرة، مستحقة (7
  /// أيام)، قريبة الاستحقاق (30 يومًا).
  static String? _dueStageOf(DateTime? due) {
    if (due == null) return null;
    final today = DateUtils.dateOnly(DateTime.now());
    final days = DateUtils.dateOnly(due).difference(today).inDays;
    if (days < 0) return 'متأخرة';
    if (days <= 7) return 'مستحقة';
    if (days <= 30) return 'قريبة الاستحقاق';
    return null;
  }

  /// هل للأصل دفعة غير مسددة (أو شيك) في هذه المرحلة؟
  bool _hasPaymentInStage(
    _AssetItem item,
    String stage, {
    bool chequesOnly = false,
  }) {
    for (final contract in _contractsOf(item)) {
      final id = contract.id;
      if (id == null) continue;
      for (final payment in _paymentsByContract[id] ?? const []) {
        if (payRemaining(payment) <= 0) continue;
        if (_dueStageOf(payment.dueDate) != stage) continue;
        if (chequesOnly) {
          final extra = decodePayExtra(payment.notes);
          final isCheque = (extra[kPayMethod] ?? '').trim() == 'شيك' ||
              (extra[kPayCheque] ?? '').trim().isNotEmpty;
          if (!isCheque) continue;
        }
        return true;
      }
    }
    return false;
  }

  bool _matchesAdvancedAssetFilters(_AssetItem item) {
    // مقارنة بعد trim: قائمة الأنواع تُبنى من قيم منظّفة، فأي فراغ زائد
    // في البيانات كان يمنع العنصر من مطابقة نوعه نفسه.
    if (_filter.subCategory != null) {
      final sub = _assetSubTypeOf(item);
      if (_filter.subCategory == 'أخرى') {
        // «أخرى»: ما لا يندرج تحت أي نوع معروف في فئته.
        final known = _assetSubCategories(item.category)
            .where((value) => value != 'أخرى');
        if (known.contains(sub)) return false;
      } else if (sub != _filter.subCategory) {
        return false;
      }
    }
    final today = DateUtils.dateOnly(DateTime.now());
    switch (_filter.status) {
      // قائمة «الحالة ▼» الجديدة.
      case 'قريبة الاستحقاق':
        if (!_openDueDays(item).any((d) => d >= 0 && d <= 7)) return false;
      case 'مستحقة':
        if (!_openDueDays(item).any((d) => d == 0)) return false;
      case 'متأخرة':
        if (!item.needsAttention && !_openDueDays(item).any((d) => d < 0)) {
          return false;
        }
      case 'مكتملة':
        if (item.needsAttention ||
            item.isFrozen ||
            _openPaymentsOf(item).isNotEmpty) {
          return false;
        }
      case 'تنتهي قريبًا':
        {
          final end = _assetEndDate(item);
          if (end == null) return false;
          final left = DateUtils.dateOnly(end).difference(today).inDays;
          if (left < 0 || left > 30) return false;
        }
      case 'منتهية':
        {
          final end = _assetEndDate(item);
          if (end == null || !DateUtils.dateOnly(end).isBefore(today)) {
            return false;
          }
        }
      case 'نشط':
        if (item.isFrozen || item.needsAttention) return false;
      case 'المستحق بعد 7 أيام':
        final due = _parseAssetDate(item.endDate);
        if (due == null) return false;
        final days = due.difference(DateUtils.dateOnly(DateTime.now())).inDays;
        if (days < 0 || days > 7) return false;
      case 'متأخر':
        if (!item.needsAttention) return false;
      case 'مكتمل':
        if (item.needsAttention || item.isFrozen) return false;
      case 'ملغاة':
        if (!_isCancelledAsset(item)) return false;
      case 'مسودة':
        if (!_hasDraftContract(item)) return false;
      case 'مؤرشف':
        if (!item.isFrozen) return false;
    }
    if (!_filter.matchesDate(_parseAssetDate(item.endDate))) return false;
    final amount = num.tryParse(
      item.rentValue.replaceAll(RegExp(r'[^0-9.]'), ''),
    );
    if ((_filter.amountFrom != null || _filter.amountTo != null) &&
        (amount == null || !_filter.matchesAmount(amount))) {
      return false;
    }
    if (_filter.documentName.isNotEmpty &&
        !AppFilterValues.textMatches(_filter.documentName, [
          ...item.documents,
          ...item.contracts,
          for (final entry in _entriesByAsset[item.id ?? ''] ??
              const <ProjectAssetEntryRecord>[])
            if (entry.kind == ProjectAssetEntryRecord.kindDocument)
              ...entry.data.values,
        ])) {
      return false;
    }
    // المستند — الفلتر ▼.
    if (_filter.documentState != null &&
        !_assetDocMatches(item, _filter.documentState!)) {
      return false;
    }
    // العملة: عملة الأصل إن سُجّلت، وإلا عملة التطبيق.
    if (_filter.currency != null) {
      final currency = AppSettings.currencyOf(item.propertyMeta['العملة']);
      if (currency != _filter.currency) return false;
    }
    // طريقة الدفع: أي دفعة للأصل بهذه الطريقة.
    if (_filter.paymentMethod != null) {
      String kindOf(String method) => method.contains('نقد') ||
              method.contains('كاش')
          ? 'نقدًا'
          : method.contains('تحويل')
          ? 'تحويل بنكي'
          : method.contains('بطاقة')
          ? 'بطاقة بنكية'
          : method.contains('محفظة')
          ? 'محفظة إلكترونية'
          : method.trim().isEmpty
          ? ''
          : 'أخرى';
      final matches = _paymentsOfAsset(item).any(
        (payment) =>
            kindOf(decodePayExtra(payment.notes)[kPayMethod] ?? '') ==
            _filter.paymentMethod,
      );
      if (!matches) return false;
    }
    // الدين: «لي» دفعات مستحقة لم تُسدَّد، و«عليّ» عقار مستأجر من الغير
    // (إيجاره عليك).
    switch (_filter.debtDirection) {
      case 'لي':
        if (_openPaymentsOf(item).isEmpty) return false;
      case 'عليّ':
        if (!item.isSublease) return false;
    }
    // الصيانة ▼: من يتحمّلها — صيانة الوحدات، أو «الصيانة على» في الآلية.
    // المبلغ ▼ بالاستحقاق: أصل له دفعة بهذه المرحلة.
    final amountStage = _filter.amountShortcut;
    if (const ['قريبة الاستحقاق', 'مستحقة', 'متأخرة'].contains(amountStage) &&
        !_hasPaymentInStage(item, amountStage!)) {
      return false;
    }
    // الشيكات ▼: أصل له شيك بهذه المرحلة.
    final chequeStage = _filter.chequeState;
    if (chequeStage != null &&
        !_hasPaymentInStage(item, chequeStage, chequesOnly: true)) {
      return false;
    }
    if (_filter.maintenanceBy != null) {
      final wanted = _filter.maintenanceBy!;
      bool same(String value) {
        final v = value.trim();
        return switch (wanted) {
          'على المؤجر' => v == 'على المؤجر' || v == 'على المالك',
          'على المستأجر' => v == 'على المستأجر',
          _ => v.startsWith('مناصفة'),
        };
      }

      var found = same(item.propertyMeta['الصيانة على'] ?? '');
      for (final unit in item.units) {
        if (found) break;
        final raw = unit.extras['سجل الصيانة'] ?? '';
        if (raw.isEmpty) continue;
        try {
          final decoded = jsonDecode(raw);
          if (decoded is List) {
            found = decoded.whereType<Map>().any(
              (entry) => same('${entry['النوع'] ?? ''}'),
            );
          }
        } catch (_) {
          // سجل صيانة تالف لا يمنع بقية الفلترة.
        }
      }
      if (!found) return false;
    }
    if (_filter.personName.isNotEmpty &&
        !AppFilterValues.textMatches(_filter.personName, [
          item.owner,
          item.tenant,
        ])) {
      return false;
    }
    if (_filter.delegateName.isNotEmpty &&
        !AppFilterValues.textMatches(_filter.delegateName, [
          item.owner,
          for (final employee in item.employees) employee['الاسم'] ?? '',
        ])) {
      return false;
    }
    if (_filter.placeName.isNotEmpty &&
        !AppFilterValues.textMatches(_filter.placeName, [
          item.locationOrType,
          item.mapLink,
        ])) {
      return false;
    }
    return true;
  }

  /// تحويل تاريخ نصّي (d/M/yyyy أو yyyy/M/d) إلى DateTime، أو null.
  DateTime? _parseAssetDate(String raw) {
    final parts = raw.split(RegExp(r'[/-]'));
    if (parts.length != 3) return null;
    final first = int.tryParse(parts[0]);
    final second = int.tryParse(parts[1]);
    final third = int.tryParse(parts[2]);
    if (first == null || second == null || third == null) return null;
    return first > 31
        ? DateTime(first, second, third)
        : DateTime(third, second, first);
  }

  /// خيارات الفلتر الصغير حسب الفئة المختارة.
  /// (حسب الورقة: نفسها للكل وللعقارات والأنشطة والآليات.)
  List<String> _quickSortOptions() => const [
    'الأحدث أولاً',
    'نشط',
    'ملغاة',
    'مسودة',
    'مستندات تنتهي قريبًا',
    'مستندات منتهية',
    'قريبة الاستحقاق',
    'مستحقة',
    'مفوَّض أنا بإدارته',
    'فوّضت غيري بإدارته',
  ];

  /// كل دفعات الأصل (من عقود وحداته أو عقد الآلية).
  /// (عقد أُلغي بالتسوية: ما بقي من دفعاته سُوِّي، فلا يُحسب مستحقًا.)
  List<PropertyUnitPaymentRecord> _paymentsOfAsset(_AssetItem item) => [
    for (final contract in _contractsOf(item))
      for (final payment
          in _paymentsByContract[contract.id ?? ''] ??
              const <PropertyUnitPaymentRecord>[])
        if (!paymentWaivedByClosure(contract, payment)) payment,
  ];

  /// الدفعات التي لم تُسدَّد بالكامل.
  List<PropertyUnitPaymentRecord> _openPaymentsOf(_AssetItem item) => [
    for (final payment in _paymentsOfAsset(item))
      if (payment.amountDue - payment.amountPaid > 0.009) payment,
  ];

  /// أيام حتى الاستحقاق لكل دفعة مفتوحة (سالب = فات موعدها).
  Iterable<int> _openDueDays(_AssetItem item) {
    final today = DateUtils.dateOnly(DateTime.now());
    return [
      for (final payment in _openPaymentsOf(item))
        if (payment.dueDate != null)
          DateUtils.dateOnly(payment.dueDate!).difference(today).inDays,
    ];
  }

  /// تواريخ انتهاء مستندات الأصل: سجلات «المستندات»، وشهادات الآلية
  /// وتواريخ ملكيتها وضمانها.
  List<DateTime> _assetDocExpiries(_AssetItem item) {
    final out = <DateTime>[];
    for (final entry in _entriesByAsset[item.id ?? ''] ??
        const <ProjectAssetEntryRecord>[]) {
      if (entry.kind != ProjectAssetEntryRecord.kindDocument) continue;
      final date = _parseAssetDate(entry.data['تاريخ الانتهاء'] ?? '');
      if (date != null) out.add(date);
    }
    for (final meta in item.propertyMeta.entries) {
      if (!meta.key.contains('انتهاء') && meta.key != 'تاريخ الضمان') {
        continue;
      }
      final date = _parseAssetDate(meta.value.trim());
      if (date != null) out.add(date);
    }
    return out;
  }

  bool _assetDocMatches(_AssetItem item, String label) {
    final today = DateUtils.dateOnly(DateTime.now());
    final expiries = _assetDocExpiries(item);
    if (label.contains('قريب')) {
      return expiries.any((date) {
        final days = date.difference(today).inDays;
        return days >= 0 && days <= 30;
      });
    }
    if (label.contains('منته')) {
      return expiries.any((date) => date.isBefore(today));
    }
    return true;
  }

  /// تاريخ انتهاء الأصل: أقرب عقد سارٍ، وإلا تاريخ الأصل نفسه.
  DateTime? _assetEndDate(_AssetItem item) =>
      _activeContractOf(item)?.endDate ?? _parseAssetDate(item.endDate);

  /// خيار الفلتر الصغير.
  bool _matchesAssetQuickFilter(_AssetItem item, String label) {
    switch (label) {
      case 'نشط':
        return !item.isFrozen && !item.needsAttention;
      case 'ملغاة':
        return item.status.contains('ملغا');
      case 'مسودة':
        return _hasDraftContract(item);
      case 'مستندات تنتهي قريبًا':
      case 'مستندات قريبة الإنتهاء':
        return _assetDocMatches(item, 'قريبة');
      case 'مستندات منتهية':
        return _assetDocMatches(item, 'منتهية');
      case 'قريبة الاستحقاق':
        return _openDueDays(item).any((days) => days >= 0 && days <= 7);
      case 'مستحقة':
        return _openDueDays(item).any((days) => days == 0);
      case 'مفوَّض أنا بإدارته':
        return DelegatedAssets.isDelegated(item.id);
      case 'فوّضت غيري بإدارته':
        return OutgoingDelegations.of(item.id).isNotEmpty;
      default:
        return true;
    }
  }

  /// الفئات الفرعية: أنواع العقار كما في «إضافة عقار»، وتصنيفات النشاط
  /// كما في «إضافة نشاط»، والمركبات أنواعها البرية والبحرية.
  static List<String> _assetSubCategories(String category) =>
      switch (category) {
    'real_estate' => [
      for (final option in _propertyTypeOptions) option['label'] as String,
      'أخرى',
    ],
    'activity' => _activityTypeOptions,
    'equipment' => _allVehicleTypes,
    _ => const <String>[],
  };

  /// النوع الذي يُطابَق به الفلتر: للمركبات نوعها المختار عند الإضافة،
  /// والسجلات القديمة (قبل التصنيف) بنوعها المكتوب فتقع تحت «أخرى».
  static String _assetSubTypeOf(_AssetItem item) {
    if (item.category == 'equipment') {
      final type = (item.propertyMeta[_EquipKeys.vehicleType] ?? '').trim();
      if (type.isNotEmpty) return type;
    }
    return item.subType.trim();
  }

  /// عدد عناصر فئة بعينها — يظهر داخل رقاقة الفئة في أعلى الصفحة.
  int _categoryCount(String key) =>
      _items.where((item) => _matchesFilter(item, key)).length;

  List<_AssetItem> _filteredItems() {
    final query = _searchController.text.trim();

    final filtered = _items.where((item) {
      final typeMatches = _matchesFilter(item, _selectedFilter);
      final queryMatches = matchesSearchQuery(
        query: query,
        fields: [
          item.title,
          item.subType,
          item.category,
          item.followupNote,
          item.locationOrType,
          item.status,
          item.owner,
          item.tenant,
          item.rentValue,
          item.amountLabel,
          item.endDate,
          item.annualYield,
          item.description,
          ...item.documents,
          ...item.contracts,
          ...item.tasks,
          ...item.alerts,
          ...item.logs,
        ],
      );
      return typeMatches &&
          queryMatches &&
          _matchesAdvancedAssetFilters(item);
    }).toList();

    // الفلتر الصغير: كل خيار يُظهر ما يطابقه فقط، و«الأحدث أولاً» ترتيب.
    filtered.removeWhere(
      (item) => !_matchesAssetQuickFilter(item, _selectedSort),
    );

    num assetAmount(_AssetItem item) =>
        num.tryParse(item.rentValue.replaceAll(RegExp(r'[^0-9.]'), '')) ?? 0;

    filtered.sort((a, b) {
      // المبلغ ▼: «أعلى/أقل مبلغًا» ترتيب.
      final order = _filter.amountShortcut;
      if (order == 'أعلى مبلغ' || order == 'أعلى مبلغًا') {
        final byAmount = assetAmount(b).compareTo(assetAmount(a));
        if (byAmount != 0) return byAmount;
      } else if (order == 'أقل مبلغ' || order == 'أقل مبلغًا') {
        final byAmount = assetAmount(a).compareTo(assetAmount(b));
        if (byAmount != 0) return byAmount;
      }
      return (_parseAssetDate(b.endDate) ?? DateTime(2000)).compareTo(
        _parseAssetDate(a.endDate) ?? DateTime(2000),
      );
    });
    return filtered;
  }

  IconData _filterIcon(String key) {
    if (key == 'real_estate') return Icons.apartment_rounded;
    if (key == 'activity') return Icons.storefront_rounded;
    if (key == 'equipment') return Icons.precision_manufacturing_outlined;
    return Icons.grid_view_rounded;
  }

  /// مركز المتابعة — البنية الموحّدة للعقارات والأنشطة والآليات:
  ///
  /// - **مالية**: شيكات، كاش، تحويلات مالية، تأمين، أخرى — لكلٍّ ما قرب
  ///   استحقاقه (خلال 30 يومًا) وما استُحق (خلال 7 أيام) وما تأخر.
  /// - **المستندات**: وثائق شخصية ووثائق عامة — ما قرب انتهاؤه (خلال 30
  ///   يومًا) وما انتهى.
  /// - **متابعة وتخطيط**: ما قرب (خلال 7 أيام) وما حان دوره اليوم وما تأخر.
  /// - **الطلبات**: ما ينتظر موافقة.
  ///
  /// الضغط على بند يعرض بياناته للاطلاع فقط — لا إجراء ولا انتقال.
  /// والبند الفارغ يظهر صفرًا.
  List<FollowUpGroup> _followUpGroups(List<_AssetItem> assets) {
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    int daysTo(DateTime date) =>
        DateTime(date.year, date.month, date.day).difference(today).inDays;

    /// مرحلة المبلغ: متأخرة، مستحقة (7 أيام)، قريبة الاستحقاق (30 يومًا).
    String? moneyStage(DateTime? due) {
      if (due == null) return null;
      final days = daysTo(due);
      if (days < 0) return 'متأخرة';
      if (days <= 7) return 'مستحقة';
      if (days <= 30) return 'قريبة الاستحقاق';
      return null;
    }

    /// مرحلة المستند: منتهي، أو قريب الانتهاء (30 يومًا).
    String? docStage(DateTime? expiry) {
      if (expiry == null) return null;
      final days = daysTo(expiry);
      if (days < 0) return 'منتهي';
      if (days <= 30) return 'قريب الانتهاء';
      return null;
    }

    /// مرحلة المتابعة: متأخرة، حان دورها اليوم، قريبة (7 أيام).
    String? planStage(DateTime? date) {
      if (date == null) return null;
      final days = daysTo(date);
      if (days < 0) return 'متأخرة';
      if (days == 0) return 'حان دورها';
      if (days <= 7) return 'قريبة';
      return null;
    }

    int stageRank(String stage) => switch (stage) {
      'متأخرة' || 'منتهي' => 0,
      'حان دورها' || 'مستحقة' => 1,
      _ => 2,
    };

    Color stageColor(String stage) => switch (stage) {
      'متأخرة' || 'منتهي' => const Color(0xFFC4392E),
      'حان دورها' || 'مستحقة' => const Color(0xFFA6691A),
      _ => const Color(0xFF0E7161),
    };

    DateTime? flexDate(String? raw) {
      final text = (raw ?? '').trim();
      if (text.isEmpty) return null;
      final direct = DateTime.tryParse(text);
      if (direct != null) return direct;
      final parts = text.split(RegExp(r'[/\-]'));
      if (parts.length != 3) return null;
      final a = int.tryParse(parts[0]);
      final b = int.tryParse(parts[1]);
      final c = int.tryParse(parts[2]);
      if (a == null || b == null || c == null) return null;
      // يوم/شهر/سنة، أو سنة/شهر/يوم.
      return a > 31 ? DateTime(a, b, c) : DateTime(c, b, a);
    }

    /// صف للاطلاع فقط: بلا onTap.
    FollowUpEntry row({
      required String title,
      required String subtitle,
      required String stage,
      required IconData icon,
      String? trailing,
    }) => FollowUpEntry(
      title: title,
      subtitle: subtitle,
      icon: icon,
      color: stageColor(stage),
      trailingText: trailing,
    );

    List<FollowUpEntry> sorted(
      List<(String stage, DateTime date, FollowUpEntry entry)> items,
    ) {
      items.sort((x, y) {
        final byStage = stageRank(x.$1).compareTo(stageRank(y.$1));
        return byStage != 0 ? byStage : x.$2.compareTo(y.$2);
      });
      return [for (final item in items) item.$3];
    }

    // ---- مالية: من جدول الدفعات وحده (إيجار + رسوم + تأمين) ----
    List<FollowUpEntry> money(
      List<_AssetItem> scoped,
      bool Function(String method, String kind) include,
    ) {
      final items = <(String, DateTime, FollowUpEntry)>[];
      for (final item in scoped) {
        for (final contract in _contractsOf(item)) {
          final id = contract.id;
          if (id == null) continue;
          // المسودة لم تُعتمد بعد: دفعاتها ليست مستحقة.
          if (contract.status == PropertyUnitContractRecord.statusPending) {
            continue;
          }
          for (final payment in _paymentsByContract[id] ?? const []) {
            final remaining = payRemaining(payment);
            if (remaining <= 0) continue;
            // سقطت بإلغاء العقد / تسويته: لا تُتابَع (كما في صفحة الأصل).
            if (paymentWaivedByClosure(contract, payment)) continue;
            final due = payment.dueDate;
            final stage = moneyStage(due);
            if (stage == null || due == null) continue;
            final extra = decodePayExtra(payment.notes);
            final method = (extra[kPayMethod] ?? '').trim();
            final kind = (extra[kPayKind] ?? kPayKindRent).trim();
            if (!include(method, kind)) continue;
            final cheque = (extra[kPayCheque] ?? '').trim();
            final name = (extra[kPayName] ?? kind).trim();
            items.add((
              stage,
              due,
              row(
                title: cheque.isEmpty ? name : 'شيك $cheque · $name',
                subtitle: [
                  stage,
                  formatDayMonthYear(due),
                  contract.unitName ?? 'وحدة',
                  item.title,
                  if ((contract.tenantName ?? '').trim().isNotEmpty)
                    contract.tenantName!.trim(),
                ].join(' · '),
                stage: stage,
                icon: Icons.payments_outlined,
                trailing: formatMoneyValue(remaining),
              ),
            ));
          }
        }
      }
      return sorted(items);
    }

    // ---- المستندات: سجلات الأصل + مستندات الوحدات ----
    const personalWords = [
      'هوية',
      'جواز',
      'إقامة',
      'اقامة',
      'رخصة قيادة',
      'بطاقة',
      'شخصي',
    ];
    List<FollowUpEntry> documents(List<_AssetItem> scoped, bool personal) {
      final items = <(String, DateTime, FollowUpEntry)>[];
      for (final item in scoped) {
        for (final entry in _entriesByAsset[item.id ?? ''] ?? const []) {
          if (entry.kind != ProjectAssetEntryRecord.kindDocument) continue;
          final name = (entry.data['اسم المستند'] ?? '').trim();
          final type = (entry.data['نوع المستند'] ?? '').trim();
          final isPersonal = personalWords.any(
            (w) => name.contains(w) || type.contains(w),
          );
          if (isPersonal != personal) continue;
          final expiry = flexDate(entry.data['تاريخ الانتهاء']);
          final stage = docStage(expiry);
          if (stage == null || expiry == null) continue;
          items.add((
            stage,
            expiry,
            row(
              title: name.isEmpty ? (type.isEmpty ? 'مستند' : type) : name,
              subtitle: [
                stage,
                formatDayMonthYear(expiry),
                if (type.isNotEmpty) type,
                item.title,
              ].join(' · '),
              stage: stage,
              icon: personal ? Icons.badge_outlined : Icons.description_outlined,
            ),
          ));
        }
        for (final unit in item.units) {
          final raw = unit.extras['مستندات الوحدة'] ?? '';
          if (raw.trim().isEmpty) continue;
          List<dynamic> list;
          try {
            final decoded = jsonDecode(raw);
            list = decoded is List ? decoded : const [];
          } catch (_) {
            list = const [];
          }
          for (final doc in list.whereType<Map>()) {
            final owner = '${doc['الجهة'] ?? ''}';
            // مستندات المستأجر والمؤجر شخصية؛ مستندات العقار عامة.
            final isPersonal =
                owner.contains('المستأجر') || owner.contains('المؤجر');
            if (isPersonal != personal) continue;
            final expiry = flexDate('${doc['تاريخ الانتهاء'] ?? ''}');
            final stage = docStage(expiry);
            if (stage == null || expiry == null) continue;
            final name = '${doc['اسم المستند'] ?? ''}'.trim();
            items.add((
              stage,
              expiry,
              row(
                title: name.isEmpty ? 'مستند' : name,
                subtitle: [
                  stage,
                  formatDayMonthYear(expiry),
                  if (owner.isNotEmpty) owner,
                  unit.name,
                  item.title,
                ].join(' · '),
                stage: stage,
                icon: personal
                    ? Icons.badge_outlined
                    : Icons.description_outlined,
              ),
            ));
          }
        }
      }
      return sorted(items);
    }

    // ---- متابعة وتخطيط: متابعات الوحدات، والعقود المنتهية أو القريبة ----
    List<FollowUpEntry> planning(List<_AssetItem> scoped, String kind) {
      final items = <(String, DateTime, FollowUpEntry)>[];
      for (final item in scoped) {
        for (final unit in item.units) {
          final raw = unit.extras['متابعات الوحدة'] ?? '';
          if (raw.trim().isEmpty) continue;
          List<dynamic> list;
          try {
            final decoded = jsonDecode(raw);
            list = decoded is List ? decoded : const [];
          } catch (_) {
            list = const [];
          }
          for (final task in list.whereType<Map>()) {
            if (_followKindOf('${task['النوع'] ?? ''}') != kind) continue;
            final date = flexDate('${task['التاريخ'] ?? ''}');
            final stage = planStage(date);
            if (stage == null || date == null) continue;
            final title = '${task['البند'] ?? ''}'.trim();
            items.add((
              stage,
              date,
              row(
                title: title.isEmpty ? 'متابعة' : title,
                subtitle: [
                  stage,
                  formatDayMonthYear(date),
                  unit.name,
                  item.title,
                ].join(' · '),
                stage: stage,
                icon: Icons.event_note_outlined,
              ),
            ));
          }
        }
        // بنود «المتابعة والتخطيط» على مستوى الأصل نفسه، كلٌّ في نوعه.
        for (final entry in _entriesByAsset[item.id ?? ''] ?? const []) {
          final type = entry.data['نوع المتابعة'];
          if (type == null || _followKindOf(type) != kind) continue;
          final date = flexDate(entry.data['التاريخ']);
          final stage = planStage(date);
          if (stage == null || date == null) continue;
          final title = (entry.data['العنوان'] ?? '').trim();
          items.add((
            stage,
            date,
            row(
              title: title.isEmpty ? kind : title,
              subtitle: [
                stage,
                formatDayMonthYear(date),
                item.title,
              ].join(' · '),
              stage: stage,
              icon: _followKindIcon(kind),
            ),
          ));
        }
        // انتهاء العقود تذكيرات: تحت «تذكير» وحده.
        if (kind != 'تذكير') continue;
        // عقد إيجار انتهى أو ينتهي خلال أسبوع: يحتاج تجديدًا أو إخلاءً.
        for (final contract in _contractsOf(item)) {
          // المُغلق (ملغي / مُجدَّد / منتهٍ بتسوية) والمسودة لا يُذكَّر بهما.
          if (_contractClosed(contract) ||
              contract.status == PropertyUnitContractRecord.statusPending) {
            continue;
          }
          final end = contract.endDate;
          final stage = planStage(end);
          if (stage == null || end == null) continue;
          items.add((
            stage,
            end,
            row(
              title: 'انتهاء عقد ${contract.unitName ?? 'وحدة'}',
              subtitle: [
                stage,
                formatDayMonthYear(end),
                if ((contract.tenantName ?? '').trim().isNotEmpty)
                  contract.tenantName!.trim(),
                item.title,
              ].join(' · '),
              stage: stage,
              icon: Icons.event_busy_outlined,
            ),
          ));
        }
        // عقود الأصل الأخرى (صيانة، خدمات...) بتاريخ انتهائها.
        for (final entry in _entriesByAsset[item.id ?? ''] ?? const []) {
          if (entry.kind != ProjectAssetEntryRecord.kindContract) continue;
          final end = flexDate(entry.data['تاريخ الانتهاء']);
          final stage = planStage(end);
          if (stage == null || end == null) continue;
          final name = (entry.data['اسم العقد'] ?? '').trim();
          items.add((
            stage,
            end,
            row(
              title: name.isEmpty ? 'عقد' : name,
              subtitle: [
                stage,
                formatDayMonthYear(end),
                item.title,
              ].join(' · '),
              stage: stage,
              icon: Icons.description_rounded,
            ),
          ));
        }
      }
      return sorted(items);
    }

    // ---- صيانة: ما موعده اليوم أو خلال أسبوع ----
    List<FollowUpEntry> maintenance(List<_AssetItem> scoped) {
      final items = <(String, DateTime, FollowUpEntry)>[];
      void add(String title, DateTime? date, String place, String state) {
        // المنتهية لا تُتابَع، والمفتوحة («تحت الصيانة») التي فات موعدها
        // تبقى «متأخرة».
        if (state == _kMaintDone || date == null) return;
        if (daysTo(date) < 0 && state != _kMaintOpen) return;
        final stage = planStage(date);
        if (stage == null) return;
        items.add((
          stage,
          date,
          row(
            title: title.isEmpty ? 'صيانة' : title,
            subtitle: [stage, formatDayMonthYear(date), place].join(' · '),
            stage: stage,
            icon: Icons.build_rounded,
          ),
        ));
      }

      for (final item in scoped) {
        for (final unit in item.units) {
          final raw = unit.extras['سجل الصيانة'] ?? '';
          if (raw.trim().isEmpty) continue;
          try {
            final decoded = jsonDecode(raw);
            if (decoded is! List) continue;
            for (final entry in decoded.whereType<Map>()) {
              add(
                '${entry['الوصف'] ?? ''}'.trim(),
                flexDate('${entry['التاريخ'] ?? ''}'),
                '${unit.name} · ${item.title}',
                '${entry[_kMaintStateKey] ?? ''}'.trim(),
              );
            }
          } catch (_) {
            // سجل صيانة تالف لا يوقف مركز المتابعة.
          }
        }
        for (final entry in _entriesByAsset[item.id ?? ''] ?? const []) {
          if (entry.kind != ProjectAssetEntryRecord.kindMaintenance) continue;
          add(
            (entry.data['وصف العطل'] ?? entry.data['الوصف'] ?? '').trim(),
            flexDate(entry.data['تاريخ التنفيذ'] ?? entry.data['التاريخ']) ??
                flexDate(entry.data['تاريخ الطلب']),
            item.title,
            (entry.data[_kMaintStateKey] ?? '').trim(),
          );
        }
      }
      return sorted(items);
    }

    FollowUpGroup groupFor(
      String key,
      String title,
      IconData icon,
      Color color,
    ) {
      final scoped = assets
          .where((item) => item.category == key)
          .toList(growable: false);
      bool isDeposit(String kind) => kind == kPayKindDeposit;
      return FollowUpGroup(
        title: title,
        icon: icon,
        color: color,
        metrics: [
          const FollowUpMetric(
            label: 'مالية',
            icon: Icons.account_balance_wallet_outlined,
            entries: [],
            isHeading: true,
          ),
          FollowUpMetric(
            label: 'شيكات',
            icon: Icons.receipt_long_outlined,
            indented: true,
            entries: money(
              scoped,
              (method, kind) => !isDeposit(kind) && method == 'شيك',
            ),
          ),
          FollowUpMetric(
            label: 'كاش',
            icon: Icons.payments_outlined,
            indented: true,
            entries: money(
              scoped,
              (method, kind) => !isDeposit(kind) && method == 'كاش',
            ),
          ),
          FollowUpMetric(
            label: 'تحويلات مالية',
            icon: Icons.swap_horiz_rounded,
            indented: true,
            entries: money(
              scoped,
              (method, kind) => !isDeposit(kind) && method == 'تحويل بنكي',
            ),
          ),
          FollowUpMetric(
            label: 'تأمين',
            icon: Icons.shield_outlined,
            indented: true,
            entries: money(scoped, (method, kind) => isDeposit(kind)),
          ),
          FollowUpMetric(
            label: 'أخرى',
            icon: Icons.more_horiz_rounded,
            indented: true,
            entries: money(
              scoped,
              (method, kind) =>
                  !isDeposit(kind) &&
                  !const ['شيك', 'كاش', 'تحويل بنكي'].contains(method),
            ),
          ),
          const FollowUpMetric(
            label: 'المستندات',
            icon: Icons.folder_outlined,
            entries: [],
            isHeading: true,
          ),
          FollowUpMetric(
            label: 'وثائق شخصية',
            icon: Icons.badge_outlined,
            indented: true,
            entries: documents(scoped, true),
          ),
          FollowUpMetric(
            label: 'وثائق عامة',
            icon: Icons.description_outlined,
            indented: true,
            entries: documents(scoped, false),
          ),
          const FollowUpMetric(
            label: 'المتابعة والتخطيط',
            icon: Icons.event_note_outlined,
            entries: [],
            isHeading: true,
          ),
          // تحت «المتابعة والتخطيط»: مهمة، موعد، عادة يومية، تذكير، ملاحظات.
          for (final kind in _kFollowKinds)
            FollowUpMetric(
              label: kind,
              icon: _followKindIcon(kind),
              indented: true,
              entries: planning(scoped, kind),
            ),
          const FollowUpMetric(
            label: 'صيانة',
            icon: Icons.build_outlined,
            entries: [],
            isHeading: true,
          ),
          FollowUpMetric(
            label: 'صيانة',
            icon: Icons.build_rounded,
            indented: true,
            entries: maintenance(scoped),
          ),
          const FollowUpMetric(
            label: 'الطلبات',
            icon: Icons.hourglass_top_rounded,
            entries: [],
            isHeading: true,
          ),
          // لا طلبات موافقة في الأصول بعد — البند حاضر بصفره كما طُلب،
          // فتبقى البنية واحدة في كل الفئات.
          const FollowUpMetric(
            label: 'الطلبات',
            icon: Icons.pending_actions_outlined,
            indented: true,
            entries: [],
          ),
        ],
      );
    }

    return [
      groupFor(
        'real_estate',
        'العقارات',
        Icons.apartment_rounded,
        const Color(0xFF0A5A50),
      ),
      groupFor(
        'activity',
        'الأنشطة التجارية',
        Icons.storefront_rounded,
        const Color(0xFFCE8422),
      ),
      groupFor(
        'equipment',
        'المركبات ووسائل النقل',
        Icons.directions_car_rounded,
        const Color(0xFF0E7161),
      ),
    ];
  }

  /// مجاميع البنود الثلاثة من مجموعات مركز المتابعة نفسها، فتتطابق
  /// الأرقام بين البطاقة ونافذة «المزيد».
  ({int requests, int dues, int docs}) _followUpTotals(
    List<_AssetItem> assets,
  ) {
    var requests = 0;
    var dues = 0;
    var docs = 0;
    for (final group in _followUpGroups(assets)) {
      var section = '';
      for (final metric in group.metrics) {
        if (metric.isHeading) {
          section = metric.label;
          continue;
        }
        switch (section) {
          case 'مالية':
            dues += metric.count;
          case 'المستندات':
            docs += metric.count;
          case 'الطلبات':
            requests += metric.count;
        }
      }
    }
    return (requests: requests, dues: dues, docs: docs);
  }

  void _openFollowUpSheet(List<_AssetItem> assets) {
    showFollowUpCenterSheet(
      context: context,
      accent: const Color(0xFF0E7161),
      title: 'مركز المتابعة',
      groups: _followUpGroups(assets),
    );
  }

  /// يفتح أصلًا من سجله — للفرع من داخل نشاطه الرئيسي.
  Future<void> _openRecord(ProjectAssetRecord record) async {
    var index = _items.indexWhere((e) => e.id != null && e.id == record.id);
    if (index < 0) {
      setState(() => _items.add(_assetFromRecord(record)));
      index = _items.length - 1;
    }
    await _openDetails(_items[index]);
  }

  Future<void> _openDetails(_AssetItem item) {
    if (!PlanGate.canView(context, item.category)) return Future.value();
    return Navigator.of(context)
        .push(
      MaterialPageRoute(
        builder: (_) => ProjectAssetDetailsScreen(
          item: item,
          repository: _repository,
          onOpenRecord: _openRecord,
          onItemChanged: (updated) {
            final index = _items.indexWhere((e) => _sameAsset(e, updated));
            if (index == -1) return;
            // نُقل إلى سلة المهملات: يختفي من القائمة ويُحفظ بحالته الجديدة.
            if (updated.status == _kAssetTrashStatus) {
              setState(() => _items.removeAt(index));
              _updateAssetRemote(updated);
              return;
            }
            setState(() {
              _items[index] = updated;
              _items.sort(
                (a, b) => (b.isPinned ? 1 : 0).compareTo(a.isPinned ? 1 : 0),
              );
            });
            _updateAssetRemote(updated);
          },
          onItemDeleted: (deleted) {
            setState(() {
              _items.removeWhere((e) => _sameAsset(e, deleted));
            });
            _deleteAssetRemote(deleted);
          },
        ),
      ),
    )
        .then((_) {
      if (mounted) _loadContracts();
    });
  }

  bool _sameAsset(_AssetItem a, _AssetItem b) {
    if (a.id != null && b.id != null) return a.id == b.id;
    return a.title == b.title &&
        a.category == b.category &&
        a.locationOrType == b.locationOrType &&
        a.createdAt == b.createdAt;
  }

  // الفلتر الرئيسي: نفس قالب الشاشات الأربع، والأقسام وترتيبها مطابقة
  // لملف "فلاتر فوندلي" لصفحة العقارات والأنشطة والمعدات.
  void _openFilterSheet() {
    const labels = {
      'all': 'الكل',
      'real_estate': 'العقارات',
      'activity': 'الأنشطة التجارية',
      'equipment': 'المركبات ووسائل النقل',
    };
    showAppFilterSheet(
      context: context,
      title: 'العقارات والأنشطة والمركبات',
      accent: const Color(0xFF0E7161),
      values: _filter..mainCategory = labels[_selectedFilter] ?? 'الكل',
      mainCategories: labels.values.toList(growable: false),
      // العقارات ← أنواع العقار، الأنشطة ← تصنيفات النشاط، المركبات ←
      // أنواعها (برية وبحرية).
      subCategoriesFor: (main) => _assetSubCategories(
        labels.entries
            .firstWhere(
              (entry) => entry.value == main,
              orElse: () => const MapEntry('all', 'الكل'),
            )
            .key,
      ),
      sections: _assetFilterSections(labels[_selectedFilter] ?? 'الكل'),
      sectionsFor: _assetFilterSections,
      // المبلغ ▼: الاستحقاق أولًا ثم الترتيب والمخصص.
      amountOrders: const [
        'قريبة الاستحقاق',
        'مستحقة',
        'متأخرة',
        ...kAppFilterAmountOrders,
      ],
      // الحالة: نفس الالتزامات الشخصية + «تنتهي قريبًا» و«منتهية».
      selectStatuses: const [
        ...kAppFilterSelectStatuses,
        'ملغاة',
        'مسودة',
        'تنتهي قريبًا',
        'منتهية',
      ],
      delegatesLabel: 'التفويض',
      placeLabel: 'مواقع وأماكن',
      placeHint: 'اكتب اسم الموقع أو المكان',
      onApply: (values) => setState(() {
        final picked = labels.entries
            .firstWhere(
              (entry) => entry.value == values.mainCategory,
              orElse: () => const MapEntry('all', 'الكل'),
            )
            .key;
        // 'الكل' من نافذة التصفية = بلا فئة، فتعود شاشة «اختر إحدى الفئات».
        _selectedFilter =
            picked == 'all' || PlanAccess.blocksView(picked) ? '' : picked;
        _filter
          ..mainCategory = values.mainCategory
          ..subCategory = values.subCategory
          ..dateFrom = values.dateFrom
          ..dateTo = values.dateTo
          ..status = values.status
          ..amountFrom = values.amountFrom
          ..amountTo = values.amountTo
          ..amountShortcut = values.amountShortcut
          ..documentName = values.documentName
          ..documentState = values.documentState
          ..personName = values.personName
          ..personCategory = values.personCategory
          ..delegateName = values.delegateName
          ..placeName = values.placeName
          ..datePeriod = values.datePeriod
          ..currency = values.currency
          ..paymentMethod = values.paymentMethod
          ..debtDirection = values.debtDirection
          ..maintenanceBy = values.maintenanceBy
          ..chequeState = values.chequeState;
      }),
    );
  }

  /// أقسام الفلتر الكبير بترتيب الورقة. المركبات فئاتها الفرعية أنواعها.
  static List<AppFilterSection> _assetFilterSections(String main) => [
    AppFilterSection.mainCategory,
    if (main == 'العقارات' ||
        main == 'الأنشطة التجارية' ||
        main == 'المركبات ووسائل النقل')
      AppFilterSection.subCategory,
    AppFilterSection.statusSelect,
    AppFilterSection.amountSelect,
    // الشيكات تحت المبلغ: قريبة الاستحقاق / مستحقة / متأخرة.
    AppFilterSection.cheques,
    AppFilterSection.currency,
    AppFilterSection.paymentMethod,
    AppFilterSection.documentSelect,
    AppFilterSection.debt,
    AppFilterSection.maintenance,
    AppFilterSection.people,
    AppFilterSection.delegates,
    AppFilterSection.place,
  ];

  void _openAddEntrySheet() {
    // العقار أولًا لأنه أكثر ما يُضاف، وبلا كلمة «إضافة» في العناوين —
    // عنوان النافذة يقولها مرة واحدة. و«أخرى» حُذفت: نوع بلا نموذج ولا
    // حقول لا ينتج عنه سجل صالح.
    final typeOptions = <_AssetEntryTypeOption>[
      const _AssetEntryTypeOption(
        title: 'عقار',
        subtitle: 'عقار وأرض وغيرهم',
        icon: Icons.apartment_rounded,
        color: Color(0xFF34A894),
      ),
      // المركبات بجانب العقار، والنشاط التجاري تحتهما.
      const _AssetEntryTypeOption(
        title: 'المركبات ووسائل النقل',
        subtitle: 'مركبات برية وبحرية ومعدات',
        icon: Icons.directions_car_rounded,
        color: Color(0xFF0E7161),
      ),
      const _AssetEntryTypeOption(
        title: 'نشاط تجاري',
        subtitle: 'نشاط بيع أو خدمة',
        icon: Icons.storefront_rounded,
        color: Color(0xFFCE8422),
      ),
    ];
    // الفئة المخفية من «تخصيص الصفحات» لا تُضاف.
    typeOptions.removeWhere(
      (option) => _assetCategoryHidden(switch (option.title) {
        'عقار' => 'real_estate',
        'نشاط تجاري' => 'activity',
        _ => 'equipment',
      }),
    );

    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (context) {
        final maxSheetHeight = MediaQuery.of(context).size.height * 0.82;
        return SafeArea(
          top: false,
          child: Container(
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 18),
            decoration: const BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
            ),
            child: ConstrainedBox(
              constraints: BoxConstraints(maxHeight: maxSheetHeight),
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Center(
                      child: Container(
                        width: 44,
                        height: 4,
                        decoration: BoxDecoration(
                          color: const Color(0xFFD5DEDB),
                          borderRadius: BorderRadius.circular(999),
                        ),
                      ),
                    ),
                    const SizedBox(height: 14),
                    const Align(
                      alignment: Alignment.centerRight,
                      child: Text(
                        'اختيار نوع الإضافة',
                        style: TextStyle(
                          fontSize: 17,
                          fontWeight: FontWeight.w800,
                          color: Color(0xFF022E2A),
                        ),
                      ),
                    ),
                    const SizedBox(height: 5),
                    const Align(
                      alignment: Alignment.centerRight,
                      child: Text(
                        'اختر الفئة التي تريد إضافتها',
                        style: TextStyle(
                          fontSize: 11,
                          color: Color(0xFF5C6B68),
                        ),
                      ),
                    ),
                    const SizedBox(height: 12),
                    LayoutBuilder(
                      builder: (context, constraints) {
                        final cardWidth = (constraints.maxWidth - 8) / 2;
                        return Wrap(
                          // اتجاه صريح: العقار أول المربعات فيقع يمينًا،
                          // والنشاط بجانبه يسارًا، والمركبات تحت العقار.
                          textDirection: AppTr.uiDir,
                          spacing: 8,
                          runSpacing: 8,
                          children: List.generate(typeOptions.length, (index) {
                            final option = typeOptions[index];
                            return SizedBox(
                              width: cardWidth,
                              child: _AssetEntryActionCard(
                                key: ValueKey('projects-entry-type-$index'),
                                title: option.title,
                                subtitle: option.subtitle,
                                icon: option.icon,
                                color: option.color,
                                onTap: () {
                                  Navigator.of(context).pop();
                                  switch (option.title) {
                                    case 'عقار':
                                      _openAddPropertyWizard();
                                    case 'نشاط تجاري':
                                      _openAddBusinessActivity();
                                    case 'المركبات ووسائل النقل':
                                      _openAddEquipment();
                                  }
