                              // موقع ونوع وحالة وعقد، وبقية الفئات أقل.
                              stacked: item.category == 'real_estate',
                              // العقار: شاغر / مؤجر يسار السطر الثاني بلونه.
                              categoryStatus: item.category == 'real_estate'
                                  ? _assetStatusLabel(item)
                                  : null,
                              // محفوظ مسودة: «مسودة» بجانب «شاغر».
                              draftTag: _hasDraftContract(item) &&
                                      !_isCancelledAsset(item)
                                  ? 'مسودة'
                                  : null,
                              // سهم لليسار يوضح الدخول للعنصر.
                              showChevron: true,
                              onTap: () => _openDetails(item),
                            ),
                          ),
                        ),
                        if (_isLoadingRemote && _items.isEmpty)
                          const Padding(
                            padding: EdgeInsets.only(top: 28),
                            child: Center(
                              child: Text(
                                'جارٍ تحميل السجلات من الخادم...',
                                style: TextStyle(color: Color(0xFF5C6B68)),
                              ),
                            ),
                          )
                        else if (_items.isEmpty)
                          const Padding(
                            padding: EdgeInsets.symmetric(
                              horizontal: 20,
                              vertical: 28,
                            ),
                            child: Center(
                              child: Text(
                                'لا توجد عقارات أو أنشطة بعد.\n'
                                'اضغط «إضافة» لتسجيل أول أصل.',
                                textAlign: TextAlign.center,
                                style: TextStyle(
                                  height: 1.8,
                                  color: Color(0xFF5C6B68),
                                ),
                              ),
                            ),
                          )
                        else if (_selectedFilter.isEmpty)
                          _chooseCategoryHint()
                        else if (filtered.isEmpty)
                          const Padding(
                            padding: EdgeInsets.only(top: 24),
                            child: Center(
                              child: Text(
                                'لا توجد نتائج ضمن هذه التصفية',
                                style: TextStyle(color: Color(0xFF5C6B68)),
                              ),
                            ),
                          ),
                ]),
              ),
            ),
          ],
        ),
      ),
      ),
    );
  }

  /// نص مميّز مكان العناصر قبل اختيار أي فئة.
  Widget _chooseCategoryHint() => const _ChooseHint();

  /// العقارات والأنشطة المؤرشفة — مصدر زر «الأرشيف».
  List<_AssetItem> get _archivedAssets =>
      _items.where((asset) => asset.status == 'مؤرشف').toList(growable: false);

  /// نافذة الأرشيف: إلغاء الأرشفة تعيد الأصل نشطًا وتفكّ تجميده.
  Future<void> _openArchiveSheet() async {
    final changed = await showArchiveSheet(
      context,
      title: 'العقارات والأنشطة',
      entries: [
        for (final asset in _archivedAssets)
          ArchiveEntry(
            title: asset.title,
            subtitle: asset.subType,
            icon: Icons.business_center_rounded,
            onUnarchive: () async {
              final index = _items.indexWhere((e) => _sameAsset(e, asset));
              if (index == -1) return false;
              final updated = asset.copyWith(
                status: 'نشط',
                isFrozen: false,
              );
              setState(() => _items[index] = updated);
              _updateAssetRemote(updated);
              return true;
            },
          ),
      ],
    );
    if (!changed || !mounted) return;
    setState(() {});
  }

  void _openSmartCalendar() {
    Navigator.of(
      context,
    ).push(MaterialPageRoute(builder: (_) => const SmartCalendarScreen()));
  }
}

