  );

  /// نفس نموذج المتابعة والتخطيط في الالتزامات المشتركة، للإضافة والتعديل.
  Future<void> _openAssetFollowForm(
    String kind, {
    Map<String, String>? existing,
    int? editIndex,
  }) async {
    final values = await showSharedFollowUpForm(
      context,
      kind: kind,
      color: _followGroup.color,
      initial: existing == null
          ? const {}
          : {
              ...existing,
              'الوصف': existing['الوصف'] ?? existing['التفاصيل'] ?? '',
            },
    );
    if (values == null || !mounted) return;
    final data = <String, String>{
      ...?existing,
      ...values,
      'نوع المتابعة': kind,
      'التفاصيل': values['الوصف'] ?? '',
    };
    data['_reminder_id'] =
        existing?['_reminder_id'] ??
        'asset-entry-${DateTime.now().microsecondsSinceEpoch}';
    _persistEntry(_followGroup, data, editIndex: editIndex);
  }

  /// تفاصيل بند المتابعة كما أُدخل، مع فتح المرفق والتعديل والحذف.
  Future<void> _showAssetFollowDetails(Map<String, String> e, int index) async {
    final kind = _followKindOf(e['نوع المتابعة'] ?? '');
    final rows = <(String, String)>[
      ('النوع', kind),
      for (final key in const [
        'التاريخ',
        'الوقت',
        'الوصف',
        'التكرار',
        'وقت التذكير',
        'ملاحظات',
      ])
        if ((key == 'الوصف'
                ? (e['الوصف'] ?? e['التفاصيل'] ?? '')
                : (e[key] ?? ''))
            .trim()
            .isNotEmpty)
          (
            key,
            key == 'الوصف' ? (e['الوصف'] ?? e['التفاصيل'] ?? '') : e[key]!,
          ),
    ];
    final attachment = (e['المرفق'] ?? '').trim();
    final action = await showModalBottomSheet<String>(
      context: context,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(AppTheme.rCard),
        ),
      ),
      builder: (sheetContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: SafeArea(
          child: ListView(
            shrinkWrap: true,
            padding: const EdgeInsets.fromLTRB(16, 14, 16, 18),
            children: [
              Text(
                (e['العنوان'] ?? '').trim().isEmpty ? kind : e['العنوان']!,
                textAlign: TextAlign.right,
                style: const TextStyle(
                  fontSize: 15,
                  fontWeight: FontWeight.w900,
                  color: Color(0xFF022E2A),
                ),
              ),
              const SizedBox(height: 10),
              for (final row in rows)
                Padding(
                  padding: const EdgeInsets.only(bottom: 6),
                  child: Row(
                    textDirection: AppTr.uiDir,
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      SizedBox(
                        width: 90,
                        child: Text(
                          row.$1,
                          textAlign: TextAlign.right,
                          style: const TextStyle(
                            fontSize: 11.5,
                            fontWeight: FontWeight.w700,
                            color: Color(0xFF5C6B68),
                          ),
                        ),
                      ),
                      Expanded(
                        child: Text(
                          row.$2,
                          textAlign: TextAlign.right,
                          style: const TextStyle(
                            fontSize: 12.5,
                            fontWeight: FontWeight.w800,
                            color: Color(0xFF022E2A),
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              const SizedBox(height: 8),
              if (attachment.isNotEmpty)
                OutlinedButton.icon(
                  onPressed: () => Navigator.pop(sheetContext, 'file'),
                  icon: const Icon(Icons.attach_file_rounded, size: 18),
                  label: const Text('فتح المرفق'),
                ),
              const SizedBox(height: 8),
              Row(
                children: [
                  Expanded(
                    child: OutlinedButton.icon(
                      onPressed: () => Navigator.pop(sheetContext, 'edit'),
                      icon: const Icon(Icons.edit_outlined, size: 18),
                      label: const Text('تعديل'),
                    ),
                  ),
                  const SizedBox(width: 8),
                  Expanded(
                    child: OutlinedButton.icon(
                      style: OutlinedButton.styleFrom(
                        foregroundColor: AppTheme.danger,
                      ),
                      onPressed: () => Navigator.pop(sheetContext, 'delete'),
                      icon: const Icon(Icons.delete_outline_rounded, size: 18),
                      label: const Text('حذف'),
                    ),
                  ),
                ],
              ),
            ],
          ),
        ),
      ),
    );
    if (!mounted || action == null) return;
    switch (action) {
      case 'file':
        await _openAssetStoredFile(attachment);
      case 'edit':
        await _openAssetFollowForm(kind, existing: e, editIndex: index);
      case 'delete':
        final ok = await confirmAction(
          context,
          title: 'حذف $kind',
          message: 'هل أنت متأكد من حذف «${e['العنوان'] ?? kind}»؟',
          confirmLabel: 'حذف',
          danger: true,
        );
        if (ok && mounted) _deleteEntry(_followGroup, index);
    }
  }

  /// «المتابعة والتخطيط»: نفس قائمة الالتزامات المشتركة — صف لكل بند
  /// بنوعه وتاريخه، وسهم فلتر الأنواع في سطر العنوان.
  Widget _assetFollowUpsSection() {
    final all = _entriesByKind[_entryKindRental] ?? const <Map<String, String>>[];
    final rows = _assetFollowUps
        .where(
          (e) =>
              (_assetFollowKind == 'الكل' ||
                  _followKindOf(e['نوع المتابعة'] ?? '') ==
                      _assetFollowKind) &&
              followStatusMatches(_assetFollowStatus, e['التاريخ'] ?? ''),
        )
        .toList(growable: false);
    // فلترا النوع والحالة تحت العنوان مباشرة.
    final filters = FollowFiltersRow(
      kind: _assetFollowKind,
      status: _assetFollowStatus,
      onKind: (value) => setState(() => _assetFollowKind = value),
      onStatus: (value) => setState(() => _assetFollowStatus = value),
    );
    final note = _item.followupNote.trim();
    // ملاحظة الإنشاء التلقائية ليست متابعة كتبها المستخدم، فلا تُعرض.
    final showNote =
        (_assetFollowKind == 'الكل' || _assetFollowKind == 'ملاحظات') &&
        _assetFollowStatus == followStatusFilterOptions.first &&
        note.isNotEmpty &&
        note != 'لا توجد ملاحظات متابعة' &&
        note != 'تم الإنشاء وبانتظار استكمال البيانات';
    final color = _followGroup.color;
    if (rows.isEmpty && !showNote) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          filters,
          Padding(
            padding: const EdgeInsets.symmetric(vertical: 24),
            child: Center(
              child: Text(
                _assetFollowUps.isEmpty
                    ? 'لا يوجد أي بيانات حاليًا، اضغط + للإضافة'
                    : 'لا توجد متابعة أو تخطيط مطابق للفلتر',
                style: const TextStyle(color: Color(0xFF5C6B68)),
              ),
            ),
          ),
        ],
      );
    }
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        filters,
        if (showNote)
          Container(
            margin: const EdgeInsets.only(bottom: 8),
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.circular(12),
              border: Border.all(color: const Color(0xFFE4EAE8)),
            ),
            child: Text(
              note,
              textAlign: TextAlign.right,
              style: const TextStyle(
                fontSize: 11.5,
                height: 1.5,
                color: Color(0xFF2C3B38),
              ),
            ),
          ),
        for (final e in rows)
          Padding(
            padding: const EdgeInsets.only(bottom: 8),
            child: InkWell(
              borderRadius: BorderRadius.circular(12),
              onTap: () => _showAssetFollowDetails(e, all.indexOf(e)),
              child: Container(
                padding: const EdgeInsets.all(12),
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(12),
                  border: Border.all(color: const Color(0xFFE4EAE8)),
                ),
                child: Row(
                  children: [
                    Container(
                      width: 34,
                      height: 34,
                      decoration: BoxDecoration(
                        color: color.withValues(alpha: 0.1),
                        borderRadius: BorderRadius.circular(8),
                      ),
                      child: Icon(
                        _followKindIcon(_followKindOf(e['نوع المتابعة'] ?? '')),
                        size: 17,
                        color: color,
                      ),
                    ),
                    const SizedBox(width: 10),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            (e['العنوان'] ?? '').trim().isEmpty
                                ? _followKindOf(e['نوع المتابعة'] ?? '')
                                : e['العنوان']!,
                            maxLines: 3,
                            style: const TextStyle(
                              fontSize: 12,
                              fontWeight: FontWeight.w800,
                              color: Color(0xFF022E2A),
                            ),
                          ),
                          Text(
                            [
                              _followKindOf(e['نوع المتابعة'] ?? ''),
                              if ((e['التاريخ'] ?? '').trim().isNotEmpty)
                                e['التاريخ']!.trim(),
                              if ((e['ملاحظات'] ?? e['التفاصيل'] ?? '')
                                  .trim()
                                  .isNotEmpty)
                                (e['ملاحظات'] ?? e['التفاصيل'])!.trim(),
                            ].join(' · '),
                            maxLines: 3,
                            style: const TextStyle(
                              fontSize: 10,
                              color: Color(0xFF5C6B68),
                              fontWeight: FontWeight.w600,
                            ),
                          ),
                        ],
                      ),
                    ),
                    if ((e['المرفق'] ?? '').isNotEmpty)
                      Icon(Icons.attach_file_rounded, size: 16, color: color),
                  ],
                ),
              ),
            ),
          ),
      ],
    );
  }

  /// قيمة الحقل عند فتح النموذج: المحفوظة إن كانت ضمن الخيارات، وإلا
  /// ما يقابلها (نوع مستند قديم) أو أول خيار.
  static String _optionValueFor(_FieldDef field, String? saved) {
    final options = field.options;
    final value = (saved ?? '').trim();
    if (options == null) return saved ?? '';
    if (options.contains(value)) return value;
    if (field.label == 'نوع المستند' && value.isNotEmpty) {
      return _docTypeOfRaw(value);
    }
    return options.first;
  }

  /// نوع المستند كما يُعرض ويُفلتر: «عقد» → «عقود»، و«مستند» أو غير
  /// المعروف → «مستندات أخرى».
  static String _docTypeOfRaw(String raw) {
    final value = raw.trim();
    if (value == 'عقد' || value == 'عقود') return 'عقود';
    if (_kDocTypes.contains(value)) return value;
    return 'مستندات أخرى';
  }

  List<Map<String, String>> _docsOfType(String type) =>
      _filterEntries(_entriesByKind[_entryKindDocument] ?? const [])
          .where((doc) => _docTypeOfRaw(doc['نوع المستند'] ?? '') == type)
          .toList(growable: false);

  int get _docsFilteredCount {
    final all = _filterEntries(_entriesByKind[_entryKindDocument] ?? const []);
    final contracts =
        _filterEntries(_entriesByKind[_entryKindContract] ?? const []).length;
    if (_docTypeFilter == 'الكل') return all.length + contracts;
    return _docsOfType(_docTypeFilter).length +
        (_docTypeFilter == 'عقود' ? contracts : 0);
  }

