  /// قسم نوع واحد: عنوانه وعدده، ثم بنوده.
  Widget _docTypeSection(String type, {bool showTitle = true}) {
    final group = _groups.firstWhere((g) => g.kind == _entryKindDocument);
    final all = _entriesByKind[_entryKindDocument] ?? const <Map<String, String>>[];
    final shown = _docsOfType(type);
    final contractGroup =
        _groups.firstWhere((g) => g.kind == _entryKindContract);
    final contractsAll =
        _entriesByKind[_entryKindContract] ?? const <Map<String, String>>[];
    // العقود المسجلة قديمًا في مجموعة «العقود» تبقى ظاهرة داخل «عقود».
    final oldContracts = type == 'عقود'
        ? _filterEntries(contractsAll)
        : const <Map<String, String>>[];
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        if (showTitle)
          Padding(
            padding: const EdgeInsets.only(bottom: 6, top: 2),
            child: Row(
              textDirection: AppTr.uiDir,
              children: [
                Expanded(
                  child: Text(
                    type,
                    textAlign: AppTr.alignEnd,
                    style: const TextStyle(
                      fontSize: 13,
                      fontWeight: FontWeight.w900,
                      color: AppTheme.title,
                    ),
                  ),
                ),
                Text(
                  '${shown.length + oldContracts.length}',
                  style: const TextStyle(
                    fontSize: 11,
                    fontWeight: FontWeight.w800,
                    color: AppTheme.muted,
                  ),
                ),
              ],
            ),
          ),
        if (shown.isNotEmpty || oldContracts.isEmpty)
          _EntryGroupCard(
            showHeader: false,
            emptyText: 'لا توجد «$type» بعد — اضغط + للإضافة',
            group: group,
            entries: shown,
            onAdd: () => _openActionForm(group),
            onEdit: (index) {
              final original = all.indexOf(shown[index]);
              if (original < 0) return;
              _openActionForm(
                group,
                existing: all[original],
                editIndex: original,
              );
            },
            onOpenFile: _openAssetStoredFile,
            onDelete: (index) {
              final original = all.indexOf(shown[index]);
              if (original < 0) return;
              _deleteEntry(group, original);
            },
          ),
        if (oldContracts.isNotEmpty) ...[
          if (shown.isNotEmpty) const SizedBox(height: 8),
          _EntryGroupCard(
            showHeader: false,
            group: contractGroup,
            entries: oldContracts,
            onAdd: () => _openActionForm(group),
            onEdit: (index) {
              final original = contractsAll.indexOf(oldContracts[index]);
              if (original < 0) return;
              _openActionForm(
                contractGroup,
                existing: contractsAll[original],
                editIndex: original,
              );
            },
            onOpenFile: _openAssetStoredFile,
            onDelete: (index) {
              final original = contractsAll.indexOf(oldContracts[index]);
              if (original < 0) return;
              _deleteEntry(contractGroup, original);
            },
          ),
        ],
      ],
    );
  }

  /// «المستندات»: مع «الكل» كل نوع في مكانه بعنوانه، ومع نوع محدد بنوده فقط.
  Widget _documentsByType() {
    if (_docTypeFilter != 'الكل') {
      return _docTypeSection(_docTypeFilter, showTitle: false);
    }
    final contracts =
        _filterEntries(_entriesByKind[_entryKindContract] ?? const []);
    final types = _kDocTypes
        .where(
          (type) =>
              _docsOfType(type).isNotEmpty ||
              (type == 'عقود' && contracts.isNotEmpty),
        )
        .toList(growable: false);
    if (types.isEmpty) {
      return const _DetailHintCard(
        message: 'لا توجد مستندات بعد — اضغط + للإضافة.',
      );
    }
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        for (var i = 0; i < types.length; i++) ...[
          if (i > 0) const SizedBox(height: 14),
          _docTypeSection(types[i]),
        ],
      ],
    );
  }

  static const List<String> _entryPeriodOptions = [
    'الكل',
    'هذا الشهر',
    'آخر 3 أشهر',
    'هذه السنة',
    'مخصص',
  ];

  /// الفترة المختارة مع «مخصص».
  DateTimeRange? _entryCustomRange;

  String get _entryPeriodLabel {
    final range = _entryCustomRange;
    if (_entryPeriodFilter != 'مخصص' || range == null) {
      return _entryPeriodFilter;
    }
    return '${formatDayMonthYear(range.start)} – '
        '${formatDayMonthYear(range.end)}';
  }

  Future<void> _pickEntryPeriod(String value) async {
    if (value != 'مخصص') {
      setState(() => _entryPeriodFilter = value);
      return;
    }
    final now = DateTime.now();
    final picked = await showDateRangePicker(
      context: context,
      firstDate: DateTime(2015),
      lastDate: DateTime(2070),
      initialDateRange: _entryCustomRange ??
          DateTimeRange(
            start: DateTime(now.year, now.month, 1),
            end: DateTime(now.year, now.month, now.day),
          ),
      helpText: AppTr.tr('اختر الفترة'),
    );
    if (picked == null || !mounted) return;
    setState(() {
      _entryCustomRange = picked;
      _entryPeriodFilter = 'مخصص';
    });
  }

  /// بنود النوع بعد البحث وفلتر الفترة (نفس الخرائط الأصلية، لا نسخ).
  List<Map<String, String>> _financeEntries(String kind) {
    final dateKey = kind == _entryKindRevenue ? 'تاريخ الإيراد' : 'تاريخ المصروف';
    final all = _filterEntries(_entriesByKind[kind] ?? const []);
    if (_entryPeriodFilter == 'الكل') return all;
    final now = DateTime.now();
    DateTime from;
    DateTime? to;
    if (_entryPeriodFilter == 'مخصص') {
      final range = _entryCustomRange;
      if (range == null) return all;
      from = DateTime(range.start.year, range.start.month, range.start.day);
      to = DateTime(range.end.year, range.end.month, range.end.day, 23, 59);
    } else {
      from = switch (_entryPeriodFilter) {
        'هذا الشهر' => DateTime(now.year, now.month, 1),
        'آخر 3 أشهر' => DateTime(now.year, now.month - 2, 1),
        _ => DateTime(now.year, 1, 1),
      };
    }
    return all.where((entry) {
      final date = _parseFlexibleDate((entry[dateKey] ?? '').trim());
      if (date == null || date.isBefore(from)) return false;
      return to == null || !date.isAfter(to);
    }).toList(growable: false);
  }

  double _financeTotal(List<Map<String, String>> entries) {
    var total = 0.0;
    for (final entry in entries) {
      total +=
          double.tryParse(
            (entry['المبلغ'] ?? '').replaceAll(',', '').trim(),
          ) ??
          0;
    }
    return total;
  }

