  /// وحدة مخزَّنة «مؤجرة» وليس لها أي عقد (كانت شارة الحالة تقلبها بلمسة
  /// بلا عقد): تعود «شاغرة»، فيصحّ وضع العقار («مؤجر جزئيًا») وأرقامه.
  void _healRentedWithoutContract(List<PropertyUnitContractRecord> contracts) {
    final keys = {for (final contract in contracts) contract.unitKey};
    var changed = false;
    final units = <_PropertyUnit>[];
    for (final unit in _item.units) {
      if (unit.status == 'مؤجرة' && !keys.contains(unit.unitKey)) {
        changed = true;
        units.add(unit.copyWith(status: 'شاغرة'));
      } else {
        units.add(unit);
      }
    }
    if (changed) _updateItem(_item.copyWith(units: units));
  }

  Future<void> _loadUnitContractsFromRemote() async {
    final repository = widget.repository;
    final assetId = widget.item.id;
    if (repository == null || assetId == null || assetId.isEmpty) return;
    try {
      final contracts = await repository.fetchUnitContracts(assetId);
      if (!mounted) return;
      setState(() => _unitContracts = contracts);
      _healRentedWithoutContract(contracts);
      await _loadPropertyPayments();
      await _loadPropertyUnitTransactions();
    } catch (_) {
      // تُترك القائمة فارغة عند الفشل بدل عرض خطأ يعطّل تبويب الوحدات كاملاً.
    }
  }

  /// دخل ومصاريف الوحدات (المسجّلة داخل كل وحدة) — لصافي ربح العقار.
  List<PropertyUnitTransactionRecord> _unitTransactions = const [];

  Future<void> _loadPropertyUnitTransactions() async {
    final repository = widget.repository;
    final assetId = widget.item.id;
    if (repository == null || assetId == null || assetId.isEmpty) return;
    try {
      final rows = await repository.fetchUnitTransactions(assetId);
      if (!mounted) return;
      setState(() => _unitTransactions = rows);
    } catch (_) {
      // جدول الحركات قد لا يكون موجودًا: يُحسب الصافي بلا حركات الوحدات.
    }
  }

  // ---------------- صافي الربح ----------------

  static double _amountOf(String? raw) =>
      double.tryParse(
        (raw ?? '').replaceAll(',', '').replaceAll('٬', '').trim(),
      ) ??
      0;

  /// كل ما دخل من العقار وكل ما خرج منه كمصروف، بنودًا مفصّلة.
  ///
  /// الفعلي: المحصَّل فعلًا ناقص المصروف حتى اليوم. المتوقع: يضاف إليه ما
  /// بقي للتحصيل وما هو مجدول من مصاريف قادمة. التأمينات لا تُحسب دخلًا
  /// لأنها تُرد للمستأجر، والصيانة التي على المستأجر لا تُحسب مصروفًا.
  ({
    double rent,
    double fees,
    double propertyIncome,
    double unitsIncome,
    double propertyExpenses,
    double unitsExpenses,
    double propertyMaintenance,
    double unitsMaintenance,
    double deposits,
    double toCollect,
    double upcomingExpenses,
    double leasePaid,
  })
  _netProfitParts() {
    final today = DateUtils.dateOnly(DateTime.now());
    bool future(DateTime? date) =>
        date != null && DateUtils.dateOnly(date).isAfter(today);
    var rent = 0.0, fees = 0.0, deposits = 0.0, toCollect = 0.0;
    // النشاط التجاري مستأجر: دفعات عقده «عليه» — مصروف لا دخل.
    var leasePaid = 0.0, leaseToPay = 0.0;
    final payer = _item.category == 'activity';
    for (final entry in _propertyPayments) {
      if (payer) {
        final payment = entry.payment;
        final kind = decodePayExtra(payment.notes)[kPayKind] ?? kPayKindRent;
        if (kind == kPayKindDeposit) {
          deposits += payment.amountPaid;
          continue;
        }
        leasePaid += payment.amountPaid;
        leaseToPay += payRemaining(payment);
        continue;
      }
      final payment = entry.payment;
      final kind = decodePayExtra(payment.notes)[kPayKind] ?? kPayKindRent;
      if (kind == kPayKindDeposit) {
        deposits += payment.amountPaid;
        continue;
      }
      if (kind == kPayKindFee) {
        fees += payment.amountPaid;
      } else {
        rent += payment.amountPaid;
      }
      final left = payRemaining(payment);
      if (left > 0.009) toCollect += left;
    }
    var propertyIncome = 0.0, propertyExpenses = 0.0, upcoming = 0.0;
    for (final row in _entriesByKind[_entryKindRevenue] ?? const []) {
      propertyIncome += _amountOf(row['المبلغ']);
    }
    for (final row in _entriesByKind[_entryKindExpense] ?? const []) {
      final amount = _amountOf(row['المبلغ']);
      if (future(_parseFlexibleDate((row['تاريخ المصروف'] ?? '').trim()))) {
        upcoming += amount;
      } else {
        propertyExpenses += amount;
      }
    }
    var unitsIncome = 0.0, unitsExpenses = 0.0;
    for (final t in _unitTransactions) {
      if (t.isIncome) {
        unitsIncome += t.amount;
      } else if (future(t.occurredOn)) {
        upcoming += t.amount;
      } else {
        unitsExpenses += t.amount;
      }
    }
    // الصيانة على المؤجر وحدها مصروف عليه.
    var propertyMaintenance = 0.0, unitsMaintenance = 0.0;
    for (final raw in _entriesByKind[_entryKindMaintenance] ?? const []) {
      final row = _maintenanceCompat(raw);
      if ((row['النوع'] ?? '') == 'على المستأجر') continue;
      final amount = _amountOf(row['المبلغ']);
      if (future(_parseFlexibleDate((row['التاريخ'] ?? '').trim()))) {
        upcoming += amount;
      } else {
        propertyMaintenance += amount;
      }
    }
    for (final unit in _item.units) {
      final raw = (unit.extras['سجل الصيانة'] ?? '').trim();
      if (raw.isEmpty) continue;
      try {
        final decoded = jsonDecode(raw);
        if (decoded is! List) continue;
        for (final item in decoded.whereType<Map>()) {
          if ('${item['النوع'] ?? ''}' == 'على المستأجر') continue;
          final amount = _amountOf('${item['المبلغ'] ?? ''}');
          if (future(_parseFlexibleDate('${item['التاريخ'] ?? ''}'.trim()))) {
            upcoming += amount;
          } else {
            unitsMaintenance += amount;
          }
        }
      } catch (_) {
        // سجل صيانة تالف لا يوقف الحساب.
      }
    }
    return (
      rent: rent,
      fees: fees,
      propertyIncome: propertyIncome,
      unitsIncome: unitsIncome,
      propertyExpenses: propertyExpenses,
      unitsExpenses: unitsExpenses,
      propertyMaintenance: propertyMaintenance,
      unitsMaintenance: unitsMaintenance,
      deposits: deposits,
      toCollect: toCollect,
      upcomingExpenses: upcoming + leaseToPay,
      leasePaid: leasePaid,
    );
  }

  String _netMoney(double value) =>
      '${formatMoneyValue(value)} ${AppSettings.currencySuffix}';

  /// بطاقة «صافي الربح» المميزة أعلى «الحركات المالية».
  Widget _netProfitCard() {
    final p = _netProfitParts();
    final income = p.rent + p.fees + p.propertyIncome + p.unitsIncome;
    final expenses = p.propertyExpenses +
        p.unitsExpenses +
        p.propertyMaintenance +
        p.unitsMaintenance +
        p.leasePaid;
    final net = income - expenses;
    final loss = net < 0;
    final margin = income <= 0 ? 0.0 : (net / income * 100);
    final share = income + expenses <= 0 ? 0.5 : income / (income + expenses);
    const deep = Color(0xFF0A5A50);
    // بطاقة مدمجة (عقار ونشاط ومركبات): العنوان والصافي في سطر، ثم شريط
