  /// يجمع دفعات كل عقود الوحدات في قائمة واحدة مرتّبة بتاريخ الاستحقاق،
  /// مع ترقيم كل دفعة داخل عقدها («الدفعة 2 من 4»).
  Future<void> _loadPropertyPayments() async {
    final repository = widget.repository;
    if (repository == null) return;
    final collected = <RentPaymentEntry>[];
    for (final contract in _unitContracts) {
      final id = contract.id;
      if (id == null || id.isEmpty) continue;
      try {
        var payments = await repository.fetchUnitPayments(id);
        // دفعات العقود المحفوظة قبل الربط تُولَّد هنا أيضًا، فيرى العقار
        // مستحقات وحداته دون أن يُفتح كل منها على حدة. عقود الآليات
        // دفعاتها مضافة مباشرة، فلا تُطابَق مع نموذج عقد الإيجار.
        // «التأجير المباشر» دفعاته تُسجَّل يدويًا، فلا يُطابَق مع عقد.
        if (contract.unitKey != _kEquipWalkInKey &&
            (contract.unitKey != _kEquipUnitKey ||
                _isLeaseContract(contract)) &&
            await syncLeasePaymentRecords(
          repository: repository,
          contract: contract,
          existing: payments,
        )) {
          payments = await repository.fetchUnitPayments(id);
        }
        // عقد مُغلق: ما سُوّي أو استُحق بعد إغلاقه لا يظهر؛ وما استُحق قبله
        // ولم يُسوَّ يبقى مستحقًا يُتابَع.
        payments = payments
            .where((p) => !paymentWaivedByClosure(contract, p))
            .toList();
        for (var i = 0; i < payments.length; i++) {
          collected.add(
            RentPaymentEntry(
              contract: contract,
              payment: payments[i],
              unitName: contract.unitName ?? 'وحدة',
              order: i + 1,
              totalInContract: payments.length,
            ),
          );
        }
      } catch (_) {
        // عقد تعذّرت قراءة دفعاته لا يمنع عرض بقية العقود.
      }
    }
    collected.sort((a, b) {
      final da = a.payment.dueDate;
      final db = b.payment.dueDate;
      if (da == null && db == null) return 0;
      if (da == null) return 1;
      if (db == null) return -1;
      return da.compareTo(db);
    });
    if (!mounted) return;
    setState(() => _propertyPayments = collected);
  }

  /// مستحقات وحدة بعينها التي تحتاج متابعة.
  ///
  /// تُقرأ من جدول الدفعات مباشرة: كل دفعة حالتها «مستحقة» أو «متأخرة»
  /// في أي عقد يخصّ هذه الوحدة. الباقي = المستحق ناقص المدفوع، فدفعة
  /// سُدّدت جزئيًا تظهر ببقيّتها لا بكامل قيمتها.
  String _unitDuesNote(_PropertyUnit unit) => _unitsDuesNote([unit]);

  /// كلمة التفويض تحت حالة الوحدة: «مفوَّض أنا بإدارته» إن فوّضني صاحب
  /// العقار، و«فوّضت غيري بإدارته» إن فوّضت هذه الوحدة لغيري.
  String _unitDelegationLabel(_PropertyUnit unit, int index) {
    if (DelegatedAssets.isDelegated(_item.id)) return 'مفوَّض أنا بإدارته';
    return OutgoingDelegations.unitNoteOf(
          _item.id,
          number: unit.unitNumber,
          name: unit.name,
          index: index,
        ).isEmpty
        ? ''
        : 'فوّضت غيري بإدارته';
  }

  /// حالة بطاقة الوحدة: عقد انتهى بتاريخه ولم يُلغَ = «منتهي العقد» (مثل
  /// رأس الوحدة) — تصبح «شاغرة» بعد إلغائه.
  String _unitDisplayStatus(_PropertyUnit unit) {
    final status = _effectiveUnitStatus(unit);
    if (status != 'شاغرة') return status;
    final endedOpen = _unitContracts.any(
      (c) =>
          c.unitKey == unit.unitKey &&
          c.status != PropertyUnitContractRecord.statusPending &&
          _contractEndedOpen(c),
    );
    return endedOpen ? 'منتهي العقد' : status;
  }

  /// مستحقات مجموعة وحدات (عقد متعدد الوحدات) — بنفس صيغة الوحدة.
  String _unitsDuesNote(List<_PropertyUnit> units) {
    final keys = {for (final u in units) u.unitKey};
    var count = 0;
    var remaining = 0.0;
    for (final entry in _propertyPayments) {
      if (!keys.contains(entry.contract.unitKey)) continue;
      // مستحقات مستأجر سابق لا تُكتب على البطاقة (مكانها مركز المتابعة
      // والسجل التاريخي).
      if (_isOldDue(entry)) continue;
      if (!_isCurrentDue(entry)) continue;
      count++;
      final due = entry.payment.amountDue - entry.payment.amountPaid;
      if (due > 0) remaining += due;
    }
    if (count == 0) return '';
    final amount = remaining > 0
        ? ' (${formatMoneyValue(remaining)} ${AppSettings.currencySuffix})'
        : '';
    return 'مستحقات: $count دفعة$amount';
  }

  /// مستحق يحتاج متابعة على عقد قائم (غير ملغي ولا منتهٍ).
  bool _isCurrentDue(RentPaymentEntry entry) {
    if (_contractClosed(entry.contract)) return false;
    // المسودة لم تُعتمد بعد: دفعاتها ليست مستحقة.
    if (entry.contract.status == PropertyUnitContractRecord.statusPending) {
      return false;
    }
    final label = rentPaymentStatusLabel(entry.payment);
    return label == 'مستحقة' || label == 'متأخرة';
  }

  /// «مستحقات قديمة»: باقية على عقد أُلغي أو انتهى (مستأجر سابق) ولم
  /// تُسوَّ — مكانها «السجل التاريخي»، وتُعدّ هنا للمتابعة.
  bool _isOldDue(RentPaymentEntry entry) =>
      _contractClosed(entry.contract) &&
      payRemaining(entry.payment) > 0 &&
      !LeaseContractData.isSettled(entry.contract.notes) &&
      !paymentWaivedByClosure(entry.contract, entry.payment);

  /// عدد الدفعات التي تحتاج متابعة (مستحقة أو متأخرة) على العقد القائم.
  int get _dueFollowUpCount =>
      _propertyPayments.where(_isCurrentDue).length;

  /// عدد «المستحقات القديمة».
  int get _oldDuesCount => _propertyPayments.where(_isOldDue).length;

  /// المستندات التي تحتاج متابعة: انتهت أو تنتهي خلال 30 يومًا.
  List<Map<String, String>> get _docsFollowUp {
    final docs = _entriesByKind[_entryKindDocument] ?? const [];
    final now = DateTime.now();
    return docs.where((doc) {
      final raw = (doc['تاريخ الانتهاء'] ?? '').trim();
      if (raw.isEmpty) return false;
      final parsed = _parseFlexibleDate(raw);
      if (parsed == null) return false;
      // بالتاريخ لا بالساعة (كان يُدخل ما ينتهي بعد 31 يومًا).
      return DateUtils.dateOnly(parsed)
              .difference(DateUtils.dateOnly(now))
              .inDays <=
          30;
    }).toList(growable: false);
  }

  /// عقود تحتاج متابعة: انتهى تاريخها ولم تُلغَ أو تُجدَّد، أو تنتهي خلال
  /// 30 يومًا — (العقد، حالته).
  List<(PropertyUnitContractRecord, String)> get _contractsFollowUp {
    final today = DateUtils.dateOnly(DateTime.now());
    final groups = <String>{};
    final out = <(PropertyUnitContractRecord, String)>[];
    for (final c in _unitContracts) {
      if (c.status == PropertyUnitContractRecord.statusPending ||
          _contractClosed(c)) {
        continue;
      }
      final end = c.endDate;
      if (end == null) continue;
      // العقد متعدد الوحدات يُذكر مرة واحدة.
      final group = (c.groupKey ?? '').trim();
      if (group.isNotEmpty && !groups.add(group)) continue;
      final days = DateUtils.dateOnly(end).difference(today).inDays;
      if (days < 0) {
        out.add((c, 'منتهي — يحتاج تجديدًا أو إلغاء'));
      } else if (days <= 30) {
        out.add((c, 'قارب على الانتهاء'));
      }
    }
    return out;
  }

  /// وحدات عليها صيانة مفتوحة.
  List<_PropertyUnit> get _maintFollowUp =>
      _item.units.where(_unitMaintOpen).toList(growable: false);

  /// عدد ما يحتاج متابعة من العقود والصيانة (لشريط مركز المتابعة).
  int get _otherFollowUpCount =>
      _contractsFollowUp.length + _maintFollowUp.length;

  static DateTime? _parseFlexibleDate(String raw) {
    final direct = DateTime.tryParse(raw);
    if (direct != null) return direct;
    final parts = raw.split(RegExp(r'[/\-]'));
    if (parts.length != 3) return null;
    final a = int.tryParse(parts[0]);
    final b = int.tryParse(parts[1]);
    final c = int.tryParse(parts[2]);
    if (a == null || b == null || c == null) return null;
    if (parts[0].length == 4) return DateTime(a, b, c);
    return DateTime(c, b, a);
  }

  /// يفتح ما يحتاج متابعة: الدفعات المستحقة/المتأخرة والمستندات القريبة.
  void _openAssetFollowUpBox() {
    final dues = _propertyPayments.where(_isCurrentDue).toList(growable: false);
    final oldDues =
        _propertyPayments.where(_isOldDue).toList(growable: false);
    final docs = _docsFollowUp;
    final contracts = _contractsFollowUp;
    final maint = _maintFollowUp;
    Widget row(String text) => Container(
      margin: const EdgeInsets.only(bottom: 6),
      padding: const EdgeInsets.all(10),
      decoration: BoxDecoration(
        color: AppTheme.paper,
        borderRadius: BorderRadius.circular(AppTheme.rInner),
