      child: Text(
        text,
        textAlign: TextAlign.right,
        style: const TextStyle(
          fontSize: 11,
          height: 1.5,
          fontWeight: FontWeight.w700,
          color: Color(0xFF022E2A),
        ),
      ),
    );
    Widget head(String text) => Padding(
      padding: const EdgeInsets.only(top: 14, bottom: 6),
      child: Text(
        text,
        textAlign: TextAlign.right,
        style: const TextStyle(
          fontSize: 12,
          fontWeight: FontWeight.w900,
          color: Color(0xFFA6691A),
        ),
      ),
    );
    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(AppTheme.rCard)),
      ),
      builder: (sheetContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: DraggableScrollableSheet(
          expand: false,
          initialChildSize: 0.6,
          maxChildSize: 0.9,
          builder: (context, controller) => ListView(
            controller: controller,
            padding: const EdgeInsets.fromLTRB(16, 14, 16, 24),
            children: [
              const Text(
                'ما يحتاج متابعة',
                textAlign: TextAlign.right,
                style: TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w900,
                  color: Color(0xFF022E2A),
                ),
              ),
              const SizedBox(height: 12),
              Text(
                'مستحقات (${dues.length})',
                textAlign: TextAlign.right,
                style: const TextStyle(
                  fontSize: 12,
                  fontWeight: FontWeight.w900,
                  color: Color(0xFFA6691A),
                ),
              ),
              const SizedBox(height: 6),
              if (dues.isEmpty)
                const Text(
                  'لا توجد مستحقات قريبة.',
                  textAlign: TextAlign.right,
                  style: TextStyle(fontSize: 11, color: Color(0xFF5C6B68)),
                )
              else
                for (final entry in dues)
                  Container(
                    margin: const EdgeInsets.only(bottom: 6),
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: AppTheme.paper,
                      borderRadius: BorderRadius.circular(AppTheme.rInner),
                      border: Border.all(color: AppTheme.hairline),
                    ),
                    child: Text(
