              // «السجل التاريخي».
              if (oldDues.isNotEmpty) ...[
                const SizedBox(height: 14),
                Text(
                  'مستحقات قديمة (${oldDues.length})',
                  textAlign: TextAlign.right,
                  style: const TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w900,
                    color: Color(0xFF8C3A32),
                  ),
                ),
                const SizedBox(height: 4),
                const Text(
                  'على عقود ملغاة أو منتهية — تجدها مفصّلة وتسدّدها من '
                  '«السجل التاريخي».',
                  textAlign: TextAlign.right,
                  style: TextStyle(
                    fontSize: 10.5,
                    height: 1.5,
                    fontWeight: FontWeight.w600,
                    color: Color(0xFF5C6B68),
                  ),
                ),
                const SizedBox(height: 6),
                for (final entry in oldDues)
                  Container(
                    margin: const EdgeInsets.only(bottom: 6),
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: AppTheme.paper,
                      borderRadius: BorderRadius.circular(AppTheme.rInner),
                      border: Border.all(color: AppTheme.hairline),
                    ),
                    child: Text(
                      '${entry.unitName} · '
                      '${(entry.contract.tenantName ?? '').trim()} · '
                      'المتبقي ${payMoney(payRemaining(entry.payment))} · '
                      'استحقاق ${fmtPayDate(entry.payment.dueDate)}',
                      textAlign: TextAlign.right,
                      style: const TextStyle(
                        fontSize: 11,
                        height: 1.5,
                        fontWeight: FontWeight.w700,
                        color: Color(0xFF022E2A),
                      ),
                    ),
                  ),
              ],
              const SizedBox(height: 14),
              Text(
                'مستندات (${docs.length})',
                textAlign: TextAlign.right,
                style: const TextStyle(
                  fontSize: 12,
                  fontWeight: FontWeight.w900,
                  color: Color(0xFFA6691A),
                ),
              ),
              const SizedBox(height: 6),
              if (docs.isEmpty)
