  /// النشاط والمركبات: الدفعات الإيجارية تُسجَّل في «إدارة النشاط» /
  /// «إدارة التأجير» — بلا دفعات يظهر تنبيه يدلّ عليها.
  Future<void> _rentPaymentsHint() async {
    final activity = _item.category == 'activity';
    final place = activity ? 'إدارة النشاط' : 'إدارة التأجير';
    final go = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: AlertDialog(
          title: const Text('تنبيه'),
          content: Text(
            activity
                ? 'لإضافة الدفعات الإيجارية اذهب إلى «إدارة النشاط»: سجّل '
                      'عقد الإيجار، وأضف الدفعات فيه.'
                : 'لإضافة الدفعات الإيجارية اذهب إلى «إدارة التأجير»: سجّل '
                      'عقد التأجير، وأضف الدفعات فيه.',
            textAlign: TextAlign.right,
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(false),
              child: const Text('إغلاق'),
            ),
            FilledButton(
              onPressed: () => Navigator.of(dialogContext).pop(true),
              child: Text('الذهاب إلى $place'),
            ),
          ],
        ),
      ),
    );
    if (go != true || !mounted) return;
    setState(() {
      _selectedTab = activity
          ? (_isBranchActivity ? 1 : _kActivityLeaseTab)
          : 1;
    });
  }

