  /// أحدث عقد نشط (غير منتهٍ) لوحدة معيّنة، إن وُجد.
  PropertyUnitContractRecord? _activeContractForUnit(String unitKey) {
    for (final c in _unitContracts) {
      if (c.unitKey == unitKey && !_contractClosed(c)) {
        return c;
      }
    }
    return null;
  }

  /// عقد نشط "تمثيلي" يُعرض على خريطة رأس العقار — يُستخدم فقط عندما يكون
  /// العقار نفسه إيجارًا من الباطن (isSublease)، لعرض لمحة سريعة عن أحد
  /// عقود الوحدات النشطة فيه (بيانات حقيقية من قاعدة البيانات، وليست بيانات
  /// وهمية).
  PropertyUnitContractRecord? get _representativeContract {
    if (!_item.isSublease) return null;
    for (final c in _unitContracts) {
      if (!_contractClosed(c)) return c;
    }
    return null;
  }

  /// يجمع الوحدات المشتركة في نفس عقد "متعدد الوحدات" (group_key واحد)
  /// لعرضها كبطاقة واحدة موحّدة بدل بطاقة منفصلة لكل وحدة.
  Map<String, List<_PropertyUnit>> _multiUnitGroups() {
    final groups = <String, List<_PropertyUnit>>{};
    for (final unit in _item.units) {
      final contract = _activeContractForUnit(unit.unitKey);
      if (contract?.groupKey == null) continue;
      groups.putIfAbsent(contract!.groupKey!, () => []).add(unit);
    }
    return groups;
  }

  Future<void> _openMultiUnitContractForm() async {
    final assetId = _item.id;
    final repository = widget.repository;
    if (assetId == null || repository == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('يجب حفظ العقار أولاً قبل إنشاء عقد متعدد الوحدات')),
      );
      return;
    }
    final vacantUnits = _item.units
        .where((u) => _activeContractForUnit(u.unitKey) == null)
        .toList();
    if (vacantUnits.length < 2) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('يلزم وجود وحدتين شاغرتين على الأقل لإنشاء عقد متعدد الوحدات'),
        ),
      );
      return;
    }
    final saved = await Navigator.of(context).push<PropertyUnitContractRecord>(
      MaterialPageRoute(
        builder: (_) => LeaseContractFormScreen(
          repository: repository,
          assetId: assetId,
          unitKey: '',
          unitName: '',
          propertyTitle: _item.title,
          propertyType: _assetPropertyType(_item),
          propertyMeta: _item.propertyMeta,
          leaseType: PropertyUnitContractRecord.leaseTypeMultiUnit,
          title: 'عقد متعدد الوحدات',
          unitChoices: [
            for (final unit in vacantUnits) (key: unit.unitKey, name: unit.name),
          ],
        ),
      ),
    );
    if (saved == null || !mounted) return;
    await _loadUnitContractsFromRemote();
    if (!mounted) return;
    // الوحدات المشمولة وحدها تصير مؤجرة (أو مسودة إن حُفظ العقد مسودة).
    final group = saved.groupKey;
    final keys = <String>{
      for (final c in _unitContracts)
        if (group != null && c.groupKey == group) c.unitKey,
      saved.unitKey,
    };
    final units = List<_PropertyUnit>.from(_item.units);
    for (var i = 0; i < units.length; i++) {
      if (keys.contains(units[i].unitKey)) {
        units[i] = units[i].copyWith(
          status: saved.status == PropertyUnitContractRecord.statusPending
              ? 'مسودة'
              : 'مؤجرة',
        );
      }
    }
    _updateItem(_item.copyWith(units: units));
  }

  Future<void> _loadEntriesFromRemote() async {
    final repository = widget.repository;
    final assetId = widget.item.id;
    if (repository == null || assetId == null || assetId.isEmpty) return;
    try {
      final entries = await repository.fetchEntries(assetId);
      if (!mounted) return;
      final grouped = <String, List<Map<String, String>>>{
        for (final group in _groups) group.kind: [],
      };
      for (final entry in entries) {
        final data = Map<String, String>.from(entry.data);
        if (entry.id != null) data['_id'] = entry.id!;
        grouped[entry.kind]?.add(data);
      }
      setState(() {
        for (final group in _groups) {
          _entriesByKind[group.kind] = grouped[group.kind] ?? [];
        }
        _contracts
          ..clear()
          ..addAll(
            _entriesByKind[_entryKindContract]!.map(
              (e) => e['اسم العقد'] ?? '',
            ),
          );
        _documents
          ..clear()
          ..addAll(
            _entriesByKind[_entryKindDocument]!.map(
              (e) => e['اسم المستند'] ?? '',
            ),
          );
      });
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('تعذر تحميل سجلات الأصل: $error'),
          behavior: SnackBarBehavior.floating,
        ),
      );
    }
  }

  void _updateItem(_AssetItem updated) {
    // وحدة أُرشفت أو حُذفت تخرج من القائمة إلى [shelvedUnits].
    if (updated.units.any((u) => !_unitIsLive(u))) {
      updated = updated.copyWith(
        units: updated.units.where(_unitIsLive).toList(),
        shelvedUnits: [
          ...updated.shelvedUnits,
          ...updated.units.where((u) => !_unitIsLive(u)),
        ],
      );
    }
    setState(() => _item = updated);
    widget.onItemChanged?.call(updated);
  }

  /// «تعديل» العقار: كل ما أُدخل فيه مملوءًا — بيانات العقار، وكل نوع وحدة
  /// بوحداته، والمرافق العامة.
  Future<void> _openPropertyFullEdit({String? initialSelected}) async {
    final result = await Navigator.of(context).push<_PropertyEditResult>(
      MaterialPageRoute(
        builder: (_) => _PropertyFullEditScreen(
          item: _item,
          initialSelected: initialSelected,
        ),
      ),
    );
    if (result == null || !mounted) return;
    _updateItem(result.item);
    // اسم الوحدة مكتوب أيضًا في عقودها — يُحدَّث هناك.
    final repo = widget.repository;
    final assetId = _item.id;
    if (result.renamed.isNotEmpty && repo != null && assetId != null) {
      try {
        final contracts = await repo.fetchUnitContracts(assetId);
        for (final contract in contracts) {
          final name = result.renamed[contract.unitKey];
          if (name == null || (contract.unitName ?? '') == name) continue;
          await repo.upsertUnitContract(contract.copyWith(unitName: name));
        }
      } catch (error) {
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('حُفظ التعديل، وتعذّر تحديث اسم الوحدة في العقد: $error'),
            behavior: SnackBarBehavior.floating,
          ),
        );
        return;
      }
    }
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('تم حفظ تعديل العقار'),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  void _onTopMenuAction(ThreeDotMenuAction action) {
    if (action == ThreeDotMenuAction.share) {
      Share.share(
        'تفاصيل ${_singularCategoryLabel(_item.category)}\n'
        'الاسم: ${_item.title}\n'
        'النوع: ${_item.subType}\n'
        'الحالة: ${_item.status}\n'
        'الموقع: ${_item.locationOrType}\n'
        'القيمة: ${_item.amountLabel}',
      );
      return;
    }

    if (action == ThreeDotMenuAction.freeze) {
      _updateItem(_item.copyWith(isFrozen: !_item.isFrozen));
      return;
    }

    if (action == ThreeDotMenuAction.pinHome) {
      _updateItem(_item.copyWith(isPinned: !_item.isPinned));
      return;
    }

    if (action == ThreeDotMenuAction.archive) {
      _updateItem(
        _item.copyWith(
          status: 'مؤرشف',
          needsAttention: false,
          isFrozen: true,
          // تاريخ الأرشفة يظهر في «السجل التاريخي».
          propertyMeta: Map<String, String>.of(_item.propertyMeta)
            ..[_kArchivedAtKey] = _isoToday(),
        ),
      );
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('تمت أرشفة الأصل')));
      return;
    }

    // لا حذف مباشر: «إلغاء» أولًا فيبقى العنصر ظاهرًا بحالة «ملغي»، ومن
    // العنصر الملغى «حذف» ينقله إلى سلة المهملات، ومن السلة الحذف النهائي.
    // (التأكيد تمّ في قائمة الثلاث نقاط نفسها.)
    if (action == ThreeDotMenuAction.delete) {
      final label = _singularCategoryLabel(_item.category);
      final blocked = _cancelBlockedMessage;
      if (blocked != null) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(content: Text(blocked), behavior: SnackBarBehavior.floating),
        );
        return;
      }
      if (!_isCancelledAsset(_item)) {
        // تاريخ الإلغاء يُحفظ ويظهر تحت الحالة في القائمة.
        final now = DateTime.now();
        _updateItem(
          _item.copyWith(
            status: 'ملغي',
            needsAttention: false,
            propertyMeta: _item.category == 'activity' ||
                    _item.category == 'real_estate' ||
                    _item.category == 'equipment'
                ? (Map<String, String>.of(_item.propertyMeta)
                    ..[_ActKeys.cancelledAt] =
                        '${now.day}/${now.month}/${now.year}')
                : null,
          ),
        );
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              'أُلغي «${_item.title}» — يبقى في «السجل التاريخي»',
            ),
            behavior: SnackBarBehavior.floating,
          ),
        );
        return;
      }
      // لا حذف في العقارات والأنشطة والمركبات: الملغى يبقى للرجوع إليه.
      if (_item.category == 'real_estate' ||
          _item.category == 'activity' ||
          _item.category == 'equipment') {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              '«${_item.title}» ملغى ولا يُحذف — تجده في «السجل التاريخي»',
            ),
            behavior: SnackBarBehavior.floating,
          ),
        );
        return;
      }
      final meta = Map<String, String>.of(_item.propertyMeta)
        ..['الحالة قبل الحذف'] = _item.status
        ..['تاريخ الحذف'] = _trashStamp()
        ..['مصدر السجل'] = _categoryLabel(_item.category);
      _updateItem(
        _item.copyWith(status: _kAssetTrashStatus, propertyMeta: meta),
      );
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('نُقل $label «${_item.title}» إلى سلة المهملات'),
          behavior: SnackBarBehavior.floating,
        ),
      );
      Navigator.of(context).pop();
      return;
    }

    if (action == ThreeDotMenuAction.edit) {
      // العقار: شاشة تعديل كاملة بكل ما أُدخل (البيانات، الوحدات بأنواعها،
      // المرافق) — لا البيانات الأساسية وحدها.
      if (_item.category == 'real_estate') {
        _openPropertyFullEdit();
        return;
      }
      // المركبة: نموذج إضافة المركبة نفسه مملوءًا ببياناتها.
      if (_item.category == 'equipment') {
        _editEquipment();
        return;
      }
      final titleController = TextEditingController(text: _item.title);
      final locationController = TextEditingController(
        text: _item.locationOrType,
      );
      final ownerController = TextEditingController(text: _item.owner);
      final descriptionController = TextEditingController(
        text: _item.description,
      );
      final annexCounts = <String, int>{
        for (final label in _propertyAnnexLabels)
          label: _item.annexes[label] ?? 0,
      };
      final otherAnnex = _item.annexes.entries
          .where((entry) => entry.key.startsWith('أخرى: '))
          .map((entry) => entry.key.substring('أخرى: '.length))
          .join('، ');
      final otherAnnexController = TextEditingController(text: otherAnnex);
      final mapLinkController = TextEditingController(text: _item.mapLink);
      final latController = TextEditingController(
        text: _item.latitude?.toString() ?? '',
      );
      final lngController = TextEditingController(
        text: _item.longitude?.toString() ?? '',
      );
      showModalBottomSheet<void>(
        context: context,
        isScrollControlled: true,
        backgroundColor: Colors.white,
        shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(16)),
        ),
        builder: (context) => StatefulBuilder(
          builder: (context, setModalState) => Padding(
            padding: EdgeInsets.fromLTRB(
              16,
              12,
              16,
              MediaQuery.of(context).viewInsets.bottom + 16,
            ),
            child: Directionality(
              textDirection: AppTr.uiDir,
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    const Text(
                      'تعديل البيانات',
                      style: TextStyle(
                        fontSize: 15,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                    const SizedBox(height: 10),
                    TextField(
                      controller: titleController,
                      decoration: InputDecoration(
                        labelText: AppTr.tr('اسم ${_singularCategoryLabel(_item.category)}'),
                      ),
                    ),
                    const SizedBox(height: 8),
                    TextField(
                      controller: locationController,
                      decoration: InputDecoration(
                        labelText: AppTr.tr('الموقع/النوع'),
                      ),
                    ),
                    const SizedBox(height: 8),
                    TextField(
                      controller: ownerController,
                      decoration: InputDecoration(labelText: AppTr.tr('المالك')),
                    ),
                    const SizedBox(height: 8),
                    TextField(
                      controller: descriptionController,
                      maxLines: 3,
                      decoration: InputDecoration(
                        labelText: AppTr.tr('الوصف العام'),
                      ),
                    ),
                    if (_item.category == 'real_estate') ...[
                      const SizedBox(height: 8),
                      _PropertyAnnexesEditor(
                        counts: annexCounts,
                        otherController: otherAnnexController,
                        onCountChanged: (label, count) =>
                            setModalState(() => annexCounts[label] = count),
                      ),
                      const SizedBox(height: 12),
                      TextField(
                        controller: mapLinkController,
                        decoration: InputDecoration(
                          labelText: AppTr.tr('رابط الموقع على خرائط جوجل'),
                          hintText: AppTr.tr('الصق رابط Google Maps هنا'),
                        ),
                      ),
                      const SizedBox(height: 4),
                      const Align(
                        alignment: Alignment.centerRight,
                        child: Text(
                          'تُستخرج الإحداثيات تلقائيًا من الرابط لعرض خريطة العقار.',
                          textAlign: TextAlign.right,
                          style: TextStyle(fontSize: 10, color: Color(0xFF5C6B68)),
                        ),
                      ),
                    ],
                    const SizedBox(height: 12),
                    FilledButton(
                      onPressed: () {
                        final manualLat = double.tryParse(
                          latController.text.trim(),
                        );
                        final manualLng = double.tryParse(
                          lngController.text.trim(),
                        );
                        final parsedFromLink = _parseLatLngFromMapLink(
                          mapLinkController.text,
                        );
                        _updateItem(
                          _item.copyWith(
                            title: titleController.text.trim().isEmpty
                                ? _item.title
                                : titleController.text.trim(),
                            locationOrType:
                                locationController.text.trim().isEmpty
                                ? _item.locationOrType
                                : locationController.text.trim(),
                            owner: ownerController.text.trim().isEmpty
                                ? _item.owner
                                : ownerController.text.trim(),
                            description: descriptionController.text.trim(),
                            annexes: {
                              for (final entry in annexCounts.entries)
                                if (entry.value > 0) entry.key: entry.value,
                              if (otherAnnexController.text.trim().isNotEmpty)
                                'أخرى: ${otherAnnexController.text.trim()}': 1,
                            },
                            mapLink: mapLinkController.text.trim(),
                            latitude:
                                manualLat ?? parsedFromLink?.$1 ?? _item.latitude,
                            longitude:
                                manualLng ?? parsedFromLink?.$2 ?? _item.longitude,
                          ),
                        );
                        Navigator.pop(context);
                      },
                      child: const Text('حفظ التعديل'),
                    ),
                  ],
                ),
              ),
            ),
          ),
        ),
      );
    }
  }

  late Map<String, List<Map<String, String>>> _entriesByKind;

  List<Map<String, String>> _cloneEntries(Iterable<Map<String, String>> src) =>
      src.map((e) => Map<String, String>.from(e)).toList();

  @override
  void dispose() {
    DelegatedAssets.writes.removeListener(_onDelegatedWrite);
    _searchController.dispose();
    super.dispose();
  }

  DateTime _lastDelegatedNotice = DateTime(2000);

  /// «مفوَّض أنا بإدارته» أو «فوّضت غيري بإدارته» تحت «ملخص عام».
  Map<String, (String, Color)> get _navNotes => {
    if (_delegationBadgeOf(_item.id) case final badge?)
      'ملخص عام': (badge, _kDelegatedColor),
  };

  /// المفوَّض حفظ شيئًا في هذا العنصر: يُقال له إن صاحبه أُشعر.
  void _onDelegatedWrite() {
    if (!mounted || DelegatedAssets.lastWriteAsset != _item.id) return;
    final delegation = DelegatedAssets.of(_item.id);
    if (delegation == null) return;
    final now = DateTime.now();
    if (now.difference(_lastDelegatedNotice).inSeconds < 4) return;
    _lastDelegatedNotice = now;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          '${AppTr.tr('تم الحفظ وإشعار')} ${delegation.owner} '
          '${AppTr.tr('بما قمت به')}',
        ),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  List<String> _mainTabsFor(_AssetItem item) {
    if (item.category == 'activity') {
      return const ['الملخص', 'المالية', 'العملاء', 'الموردون', 'الأشخاص'];
    }
    return const ['الملخص', 'العقود', 'الأشخاص', 'المالية', 'الصيانة'];
  }

  List<String> _secondaryTabsFor(_AssetItem item) {
    if (item.category == 'activity') {
      return const ['الأصول والمعدات', 'المستندات', 'المهام'];
    }
    return const ['المستندات', 'المهام'];
  }

  /// فتح مستند محفوظ من داخل شاشة تفاصيل العقار.
  Future<void> _openAssetStoredFile(String path) async {
    final error = await DocumentStore.open(path);
    if (!mounted || error == null) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(error), behavior: SnackBarBehavior.floating),
    );
  }

