                              data['_reminder_id'] =
                                  existing?['_reminder_id'] ??
                                  'asset-entry-${DateTime.now().microsecondsSinceEpoch}';
                              final existingId = existing?['_id'] ?? '';
                              if (isEditing && existingId.isNotEmpty) {
                                data['_id'] = existingId;
                              }
                              final primaryLabel = group.fields.first.label;
                              // الحقول الإلزامية (والأول دائمًا): تنبيه فوق
                              // النموذج بما ينقص.
                              final missing = [
                                for (final field in group.fields)
                                  if ((field.required ||
                                          field.label == primaryLabel) &&
                                      (data[field.label] ?? '').isEmpty)
                                    field.display ?? field.label,
                              ];
