  void _persistEntry(
    _ActionGroup group,
    Map<String, String> data, {
    int? editIndex,
  }) {
    final list = _entriesByKind[group.kind]!;
    setState(() {
      if (editIndex != null && editIndex >= 0 && editIndex < list.length) {
        list[editIndex] = data;
      } else {
        list.insert(0, data);
      }

      // Keep legacy string lists in sync for the summary chips.
      if (group.kind == _entryKindContract) {
        _contracts
          ..clear()
          ..addAll(list.map((e) => e['اسم العقد'] ?? ''));
      } else if (group.kind == _entryKindDocument) {
        _documents
          ..clear()
          ..addAll(list.map((e) => e['اسم المستند'] ?? ''));
      }
    });
    _syncEntryToRemote(group, data);
    _syncEntryReminder(group, data);
  }

  /// بند صيانة البناية بمفاتيح نموذج الوحدة؛ البنود القديمة تُقرأ
  /// بمفاتيحها القديمة (وصف العطل، التكلفة، تاريخ التنفيذ، الفني).
  Map<String, String> _maintenanceCompat(Map<String, String> e) {
    String pick(String key, String old) =>
        (e[key] ?? '').trim().isNotEmpty ? e[key]! : (e[old] ?? '');
    return <String, String>{
      ...e,
      'الوصف': pick('الوصف', 'وصف العطل'),
      'المبلغ': pick('المبلغ', 'التكلفة'),
      'الشركة المنفذة': pick('الشركة المنفذة', 'الفني / المقاول'),
      'التاريخ': pick('التاريخ', 'تاريخ التنفيذ'),
    };
  }

  /// إضافة/تعديل صيانة البناية بنفس نموذج صيانة الوحدة.
  Future<void> _openPropertyMaintenance({
    Map<String, String>? existing,
    int? index,
  }) async {
    final sheet = await _showMaintenanceSheetShared(
      context,
      existing: existing == null ? null : _maintenanceCompat(existing),
    );
    if (sheet == null || !mounted) return;
    // التعديل يحمل معرّف السجل وتذكيره: يُحدَّث نفس السجل على الخادم بدل
    // إضافة نسخة ثانية في كل تعديل.
    final row = <String, String>{
      ...sheet,
      for (final key in const ['_id', '_reminder_id'])
        if ((existing?[key] ?? '').isNotEmpty && (sheet[key] ?? '').isEmpty)
          key: existing![key]!,
    };
    _persistEntry(
      _groups.firstWhere((g) => g.kind == _entryKindMaintenance),
      row,
      editIndex: index,
    );
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(index == null ? 'تم حفظ الصيانة' : 'تم حفظ التعديل'),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  /// «انتهاء الصيانة» للعقار أو المركبة أو النشاط: يُغلق البند باليوم
  /// والوقت والملاحظة، فتزول «صيانة» من الحالة.
  Future<void> _finishPropertyMaintenance(
    Map<String, String> raw,
    int index,
  ) async {
    final done = await _finishMaintenanceShared(context, raw);
    if (done == null || !mounted) return;
    _persistEntry(
      _groups.firstWhere((g) => g.kind == _entryKindMaintenance),
      done,
      editIndex: index,
    );
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('تم تسجيل انتهاء الصيانة'),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  /// قائمة صيانة البناية بنفس صفوف صيانة الوحدة وتفاصيلها.
  Widget _propertyMaintenanceList() {
    final group = _groups.firstWhere((g) => g.kind == _entryKindMaintenance);
    final all = _entriesByKind[_entryKindMaintenance]!;
    final entries = _filterEntries(all);
    if (entries.isEmpty) {
      return const _DetailHintCard(
        message: 'لا توجد أعمال صيانة بعد — اضغط + لإضافة صيانة.',
      );
    }
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        for (final raw in entries)
          Builder(
            builder: (context) {
              final e = _maintenanceCompat(raw);
              final index = all.indexOf(raw);
              final title = e['الوصف']!.isEmpty ? 'صيانة' : e['الوصف']!;
              return _itemRowShared(
                icon: Icons.build_circle_outlined,
                accent: (e['النوع'] ?? '') == 'على المستأجر'
                    ? AppTheme.gold
                    : _kPropertyColor,
                line1: [
                  title,
                  if (e['المبلغ']!.isNotEmpty)
                    '${e['المبلغ']} ${AppSettings.currencySuffix}',
                ].join(' · '),
                line2: [
                  if (_maintIsOpen(e)) _kMaintOpen,
                  e['التاريخ']!,
                  e['الشركة المنفذة']!,
                  e['النوع'] ?? '',
                ].where((part) => part.isNotEmpty).join(' · '),
                onTap: () => _showItemDetailsShared(
                  context,
                  title: title,
                  icon: Icons.build_circle_outlined,
                  row: {
                    for (final entry in raw.entries)
                      if (!entry.key.startsWith('_')) entry.key: entry.value,
                  },
                  onEdit: () =>
                      _openPropertyMaintenance(existing: raw, index: index),
                  onDelete: () => _deleteEntry(group, index),
                  onOpenFile: _openAssetStoredFile,
                  onFinishMaintenance: () =>
                      _finishPropertyMaintenance(raw, index),
                ),
              );
            },
          ),
      ],
    );
  }

  void _deleteEntry(_ActionGroup group, int index) {
    // العقود والحركات المالية (السندات والمصروفات) لا تُحذف — تُعدَّل فقط.
    if (_kNoDeleteEntryKinds.contains(group.kind)) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'العقود والحركات المالية لا تُحذف — للتصحيح استعمل «تعديل»',
          ),
          behavior: SnackBarBehavior.floating,
        ),
      );
      return;
    }
    final list = _entriesByKind[group.kind]!;
    if (index < 0 || index >= list.length) return;
    final reminderId = list[index]['_reminder_id'];
    final entryId = list[index]['_id'];
    setState(() {
      list.removeAt(index);
      if (group.kind == _entryKindContract) {
        _contracts
          ..clear()
          ..addAll(list.map((e) => e['اسم العقد'] ?? ''));
      } else if (group.kind == _entryKindDocument) {
        _documents
          ..clear()
          ..addAll(list.map((e) => e['اسم المستند'] ?? ''));
      }
    });
    if (reminderId != null && reminderId.isNotEmpty) {
      AppRemindersStore.remove(reminderId);
    }
    // بدون هذا الاستدعاء يبقى السجل المحذوف محفوظًا في قاعدة البيانات إلى
    // الأبد رغم اختفائه من الشاشة، ويعود للظهور فور إعادة تحميل البيانات.
    if (entryId != null && entryId.isNotEmpty) {
      widget.repository?.deleteEntry(entryId).catchError((error) {
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('تعذر حذف السجل من قاعدة البيانات: $error'),
            behavior: SnackBarBehavior.floating,
          ),
        );
      });
    }
  }

  Future<void> _syncEntryReminder(
    _ActionGroup group,
    Map<String, String> data,
  ) async {
    if (group.kind != _entryKindContract && group.kind != _entryKindDocument) {
      return;
    }
    final reminderId = data['_reminder_id'] ?? '';
    final expiry = AppRemindersStore.parseDisplayDate(
      data['تاريخ الانتهاء'] ?? '',
    );
    if (reminderId.isEmpty) return;
    if (expiry == null) {
      await AppRemindersStore.remove(reminderId);
      return;
    }
    await AppRemindersStore.upsert(
      AppReminder(
        id: reminderId,
        title: data[group.fields.first.label] ?? group.title,
        module: 'العقارات والأنشطة التجارية',
        expiryDate: expiry,
        remindBeforeDays: AppRemindersStore.reminderDaysFromLabel(
          data['التذكير قبل الانتهاء'] ?? '',
        ),
      ),
    );
  }

  Future<void> _syncEntryToRemote(
    _ActionGroup group,
    Map<String, String> data,
  ) async {
    final repository = widget.repository;
    final assetId = widget.item.id;
    if (repository == null || assetId == null || assetId.isEmpty) return;
    try {
      // تمرير المعرّف الحالي (إن وُجد) يجعل الاستدعاء تحديثًا لنفس السجل
      // بدل إنشاء سجل جديد مكرر في كل مرة يُعدَّل فيها هذا العنصر — بدون
      // هذا كانت كل عملية تعديل تُضاعف السجل على الخادم دون حذف القديم.
      final existingId = data['_id'];
      final saved = await repository.upsertEntry(
        ProjectAssetEntryRecord(
          id: (existingId != null && existingId.isNotEmpty)
              ? existingId
              : null,
          assetId: assetId,
          kind: group.kind,
          data: Map<String, String>.of(data)..remove('_id'),
        ),
      );
      if (!mounted || saved.id == null) return;
      final list = _entriesByKind[group.kind];
      if (list == null) return;
      final index = list.indexWhere(
        (entry) =>
            identical(entry, data) || (existingId != null && entry['_id'] == existingId),
      );
      if (index != -1) {
        setState(() => list[index]['_id'] = saved.id!);
      }
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('تعذر مزامنة بيانات ${group.title}: $error'),
          behavior: SnackBarBehavior.floating,
        ),
      );
    }
  }

