  bool _matchesQuery(String value) {
    final query = _searchController.text.trim();
    return query.isEmpty || value.contains(query);
  }

  List<String> _filterItems(List<String> items) {
    if (_searchController.text.trim().isEmpty) return items;
    return items.where(_matchesQuery).toList(growable: false);
  }

  Color _categoryColor(String key) {
    switch (key) {
      case 'real_estate':
        return const Color(0xFF0A5A50);
      case 'activity':
        return const Color(0xFFCE8422);
      case 'equipment':
        return const Color(0xFF0E7161);
      case 'other':
        return const Color(0xFF0E7161);
      default:
        return const Color(0xFF04413B);
    }
  }

  Color get _pageColor => Color.lerp(
    _item.iconColor ?? _categoryColor(_item.category),
    const Color(0xFF022E2A),
    0.35,
  )!;

  // ===== «السجل» و«السجل التاريخي» (العقارات والأنشطة والمركبات) =====

  static const List<DetailSectionTab> _recordTabs = [
    DetailSectionTab(label: 'السجل', icon: Icons.receipt_long_outlined),
    DetailSectionTab(label: 'السجل التاريخي', icon: Icons.history_edu_outlined),
  ];

  /// تاريخ من نص بأي صيغة مستعملة في السجلات.
  DateTime? _recordDate(String? raw) {
    final text = (raw ?? '').trim();
    if (text.isEmpty) return null;
    return _parseFlexibleDate(text.split(' ').first) ?? DateTime.tryParse(text);
  }

  /// كل حركة على الأصل بتاريخها: العقود وإلغاؤها وانتهاؤها، المحصّل
  /// والمستحق والتأمينات، الصيانة والمستندات والمتابعة والدخل والمصروف،
  /// وسطور سجل النشاط.
  List<AssetRecordEvent> _recordEvents() {
    final out = <AssetRecordEvent>[];
    final today = DateUtils.dateOnly(DateTime.now());
    for (final c in _unitContracts) {
      final unit = (c.unitName ?? '').trim();
      final tenant = (c.tenantName ?? '').trim();
      out.add(
        AssetRecordEvent(
          date: c.startDate,
          title: 'عقد إيجار',
          detail: tenant.isEmpty ? '' : 'المستأجر: $tenant',
          unit: unit,
          icon: Icons.assignment_rounded,
          kind: AssetRecordEvent.kindContract,
        ),
      );
      if (c.status == _kContractCancelled) {
        out.add(
          AssetRecordEvent(
            date: c.endDate,
            title: 'إلغاء العقد',
            detail: LeaseContractData.isSettled(c.notes)
                ? 'تمت تسوية المبالغ'
                : (tenant.isEmpty ? '' : 'المستأجر: $tenant'),
            unit: unit,
            icon: Icons.cancel_outlined,
            kind: AssetRecordEvent.kindContract,
          ),
        );
      } else if (c.endDate != null &&
          DateUtils.dateOnly(c.endDate!).isBefore(today)) {
        out.add(
          AssetRecordEvent(
            date: c.endDate,
            title: 'انتهاء العقد',
            detail: tenant.isEmpty ? '' : 'المستأجر: $tenant',
            unit: unit,
            icon: Icons.event_busy_outlined,
            kind: AssetRecordEvent.kindContract,
          ),
        );
      }
    }
    for (final entry in _propertyPayments) {
      final p = entry.payment;
      final deposit = entry.kindLabel == kPayKindDeposit;
      final tenant = (entry.contract.tenantName ?? '').trim();
      if (p.amountPaid > 0.009) {
        out.add(
          AssetRecordEvent(
            date: p.paidAt ?? p.dueDate,
            title: deposit ? 'دفع تأمين' : 'تحصيل: ${entry.title}',
            detail: tenant,
            unit: entry.unitName,
            icon: deposit ? Icons.shield_outlined : Icons.payments_outlined,
            kind: deposit
                ? AssetRecordEvent.kindDeposit
                : AssetRecordEvent.kindPayment,
            amount: p.amountPaid,
          ),
        );
      }
      final left = payRemaining(p);
      if (left > 0 &&
          p.dueDate != null &&
          !DateUtils.dateOnly(p.dueDate!).isAfter(today)) {
        out.add(
          AssetRecordEvent(
            date: p.dueDate,
            title: 'مستحق: ${entry.title}',
            detail: tenant,
            unit: entry.unitName,
            icon: Icons.error_outline_rounded,
            kind: AssetRecordEvent.kindDue,
            amount: left,
          ),
        );
      }
    }
    String first(Map<String, String> e, List<String> keys) {
      for (final key in keys) {
        final value = (e[key] ?? '').trim();
        if (value.isNotEmpty) return value;
      }
      return '';
    }

    void addKind(String kind, String label, IconData icon, String recordKind) {
      for (final e in _entriesByKind[kind] ?? const <Map<String, String>>[]) {
        final follow = e.containsKey('نوع المتابعة');
        if (kind == _entryKindRental && !follow) continue;
        final title = first(e, const [
          'العنوان',
          'اسم المستند',
          'البند',
          'اسم العقد',
          'نوع الصيانة',
          'نوع المستند',
          'الوصف',
        ]);
        out.add(
          AssetRecordEvent(
            date: _recordDate(
              first(e, const [
                'التاريخ',
                'تاريخ الطلب',
                'تاريخ الإصدار',
                'تاريخ البدء',
                'تاريخ الاستحقاق',
                'تاريخ الانتهاء',
              ]),
            ),
            title: title.isEmpty ? label : '$label: $title',
            detail: follow ? (e['نوع المتابعة'] ?? '') : '',
            unit: first(e, const ['الوحدة', 'الوحدة المعنية']),
            icon: icon,
            kind: recordKind,
            amount: double.tryParse(
                  first(e, const ['المبلغ', 'التكلفة', 'القيمة'])
                      .replaceAll(',', ''),
                ) ??
                0,
            // كل ما سُجّل في البند — للسجل التاريخي المفصّل وطباعته.
            fields: Map<String, String>.of(e),
          ),
        );
      }
    }

    addKind(
      _entryKindMaintenance,
      'صيانة',
      Icons.build_outlined,
      AssetRecordEvent.kindMaintenance,
    );
    addKind(
      _entryKindDocument,
      'مستند',
      Icons.description_outlined,
      AssetRecordEvent.kindDocument,
    );
    addKind(
      _entryKindRental,
      'متابعة',
      Icons.event_note_outlined,
      AssetRecordEvent.kindFollow,
    );
    addKind(
      _entryKindRevenue,
      'دخل',
      Icons.trending_up_rounded,
      AssetRecordEvent.kindMoney,
    );
    addKind(
      _entryKindExpense,
      'مصروف',
      Icons.trending_down_rounded,
      AssetRecordEvent.kindMoney,
    );
    addKind(
      _entryKindContract,
      'عقد',
      Icons.assignment_outlined,
      AssetRecordEvent.kindContract,
    );
    for (final line in _item.logs) {
      if (line.trim().isEmpty) continue;
      out.add(AssetRecordEvent(title: line.trim()));
    }
    return out;
  }

  /// الحالة الآن لوحدة (أو للمركبة): «مؤجرة — المستأجر» أو شاغرة أو صيانة.
  String _recordUnitStatus(String name) {
    if (_item.category == 'equipment') {
      final label = _equipStatusLabel;
      final tenant =
          (_equipContracts.where(_contractHolds).firstOrNull?.tenantName ?? '')
              .trim();
      return label == 'مؤجر' && tenant.isNotEmpty ? 'مؤجر — $tenant' : label;
    }
    for (final unit in _item.units) {
      if (unit.name.trim() != name.trim()) continue;
      final status = _effectiveUnitStatus(unit);
      final tenant =
          (_unitContracts
                      .where(
                        (c) => c.unitKey == unit.unitKey && _contractHolds(c),
                      )
                      .firstOrNull
                      ?.tenantName ??
                  '')
              .trim();
      return status == 'مؤجرة' && tenant.isNotEmpty
          ? 'مؤجرة — $tenant'
          : status;
    }
    return '';
  }

  /// قسما «السجل» و«السجل التاريخي» يفتحان صفحتهما مباشرة؛ يعيد true إن
  /// فُتحت إحداهما (فلا يتغيّر القسم المختار).
  bool _openRecordsTab(String label) {
    if (label != 'السجل' && label != 'السجل التاريخي') return false;
    final category = _item.category;
    Navigator.of(context).push(
      MaterialPageRoute<void>(
        builder: (_) => AssetRecordsScreen(
          assetTitle: _item.title,
          history: label == 'السجل التاريخي',
          events: _recordEvents,
          payments: () => _propertyPayments,
          contracts: () => _unitContracts,
          units: [for (final u in _item.units) u.name],
          repository: widget.repository,
          reload: _loadPropertyPayments,
          accent: category == 'activity'
              ? _kActivityColor
              : (category == 'equipment' ? _kEquipmentColor : _kPropertyColor),
          unitLabel: category == 'real_estate'
              ? 'الوحدة'
              : (category == 'equipment' ? 'المركبة' : 'العقد'),
          currentStatus: _recordUnitStatus,
          // السجل التاريخي بشكل واحد للعقار والمركبة والنشاط: ما أُلغي أو
          // أُرشف فقط (العنصر نفسه والعقود/الوحدات).
          archiveItems: _archiveItems,
          unitDetails: category == 'real_estate'
              ? _archiveUnitDetails
              : _archiveAssetDetails,
          assetType: _archiveAssetType(),
        ),
      ),
    );
    return true;
  }

  /// نوع العنصر لرأس السجل التاريخي: نوع العقار، أو نوع المركبة، أو نوع
  /// النشاط.
  String _archiveAssetType() {
    if (_item.category == 'real_estate') return _assetPropertyType(_item);
    if (_item.category == 'equipment') {
      final type = (_item.propertyMeta[_EquipKeys.vehicleType] ?? '').trim();
      if (type.isNotEmpty) return type;
      final cls = (_item.propertyMeta[_EquipKeys.vehicleClass] ?? '').trim();
      return cls.isNotEmpty ? cls : _item.subType.trim();
    }
    return _item.subType.trim();
  }

  /// بيانات وحدة لصفحة عنصر السجل التاريخي: حقولها (النوع، الرقم،
  /// المساحة، الغرف، العدادات...) وقوائمها المسجّلة فيها (الصيانة،
  /// المرافق، الملاحظات...) — من الوحدة الحية أو المؤرشفة.
  ({
    List<(String, String)> info,
    List<(String, List<Map<String, String>>)> lists,
  })
  _archiveUnitDetails(String unitName) {
    _PropertyUnit? unit;
    for (final u in [..._item.units, ..._item.shelvedUnits]) {
      if (u.name.trim() == unitName.trim()) {
        unit = u;
        break;
      }
    }
    if (unit == null) return (info: const [], lists: const []);
    final info = <(String, String)>[
      if (unit.unitNumber.trim().isNotEmpty) ('رقم الوحدة', unit.unitNumber),
      if (unit.area.trim().isNotEmpty) ('المساحة', unit.area),
      if (unit.rooms > 0) ('عدد الغرف', '${unit.rooms}'),
      if (unit.halls > 0) ('عدد الصالات', '${unit.halls}'),
      if (unit.balconies > 0) ('عدد البلكونات', '${unit.balconies}'),
      if (unit.bathrooms > 0) ('عدد الحمامات', '${unit.bathrooms}'),
      if (unit.parkingCount > 0) ('مواقف السيارات', '${unit.parkingCount}'),
      if (unit.notes.trim().isNotEmpty) ('ملاحظات', unit.notes),
    ];
    final lists = <(String, List<Map<String, String>>)>[];
    unit.extras.forEach((key, value) {
      if (key.startsWith('__')) return;
      final text = value.trim();
      if (text.isEmpty) return;
      if (text.startsWith('[')) {
        try {
          final decoded = jsonDecode(text);
          if (decoded is! List) return;
          final rows = <Map<String, String>>[
            for (final row in decoded)
              if (row is Map)
                {
                  for (final e in row.entries)
                    '${e.key}': '${e.value ?? ''}',
                },
          ];
          if (rows.isNotEmpty) lists.add((key, rows));
        } catch (_) {
          // قائمة تالفة لا تُعرض.
        }
        return;
      }
      if (text.startsWith('{')) return;
      info.add((LeaseContractData.metaLabel(key), text));
    });
    return (info: info, lists: lists);
  }

  /// بيانات المركبة أو النشاط لصفحة عنصر السجل التاريخي: كل ما سُجّل
  /// عنها (التصنيف، النوع، اللوحة، الشاصي، المرسى...) بلا التذكيرات.
  ({
    List<(String, String)> info,
    List<(String, List<Map<String, String>>)> lists,
  })
  _archiveAssetDetails(String _) {
    final info = <(String, String)>[
      if (_item.subType.trim().isNotEmpty) ('النوع / الموديل', _item.subType),
      if (_item.serialNumber.trim().isNotEmpty &&
          _item.serialNumber.trim() != 'غير محدد')
        ('الرقم التسلسلي', _item.serialNumber),
      if (_item.locationOrType.trim().isNotEmpty &&
          _item.locationOrType.trim() != 'غير محدد')
        ('الموقع', _item.locationOrType),
    ];
    _item.propertyMeta.forEach((key, value) {
      final text = value.trim();
      if (text.isEmpty || key.startsWith('_') || key.contains('تذكير')) {
        return;
      }
      if (text.startsWith('[') || text.startsWith('{')) return;
      if (key == _kArchivedAtKey || key == _ActKeys.cancelledAt) return;
      info.add((LeaseContractData.metaLabel(key), text));
    });
    return (info: info, lists: const []);
  }

  /// نوع الوحدة من اسمها (للوحدات الحية والمؤرشفة).
  String _unitTypeByName(String name) {
    for (final unit in [..._item.units, ..._item.shelvedUnits]) {
      if (unit.name.trim() == name.trim()) return unit.type;
    }
    return '';
  }

  /// عناصر «السجل التاريخي» للعقار: العقار نفسه إن أُلغي أو أُرشف، وكل
  /// عقد وحدة أُلغي، وكل وحدة أُرشفت — بنوعها واسمها وتاريخ الإلغاء أو
  /// الأرشفة.
  List<AssetArchiveItem> _archiveItems() {
    final out = <AssetArchiveItem>[];
    final allUnits = [..._item.units, ..._item.shelvedUnits];
    String typeOf(String unitKey, String name) {
      // المركبة والنشاط: نوعهما هو نوع العقد.
      if (_item.category != 'real_estate') return _archiveAssetType();
      for (final unit in allUnits) {
        if (unit.unitKey == unitKey) return unit.type;
      }
      for (final unit in allUnits) {
        if (unit.name.trim() == name.trim()) return unit.type;
      }
      return '';
    }

    final cancelledAsset = _isCancelledAsset(_item);
    if (cancelledAsset || _item.status == 'مؤرشف') {
      out.add(
        AssetArchiveItem(
          name: _item.title,
          type: _archiveAssetType(),
          cancelled: cancelledAsset,
          date: _recordDate(
            _item.propertyMeta[cancelledAsset
                ? _ActKeys.cancelledAt
                : _kArchivedAtKey],
          ),
          isAsset: true,
        ),
      );
    }
    for (final c in _unitContracts) {
      if (c.status != _kContractCancelled) continue;
      final name = (c.unitName ?? '').trim();
      out.add(
        AssetArchiveItem(
          name: name.isEmpty ? 'وحدة' : name,
          type: typeOf(c.unitKey, name),
          cancelled: true,
          date: _recordDate(
                LeaseContractData.decode(c.notes).contract[_kCancelDateKey],
              ) ??
              c.endDate,
          unitName: name,
          contractId: c.id,
        ),
      );
    }
    for (final unit in _item.shelvedUnits) {
      if (unit.status != _kUnitArchived) continue;
      out.add(
        AssetArchiveItem(
          name: unit.name,
          type: unit.type,
          cancelled: false,
          date: _recordDate(unit.extras[_kArchivedAtKey]),
          unitName: unit.name,
        ),
      );
    }
    return out;
  }

