  /// طيّ عمود الفئات في صفحات التفاصيل (سهم على الخط الفاصل).
  bool _detailNavCollapsed = false;

  /// فلتر حالة الوحدات في نهاية مستطيل "العناصر": الكل/شاغرة/مؤجرة.
  String _unitStatusFilter = 'الكل';

  /// مستطيل بحث الوحدات داخل قسم «الوحدات» (يفتح من علامة البحث).
  bool _unitSearchOpen = false;

  Widget _unitSearchToggle() => IconButton(
    tooltip: AppTr.tr('ابحث عن وحدة'),
    visualDensity: VisualDensity.compact,
    icon: Icon(
      _unitSearchOpen ? Icons.search_off_rounded : Icons.search_rounded,
      size: 21,
      color: _kPropertyColor,
    ),
    onPressed: () => setState(() {
      _unitSearchOpen = !_unitSearchOpen;
      if (!_unitSearchOpen) _searchController.clear();
    }),
  );

  bool _unitMatchesStatusFilter(_PropertyUnit unit) {
    final status = _effectiveUnitStatus(unit);
    return switch (_unitStatusFilter) {
      'شاغرة' => status == 'شاغرة' && !_unitIsCancelled(unit),
      // «مؤجرة» وحدها (لا المجمّدة ولا منتهي العقد).
      'مؤجرة' => status == 'مؤجرة' && !_unitIsCancelled(unit),
      'مسودة' => status == 'مسودة' && !_unitIsCancelled(unit),
      'ملغاة' => _unitContractCancelled(unit),
      _ => true,
    };
  }

  /// وحدة «ملغاة»: أُلغي آخر عقد لها بالتسوية ولم يُكتب لها عقد جديد بعد.
  bool _unitContractCancelled(_PropertyUnit unit) {
    if (_unitIsCancelled(unit)) return true;
    if (_activeContractForUnit(unit.unitKey) != null) return false;
    return _unitContracts.any(
      (c) => c.unitKey == unit.unitKey && c.status == _kContractCancelled,
    );
  }

  /// وحدة ملغاة: أُلغيت من قائمة الثلاث نقاط في تفاصيلها.
  bool _unitIsCancelled(_PropertyUnit unit) => unit.status.contains('ملغ');

