  /// الرجوع خطوة واحدة: قسم مفتوح ← قائمة الأقسام، ثم خروج من الصفحة.
  void _handleStepBack() {
    if (_selectedTab >= 0) {
      setState(() {
        _selectedTab = -1;
        _detailNavCollapsed = false;
      });
      return;
    }
    Navigator.pop(context);
  }

  /// يجعل زر الرجوع في النظام يتبع نفس منطق الخطوة الواحدة.
  Widget _wrapStepBack(Widget child) => PopScope(
    canPop: _selectedTab < 0,
    onPopInvokedWithResult: (didPop, result) {
      if (didPop) return;
      _handleStepBack();
    },
    child: child,
  );

  /// عمود الخط الفاصل بين الفئات والعناصر مع سهم الطي/الإرجاع.
  Widget _navDividerColumn() {
    return SizedBox(
      width: _kDividerWidth,
      child: Column(
        children: [
          SizedBox(
            height: 120,
            child: Center(
              child: Container(width: 1, color: const Color(0xFFE4EAE8)),
            ),
          ),
          _BlinkingCollapseButton(
            collapsed: _detailNavCollapsed,
            onTap: () {
              if (!_detailNavCollapsed && _selectedTab < 0) {
                ScaffoldMessenger.of(context).showSnackBar(
                  const SnackBar(
                    content: Text('اختر قسمًا أولًا لعرض محتواه'),
                    behavior: SnackBarBehavior.floating,
                  ),
                );
                return;
              }
              setState(() {
                if (_detailNavCollapsed) {
                  // الرجوع إلى قائمة الأقسام بلا اختيار.
                  _detailNavCollapsed = false;
                  _selectedTab = -1;
                } else {
                  _detailNavCollapsed = true;
                }
              });
            },
          ),
          Expanded(
            child: Center(
              child: Container(width: 1, color: const Color(0xFFE4EAE8)),
            ),
          ),
        ],
      ),
    );
  }

  /// فلتر شاغرة/مؤجرة في نهاية شريط العناصر (قسم الوحدات).
  Widget _unitStatusFilterButton() {
    return PopupMenuButton<String>(
      tooltip: AppTr.tr('تصفية الوحدات'),
      position: PopupMenuPosition.under,
      onSelected: (value) => setState(() => _unitStatusFilter = value),
      itemBuilder: (context) => [
        // «ملغاة»: وحدات أُلغي عقدها. والمؤرشفة في صفحة «الأرشيف» العامة.
        for (final option in const ['الكل', 'شاغرة', 'مؤجرة', 'مسودة', 'ملغاة'])
          PopupMenuItem(
            value: option,
            child: Text(
              option,
              textAlign: TextAlign.right,
              style: TextStyle(
                fontSize: 12,
                fontWeight: option == _unitStatusFilter
                    ? FontWeight.w900
                    : FontWeight.w600,
                color: option == _unitStatusFilter
                    ? _kPropertyColor
                    : const Color(0xFF022E2A),
              ),
            ),
          ),
      ],
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(
            _unitStatusFilter,
            style: const TextStyle(
              fontSize: 11,
              fontWeight: FontWeight.w800,
              color: _kPropertyColor,
            ),
          ),
          const Icon(
            Icons.keyboard_arrow_down_rounded,
            size: 16,
            color: _kPropertyColor,
          ),
        ],
      ),
    );
  }

  /// عدد عناصر القسم المفتوح — يظهر في شريط "العناصر".
  int _realEstateTabCount(_AssetItem item) => switch (_selectedTab) {
    0 => item.propertyMeta.length,
    1 => item.units.length,
    2 => _financeTab == 0
        ? _filteredPaymentsCount
        : _financeEntries(
            _financeTab == 1 ? _entryKindRevenue : _entryKindExpense,
          ).length,
    3 => _assetFollowUps.length,
    4 => _entriesByKind[_entryKindMaintenance]?.length ?? 0,
    5 => _docsFilteredCount,
    6 => 1 + _unitContracts.length,
    7 => item.annexes.length,
    8 => _allCheques()
        .where(
          (entry) =>
              _propChequeState == 'الكل' ||
              chequeStateOf(entry.row) == _propChequeState,
        )
        .length,
    _ => 0,
  };

  int _activityTabCount(_AssetItem item) => switch (_selectedTab) {
    1 => _isBranchActivity ? item.employees.length : _branchRecords.length,
    _kActivityLeaseTab => _activityContract == null ? 0 : 1,
    2 => _financeTab == 0
        ? _filteredPaymentsCount
        : _financeEntries(
            _financeTab == 1 ? _entryKindRevenue : _entryKindExpense,
          ).length,
    3 => _assetFollowUps.length,
    4 => _entriesByKind[_entryKindMaintenance]?.length ?? 0,
    5 => _docsFilteredCount,
    6 => 1 + item.employees.length,
    7 => item.annexes.length,
    _ => 0,
  };

  int _equipmentTabCount() => switch (_selectedTab) {
    1 => _equipPayments.length,
    2 => _financeTab == 0
        ? _filteredPaymentsCount
        : _financeEntries(
            _financeTab == 1 ? _entryKindRevenue : _entryKindExpense,
          ).length,
    3 => _assetFollowUps.length,
    4 => _entriesByKind[_entryKindMaintenance]?.length ?? 0,
    5 => _docsFilteredCount,
    7 => _item.annexes.length,
    8 => _allCheques()
        .where(
          (entry) =>
              _propChequeState == 'الكل' ||
              chequeStateOf(entry.row) == _propChequeState,
        )
        .length,
    _ => 0,
  };

  /// حقل البحث الموحّد تحت صندوق التفاصيل — يصفّي محتوى القسم المفتوح.
  Widget _detailSearchField(String sectionLabel) {
