  /// سطر تركيبة الوحدات التوضيحي: "3 شقة · 2 استديو · 2 محل".
  /// هل تطابق الوحدة نص البحث المكتوب في مستطيل البحث أعلى الصفحة؟
  bool _unitMatchesSearch(_PropertyUnit unit) {
    // المفوَّض على وحدات بعينها: الخادم يرسل وحداته وحدها.
    final query = _searchController.text.trim();
    if (query.isEmpty) return true;
    return unit.name.contains(query) ||
        unit.type.contains(query) ||
        unit.unitNumber.contains(query) ||
        unit.status.contains(query);
  }

  /// هل تنتمي الوحدة إلى النوع (أو الحالة) المفتوح من بطاقة الوحدات؟
  bool _unitMatchesOpenType(_PropertyUnit unit) {
    final open = _openUnitType;
    if (open == null) return true;
    if (open == _kVacantUnitsKey) {
      return _effectiveUnitStatus(unit) == 'شاغرة';
    }
    return unit.type == open;
  }

  /// مجموع مبالغ نوع إدخالات (حقل المبلغ يختلف باختلاف النوع).
  double _sumEntries(String kind, String amountField) {
    var total = 0.0;
    for (final entry in _entriesByKind[kind] ?? const []) {
      total +=
          double.tryParse(
            (entry[amountField] ?? '').replaceAll(',', '').trim(),
          ) ??
          0;
    }
    return total;
  }

  /// بطاقة "صافي الربح" — منطقها المحدد:
  /// صافي الربح = (الإيرادات المسجلة + الإيجارات المسجلة في الوحدات)
  ///               − المصروفات.
  /// تسجيل الإيرادات نفسه يتم من داخل البطاقة، فلا يوجد قسم "إيرادات"
  /// منفصل بعد الآن.
  Widget _buildNetProfitCard() {
    final revenues = _sumEntries(_entryKindRevenue, 'المبلغ');
    final rents = _sumEntries(_entryKindRental, 'قيمة الإيجار');
    final expenses = _sumEntries(_entryKindExpense, 'المبلغ');
    final net = revenues + rents - expenses;
    final netColor = net >= 0
        ? const Color(0xFF34A894)
        : const Color(0xFFC4392E);
    final revenueEntries = _entriesByKind[_entryKindRevenue] ?? const [];
    final revenueGroup = _groups.firstWhere(
      (g) => g.kind == _entryKindRevenue,
    );

    Widget row(String label, String value, {Color? color, bool bold = false}) {
      return Padding(
        padding: const EdgeInsets.symmetric(vertical: 4),
        child: Row(
          textDirection: AppTr.uiDir,
          children: [
            Expanded(
              child: Text(
                label,
                textAlign: TextAlign.right,
                style: TextStyle(
                  fontSize: bold ? 12 : 11,
                  fontWeight: bold ? FontWeight.w900 : FontWeight.w600,
                  color: bold
                      ? const Color(0xFF022E2A)
                      : const Color(0xFF5C6B68),
                ),
              ),
            ),
            Text(
              value,
              style: TextStyle(
                fontSize: bold ? 13 : 12,
                fontWeight: FontWeight.w900,
                color: color ?? const Color(0xFF022E2A),
              ),
            ),
          ],
        ),
      );
    }

    return Container(
      padding: const EdgeInsets.all(14),
      decoration: BoxDecoration(
        color: AppTheme.surface,
        borderRadius: BorderRadius.circular(AppTheme.rField),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            textDirection: AppTr.uiDir,
            children: [
              const Icon(
                Icons.trending_up_rounded,
                size: 18,
                color: Color(0xFF34A894),
              ),
              const SizedBox(width: 8),
              const Expanded(
                child: Text(
                  'صافي الربح',
                  textAlign: TextAlign.right,
                  style: TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w900,
                    color: Color(0xFF022E2A),
                  ),
                ),
              ),
              TextButton.icon(
                onPressed: () => _openActionForm(revenueGroup),
                icon: const Icon(Icons.add_rounded, size: 16),
                label: const Text('تسجيل إيراد'),
              ),
            ],
          ),
          const SizedBox(height: 4),
          row('الإيرادات المسجلة', revenues.toStringAsFixed(2)),
          row('إيرادات الإيجارات (من قسم الوحدات)', rents.toStringAsFixed(2)),
          row(
            'المصروفات (تُخصم)',
            '- ${expenses.toStringAsFixed(2)}',
            color: const Color(0xFFC4392E),
          ),
          const Divider(height: 18, color: Color(0xFFF2F6F5)),
          row(
            'صافي الربح = الإيرادات + الإيجارات − المصروفات',
            net.toStringAsFixed(2),
            color: netColor,
            bold: true,
          ),
          if (revenueEntries.isNotEmpty) ...[
            const Divider(height: 18, color: Color(0xFFF2F6F5)),
            const Align(
              alignment: Alignment.centerRight,
              child: Text(
                'الإيرادات المسجلة',
                style: TextStyle(
                  fontSize: 11,
                  fontWeight: FontWeight.w800,
                  color: Color(0xFF2C3B38),
                ),
              ),
            ),
            const SizedBox(height: 4),
            for (var i = 0; i < revenueEntries.length; i++)
              InkWell(
                onTap: () => _openActionForm(
                  revenueGroup,
                  existing: revenueEntries[i],
                  editIndex: i,
                ),
                child: Padding(
                  padding: const EdgeInsets.symmetric(vertical: 5),
                  child: Row(
                    textDirection: AppTr.uiDir,
                    children: [
                      Expanded(
                        child: Text(
                          revenueEntries[i]['المصدر']?.isNotEmpty == true
                              ? revenueEntries[i]['المصدر']!
                              : 'إيراد',
                          textAlign: TextAlign.right,
                          style: const TextStyle(
                            fontSize: 11,
                            fontWeight: FontWeight.w700,
                          ),
                        ),
                      ),
                      Text(
                        revenueEntries[i]['المبلغ'] ?? '0',
                        style: const TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w900,
                          color: Color(0xFF34A894),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
          ],
        ],
      ),
    );
  }

  /// مجال البحث في «إدارة الشيكات»: الاسم أو رقم الشيك أو التاريخ.
  /// كان البحث لا يمسّ الشيكات أصلًا، فيُكتب النص ولا يتغيّر شيء.
  static const List<String> _chequeScopes = [
    'الاسم',
    'رقم الشيك',
    'التاريخ',
  ];
  String _chequeScope = 'الاسم';

  /// هل يطابق الشيك نص البحث ضمن مجال بعينه؟
  bool _chequeMatchesScope(
    _ChequeEntry entry,
    String scope,
  ) {
    final query = _searchController.text.trim();
    if (query.isEmpty) return true;
    final haystack = switch (scope) {
      'رقم الشيك' => entry.row[LeaseContractData.kPaymentCheque] ?? '',
      'التاريخ' =>
        '${entry.row[LeaseContractData.kPaymentDue] ?? ''} '
            '${entry.row[LeaseContractData.kPaymentChequeDate] ?? ''}',
      _ => '${entry.tenant} ${entry.unit}',
    };
    return haystack.toLowerCase().contains(query.toLowerCase());
  }

  /// فلاتر «إدارة الشيكات» في صفحة العقار — نفس نافذة صفحة الوحدة.
  final Map<String, String> _propChequeFilters = <String, String>{};

  /// فلتر حالة الشيك في سطر عنوان «إدارة الشيكات».
  String _propChequeState = 'الكل';

  bool _chequeMatchesSearch(_ChequeEntry entry) => chequeRowMatches(
    _propChequeFilters,
    _searchController.text,
    entry.row,
    personName: '${entry.tenant} ${entry.unit}',
    contractNo: leaseContractNumber(entry.contract),
  );

  Future<void> _openPropChequeFilters() async {
    final next = await showChequeFiltersSheet(context, _propChequeFilters);
    if (!mounted || next == null) return;
    setState(() {
      _propChequeFilters
        ..clear()
        ..addAll(next);
    });
  }

  /// شريط الفلاتر تحت البحث: زر النافذة بعدّاده، و«امسح» حين يعمل فلتر.
  Widget _propChequeFilterBar() {
    return Padding(
      padding: const EdgeInsets.fromLTRB(14, 0, 14, 8),
      child: chequeFilterBar(
        active: chequeActiveFilterCount(_propChequeFilters),
        onOpen: _openPropChequeFilters,
        onClear: () => setState(_propChequeFilters.clear),
      ),
    );
  }

  /// رقاقات تحديد مجال البحث تحت مستطيل البحث، وبجانب كل واحدة عدد ما
  /// يطابقها من الشيكات بنص البحث الحالي.
  /// نفس الرقاقات لكن بهوامش الشريط العلوي، تحت مستطيل البحث مباشرة.
  Widget _chequeScopeChipsBar() => Padding(
    padding: const EdgeInsets.fromLTRB(14, 0, 14, 8),
    child: _chequeScopeChips(_allCheques()),
  );

  Widget _chequeScopeChips(
    List<_ChequeEntry> all,
  ) => Padding(
    padding: const EdgeInsets.only(bottom: 0),
    child: Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        // توضيح: هذه رقاقات تختار مجال البحث، لا حقولًا يُكتب داخلها.
        const Padding(
          padding: EdgeInsets.only(bottom: 6),
          child: Text(
            'ابحث بواسطة — اختر المجال ثم اكتب في مستطيل البحث أعلاه',
            textAlign: TextAlign.right,
            style: TextStyle(
              fontSize: 10.5,
              fontWeight: FontWeight.w700,
              color: Color(0xFF5C6B68),
            ),
          ),
        ),
        Row(
      textDirection: AppTr.uiDir,
      children: [
        for (final scope in _chequeScopes)
          Padding(
            padding: const EdgeInsetsDirectional.only(end: 8),
            child: _ProjectsFilterChip(
              title: scope,
              count: all
                  .where((entry) => _chequeMatchesScope(entry, scope))
                  .length,
              selected: _chequeScope == scope,
              onTap: () => setState(() => _chequeScope = scope),
            ),
          ),
      ],
        ),
      ],
    ),
  );

  /// كل شيكات عقود وحدات هذا العقار مجمّعة — مصدر قسم «إدارة الشيكات».
  List<_ChequeEntry> _allCheques() {
    final out = <_ChequeEntry>[];
    for (final contract in _unitContracts) {
      final lease = LeaseContractData.decode(contract.notes);
      for (final row in lease.cheques) {
        out.add((
          tenant: contract.tenantName ?? '',
          unit: contract.unitName ?? 'وحدة',
          row: row,
          contract: contract,
        ));
      }
    }
    out.sort((a, b) {
      final da = DateTime.tryParse(a.row[LeaseContractData.kPaymentDue] ?? '');
      final db = DateTime.tryParse(b.row[LeaseContractData.kPaymentDue] ?? '');
      if (da == null && db == null) return 0;
      if (da == null) return 1;
      if (db == null) return -1;
      return da.compareTo(db);
    });
    return out;
  }

  /// تعديل بيانات العقار الرسمية (المدينة، المنطقة، حوض، قطعة، رقم
  /// العقار، معرف العقار...) — نفس حقول عقد الإيجار الرسمي.
  Future<void> _openPropertyMetaSheet() async {
    // حقول عقد الإيجار الرسمية + رقما حسابَي المياه والكهرباء.
    const fields = <LeaseFieldSpec>[
      ...LeaseContractData.propertyFields,
      LeaseFieldSpec('رقم حساب المياه', 'رقم حساب المياه'),
      LeaseFieldSpec('رقم حساب الكهرباء', 'رقم حساب الكهرباء'),
    ];
    final controllers = <String, TextEditingController>{
      for (final spec in fields)
        spec.key: TextEditingController(text: _item.propertyMeta[spec.key] ?? ''),
    };
    final saved = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(AppTheme.rCard)),
      ),
      builder: (sheetContext) {
        return Directionality(
          textDirection: AppTr.uiDir,
          child: StatefulBuilder(
            builder: (context, setSheetState) => Padding(
            padding: EdgeInsets.fromLTRB(
              16,
              14,
              16,
              MediaQuery.of(sheetContext).viewInsets.bottom + 16,
            ),
            child: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  const Text(
                    'بيانات العقار الرسمية',
                    textAlign: TextAlign.right,
                    style: TextStyle(
                      fontSize: 13,
                      fontWeight: FontWeight.w900,
                      color: Color(0xFF022E2A),
                    ),
                  ),
                  const SizedBox(height: 4),
                  const Text(
                    'تُستعمل تلقائيًا في كل عقد إيجار لوحدات هذا العقار.',
                    textAlign: TextAlign.right,
                    style: TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w600,
                      color: Color(0xFF5C6B68),
                    ),
                  ),
                  const SizedBox(height: 12),
                  for (final spec in fields) ...[
                    if (spec.options.isNotEmpty)
                      DropdownButtonFormField<String>(
                        initialValue:
                            spec.options.contains(controllers[spec.key]!.text)
                            ? controllers[spec.key]!.text
                            : null,
                        isExpanded: true,
                        decoration: _propertyInputDecorationShared(spec.label),
                        items: [
                          for (final option in spec.options)
                            DropdownMenuItem(
                              value: option,
                              child: Text(
                                option,
                                textAlign: AppTr.alignEnd,
                              ),
                            ),
                        ],
                        onChanged: (value) => setSheetState(
                          () => controllers[spec.key]!.text = value ?? '',
                        ),
                      )
                    else
                      TextField(
                        controller: controllers[spec.key],
                        textAlign: AppTr.alignEnd,
                        maxLines: spec.multiline ? 2 : 1,
                        keyboardType: spec.numeric
                            ? const TextInputType.numberWithOptions(
                                decimal: true,
                              )
                            : TextInputType.text,
                        decoration: _propertyInputDecorationShared(spec.label),
                      ),
                    const SizedBox(height: 9),
                  ],
                  const SizedBox(height: 4),
                  FilledButton(
                    onPressed: () => Navigator.of(sheetContext).pop(true),
                    child: const Text('حفظ البيانات'),
                  ),
                ],
              ),
            ),
            ),
          ),
        );
      },
    );
    final meta = <String, String>{};
    controllers.forEach((key, controller) {
      final value = controller.text.trim();
      if (value.isNotEmpty) meta[key] = value;
    });
    for (final controller in controllers.values) {
      Future.delayed(const Duration(milliseconds: 600), controller.dispose);
    }
    if (saved != true || !mounted) return;
    _updateItem(_item.copyWith(propertyMeta: meta));
  }

  /// نافذة سريعة لإضافة فرد أو جهة — تُكتب مباشرة في «الأفراد والجهات»
  /// المشترك فتظهر هناك ويمكن سحبها في عقود الإيجار.
  /// أنواع «إضافة فرد أو جهة» — نفس أنواع «الأفراد والجهات». الشركات
  /// والجهات الحكومية والجهات الأخرى تُضاف بنموذج الجهة، والباقي بنموذج
  /// الفرد.
  static const List<(String, String)> _assetPersonTypes = [
    ('موظف', 'person_employee'),
    ('عميل', 'person_client'),
    ('مورد', 'person_supplier'),
    ('مقاول', 'person_contractor'),
    ('شريك', 'person_partner'),
    ('مندوب', 'person_representative'),
    ('استشاري', 'person_consultant'),
    ('أفراد آخرون', 'person_other'),
    ('الشركات', 'entity_company'),
    ('جهات حكومية', 'entity_government'),
    ('جهات أخرى', 'entity_other'),
  ];

  /// مفتاح ربط الفرد/الجهة بالأصل الذي أُضيف منه.
  static const String _kLinkedAssetKey = 'الأصل المرتبط';

  /// الأفراد والجهات المضافون من هذا الأصل.
  List<PeopleDirectoryEntry> _assetPeople = const [];

  /// سهم فلتر «الأفراد والجهات»: الكل أو نوع واحد.
  String _assetPersonType = 'الكل';

  Future<void> _loadAssetPeople() async {
    final entries = await PeopleDirectoryStore.load();
    if (!mounted) return;
    setState(() {
      _assetPeople = [
        for (final entry in entries)
          if ((entry.details[_kLinkedAssetKey] ?? '').trim() ==
              _item.title.trim())
            entry,
      ];
    });
  }

  /// المضافون من «+» في «الأفراد والجهات» حسب سهم الفلتر — مشترك بين
  /// العقار والنشاط والمركبة.
  List<Widget> _assetPeopleRows(Color color) => [
    for (final person in _assetPeople)
      if (_assetPersonType == 'الكل' ||
          person.categoryName == _assetPersonType ||
          (_assetPersonType == 'أفراد آخرون' &&
              person.typeKey == 'person_other') ||
          (_assetPersonType == 'جهات أخرى' &&
              person.typeKey == 'entity_other'))
        _AssetInfoRow(
          label: '${person.categoryName} — ${person.fullName}',
          value: person.firstOf(const ['رقم الهاتف', 'رقم الجوال']).isEmpty
              ? 'بلا هاتف'
              : person.firstOf(const ['رقم الهاتف', 'رقم الجوال']),
          icon: person.isEntity
              ? Icons.apartment_rounded
              : Icons.person_outline_rounded,
          color: color,
        ),
  ];

  Widget _assetPersonTypeFilter() => AppKindFilterButton(
    value: _assetPersonType,
    options: [for (final type in _assetPersonTypes) type.$1],
    accent: _kPropertyColor,
    onSelected: (value) => setState(() => _assetPersonType = value),
  );

  /// «+» في الأفراد والجهات: نموذج «إضافة فرد/جهة» نفسه في «الأفراد
  /// والجهات» مباشرة، والنوع أول خانة داخله (الشركات والجهات الحكومية
  /// والجهات الأخرى بنموذج الجهة، والباقي بنموذج الفرد).
  Future<void> _openQuickPersonSheet() async {
    await Navigator.of(context).push(
      MaterialPageRoute<void>(
        builder: (_) => PeopleManagementScreen(
          openAddForType: PeopleManagementScreen.kAddAnyType,
          linkDetails: {_kLinkedAssetKey: _item.title.trim()},
        ),
      ),
    );
    await _loadAssetPeople();
  }

  /// تعديل ملاحظات العقار.
  Future<void> _openNotesSheet() async {
    final controller = TextEditingController(text: _item.description);
    final saved = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(AppTheme.rCard)),
      ),
      builder: (sheetContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: Padding(
          padding: EdgeInsets.fromLTRB(
            16,
            14,
            16,
            MediaQuery.of(sheetContext).viewInsets.bottom + 16,
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              const Text(
                'ملاحظات العقار',
                textAlign: TextAlign.right,
                style: TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w900,
                  color: Color(0xFF022E2A),
                ),
              ),
              const SizedBox(height: 12),
              TextField(
                controller: controller,
                textAlign: AppTr.alignEnd,
                maxLines: 6,
                decoration: _propertyInputDecorationShared('اكتب ملاحظاتك هنا'),
              ),
              const SizedBox(height: 14),
              FilledButton(
                onPressed: () => Navigator.of(sheetContext).pop(true),
                child: const Text('حفظ'),
              ),
            ],
          ),
        ),
      ),
    );
    final text = controller.text.trim();
    controller.dispose();
    if (saved != true || !mounted) return;
    _updateItem(_item.copyWith(description: text));
  }

  void _showSnack(String message) {
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(message), behavior: SnackBarBehavior.floating),
    );
  }

  /// يفتح الوحدة صاحبة عقد الإيجار ليُطبع العقد من ملخصها. عقد واحد يفتح
  /// وحدته مباشرة، وأكثر من عقد يعرض قائمة لاختيار العقد المطلوب.
  Future<void> _openLeaseForPrint() async {
    final item = _item;
    _PropertyUnit? unitOf(PropertyUnitContractRecord contract) {
      for (final unit in item.units) {
        if (unit.unitKey == contract.unitKey) return unit;
      }
      return null;
    }

    if (_unitContracts.length == 1) {
      final unit = unitOf(_unitContracts.first);
      if (unit == null) {
        _showSnack('تعذّر العثور على وحدة هذا العقد');
        return;
      }
      _openUnitDetailsFor(unit);
      return;
    }

    final picked = await showModalBottomSheet<PropertyUnitContractRecord>(
      context: context,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(AppTheme.rCard),
        ),
      ),
      builder: (sheetContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: SafeArea(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const Padding(
                padding: EdgeInsets.fromLTRB(16, 16, 16, 6),
                child: Text(
                  'اختر العقد',
                  style: TextStyle(
                    fontSize: 14,
                    fontWeight: FontWeight.w900,
                    color: Color(0xFF022E2A),
                  ),
                ),
              ),
              for (final contract in _unitContracts)
                ListTile(
                  leading: const Icon(
                    Icons.description_outlined,
                    color: _kPropertyColor,
                  ),
                  title: Text(
                    contract.unitName ?? contract.unitKey,
                    textAlign: AppTr.alignEnd,
                    style: const TextStyle(
                      fontSize: 13,
                      fontWeight: FontWeight.w800,
                    ),
                  ),
                  subtitle: Text(
                    contract.tenantName ?? 'بلا مستأجر',
                    textAlign: AppTr.alignEnd,
                    style: const TextStyle(fontSize: 11),
                  ),
                  onTap: () => Navigator.pop(sheetContext, contract),
                ),
            ],
          ),
        ),
      ),
    );
    if (picked == null || !mounted) return;
    final unit = unitOf(picked);
    if (unit == null) {
      _showSnack('تعذّر العثور على وحدة هذا العقد');
      return;
    }
    _openUnitDetailsFor(unit);
  }

  /// قسم «ملخص عام»: التعريف والموقع وأرقام العقار — والبيانات الرسمية
  /// خلف زر تعديل واحد بدل مربع طويل.
  /// حالة الوحدة كما يقولها عقدها: عقد سارٍ ← مؤجرة، عقد انتهى ← شاغرة،
  /// بلا عقد ← الحالة المخزَّنة. هذا ما يصل الحلقة بين جدول العقود وبقية
  /// الشاشات.
  String _effectiveUnitStatus(_PropertyUnit unit) {
    if (unit.status.contains('ملغ')) return unit.status;
    PropertyUnitContractRecord? found;
    var draft = false;
    for (final contract in _unitContracts) {
      if (contract.unitKey != unit.unitKey) continue;
      // يوم انتهاء العقد نفسه ما زال مؤجرًا (مقارنة بالتاريخ لا بالساعة).
      if (!_contractClosed(contract) && !_contractEndedByDate(contract)) {
        // عقد ناقص محفوظ كمسودة: الوحدة لم تُؤجَّر بعد.
        if (contract.status == PropertyUnitContractRecord.statusPending) {
          draft = true;
          continue;
        }
        return 'مؤجرة';
      }
      found = contract;
    }
    if (draft) return 'مسودة';
    return found == null
        ? (unit.status == 'مؤجرة' || unit.status == 'مسودة'
              ? 'شاغرة'
              : unit.status)
        : 'شاغرة';
  }

  /// عقد محفوظ مسودة (لم يُعتمد ولم يُغلق) — نفس تعريف فلتر «مسودة» في
  /// القائمة.
  bool get _assetHasDraft => _unitContracts.any(
    (contract) =>
        contract.status == PropertyUnitContractRecord.statusPending &&
        !_contractClosed(contract),
  );

  /// لا يُلغى العقار / المركبة / النشاط وعليه عقد إيجار ساري (معتمد ولم
  /// يُسوَّ ويُغلق بعد، ولو انتهت مدته): التسوية والإلغاء من «إدارة التأجير»
  /// أولًا. null: لا مانع.
  String? get _cancelBlockedMessage {
    if (_isCancelledAsset(_item)) return null;
    final live = _unitContracts
        .where(
          (contract) =>
              !_contractClosed(contract) &&
              contract.status != PropertyUnitContractRecord.statusPending,
        )
        .toList(growable: false);
    if (live.isEmpty) return null;
    final tenants = {
      for (final contract in live)
        if ((contract.tenantName ?? '').trim().isNotEmpty)
          contract.tenantName!.trim(),
    };
    final where = switch (_item.category) {
      'equipment' => '«إدارة التأجير»',
      'activity' => '«إدارة النشاط»',
      _ => '«إدارة الإيجار» في الوحدة',
    };
    return 'لا يمكن إلغاء «${_item.title}» الآن: عليه عقد إيجار ساري'
        '${tenants.isEmpty ? '' : ' (المستأجر: ${tenants.join('، ')})'}.\n'
        'قم بتسوية عقد الإيجار الساري وإلغائه أولًا من $where، ثم ألغِ.';
  }

  /// صيانة مفتوحة («تحت الصيانة») في قسم الصيانة.
  bool get _hasOpenMaintenance =>
      (_entriesByKind[_entryKindMaintenance] ?? const <Map<String, String>>[])
          .any((e) => (e[_kMaintStateKey] ?? '') == _kMaintOpen);

  /// حالة المركبة: مؤجر أو شاغر أو صيانة — «ملغي» للعقد لا للمركبة،
  /// ومكانه السجل التاريخي.
  String get _equipStatusLabel {
    if (_isCancelledAsset(_item)) return 'ملغي';
    if (_item.status == 'مؤرشف') return 'مؤرشف';
    final base = _equipContracts.any(_contractHolds)
        ? 'مؤجر'
        // انتهت مدة العقد ولم يُلغَ / يُجدَّد بعد.
        : _equipContracts.any(_contractEndedOpen)
        ? 'منتهي العقد'
        : 'شاغر';
    // الصيانة تُضاف إلى حالة الإيجار: «شاغر / صيانة» أو «مؤجر / صيانة».
    return _hasOpenMaintenance ? '$base / صيانة' : base;
  }

  /// صيانة مفتوحة «تمنع التأجير»: لا عقد جديد ولا تجديد حتى تنتهي.
  bool get _hasBlockingMaintenance =>
      (_entriesByKind[_entryKindMaintenance] ?? const <Map<String, String>>[])
          .any(_maintBlocksLease);

  Color get _equipStatusColor => _equipStatusLabel.endsWith('صيانة')
      ? const Color(0xFFC4392E)
      : switch (_equipStatusLabel) {
    'ملغي' => const Color(0xFF8C3A32),
    'مجمّد' || 'مؤرشف' => const Color(0xFF5C6B68),
    'صيانة' || 'منتهي العقد' => const Color(0xFFC4392E),
    'شاغر' => _kVacantColor,
    _ => const Color(0xFF34A894),
  };

  String _assetStatusFromUnits(_AssetItem item) {
    // العقار المُلغى من الثلاث نقاط «ملغي»؛ وإلا شاغر أو مؤجر أو صيانة.
    if (item.category == 'real_estate' && _isCancelledAsset(item)) {
      return 'ملغي';
    }
    if (item.status == 'مؤرشف') return 'مؤرشف';
    final inMaint =
        item.needsAttention || item.status == 'صيانة' || _hasOpenMaintenance;
    String withMaint(String s) => inMaint ? '$s / صيانة' : s;
    if (item.units.isEmpty) {
      // المسودة لا تجعل العقار مؤجرًا.
      return withMaint(
        _unitContracts.any(_contractHolds)
            ? 'مؤجر'
            : _unitContracts.any(_contractEndedOpen)
            ? 'منتهي العقد'
            : 'شاغر',
      );
    }
    final leased = item.units
        .where((u) => _effectiveUnitStatus(u) == 'مؤجرة')
        .length;
    if (leased == 0) return withMaint('شاغر');
    return withMaint(leased == item.units.length ? 'مؤجر' : 'مؤجر جزئيًا');
  }

  Color _assetStatusColorFromUnits(_AssetItem item) =>
      _assetStatusFromUnits(item).endsWith('صيانة')
      ? const Color(0xFFC4392E)
      : switch (_assetStatusFromUnits(item)) {
        'ملغي' => const Color(0xFF8C3A32),
        'مجمّد' || 'مؤرشف' => const Color(0xFF5C6B68),
        'صيانة' || 'منتهي العقد' => const Color(0xFFC4392E),
        'شاغر' => _kVacantColor,
        'مؤجر جزئيًا' => _kPartlyLeasedColor,
        _ => const Color(0xFF34A894),
      };

  Widget _buildPropertySummarySection(_AssetItem item) {
    final leased = item.units
        .where(
          (u) => _effectiveUnitStatus(u) == 'مؤجرة' && !_unitIsCancelled(u),
        )
        .length;
    final vacant = item.units
        .where(
          (u) =>
              _effectiveUnitStatus(u) == 'شاغرة' ||
              _effectiveUnitStatus(u) == 'مسودة',
        )
        .length;
    String meta(String key) => (item.propertyMeta[key] ?? '').trim();
    String money(double value) =>
        '${formatMoneyValue(value)} ${AppSettings.currencySuffix}';
    // عدد الوحدات حسب ما أُضيف: «8 (5 شقة · 3 محل)».
    final byType = <String, int>{};
    for (final unit in item.units) {
      final type = unit.type.trim().isEmpty ? 'وحدة' : unit.type.trim();
      byType[type] = (byType[type] ?? 0) + 1;
    }
    final unitsText = byType.isEmpty
        ? '0'
        : '${item.units.length} (${byType.entries.map((e) => '${e.value} ${e.key}').join(' · ')})';
    bool ended(PropertyUnitContractRecord c) {
      final end = c.endDate;
      return _contractClosed(c) ||
          (end != null &&
              DateUtils.dateOnly(end).isBefore(DateUtils.dateOnly(DateTime.now())));
    }
    final endedContracts = _unitContracts.where(ended).length;
    final activeContracts = _unitContracts.length - endedContracts;
    var totalRent = 0.0;
    var received = 0.0;
    for (final entry in _propertyPayments) {
      totalRent += entry.payment.amountDue;
      received += entry.payment.amountPaid;
    }
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        if (_delegationSummaryCard(item.id) case final card?) card,
        // العقار المؤجر يُطبع عقده من ملخصه مباشرة: الزر يفتح وحدة العقد
        // إن كان واحدًا، وإلا يعرض قائمة العقود لاختيار أيها يُطبع.
        if (_unitContracts.isNotEmpty) ...[
          _summaryLeaseButton(_kPropertyColor, _openLeaseForPrint),
          const SizedBox(height: 12),
        ],
        _AssetUnifiedCard(
          title: 'بيانات العقار',
          icon: Icons.apartment_outlined,
          color: _kPropertyColor,
          // بلا «+» في الترويسة: البيانات الرسمية تُضاف من قائمة الثلاث
          // نقاط أعلى الصفحة («إضافة بيانات العقار الرسمية»).
          children: [
            for (final row in <(String, String, IconData)>[
              (
                'نوع العقار',
                meta(_kPropertyTypeKey).isEmpty
                    ? item.subType
                    : meta(_kPropertyTypeKey),
                Icons.category_outlined,
              ),
              ('مالك العقار', item.owner, Icons.person_outline_rounded),
              ('اسم العقار', item.title, Icons.badge_outlined),
              ('المدينة', meta('المدينة'), Icons.location_city_outlined),
              (
                'المنطقة',
                meta('المنطقة').isEmpty ? item.locationOrType : meta('المنطقة'),
                Icons.location_on_outlined,
              ),
              ('نوع العين', meta('نوع العين'), Icons.home_outlined),
              (
                'مساحة العين',
                meta('مساحة العين').isEmpty ? '' : '${meta('مساحة العين')} م²',
                Icons.square_foot_rounded,
              ),
              ('رقم العقار', meta('رقم العقار'), Icons.tag_rounded),
              (
                'رقم حساب المياه',
                meta('رقم حساب المياه'),
                Icons.water_drop_outlined,
              ),
              (
                'رقم حساب الكهرباء',
                meta('رقم حساب الكهرباء'),
                Icons.bolt_outlined,
              ),
              (
                'عدادات الكهرباء',
                _metersSummary(
                  meta(_kElectricCountKey),
                  meta(_kElectricMetersKey),
                ),
                Icons.bolt_rounded,
              ),
              (
                'عدادات المياه',
                _metersSummary(
                  meta(_kWaterCountKey),
                  meta(_kWaterMetersKey),
                ),
                Icons.water_drop_rounded,
              ),
            ])
              _AssetInfoRow(
                label: row.$1,
                value: row.$2.trim().isEmpty ? 'غير محدد' : row.$2,
                icon: row.$3,
                color: _kPropertyColor,
              ),
            // كل ما كُتب في صفحة بيانات العقار يظهر هنا (ما كان فارغًا لا).
            for (final row in <(String, String, IconData)>[
              ('النوع', meta(_kPropertySubTypeKey), Icons.label_outline_rounded),
              ('الوصف', item.description, Icons.notes_rounded),
              (
                'العنوان',
                item.locationOrType == 'غير محدد' ? '' : item.locationOrType,
                Icons.place_outlined,
              ),
              ('رابط الخريطة', item.mapLink, Icons.map_outlined),
              (
                'رقم عداد الكهرباء',
                meta('رقم تسجيل الوحدة'),
                Icons.bolt_outlined,
              ),
              (
                'رقم عداد المياه',
                meta('معرف العقار'),
                Icons.water_drop_outlined,
              ),
              (
                'المرافق العامة',
                item.annexes.entries
                    .map((e) => '${e.key} (${e.value})')
                    .join('، '),
                Icons.apartment_outlined,
              ),
            ])
              if (row.$2.trim().isNotEmpty)
                _AssetInfoRow(
                  label: row.$1,
                  value: row.$2,
                  icon: row.$3,
                  color: _kPropertyColor,
                ),
          ],
        ),
        const SizedBox(height: 12),
        _AssetUnifiedCard(
          title: 'ملخص العقار',
          icon: Icons.insights_outlined,
          color: _kPropertyColor,
          children: [
            _AssetInfoRow(
              label: 'عدد الوحدات',
              value: unitsText,
              icon: Icons.home_work_outlined,
              color: _kPropertyColor,
            ),
            _AssetInfoRow(
              label: 'المؤجرة',
              value: '$leased',
              icon: Icons.assignment_turned_in_outlined,
              color: AppTheme.brandMid,
            ),
            _AssetInfoRow(
              label: 'الشاغرة',
              value: '$vacant',
              icon: Icons.meeting_room_outlined,
              color: AppTheme.goldDark,
            ),
            _AssetInfoRow(
              label: 'عقود سارية',
              value: '$activeContracts',
              icon: Icons.description_outlined,
              color: _kPropertyColor,
            ),
            _AssetInfoRow(
              label: 'عقود منتهية',
              value: '$endedContracts',
              icon: Icons.event_busy_outlined,
              color: _kPropertyColor,
            ),
            _AssetInfoRow(
              label: 'إجمالي مبلغ الإيجارات',
              value: money(totalRent),
              icon: Icons.payments_outlined,
              color: _kPropertyColor,
            ),
            _AssetInfoRow(
              label: 'إجمالي المبالغ المستلمة',
              value: money(received),
              icon: Icons.call_received_rounded,
              color: AppTheme.brandMid,
            ),
            _AssetInfoRow(
              label: 'إجمالي المبالغ المتبقية',
              value: money(totalRent - received),
              icon: Icons.hourglass_bottom_rounded,
              color: AppTheme.goldDark,
            ),
            _AssetInfoRow(
              label: 'أعمال الصيانة',
              value: '${_entriesByKind[_entryKindMaintenance]?.length ?? 0}',
              icon: Icons.build_outlined,
              color: _kPropertyColor,
            ),
          ],
        ),
      ],
    );
  }

  /// قسم «إدارة الشيكات»: كل شيكات دفعات الإيجار في هذا العقار.
  Widget _buildChequesSection() {
    final allCheques = _allCheques();
    final cheques = allCheques
        .where(_chequeMatchesSearch)
        .where(
          (entry) =>
              _propChequeState == 'الكل' ||
              chequeStateOf(entry.row) == _propChequeState,
        )
        .toList(growable: false);
    if (allCheques.isEmpty) {
      return _DetailHintCard(
        message: _item.category == 'activity'
            ? 'لا توجد شيكات مسجّلة بعد.'
            : 'لا توجد شيكات مسجّلة — تُسجَّل الشيكات داخل «عقد الإيجار '
                  'الكامل» في جدول طريقة سداد دفعات الإيجار، وتظهر هنا '
                  'مجمّعة لكل وحدات العقار.',
      );
    }
    // مبلغ الشيك شاملًا الضريبة — هو ما كُتب في الشيك فعلًا.
    final total = cheques.fold<double>(
      0,
      (sum, item) =>
          sum +
          LeaseContractData.decode(item.contract.notes)
              .paymentTotalOf(item.row),
    );
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        // الإجمالي أولًا، تحت العنوان مباشرة — ثم الشيكات.
        Container(
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: AppTheme.brandSoft,
            borderRadius: BorderRadius.circular(AppTheme.rInner),
          ),
          child: Row(
            textDirection: AppTr.uiDir,
            children: [
              const Expanded(
                child: Text(
                  'إجمالي قيمة الشيكات',
                  textAlign: TextAlign.right,
                  style: TextStyle(
                    fontSize: 12,
                    fontWeight: FontWeight.w800,
                    color: Color(0xFF46534F),
                  ),
                ),
              ),
              Text(
                total.toStringAsFixed(2),
                style: const TextStyle(
                  fontSize: 14,
                  fontWeight: FontWeight.w900,
                  color: Color(0xFF04413B),
                ),
              ),
            ],
          ),
        ),
        const SizedBox(height: 10),
        if (cheques.isEmpty)
          const Padding(
            padding: EdgeInsets.symmetric(vertical: 18),
            child: Text(
              'لا يوجد شيك مطابق للبحث',
              textAlign: TextAlign.center,
              style: TextStyle(
                fontSize: 12,
                fontWeight: FontWeight.w700,
                color: Color(0xFF5C6B68),
              ),
            ),
          ),
        for (final entry in cheques)
          InkWell(
            borderRadius: BorderRadius.circular(AppTheme.rInner),
            onTap: () async {
              final repo = widget.repository;
              if (repo == null) return;
              final changed = await openChequeActions(
                context: context,
                repository: repo,
                contract: entry.contract,
                row: entry.row,
                holder: entry.tenant,
              );
              if (changed && mounted) await _loadUnitContractsFromRemote();
            },
            child: Container(
            margin: const EdgeInsets.only(bottom: 10),
            padding: const EdgeInsets.all(12),
            decoration: BoxDecoration(
              color: AppTheme.surface,
              borderRadius: BorderRadius.circular(AppTheme.rInner),
            ),
            child: Row(
              textDirection: AppTr.uiDir,
              children: [
                AppIconTile(
                  icon: Icons.receipt_long_outlined,
                  color: (entry.row[LeaseContractData.kPaymentStatus] ?? '') ==
                          'مسددة'
                      ? AppTheme.brandMid
                      : AppTheme.goldDark,
                  size: AppTheme.iconTileSmall,
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        'شيك ${entry.row[LeaseContractData.kPaymentCheque] ?? ''}'
                        ' · ${formatMoneyValue(LeaseContractData.decode(entry.contract.notes).paymentTotalOf(entry.row))}',
                        maxLines: 3,
                        textAlign: AppTr.alignEnd,
                        style: const TextStyle(
                          fontSize: 12,
                          fontWeight: FontWeight.w900,
                          color: Color(0xFF022E2A),
                        ),
                      ),
                      const SizedBox(height: 3),
                      Text(
                        '${entry.tenant.isEmpty ? entry.unit : '${entry.tenant} · ${entry.unit}'}'
                        ' · ${entry.row[LeaseContractData.kPaymentBank] ?? 'بلا بنك'}'
                        ' · استحقاق ${entry.row[LeaseContractData.kPaymentDue] ?? 'غير محدد'}'
                        ' · ${entry.row[LeaseContractData.kPaymentFee] ?? ''}',
                        maxLines: 2,
                        textAlign: AppTr.alignEnd,
                        style: const TextStyle(
                          fontSize: 11,
                          fontWeight: FontWeight.w600,
                          color: Color(0xFF46534F),
                          height: 1.4,
                        ),
                      ),
                    ],
                  ),
                ),
                Text(
                  chequeStateLabel(chequeStateOf(entry.row)),
                  style: TextStyle(
                    fontSize: 11,
                    fontWeight: FontWeight.w900,
                    color: chequeStateColor(chequeStateOf(entry.row)),
                  ),
                ),
              ],
            ),
          ),
          ),
      ],
    );
  }

  /// عنوان القسم: الاسم على اليمين و«+» ناعم على اليسار وخط فاصل تحته.
  Widget _sectionHead(
    String title, {
    VoidCallback? onAdd,
    String tooltip = 'إضافة',
    String? trailingText,
    Widget? action,
  }) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Padding(
          padding: const EdgeInsets.only(bottom: 10),
          child: Row(
            textDirection: AppTr.uiDir,
            children: [
              Expanded(
                child: Text(
                  trailingText == null ? title : '$title: $trailingText',
                  textAlign: AppTr.alignEnd,
                  maxLines: 3,
                  style: const TextStyle(
                    fontSize: 15,
                    fontWeight: FontWeight.w900,
                    color: Color(0xFF022E2A),
                  ),
                ),
              ),
              if (action != null) action,
              if (onAdd != null)
                InkWell(
                  onTap: onAdd,
                  borderRadius: BorderRadius.circular(14),
                  child: Container(
                    width: 38,
                    height: 38,
                    decoration: BoxDecoration(
                      color: AppTheme.brandSoft,
                      borderRadius: BorderRadius.circular(14),
                    ),
                    child: Tooltip(
                      message: AppTr.tr(tooltip),
                      child: const Icon(
                        Icons.add_rounded,
                        size: 21,
                        color: Color(0xFF022E2A),
                      ),
                    ),
                  ),
                ),
            ],
          ),
        ),
        const Divider(height: 1, thickness: 1, color: AppTheme.line),
        const SizedBox(height: 14),
      ],
    );
  }

  /// أوامر الإضافة الخاصة بالقسم المفتوح، معروضة في قائمة الثلاث نقاط.
  ///
  /// «ملخص عام» و«الوحدات» كان لكلٍّ منهما «+» في رأس القسم بينما القائمة
  /// أعلى الصفحة تحمل بقية الأوامر — زرّان لمعنى واحد في شاشة واحدة.
  List<ThreeDotExtraAction> _topMenuExtraActions() {
    // المركبات: «تعديل بيانات» في مكانه بالقائمة (تعديل، مشاركة، إلغاء،
    // أرشيف، تفويض آخرين). في «إدارة التأجير» وحدها: «تعديل عقد التأجير» —
    // «العقد كامل» للعرض والمشاركة فقط.
    if (_item.category == 'equipment') {
      final contract = _equipContract;
      final delegation = DelegatedAssets.of(_item.id);
      if (_selectedTab != 1 ||
          contract == null ||
          !_isLeaseContract(contract) ||
          _contractClosed(contract) ||
          (delegation != null && !delegation.canEdit)) {
        return const [];
      }
      return [
        ThreeDotExtraAction(
          label: 'تعديل عقد التأجير',
          icon: Icons.edit_note_rounded,
          onSelected: () => _openEquipContractForm(existing: contract),
        ),
      ];
    }
    if (_item.category == 'activity') {
      // النشاط الرئيسي: «إضافة فرع» مع «الفروع» كما «إضافة وحدة» مع
      // «الوحدات»، و«إضافة موظف» مع «الأفراد والجهات».
      if (_isBranchActivity) return const [];
      return switch (_selectedTab) {
        6 => [
          ThreeDotExtraAction(
            label: 'إضافة موظف',
            icon: Icons.badge_outlined,
            onSelected: () => _addEmployee(),
          ),
        ],
        _ => const [],
      };
    }
    if (_item.category != 'real_estate') return const [];
    return switch (_selectedTab) {
      0 => [
        ThreeDotExtraAction(
          label: 'إضافة بيانات العقار الرسمية',
          icon: Icons.assignment_outlined,
          onSelected: _openPropertyMetaSheet,
        ),
      ],
      // «إضافة وحدة» حُذفت من الثلاث نقاط: «+» في الوحدات يكفي.
      _ => const [],
    };
  }

  /// إجراء زر «+» لكل قسم — واحد فقط، مقابل العنوان.
  VoidCallback? _sectionAddAction() {
    final category = _item.category;
    if (category == 'real_estate') {
      switch (_selectedTab) {
        // «ملخص عام» و«الوحدات»: لا «+» في رأس القسم — الإضافة في قائمة
        // الثلاث نقاط أعلى الصفحة، انظر [_topMenuExtraActions].
        case 0:
        case 1:
          return null;
        // الحركات المالية: لا «+» في العنوان — كان يفتح «المصاريف» حتى من
        // «دخل إضافي». الإضافة من «+» سطر الإجمالي داخل كل باب، والعنوان
        // يحمل الفلتر.
        case 2:
          return null;
        case 3: // المتابعة والتخطيط — يُختار النوع ثم يُكتب البند
          return _addAssetFollowUp;
        case 4: // الصيانة — نفس نموذج صيانة الوحدة
          return () => _openPropertyMaintenance();
        case 5: // المستندات
          return () => _openActionForm(
            _groups.firstWhere((g) => g.kind == _entryKindDocument),
          );
        case 6: // الأفراد والجهات
          return _openQuickPersonSheet;
        case 7: // المرافق العامة
          return _addFacilities;
        case 8: // إدارة الشيكات — لا «+»: الشيك دفعة في عقد وحدة بعينها
          return null;
        case 9: // الملاحظات
          return _openNotesSheet;
      }
      return null;
    }
    if (category == 'activity') {
      switch (_selectedTab) {
        // الفرع: «+» يضيف موظفًا في «إدارة النشاط». النشاط الرئيسي: «+»
        // في سطر «الفروع» يضيف فرعًا.
        case 1:
          return _isBranchActivity ? () => _addEmployee() : _addBranch;
        case _kActivityLeaseTab: // إدارة النشاط — عقد الإيجار إن لم يوجد
          return _activityContract == null ? () => _openActivityLease() : null;
        case 3: // المتابعة والتخطيط — يُختار النوع ثم يُكتب البند
          return _addAssetFollowUp;
        case 4: // الصيانة — نفس نموذج صيانة العقار
          return () => _openPropertyMaintenance();
        case 5:
          return () => _openActionForm(
            _groups.firstWhere((g) => g.kind == _entryKindDocument),
          );
        case 6:
          return _openQuickPersonSheet;
        case 7:
          return _addActivityAsset;
        case 9:
          return _openNotesSheet;
      }
      return null;
    }
    if (category == 'equipment') {
      switch (_selectedTab) {
        case 1: // إدارة التأجير — «+» لعقد جديد حين لا يوجد عقد نشط
          return _equipContract == null ? () => _openEquipContractForm() : null;
        case 2: // الحركات المالية — «+» داخل كل باب كالعقار
          return null;
        case 3: // المتابعة والتخطيط
          return _addAssetFollowUp;
        case 4: // الصيانة — نفس نموذج صيانة العقار
          return () => _openPropertyMaintenance();
        case 5: // المستندات
          return () => _openActionForm(
            _groups.firstWhere((g) => g.kind == _entryKindDocument),
          );
        case 6: // الأفراد والجهات
          return _openQuickPersonSheet;
        case 7: // الإكسسوارات
          return () => _addActivityAsset(title: 'إضافة إكسسوار');
      }
      return null;
    }
    switch (_selectedTab) {
      case 1:
        return () => _openActionForm(
          _groups.firstWhere((g) => g.kind == _entryKindMaintenance),
        );
      case 3:
        return () => _openActionForm(
          _groups.firstWhere((g) => g.kind == _entryKindDocument),
        );
    }
    return null;
  }

  Widget _buildRealEstateTabContent(_AssetItem item) {
    if (_selectedTab < 0) return const _ChooseHint();
    switch (_selectedTab) {
      case 0: // ملخص عام — كل ما يتعلق بالعقار في مكان واحد
        return _buildPropertySummarySection(item);
      case 8: // إدارة الشيكات — كل شيكات عقود وحدات هذا العقار
        return _buildChequesSection();
      case 1: // الوحدات
        if (item.units.isEmpty) {
          return const _DetailHintCard(
            message: 'لا توجد وحدات بعد — استخدم زر + إضافة لإضافة شقة أو محل جديد لهذا العقار.',
          );
        }
        final groups = _multiUnitGroups();
        final groupedUnitKeys = groups.values
            .expand((units) => units.map((u) => u.unitKey))
            .toSet();
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            // زر «عقد متعدد الوحدات» انتقل إلى داخل الوحدة الشاغرة نفسها،
            // مدموجًا مع زر إنشاء عقد الإيجار الكامل.
            // بلا صندوق تركيبة: الوحدات تظهر مباشرة بطاقةً لكل وحدة
            // (اسمها وتفاصيلها وحالتها مؤجرة/شاغرة). التركيبة بالأعداد
            // معروضة أصلًا داخل صندوق اسم العقار في الأعلى.
            // عند فتح نوع معيّن تُعرض وحداته وحدها (بما فيها المشمولة بعقد
            // متعدد الوحدات)، وإلا فالعرض الكامل كما هو.
            if (_openUnitType != null) ...[
              for (var i = 0; i < item.units.length; i++) ...[
                if (_unitMatchesOpenType(item.units[i]) &&
                    _unitMatchesSearch(item.units[i]) &&
                    _unitMatchesStatusFilter(item.units[i])) ...[
                  _UnitCard(
                    unit: item.units[i],
                    // الحالة من العقد؛ ولمس الشارة يفتح الوحدة لا يقلب حالتها.
                    status: _unitDisplayStatus(item.units[i]),
                    onToggleStatus: () => _openUnitDetails(i),
                    onTap: () => _openUnitDetails(i),
                    duesNote: _unitDuesNote(item.units[i]),
                    inMaintenance: _unitMaintOpen(item.units[i]),
                    delegatedTo: _unitDelegationLabel(item.units[i], i),
                  ),
                  const SizedBox(height: 8),
                ],
              ],
              if (!item.units.any(_unitMatchesOpenType))
                const _DetailHintCard(
                  message: 'لا توجد وحدات من هذا النوع حاليًا.',
                ),
            ] else ...[
              for (final entry in groups.entries) ...[
                _MultiUnitContractCard(
                  units: entry.value,
                  contract: _activeContractForUnit(entry.value.first.unitKey)!,
                  onTap: () => _openMultiUnitContractSummary(entry.value),
                  duesNote: _unitsDuesNote(entry.value),
                  inMaintenance: entry.value.any(_unitMaintOpen),
                  delegatedTo: [
                    for (final unit in entry.value)
                      _unitDelegationLabel(unit, item.units.indexOf(unit)),
                  ].firstWhere((label) => label.isNotEmpty, orElse: () => ''),
                ),
                const SizedBox(height: 8),
              ],
              for (var i = 0; i < item.units.length; i++) ...[
                if (!groupedUnitKeys.contains(item.units[i].unitKey) &&
                    _unitMatchesSearch(item.units[i]) &&
                    _unitMatchesStatusFilter(item.units[i])) ...[
                  _UnitCard(
                    unit: item.units[i],
                    // الحالة من العقد؛ ولمس الشارة يفتح الوحدة لا يقلب حالتها.
                    status: _unitDisplayStatus(item.units[i]),
                    onToggleStatus: () => _openUnitDetails(i),
                    onTap: () => _openUnitDetails(i),
                    duesNote: _unitDuesNote(item.units[i]),
                    inMaintenance: _unitMaintOpen(item.units[i]),
                    delegatedTo: _unitDelegationLabel(item.units[i], i),
                  ),
                  const SizedBox(height: 8),
                ],
              ],
            ],
          ],
        );
      case 2: // الحركة المالية — الدفعات الإيجارية / دخل إضافي / المصاريف
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            // «صافي الربح» في مكان مميز أعلى الحركات المالية.
            _netProfitCard(),
            const SizedBox(height: 12),
            Row(
              children: [
                _propertyFinanceChip(
                  'الدفعات الإيجارية',
                  0,
                  Icons.payments_outlined,
                ),
                const SizedBox(width: 8),
                _propertyFinanceChip(
                  'دخل إضافي',
                  1,
                  Icons.trending_up_rounded,
                ),
                const SizedBox(width: 8),
                _propertyFinanceChip(
                  'المصاريف',
                  2,
                  Icons.trending_down_rounded,
                ),
              ],
            ),
            const SizedBox(height: 12),
            if (_financeTab == 0) _historyLinkCard(_kPropertyColor),
            if (_financeTab == 0)
              if (widget.repository == null)
                const _DetailHintCard(
                  message: 'يجب حفظ العقار أولاً لعرض الدفعات الإيجارية.',
                )
              else
                RentPaymentsView(
                  repository: widget.repository!,
                  assetTitle: item.title,
                  entries: _propertyPayments,
                  onChanged: _loadPropertyPayments,
                  showHeaderRow: false,
                  unitTypeOf: _unitTypeByName,
                  filter: _paymentFilter,
                  onFilterChanged: (value) =>
                      setState(() => _paymentFilter = value),
                  emptyMessage:
                      'لا توجد دفعات إيجارية بعد — تُولَّد من عقد الإيجار '
                      'الكامل لكل وحدة (تفاصيل الوحدة ← إدارة الإيجار).',
                )
            else if (_financeTab == 1)
              _financeEntriesPanel(_entryKindRevenue)
            else
              _financeEntriesPanel(_entryKindExpense),
          ],
        );
      case 3: // المتابعة والتخطيط — مهمة، موعد، عادة يومية، تذكير، ملاحظات
        return _assetFollowUpsSection();
      case 4: // الصيانة — نفس نموذج صيانة الوحدة وشكل قائمتها
        return _propertyMaintenanceList();
      case 5: // المستندات — كل نوع في مكانه، وفلتر النوع في سطر العنوان
        // سند ملكية العقار هنا مع المستندات (كان في «الوحدات»).
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Container(
              padding: const EdgeInsets.fromLTRB(14, 4, 14, 4),
              decoration: BoxDecoration(
                color: AppTheme.surface,
                borderRadius: BorderRadius.circular(AppTheme.rField),
              ),
              child: Row(
                textDirection: AppTr.uiDir,
                children: [
                  const Icon(
                    Icons.description_outlined,
                    size: 17,
                    color: _kPropertyColor,
                  ),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      'سند الملكية: ${item.serialNumber.isEmpty ? 'غير محدد' : item.serialNumber}',
                      textAlign: TextAlign.right,
                      style: const TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.w800,
                        color: Color(0xFF2C3B38),
                      ),
                    ),
                  ),
                  TextButton(
                    onPressed: _openDeedSheet,
                    child: Text(
                      item.serialNumber.isEmpty ? 'إضافة' : 'تعديل',
                    ),
                  ),
                ],
              ),
            ),
            // عقد الإيجار مع المستندات أيضًا (كما في الملخص العام).
            if (_unitContracts.isNotEmpty) ...[
              const SizedBox(height: 10),
              OutlinedButton.icon(
                onPressed: _openLeaseForPrint,
                style: OutlinedButton.styleFrom(
                  foregroundColor: _kPropertyColor,
                  minimumSize: const Size.fromHeight(46),
                ),
                icon: const Icon(Icons.description_outlined, size: 19),
                label: const Text('عقد الإيجار'),
              ),
            ],
            const SizedBox(height: 12),
            _documentsByType(),
          ],
        );
      case 6: // الأفراد والجهات — المالك والمستأجرون المرتبطون بالعقار
        return _AssetUnifiedCard(
          showHeader: false,
          title: 'الأفراد والجهات',
          icon: Icons.people_alt_outlined,
          color: _kPropertyColor,
          onAdd: _openQuickPersonSheet,
          addTooltip: 'إضافة فرد أو جهة',
          children: [
            _AssetInfoRow(
              label: 'المالك',
              value: item.owner,
              icon: Icons.person_outline_rounded,
              color: _kPropertyColor,
            ),
            if (_unitContracts.isEmpty)
              const Padding(
                padding: EdgeInsets.symmetric(vertical: 6),
                child: Align(
                  alignment: Alignment.centerRight,
                  child: Text(
                    'لا يوجد مستأجرون بعد — يُضاف المستأجر من تفاصيل '
                    'الوحدة نفسها.',
                    textAlign: TextAlign.right,
                    style: TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w600,
                      color: Color(0xFF5C6B68),
                      height: 1.5,
                    ),
                  ),
                ),
              )
            else
              for (final contract in _unitContracts)
                _AssetInfoRow(
                  label: 'مستأجر — ${contract.tenantName ?? 'بلا اسم'}',
                  value: (contract.tenantPhone ?? '').isEmpty
                      ? 'بلا هاتف'
                      : contract.tenantPhone!,
                  icon: Icons.badge_outlined,
                  color: _kPropertyColor,
                ),
            // المضافون من «+» هنا، حسب سهم الفلتر.
            for (final person in _assetPeople)
              if (_assetPersonType == 'الكل' ||
                  person.categoryName == _assetPersonType ||
                  (_assetPersonType == 'أفراد آخرون' &&
                      person.typeKey == 'person_other') ||
                  (_assetPersonType == 'جهات أخرى' &&
                      person.typeKey == 'entity_other'))
                _AssetInfoRow(
                  label: '${person.categoryName} — ${person.fullName}',
                  value: person.firstOf(const ['رقم الهاتف', 'رقم الجوال']).isEmpty
                      ? 'بلا هاتف'
                      : person.firstOf(const ['رقم الهاتف', 'رقم الجوال']),
                  icon: person.isEntity
                      ? Icons.apartment_rounded
                      : Icons.person_outline_rounded,
                  color: _kPropertyColor,
                ),
          ],
        );
      case 7: // المرافق العامة المسجلة مع العقار
        return _AssetUnifiedCard(
          showHeader: false,
          title: 'المرافق العامة',
          icon: Icons.apartment_outlined,
          color: _kPropertyColor,
          onAdd: _addFacilities,
          addTooltip: 'إضافة مرفق',
          children: [
            if (item.annexes.isEmpty)
              const Padding(
                padding: EdgeInsets.symmetric(vertical: 6),
                child: Align(
                  alignment: Alignment.centerRight,
                  child: Text(
                    'لا توجد مرافق مسجّلة بعد — تُضاف المرافق العامة من '
                    'شاشة إضافة الوحدات والمرافق (زر + إضافة في قسم '
                    'الوحدات).',
                    textAlign: TextAlign.right,
                    style: TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w600,
                      color: Color(0xFF5C6B68),
                      height: 1.5,
                    ),
                  ),
                ),
              )
            else
              for (final annex in item.annexes.entries)
                _AssetInfoRow(
                  label: annex.key,
                  value: 'العدد: ${annex.value}',
                  icon: Icons.check_circle_outline_rounded,
                  color: _kPropertyColor,
                ),
          ],
        );
      default: // الملاحظات
        return _AssetUnifiedCard(
          showHeader: false,
          title: 'الملاحظات',
          icon: Icons.sticky_note_2_outlined,
          color: _kPropertyColor,
          onAdd: _openNotesSheet,
          addTooltip: 'إضافة ملاحظة',
          children: [
            Align(
              alignment: Alignment.centerRight,
              child: Text(
                item.description.isEmpty
                    ? 'لا توجد ملاحظات مسجّلة بعد.'
                    : item.description,
                textAlign: TextAlign.right,
                style: const TextStyle(
                  fontSize: 12,
                  color: Color(0xFF2C3B38),
                  height: 1.6,
                ),
              ),
            ),
          ],
        );
    }
  }

  // ============================================================
  // فئة "الأنشطة التجارية" — نفس نمط شاشة تفاصيل العقار (هيدر + شريط
  // أبرز البيانات + تبويبات)، مع تبويب "الموظفون" الذي يقابل تبويب
  // "الوحدات" في العقارات (قائمة قابلة للتكرار).
  // ============================================================

  // نفس فئات العقار بمنطق النشاط: «إدارة النشاط» محل «الوحدات»،
  // و«الأصول والمعدات» محل «الأصول والمرافق».
  /// النشاط الرئيسي كالعقار («الفروع» مكان «الوحدات»)، والفرع كالوحدة
  /// («إدارة النشاط» مكان «إدارة الإيجار»). بقية الأقسام بالترتيب نفسه.
  List<DetailSectionTab> get _activityTabs =>
      _isBranchActivity ? _branchTabs : _mainActivityTabs;

  /// «إدارة النشاط» في النشاط الرئيسي: موضعه الثالث في القائمة، ورقمه
  /// المنطقي 10 حتى لا تتغير أرقام بقية الأقسام.
  static const int _kActivityLeaseTab = 10;

  int _activityLogicalTab(int visual) {
    if (_isBranchActivity) return visual;
    if (visual == 2) return _kActivityLeaseTab;
    return visual > 2 ? visual - 1 : visual;
  }

  int _activityVisualTab(int logical) {
    if (_isBranchActivity) return logical;
    if (logical == _kActivityLeaseTab) return 2;
    return logical >= 2 ? logical + 1 : logical;
  }

  String get _activityTabLabel {
    final visual = _activityVisualTab(_selectedTab);
    return visual >= 0 && visual < _activityTabs.length
        ? _activityTabs[visual].label
        : '';
  }

  static const List<DetailSectionTab> _mainActivityTabs = [
    DetailSectionTab(label: 'ملخص عام', icon: Icons.dashboard_outlined),
    DetailSectionTab(label: 'الفروع', icon: Icons.account_tree_outlined),
