  /// إضافة/تعديل موظف ببيانات كاملة: الاسم، الوظيفة، الجوال، تاريخ
  /// التعيين، الجنسية، والمستندات — كلها تُحفظ في بيانات النشاط نفسه.
  void _addEmployee({Map<String, String>? existing, int? editIndex}) {
    final nameCtrl = TextEditingController(text: existing?['الاسم'] ?? '');
    final roleCtrl = TextEditingController(text: existing?['الوظيفة'] ?? '');
    final phoneCtrl = TextEditingController(text: existing?['الجوال'] ?? '');
    final hireDateCtrl = TextEditingController(
      text: existing?['تاريخ التعيين'] ?? '',
    );
    final nationalityCtrl = TextEditingController(
      text: existing?['الجنسية'] ?? '',
    );
    final documentsCtrl = TextEditingController(
      text: existing?['المستندات'] ?? '',
    );
    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) {
        return SafeArea(
          top: false,
          child: Container(
            padding: EdgeInsets.only(
              left: 16,
              right: 16,
              top: 14,
              bottom: MediaQuery.of(sheetContext).viewInsets.bottom + 16,
            ),
            decoration: const BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
            ),
            child: Directionality(
              textDirection: AppTr.uiDir,
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text(
                      editIndex == null ? 'إضافة موظف' : 'تعديل بيانات الموظف',
                      style: const TextStyle(
                        fontSize: 15,
                        fontWeight: FontWeight.w900,
                        color: Color(0xFF022E2A),
                      ),
                    ),
                    const SizedBox(height: 12),
                    TextField(
                      controller: nameCtrl,
                      textAlign: AppTr.alignEnd,
                      decoration: _propertyInputDecoration('اسم الموظف'),
                    ),
                    const SizedBox(height: 10),
                    Row(
                      children: [
                        Expanded(
                          child: TextField(
                            controller: roleCtrl,
                            textAlign: AppTr.alignEnd,
                            decoration: _propertyInputDecoration('الوظيفة'),
                          ),
                        ),
                        const SizedBox(width: 10),
                        Expanded(
                          child: TextField(
                            controller: nationalityCtrl,
                            textAlign: AppTr.alignEnd,
                            decoration: _propertyInputDecoration('الجنسية'),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 10),
                    Row(
                      children: [
                        Expanded(
                          child: TextField(
                            controller: phoneCtrl,
                            textAlign: AppTr.alignEnd,
                            keyboardType: TextInputType.phone,
                            decoration: _propertyInputDecoration('رقم الهاتف'),
                          ),
                        ),
                        const SizedBox(width: 10),
                        Expanded(
                          child: TextField(
                            controller: hireDateCtrl,
                            readOnly: true,
                            textAlign: AppTr.alignEnd,
                            onTap: () async {
                              final date = await showDatePicker(
                                context: sheetContext,
                                initialDate: DateTime.now(),
                                firstDate: DateTime(1990),
                                lastDate: DateTime(2060),
                              );
                              if (date != null) {
                                hireDateCtrl.text =
                                    '${date.day}/${date.month}/${date.year}';
                              }
                            },
                            decoration: _propertyInputDecoration(
                              'تاريخ التعيين',
                            ).copyWith(
                              suffixIcon: const Icon(
                                Icons.event_rounded,
                                size: 18,
                              ),
                            ),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 10),
                    TextField(
                      controller: documentsCtrl,
                      textAlign: AppTr.alignEnd,
                      maxLines: 2,
                      decoration: _propertyInputDecoration(
                        'المستندات (إقامة، عقد عمل، شهادات...)',
                      ),
                    ),
                    const SizedBox(height: 16),
                    ElevatedButton(
                      onPressed: () {
                        if (nameCtrl.text.trim().isEmpty) return;
                        final data = {
                          'الاسم': nameCtrl.text.trim(),
                          'الوظيفة': roleCtrl.text.trim(),
                          'الجوال': phoneCtrl.text.trim(),
                          'تاريخ التعيين': hireDateCtrl.text.trim(),
                          'الجنسية': nationalityCtrl.text.trim(),
                          'المستندات': documentsCtrl.text.trim(),
                        };
                        final employees = List<Map<String, String>>.from(
                          _item.employees,
                        );
                        if (editIndex != null &&
                            editIndex < employees.length) {
                          employees[editIndex] = data;
                        } else {
                          employees.add(data);
                        }
                        _updateItem(
                          _item.copyWith(
                            employees: employees,
                            logs: [
                              editIndex == null
                                  ? 'تمت إضافة موظف: ${nameCtrl.text.trim()}'
                                  : 'تم تعديل بيانات الموظف: ${nameCtrl.text.trim()}',
                              ..._item.logs,
                            ],
                          ),
                        );
                        Navigator.of(sheetContext).pop();
                      },
                      style: ElevatedButton.styleFrom(
                        backgroundColor: _kActivityColor,
                        foregroundColor: Colors.white,
                        minimumSize: const Size.fromHeight(48),
                        shape: RoundedRectangleBorder(
                          borderRadius: BorderRadius.circular(12),
                        ),
                      ),
                      child: Text(
                        editIndex == null ? '+ إضافة' : 'حفظ التعديلات',
                        style: const TextStyle(fontWeight: FontWeight.w800),
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        );
      },
    );
  }

  void _removeEmployee(int index) {
    final employees = List<Map<String, String>>.from(_item.employees);
    if (index < 0 || index >= employees.length) return;
    employees.removeAt(index);
    _updateItem(_item.copyWith(employees: employees));
  }

  // ===== الفروع: أول نشاط يُنشأ يكون رئيسيًا، ويُربط به أي فرع عبر
  // علامة 'branch:<معرّف الرئيسي>' في عمود الرقم التسلسلي (غير مستخدم
  // للأنشطة)، فلا حاجة لأي تعديل في قاعدة البيانات. =====

  List<ProjectAssetRecord> _branchRecords = const [];

  bool get _isBranchActivity =>
      _item.category == 'activity' && _item.serialNumber.startsWith('branch:');

  Future<void> _loadBranches() async {
    final repository = widget.repository;
    final id = _item.id;
    if (_item.category != 'activity' ||
        repository == null ||
        id == null ||
        id.isEmpty) {
      return;
    }
    try {
      final all = await repository.fetchAssets();
      if (!mounted) return;
      setState(
        () => _branchRecords = all
            .where((r) => (r.serialNumber ?? '') == 'branch:$id')
            .toList(growable: false),
      );
    } catch (_) {
      // تعذّر تحميل الفروع لا يعطّل بقية الملخص.
    }
  }

  /// إنشاء فرع مرتبط بهذا النشاط الرئيسي — يرث نوع النشاط والرخصة
  /// والمدير ورأس المال، ويُدخل له اسم وموقع خاصان به.
  /// إضافة أصل أو معدة للنشاط — تُحفظ في ملحقات الأصل نفسه.
  Future<void> _addActivityAsset({String title = 'إضافة أصل أو معدة'}) async {
    final nameCtrl = TextEditingController();
    final countCtrl = TextEditingController(text: '1');
    final saved = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(AppTheme.rCard),
        ),
      ),
      builder: (sheetContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: Padding(
          padding: EdgeInsets.fromLTRB(
            16,
            16,
            16,
            MediaQuery.of(sheetContext).viewInsets.bottom + 18,
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(
                title,
                textAlign: TextAlign.right,
                style: TextStyle(
                  fontSize: 14,
                  fontWeight: FontWeight.w900,
                  color: Color(0xFF022E2A),
                ),
              ),
              const SizedBox(height: 12),
              TextField(
                controller: nameCtrl,
                textAlign: AppTr.alignEnd,
                decoration: _propertyInputDecorationShared('الاسم'),
              ),
              const SizedBox(height: 9),
              TextField(
                controller: countCtrl,
                textAlign: AppTr.alignEnd,
                keyboardType: TextInputType.number,
                decoration: _propertyInputDecorationShared('العدد'),
              ),
              const SizedBox(height: 14),
              FilledButton(
                onPressed: () => Navigator.of(sheetContext).pop(true),
                style: FilledButton.styleFrom(
                  backgroundColor: _kActivityColor,
                  foregroundColor: Colors.white,
                  minimumSize: const Size.fromHeight(48),
                ),
                child: const Text('حفظ'),
              ),
            ],
          ),
        ),
      ),
    );
    final name = nameCtrl.text.trim();
    final count = int.tryParse(countCtrl.text.trim()) ?? 1;
    nameCtrl.dispose();
    countCtrl.dispose();
    if (saved != true || name.isEmpty) return;
    final merged = <String, int>{..._item.annexes};
    merged[name] = (merged[name] ?? 0) + (count <= 0 ? 1 : count);
    _updateItem(_item.copyWith(annexes: merged));
  }

  Future<void> _addBranch() async {
    final repository = widget.repository;
    final id = _item.id;
    if (repository == null || id == null || id.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('احفظ النشاط الرئيسي أولًا قبل إضافة فرع'),
        ),
      );
      return;
    }
    // «إضافة فرع» = نفس إدخال النشاط الرئيسي: صفحة عقد إيجار الفرع (بيانات
    // العقد ثم الرخصة)، ويُنشأ الفرع من رخصته عند الحفظ. الرخصة تبدأ ببيانات
    // النشاط الرئيسي وتُعدَّل، وموقع الفرع يُكتب له.
    final lease = LeaseContractData(
      license: _activityLicenseFromMeta(
        _item.propertyMeta,
        title: _item.title,
        type: _item.subType,
      ),
    );
    lease.license.remove(LeaseContractData.kActivityLocation);
    String? createdId;
    var createdTitle = '';
    final saved = await Navigator.of(context).push<PropertyUnitContractRecord>(
      MaterialPageRoute(
        builder: (_) => LeaseContractFormScreen(
          repository: repository,
          assetId: '',
          unitKey: _kActivityUnitKey,
          unitName: '',
          propertyTitle: 'فرع جديد لنشاط: ${_item.title}',
          title: 'عقد إيجار الفرع',
          subjectLabel: 'الفرع',
          forActivity: true,
          prefillNotes: lease.encode(),
          activityClassOptions: [
            for (final type in _activityTypeOptions)
              if (!_assetTypeHidden('activity', type)) type,
          ],
          createActivity: (data) async {
            final meta = _activityMetaFromLease(data);
            String of(String key) => (data.license[key] ?? '').trim();
            final name = of(LeaseContractData.kTradeName);
            final type = of(LeaseContractData.kActivityClass);
            final location = (meta[_ActKeys.location] ?? '').trim();
            final licenseEnd = (meta[_ActKeys.licenseEnd] ?? '').trim();
            // الاسم التجاري نفسه للنشاط الرئيسي: يُميَّز الفرع برقمه.
            final title = name.isEmpty || name == _item.title
                ? '${_item.title} - فرع ${_branchRecords.length + 1}'
                : name;
            final record = ProjectAssetRecord(
              title: title,
              subType: type.isEmpty ? _item.subType : type,
              category: 'business',
              status: 'نشط',
              locationOrType: location.isEmpty
                  ? _item.locationOrType
                  : location,
              amountLabel: _item.amountLabel,
              followupNote: 'فرع تابع للنشاط الرئيسي: ${_item.title}',
              owner: _item.owner,
              // سنة-شهر-يوم (يوم/شهر/سنة كان يُرفض فيُحفظ فارغًا).
              endDate: _isoAssetDate(
                licenseEnd.isNotEmpty
                    ? licenseEnd
                    : (_item.endDate == 'غير محدد' ? '' : _item.endDate),
              ),
              description: _item.description,
              serialNumber: 'branch:$id',
            );
            final created = await repository.createAsset(record);
            createdId = created.id;
            createdTitle = created.title;
            if (mounted) {
              setState(() => _branchRecords = [..._branchRecords, created]);
            }
            return created.id;
          },
        ),
      ),
    );
    if (!mounted) return;
    final branchId = createdId;
    if (branchId == null || branchId.isEmpty) return;
    if (saved != null) {
      await _registerActivityRemindersShared(
        branchId,
        createdTitle,
        _activityMetaFromLease(LeaseContractData.decode(saved.notes)),
      );
    }
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text('تم إنشاء الفرع: $createdTitle')),
    );
    await _loadBranches();
  }

