  /// ملخص النشاط: بيانات الرخصة، ثم عقد الإيجار (العقد والعين المؤجرة
  /// والدفعات) — بلا المؤجر والمستأجر والممثل.
  /// «ملخص عام» للنشاط: بيانات عقد الإيجار ثم بيانات الرخصة — بنفس ترتيب
  /// صفحة «إضافة نشاط تجاري»، بلا المؤجر والمستأجر وممثله.
  List<Widget> _activitySummaryExtras(_AssetItem item) {
    final m = item.propertyMeta;
    final currency = AppSettings.currencySuffix;
    Widget? row(String label, String? value, IconData icon) {
      final text = (value ?? '').trim();
      if (text.isEmpty || text == 'غير محدد') return null;
      return _AssetInfoRow(
        label: label,
        value: text,
        icon: icon,
        color: _kActivityColor,
      );
    }

    // من عقد الإيجار أولًا (آخر تعديل)، ثم من بيانات النشاط المحفوظة.
    final contract = _activityContract;
    final lease = contract == null
        ? null
        : LeaseContractData.decode(contract.notes);
    final fromLease = lease == null
        ? const <String, String>{}
        : _activityMetaFromLease(lease);
    String v(String key) {
      final text = (fromLease[key] ?? '').trim();
      return text.isNotEmpty ? text : (m[key] ?? '').trim();
    }

    String reminder(String choiceKey, String daysKey) {
      final choice = v(choiceKey);
      if (choice.isEmpty || choice == 'بلا تذكير') return '';
      return choice == 'مخصص' ? 'قبل ${v(daysKey)} يوم' : choice;
    }

    final tradeName =
        (lease?.license[LeaseContractData.kTradeName] ?? '').trim();
    final activityClass =
        (lease?.license[LeaseContractData.kActivityClass] ?? '').trim();

    final contractRows = <Widget?>[
      row('نمط مدة الإيجار', v(_ActKeys.termMode), Icons.timelapse_rounded),
      row('رقم عقد الإيجار', v(_ActKeys.leaseNo), Icons.tag_rounded),
      row('تاريخ بداية العقد', v(_ActKeys.leaseStart), Icons.event_outlined),
      row(
        'تاريخ نهاية العقد',
        v(_ActKeys.leaseEnd),
        Icons.event_busy_outlined,
      ),
      row(
        'التذكير',
        reminder(_ActKeys.leaseReminder, _ActKeys.leaseReminderDays),
        Icons.notifications_active_outlined,
      ),
      row('الغرض من الإيجار', v(_ActKeys.purpose), Icons.flag_outlined),
      if (lease != null && lease.payments.isNotEmpty) ...[
        row(
          'إجمالي الدفعات الإيجارية',
          '${formatMoneyValue(lease.paymentsTotal)} $currency',
          Icons.payments_outlined,
        ),
        row(
          'عدد الدفعات',
          '${lease.payments.length}',
          Icons.format_list_numbered_rounded,
        ),
      ],
      if (lease != null && lease.adminFeesTotal > 0)
        row(
          'الرسوم الإدارية',
          '${formatMoneyValue(lease.adminFeesTotal)} $currency',
          Icons.receipt_outlined,
        ),
      if (lease != null && lease.depositsTotal > 0)
        row(
          'التأمين',
          '${formatMoneyValue(lease.depositsTotal)} $currency',
          Icons.shield_outlined,
        ),
    ].whereType<Widget>().toList(growable: false);

    final license = <Widget?>[
      row(
        'الاسم التجاري',
        tradeName.isEmpty ? item.title : tradeName,
        Icons.storefront_outlined,
      ),
      row(
        'موقع النشاط',
        v(_ActKeys.location).isEmpty
            ? item.locationOrType
            : v(_ActKeys.location),
        Icons.location_on_outlined,
      ),
      row(
        'تصنيف النشاط',
        activityClass.isEmpty ? item.subType : activityClass,
        Icons.category_outlined,
      ),
      row('الشكل القانوني', v(_ActKeys.legalForm), Icons.gavel_outlined),
      row('رقم الرخصة التجارية', v(_ActKeys.licenseNo), Icons.badge_outlined),
      row('تاريخ الإصدار', v(_ActKeys.licenseIssue), Icons.event_outlined),
      row('تاريخ الانتهاء', v(_ActKeys.licenseEnd), Icons.event_busy_outlined),
      row(
        'التذكير',
        reminder(_ActKeys.licenseReminder, _ActKeys.licenseReminderDays),
        Icons.notifications_active_outlined,
      ),
      row('عضوية الغرفة', v(_ActKeys.chamber), Icons.groups_outlined),
      row('فئة الرخصة', v(_ActKeys.licenseClass), Icons.workspace_premium_outlined),
      row(
        'الأنشطة التجارية',
        v(_ActKeys.activities).split('\n').join(' · '),
        Icons.list_alt_outlined,
      ),
      row(
        'رأس المال',
        v(_ActKeys.capital).isEmpty ? '' : '${v(_ActKeys.capital)} $currency',
        Icons.payments_outlined,
      ),
    ].whereType<Widget>().toList(growable: false);

    return [
      if (contractRows.isNotEmpty) ...[
        const SizedBox(height: 10),
        _AssetUnifiedCard(
          title: 'بيانات عقد الإيجار',
          icon: Icons.description_outlined,
          color: _kActivityColor,
          children: contractRows,
        ),
      ],
      if (license.isNotEmpty) ...[
        const SizedBox(height: 10),
        _AssetUnifiedCard(
          title: 'بيانات الرخصة',
          icon: Icons.verified_outlined,
          color: _kActivityColor,
          children: license,
        ),
      ],
      // كل ما سُجّل عند إضافة النشاط: بقية بنود العقد والرخصة، والمؤجر
      // والمستأجر، والدفعات والرسوم والتأمين.
      if (lease != null)
        for (final card in _activityLeaseCards(lease, row)) ...[
          const SizedBox(height: 10),
          card,
        ],
    ];
  }

  /// بطاقات بقية بيانات عقد النشاط — كل حقل مُعبّأ يظهر.
  List<Widget> _activityLeaseCards(
    LeaseContractData lease,
    Widget? Function(String label, String? value, IconData icon) row,
  ) {
    final currency = AppSettings.currencySuffix;
    String shown(String value) {
      final text = value.trim();
      return RegExp(r'^\d{4}-\d{2}-\d{2}').hasMatch(text)
          ? _isoToDmy(text)
          : text;
    }

    List<Widget> rowsOf(
      Map<String, String> source, {
      Set<String> skip = const {},
    }) => <Widget?>[
      for (final entry in source.entries)
        if (!skip.contains(entry.key) && !entry.key.startsWith('__'))
          row(
            entry.key == LeaseContractData.kMobile
                ? LeaseContractData.kPhone
                : entry.key,
            shown(entry.value),
            Icons.short_text_rounded,
          ),
    ].whereType<Widget>().toList(growable: false);

    Widget card(String title, IconData icon, List<Widget> children) =>
        _AssetUnifiedCard(
          title: title,
          icon: icon,
          color: _kActivityColor,
          children: children,
        );

    final contractMore = rowsOf(
      lease.contract,
      skip: {
        LeaseContractData.kTermMode,
        LeaseContractData.kTenantClass,
        LeaseContractData.kNewNo,
        LeaseContractData.kStartDate,
        LeaseContractData.kEndDate,
        LeaseContractData.kPurpose,
        LeaseContractData.kSubject,
      },
    );
    final licenseMore = rowsOf(
      lease.license,
      skip: {
        LeaseContractData.kTradeName,
        LeaseContractData.kActivityClass,
        LeaseContractData.kLegalForm,
        LeaseContractData.kLicenseNo,
        LeaseContractData.kLicenseIssue,
        LeaseContractData.kLicenseEnd,
        LeaseContractData.kChamber,
        LeaseContractData.kLicenseClass,
        LeaseContractData.kActivities,
        LeaseContractData.kCapital,
        LeaseContractData.kActivityLocation,
        ...LeaseContractData.activityReminderKeys,
      },
    );
    final lessor = rowsOf(lease.lessor);
    final tenant = rowsOf(lease.tenant);
    final representative = rowsOf(lease.representative);

    String money(String raw) {
      final value = double.tryParse(raw.trim().replaceAll(',', '')) ?? 0;
      return value == 0 ? raw.trim() : '${formatMoneyValue(value)} $currency';
    }

    final fees = <Widget?>[
      for (final f in lease.adminFees)
        row(
          (f[LeaseContractData.kAdminFeeType] ?? '').trim().isEmpty
              ? 'رسم'
              : f[LeaseContractData.kAdminFeeType]!,
          [
            money(f[LeaseContractData.kAdminFeeAmount] ?? ''),
            if ((f[LeaseContractData.kAdminFeeDue] ?? '').trim().isNotEmpty)
              shown(f[LeaseContractData.kAdminFeeDue]!),
          ].where((v) => v.trim().isNotEmpty).join(' · '),
          Icons.receipt_outlined,
        ),
    ].whereType<Widget>().toList(growable: false);
    final deposits = <Widget?>[
      for (final dep in lease.deposits)
        row(
          'مبلغ التأمين',
          [
            money(dep[LeaseContractData.kDepositAmount] ?? ''),
            (dep[LeaseContractData.kCollectMethod] ?? '').trim(),
          ].where((v) => v.trim().isNotEmpty).join(' · '),
          Icons.shield_outlined,
        ),
    ].whereType<Widget>().toList(growable: false);

    return [
      if (contractMore.isNotEmpty)
        card('بنود أخرى في العقد', Icons.article_outlined, contractMore),
      if (licenseMore.isNotEmpty)
        card('بيانات أخرى في الرخصة', Icons.verified_outlined, licenseMore),
      if (lessor.isNotEmpty)
        card('بيانات المؤجر', Icons.account_balance_rounded, lessor),
      if (tenant.isNotEmpty)
        card('بيانات المستأجر', Icons.person_rounded, tenant),
      if (representative.isNotEmpty)
        card('بيانات ممثل المستأجر', Icons.badge_outlined, representative),
      // «الدفعات الإيجارية» لا تُعرض في الملخص (مكانها «إدارة النشاط»).
      if (fees.isNotEmpty)
        card('الرسوم الإدارية', Icons.receipt_long_outlined, fees),
      if (deposits.isNotEmpty)
        card('التأمين', Icons.shield_outlined, deposits),
    ];
  }

  /// «الحركات المالية» بنفس شكل العقار: صافي الربح، ثم الدفعات الإيجارية
  /// ودخل إضافي والمصاريف. [paymentsExtra] أسفل الدفعات (تسجيل دفعة مثلًا).
