            _propertyFinanceChip('دخل إضافي', 1, Icons.trending_up_rounded),
            const SizedBox(width: 8),
            _propertyFinanceChip('المصاريف', 2, Icons.trending_down_rounded),
          ],
        ),
        const SizedBox(height: 12),
        if (_financeTab == 0) ...[
          _historyLinkCard(
            item.category == 'activity' ? _kActivityColor : _kEquipmentColor,
          ),
