  // ---------------- إدارة النشاط: عقد الإيجار ودفعاته ----------------

  /// عقد إيجار النشاط القائم (آخر عقد غير ملغى).
  PropertyUnitContractRecord? get _activityContract {
    PropertyUnitContractRecord? best;
    for (final c in _unitContracts) {
      if (c.unitKey != _kActivityUnitKey) continue;
      if (c.status == _kContractCancelled) continue;
      if (best == null) {
        best = c;
        continue;
      }
      final a = c.startDate;
      final b = best.startDate;
      if (a != null && (b == null || a.isAfter(b))) best = c;
    }
    return best;
  }

  List<RentPaymentEntry> _activityPaymentsOf(PropertyUnitContractRecord c) =>
      _propertyPayments
          .where((entry) => entry.contract.id == c.id)
          .toList(growable: false);

  String _actMoney(double value) =>
      '${formatMoneyValue(value)} ${AppSettings.currencySuffix}';

  String _actDate(DateTime? d) =>
      d == null ? '—' : '${d.day.toString().padLeft(2, '0')}/'
          '${d.month.toString().padLeft(2, '0')}/${d.year}';

  static String _actIso(DateTime d) =>
      '${d.year.toString().padLeft(4, '0')}-'
      '${d.month.toString().padLeft(2, '0')}-'
      '${d.day.toString().padLeft(2, '0')}';

  /// نموذج عقد إيجار النشاط: جديد، أو تعديل [existing]، أو تجديد.
  Future<void> _openActivityLease({
    PropertyUnitContractRecord? existing,
    PropertyUnitContractRecord? renewFrom,
    DateTime? renewStart,
    DateTime? renewEnd,
  }) async {
    if (existing == null && _hasBlockingMaintenance) {
      _showMaintBlockNotice(
        context,
        'النشاط تحت صيانة تمنع التأجير — سجّل «انتهاء الصيانة» من قسم '
        'الصيانة أولًا.',
      );
      return;
    }
    final repo = widget.repository;
    final assetId = _item.id;
    if (repo == null || assetId == null || assetId.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('يجب حفظ النشاط أولاً')),
      );
      return;
    }
    String? prefill;
    if (existing == null && renewFrom == null) {
      final lease = LeaseContractData(
        license: _activityLicenseFromMeta(
          _item.propertyMeta,
          title: _item.title,
          type: _item.subType,
        ),
      );
      lease.tenant[LeaseContractData.kName] = _item.title;
      final place = _item.locationOrType.trim();
      if ((lease.license[LeaseContractData.kActivityLocation] ?? '').isEmpty &&
          place.isNotEmpty &&
          place != 'غير محدد') {
        lease.license[LeaseContractData.kActivityLocation] = place;
      }
      prefill = lease.encode();
    }
    final saved = await Navigator.of(context).push<PropertyUnitContractRecord>(
      MaterialPageRoute(
        builder: (_) => LeaseContractFormScreen(
          repository: repo,
          assetId: assetId,
          unitKey: _kActivityUnitKey,
          unitName: _item.title,
          propertyTitle: _item.title,
          existing: existing,
          title: renewFrom != null ? 'تجديد العقد' : 'عقد إيجار النشاط',
          subjectLabel: 'النشاط',
          forActivity: true,
          prefillNotes: prefill,
          templateNotes: renewFrom?.notes,
          renewStart: renewStart,
          renewEnd: renewEnd,
          renewOldNo: renewFrom == null ? null : leaseContractNumber(renewFrom),
        ),
      ),
    );
    if (saved == null || !mounted) return;
    final leaseMeta =
        _activityMetaFromLease(LeaseContractData.decode(saved.notes));
    await _registerActivityRemindersShared(assetId, _item.title, leaseMeta);
    if (!mounted) return;
    // الرخصة وتواريخ العقد في بيانات النشاط أيضًا (البطاقة والملخص).
    if (leaseMeta.isNotEmpty) {
      final location = (leaseMeta[_ActKeys.location] ?? '').trim();
      _updateItem(
        _item.copyWith(
          propertyMeta: {..._item.propertyMeta, ...leaseMeta},
          locationOrType: location.isEmpty ? null : location,
        ),
      );
    }
    if (renewFrom != null && renewFrom.id != saved.id) {
      try {
        await repo.upsertUnitContract(
          renewFrom.copyWith(status: PropertyUnitContractRecord.statusExpired),
        );
      } catch (_) {}
    }
    await _loadUnitContractsFromRemote();
  }

  Future<int?> _pickActivityMonths(String title) => showModalBottomSheet<int>(
    context: context,
    backgroundColor: AppTheme.page,
    shape: const RoundedRectangleBorder(
      borderRadius: BorderRadius.vertical(top: Radius.circular(AppTheme.rCard)),
    ),
    builder: (sheetContext) => Directionality(
      textDirection: AppTr.uiDir,
      child: SafeArea(
        child: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 14, 16, 6),
              child: Text(
                title,
                textAlign: TextAlign.right,
                style: const TextStyle(
                  fontSize: 14,
                  fontWeight: FontWeight.w900,
                  color: Color(0xFF022E2A),
                ),
              ),
            ),
            for (final months in const [1, 3, 6, 12, 24])
              ListTile(
                title: Text(
                  months == 12
                      ? 'سنة'
                      : months == 24
                      ? 'سنتان'
                      : '$months شهر',
                  textAlign: TextAlign.right,
                ),
                onTap: () => Navigator.of(sheetContext).pop(months),
              ),
            const SizedBox(height: 8),
          ],
        ),
      ),
    ),
  );

  Future<void> _extendActivityLease(PropertyUnitContractRecord c) async {
    final repo = widget.repository;
    if (repo == null) return;
    final by = await _pickExtension(context);
    if (by == null || !mounted) return;
    final lease = LeaseContractData.decode(c.notes);
    final endTime = lease.contract[LeaseContractData.kEndTime];
    final withTime = by.hours > 0 || (endTime ?? '').trim().isNotEmpty;
    final from = _endWithTime(c.endDate ?? DateTime.now(), endTime);
    final newEnd = _extendedEnd(from, by);
    if (!await _confirmExtension(
          context,
          by: by,
          start: c.startDate,
          oldEnd: from,
          newEnd: newEnd,
          withTime: withTime,
        ) ||
        !mounted) {
      return;
    }
    final end = DateUtils.dateOnly(newEnd);
    lease.contract[LeaseContractData.kEndDate] = _actIso(end);
    if (withTime) {
      lease.contract[LeaseContractData.kEndTime] =
          '${newEnd.hour.toString().padLeft(2, '0')}:'
          '${newEnd.minute.toString().padLeft(2, '0')}';
    }
    try {
      await repo.upsertUnitContract(
        c.copyWith(
          endDate: end,
          status: PropertyUnitContractRecord.statusActive,
          notes: lease.encode(),
        ),
      );
      await _loadUnitContractsFromRemote();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('مُدِّد العقد حتى ${_actDate(end)}')),
      );
    } catch (_) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذر تمديد العقد')),
      );
    }
  }

  Future<void> _renewActivityLease(PropertyUnitContractRecord c) async {
    if (_hasBlockingMaintenance) {
      _showMaintBlockNotice(
        context,
        'النشاط تحت صيانة تمنع التأجير — سجّل «انتهاء الصيانة» من قسم '
        'الصيانة أولًا.',
      );
      return;
    }
    final months = await _pickActivityMonths('تجديد العقد');
    if (months == null || !mounted) return;
    final today = DateUtils.dateOnly(DateTime.now());
    final oldEnd = c.endDate;
    final start = oldEnd != null && !DateUtils.dateOnly(oldEnd).isBefore(today)
        ? oldEnd
        : today;
    await _openActivityLease(
      renewFrom: c,
      renewStart: start,
      renewEnd: DateTime(start.year, start.month + months, start.day),
    );
  }

  Future<void> _cancelActivityLease(PropertyUnitContractRecord c) async {
    final repo = widget.repository;
    if (repo == null) return;
    final ok = await confirmAction(
      context,
      title: 'إلغاء العقد',
      message: 'سيصبح عقد إيجار النشاط «ملغي». هل تريد المتابعة؟',
      confirmLabel: 'إلغاء العقد',
      danger: true,
    );
    if (!ok) return;
    try {
      await repo.upsertUnitContract(c.copyWith(status: _kContractCancelled));
      await _loadUnitContractsFromRemote();
    } catch (_) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذر إلغاء العقد')),
      );
    }
  }

  String _activityPayFilter = 'الكل';

  Future<void> _openActivityPaymentsPage(PropertyUnitContractRecord c) async {
    final repo = widget.repository;
    if (repo == null) return;
    await Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => _UnitPaymentsPage(
          title: 'دفعات إيجار النشاط — ${_item.title}',
          repository: repo,
          assetTitle: _item.title,
          initial: _activityPaymentsOf(c),
          initialFilter: _activityPayFilter,
          onFilterChanged: (value) {
            if (mounted) setState(() => _activityPayFilter = value);
          },
          reload: () async {
            await _loadUnitContractsFromRemote();
            final current = _activityContract;
            return current == null
                ? const <RentPaymentEntry>[]
                : _activityPaymentsOf(current);
          },
        ),
      ),
    );
  }

