  /// «إدارة النشاط»: نفس «إدارة الإيجار» في الوحدة بالضبط — الحالة و«العقد
  /// كامل»، ثم مدة العقد وأزراره، ثم صندوق الدفعات. بلا «إضافة دفعة» ولا
  /// «سند قبض» ولا «مطالبة مالية» (النشاط مستأجر).
  Widget _activityLeasePanel(_AssetItem item) {
    if (widget.repository == null || (item.id ?? '').isEmpty) {
      return const _DetailHintCard(
        message: 'يجب حفظ النشاط أولاً لإدارة عقد الإيجار.',
      );
    }
    final contract = _activityContract;
    if (contract == null) {
      // بلا زر «إضافة عقد الإيجار» الكبير: «+» يكفي. في الفرع «+» الرأس
      // للموظفين، فيظهر «+» صغير بجانب التنبيه.
      return Padding(
        padding: const EdgeInsets.only(bottom: 14),
        child: Row(
          textDirection: AppTr.uiDir,
          children: [
            const Expanded(
              child: _DetailHintCard(
                message: 'لا يوجد عقد إيجار بعد — اضغط + لإضافته.',
              ),
            ),
            if (_isBranchActivity) ...[
              const SizedBox(width: 8),
              IconButton.filled(
                tooltip: AppTr.tr('إضافة عقد الإيجار'),
                onPressed: () => _openActivityLease(),
                style: IconButton.styleFrom(
                  backgroundColor: _kActivityColor,
                  foregroundColor: Colors.white,
                ),
                icon: const Icon(Icons.add_rounded),
              ),
            ],
          ],
        ),
      );
    }
    final payments = _activityPaymentsOf(contract);
    final today = DateUtils.dateOnly(DateTime.now());
    final end = contract.endDate;
    final closed = _contractClosed(contract);
    final ended = closed ||
        (end != null && DateUtils.dateOnly(end).isBefore(today));
    var overdueCount = 0;
    for (final entry in payments) {
      final p = entry.payment;
      if (payRemaining(p) <= 0) continue;
      final due = p.dueDate == null ? null : DateUtils.dateOnly(p.dueDate!);
      if (due != null && due.isBefore(today)) overdueCount++;
    }
    final isDraft = contract.status == PropertyUnitContractRecord.statusPending;
    // حالة العقد وحده: ملغي / منتهي / مسودة / نشط. التأخير يخصّ الدفعات
    // ويظهر في صندوقها، لا في حالة العقد.
    final endedByDate = _contractEndedByDate(contract);
    final cancelled = contract.status == _kContractCancelled;
    final statusLabel = cancelled
        ? 'ملغي'
        : closed
        ? 'منتهي'
        : isDraft
        ? 'مسودة'
        : endedByDate
        ? 'منتهي'
        : 'نشط';
    final statusColor = cancelled
        ? const Color(0xFF8C3A32)
        : closed
        ? const Color(0xFF8C9A97)
        : isDraft
        ? AppTheme.goldDark
        : endedByDate
        ? const Color(0xFFC4392E)
        : const Color(0xFF0E7161);
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        // ===== سطر العقد: الحالة + زر «العقد كامل» =====
        Row(
          textDirection: AppTr.uiDir,
          children: [
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 5),
              decoration: BoxDecoration(
                color: statusColor.withValues(alpha: 0.12),
                borderRadius: BorderRadius.circular(999),
              ),
              child: Text(
                statusLabel,
                style: TextStyle(
                  fontSize: 10,
                  fontWeight: FontWeight.w900,
                  color: statusColor,
                ),
              ),
            ),
            const Spacer(),
            InkWell(
              onTap: () => _openActivityContractSheet(contract),
              borderRadius: BorderRadius.circular(AppTheme.rIcon),
              child: Container(
                padding: const EdgeInsets.symmetric(
                  horizontal: 14,
                  vertical: 10,
                ),
                decoration: BoxDecoration(
                  color: _kActivityColor,
                  borderRadius: BorderRadius.circular(AppTheme.rIcon),
                ),
                child: Row(
                  textDirection: AppTr.uiDir,
                  children: const [
                    Icon(
                      Icons.open_in_full_rounded,
                      size: 15,
                      color: Colors.white,
                    ),
                    SizedBox(width: 6),
                    Text(
                      'العقد كامل',
                      style: TextStyle(
                        fontSize: 11.5,
                        fontWeight: FontWeight.w900,
                        color: Colors.white,
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ],
        ),
        const SizedBox(height: 14),

        // ===== صندوق مدة العقد وإجراءاته =====
        _actBox('مدة العقد', Icons.calendar_month_outlined, [
          if (endedByDate && !closed)
            _endedContractAlert(
              'انتهت مدة العقد — يُرجى إلغاء العقد أو تجديده.',
            ),
          Row(
            textDirection: AppTr.uiDir,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Expanded(
                child: _actCell('بداية العقد', _actDate(contract.startDate)),
              ),
              const SizedBox(width: 12),
              Expanded(
                child: _actCell('نهاية العقد', _actDate(contract.endDate)),
              ),
            ],
          ),
          const SizedBox(height: 14),
          Row(
            children: [
              // بعد انتهاء العقد يحلّ «تجديد العقد» مكان «تمديد العقد»
              // و«تعديل العقد» معًا.
              if (ended)
                Expanded(
                  flex: 2,
                  child: _actButton(
                    'تجديد العقد',
                    Icons.autorenew_rounded,
                    () => _renewActivityLease(contract),
                  ),
                )
              else
                // التعديل من الثلاث نقاط أعلى الصفحة.
                Expanded(
                  child: _actButton(
                    'تمديد العقد',
                    Icons.more_time_rounded,
                    () => _extendActivityLease(contract),
                  ),
                ),
              const SizedBox(width: 7),
              Expanded(
                child: _actButton(
                  'إلغاء العقد',
                  Icons.cancel_outlined,
                  () => _cancelActivityLease(contract),
                  color: AppTheme.danger,
                ),
              ),
            ],
          ),
        ]),

        // ===== صندوق واحد: الإيجار والرسوم الإدارية والتأمين =====
        _actBox(
          'الدفعات الإيجارية + الدفعات الإدارية + التأمين',
          Icons.payments_outlined,
          [
            _sharedDuesBox(
              context: context,
              entries: payments,
              accent: _kActivityColor,
              onOpen: () => _openActivityPaymentsPage(contract),
            ),
          ],
        ),
      ],
    );
  }

  /// «العقد كامل»: نص عقد إيجار النشاط كاملًا مع جدول دفعاته — كما في
  /// الوحدة، مع «طباعة / مشاركة» و«تحميل».
  Future<void> _openActivityContractSheet(
    PropertyUnitContractRecord contract,
  ) async {
    final lease = LeaseContractData.decode(contract.notes);
    final payments = _activityPaymentsOf(contract);
    final buffer = StringBuffer()
      ..writeln('عقد إيجار النشاط التجاري')
      ..writeln('النشاط: ${_item.title}')
      ..writeln('رقم العقد: ${leaseContractNumber(contract)}')
      ..writeln('المستأجر: ${contract.tenantName ?? '—'}')
      ..writeln(
        'الفترة: ${_actDate(contract.startDate)} - '
        '${_actDate(contract.endDate)}',
      )
      ..writeln('');
    if (!lease.isEmpty) buffer.writeln(lease.toShareText());
    if (payments.isNotEmpty) {
      var due = 0.0, paid = 0.0;
      buffer
        ..writeln('')
        ..writeln('جدول الدفعات:');
      for (var i = 0; i < payments.length; i++) {
        final p = payments[i].payment;
        due += p.amountDue;
        paid += p.amountPaid;
        buffer.writeln(
          '${i + 1}) استحقاق ${fmtPayDate(p.dueDate)} — '
          'مستحق ${_actMoney(p.amountDue)} — '
          'مسدد ${_actMoney(p.amountPaid)} — '
          '${rentPaymentStatusLabel(p)}',
        );
      }
      buffer
        ..writeln('')
        ..writeln('إجمالي المستحق: ${_actMoney(due)}')
        ..writeln('إجمالي المسدد: ${_actMoney(paid)}')
        ..writeln('المتبقي: ${_actMoney(due - paid)}');
    }
    final text = buffer.toString();
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(AppTheme.rCard),
        ),
      ),
      builder: (sheetContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: DraggableScrollableSheet(
          expand: false,
          initialChildSize: 0.86,
          maxChildSize: 0.95,
          builder: (context, controller) => Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 14, 16, 10),
                child: Row(
                  textDirection: AppTr.uiDir,
                  children: [
                    const Icon(
                      Icons.description_outlined,
                      size: 19,
                      color: _kActivityColor,
                    ),
                    const SizedBox(width: 8),
                    const Expanded(
                      child: Text(
                        'العقد كامل',
                        style: TextStyle(
                          fontSize: 14,
                          fontWeight: FontWeight.w900,
                          color: Color(0xFF022E2A),
                        ),
                      ),
                    ),
                    IconButton(
                      tooltip: AppTr.tr('إغلاق'),
                      onPressed: () => Navigator.of(sheetContext).pop(),
                      icon: const Icon(Icons.close_rounded, size: 20),
                    ),
                  ],
                ),
              ),
              const Divider(height: 1, color: AppTheme.line),
              Expanded(
                child: ListView(
                  controller: controller,
                  padding: const EdgeInsets.fromLTRB(16, 12, 16, 12),
                  children: [
                    Container(
                      padding: const EdgeInsets.all(14),
                      decoration: BoxDecoration(
                        color: Colors.white,
                        borderRadius: BorderRadius.circular(AppTheme.rInner),
                        border: Border.all(color: AppTheme.hairline),
                      ),
                      child: Text(
                        text,
                        textAlign: TextAlign.right,
                        style: const TextStyle(
                          fontSize: 12,
                          height: 1.9,
                          fontWeight: FontWeight.w600,
                          color: Color(0xFF022E2A),
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              SafeArea(
                top: false,
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(16, 8, 16, 12),
                  child: Row(
                    children: [
                      Expanded(
                        child: FilledButton.icon(
                          style: FilledButton.styleFrom(
                            backgroundColor: _kActivityColor,
                            foregroundColor: Colors.white,
                            minimumSize: const Size(0, 48),
                          ),
                          onPressed: () => printOrShareLeaseContract(
                            sheetContext,
                            contract: contract,
                            text: text,
                            fileName: 'عقد-${_item.title}',
                            activity: true,
                            assetMeta: _item.propertyMeta,
                          ),
                          icon: const Icon(Icons.print_outlined, size: 18),
                          label: const Text('طباعة / مشاركة'),
                        ),
                      ),
                      const SizedBox(width: 10),
                      Expanded(
                        child: OutlinedButton.icon(
                          style: OutlinedButton.styleFrom(
                            minimumSize: const Size(0, 48),
                          ),
                          onPressed: () => downloadLeaseContract(
                            sheetContext,
                            contract: contract,
                            text: text,
                            fileName: 'عقد-${_item.title}',
                            activity: true,
                            assetMeta: _item.propertyMeta,
                          ),
                          icon: const Icon(Icons.download_rounded, size: 18),
                          label: const Text('تحميل'),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ],
          ),
        ),
      ),
    );
  }

  /// بطاقة فرع في «الفروع» — بنسق بطاقة الوحدة، والضغط يفتح تفاصيله.
