  /// يفتح الفرع بتفاصيله الكاملة (صفحته كصفحة الوحدة)، ثم يعيد تحميل
  /// الفروع عند الرجوع.
  Future<void> _openBranch(ProjectAssetRecord branch) async {
    final open = widget.onOpenRecord;
    if (open == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('افتح الفرع من قائمة الأنشطة التجارية.'),
          behavior: SnackBarBehavior.floating,
        ),
      );
      return;
    }
    await open(branch);
    if (mounted) await _loadBranches();
  }

  /// زر «عقد الإيجار» أعلى الملخص العام — شكل واحد في العقار والنشاط
  /// والمركبة.
  Widget _summaryLeaseButton(Color color, VoidCallback onPressed) =>
      FilledButton.icon(
        onPressed: onPressed,
        style: FilledButton.styleFrom(
          backgroundColor: color,
          foregroundColor: Colors.white,
          minimumSize: const Size.fromHeight(48),
        ),
        icon: const Icon(Icons.description_outlined, size: 19),
        label: const Text('عقد الإيجار'),
      );

  /// «عقد الإيجار» أعلى ملخص النشاط: يفتح العقد كاملًا (طباعة، تحميل).
  Widget _activityContractTopCard(_AssetItem item) {
    final contract = _activityContract;
    if (contract == null) return const SizedBox.shrink();
    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: _summaryLeaseButton(
        _kActivityColor,
        () => _openActivityContractSheet(contract),
      ),
    );
  }

  /// ملخص المركبة: زر «عقد الإيجار» فوق البيانات الفنية إن وُجد عقد.
  Widget _withEquipLeaseButton(Widget card) {
    final contract = _equipContract ??
        (_equipContracts.isEmpty ? null : _equipContracts.first);
    final delegationCard = _delegationSummaryCard(_item.id);
    if (contract == null && delegationCard == null) return card;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        ?delegationCard,
        if (contract != null)
        _summaryLeaseButton(
          _kEquipmentColor,
          () => _openEquipFullContract(contract),
        ),
        const SizedBox(height: 12),
        card,
      ],
    );
  }

  Widget _buildActivityTabContent(_AssetItem item) {
    if (_selectedTab < 0) return const _ChooseHint();
    switch (_selectedTab) {
      case 0: // ملخص عام — عقد الإيجار ثم بيانات النشاط
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            if (_delegationSummaryCard(item.id) case final card?) card,
            _activityContractTopCard(item),
            _AssetUnifiedCard(
              title: _isBranchActivity ? 'بيانات الفرع' : 'بيانات النشاط',
              icon: Icons.storefront_outlined,
              color: _kActivityColor,
              children: [
                // النشاط الرئيسي: بياناته في «بيانات عقد الإيجار» و«بيانات
                // الرخصة» أسفل هذه البطاقة.
                if (_isBranchActivity) ...[
                _AssetInfoRow(
                  label: 'نوع النشاط',
                  value: item.subType.isEmpty ? 'غير محدد' : item.subType,
                  icon: Icons.badge_outlined,
                  color: _kActivityColor,
                ),
                _AssetInfoRow(
                  label: 'الموقع / العنوان',
                  value: item.locationOrType,
                  icon: Icons.place_outlined,
                  color: _kActivityColor,
                ),
                _AssetInfoRow(
                  label: 'المدير المسؤول',
                  value: item.owner,
                  icon: Icons.person_outline_rounded,
                  color: _kActivityColor,
                ),
                _AssetInfoRow(
                  label: 'رأس المال / القيمة',
                  value: item.amountLabel,
                  icon: Icons.payments_outlined,
                  color: _kActivityColor,
                ),
                _AssetInfoRow(
                  label: 'انتهاء الرخصة',
                  value: item.endDate,
                  icon: Icons.event_busy_outlined,
                  color: _kActivityColor,
                ),
                ],
                _AssetInfoRow(
                  label: 'الحالة',
                  value: item.status,
                  icon: Icons.flash_on_outlined,
                  color: _kActivityColor,
                ),
                if (_isBranchActivity)
                  _AssetInfoRow(
                    label: 'عدد الموظفين',
                    value: '${item.employees.length}',
                    icon: Icons.groups_2_outlined,
                    color: _kActivityColor,
                  )
                else
                  _AssetInfoRow(
                    label: 'عدد الفروع',
                    value: '${_branchRecords.length}',
                    icon: Icons.account_tree_outlined,
                    color: _kActivityColor,
                  ),
                if (_isBranchActivity && item.followupNote.isNotEmpty)
                  _AssetInfoRow(
                    label: 'ملاحظة المتابعة',
                    value: item.followupNote,
                    icon: Icons.sticky_note_2_outlined,
                    color: _kActivityColor,
                  ),
              ],
            ),
            // بيانات الرخصة وعقد الإيجار من «إضافة نشاط تجاري» (بلا
            // بيانات المؤجر والمستأجر والممثل).
            ..._activitySummaryExtras(item),
          ],
        );
      case 1:
        // الفرع: «إدارة النشاط» — عقد الإيجار ودفعاته كـ«إدارة الإيجار» في
        // الوحدة، وتحته الموظفون.
        if (_isBranchActivity) {
          return Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              _activityLeasePanel(item),
              const SizedBox(height: 6),
              const Text(
                'الموظفون',
                textAlign: TextAlign.right,
                style: TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w900,
                  color: Color(0xFF022E2A),
                ),
              ),
              const SizedBox(height: 8),
              if (item.employees.isEmpty)
                const _DetailHintCard(
                  message:
                      'لا يوجد موظفون بعد — اضغط + المقابل لعنوان القسم '
                      'لإضافة موظف.',
                ),
              for (var i = 0; i < item.employees.length; i++) ...[
                _EmployeeCard(
                  data: item.employees[i],
                  onEdit: () =>
                      _addEmployee(existing: item.employees[i], editIndex: i),
                  onDelete: () => _removeEmployee(i),
                ),
                const SizedBox(height: 8),
              ],
            ],
          );
        }
        // النشاط الرئيسي: «الفروع» — بطاقة لكل فرع كبطاقات الوحدات.
        if (_branchRecords.isEmpty) {
          return const _DetailHintCard(
            message:
                'لا توجد فروع بعد — اضغط + المقابل لعنوان «الفروع» لإضافة '
                'فرع.',
          );
        }
        return Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [for (final branch in _branchRecords) _branchCard(branch)],
        );
      case _kActivityLeaseTab: // إدارة النشاط — النشاط الرئيسي
        return _activityLeasePanel(item);
      case 2: // الحركات المالية — نفس الحركات المالية في العقار
        return _financeLikeProperty(
          item,
          paymentsEmpty:
              'لا توجد دفعات إيجار بعد — اذهب إلى «إدارة النشاط» لتسجيل '
              'عقد الإيجار وإضافة الدفعات.',
        );
      case 3: // المتابعة والتخطيط — كالعقار
        return _assetFollowUpsSection();
      case 4: // الصيانة — نفس نموذج صيانة العقار وشكل قائمتها
        return _propertyMaintenanceList();
      case 6: // الأفراد والجهات — المالك والموظفون وجهات النشاط
        return _AssetUnifiedCard(
          showHeader: false,
          title: 'الأفراد والجهات',
          icon: Icons.people_alt_outlined,
          color: _kActivityColor,
          onAdd: _openQuickPersonSheet,
          addTooltip: 'إضافة فرد أو جهة',
          children: [
            _AssetInfoRow(
              label: 'المدير المسؤول',
              value: item.owner.isEmpty ? 'غير محدد' : item.owner,
              icon: Icons.person_outline_rounded,
              color: _kActivityColor,
            ),
            if (item.employees.isEmpty && _assetPeople.isEmpty)
              const Padding(
                padding: EdgeInsets.symmetric(vertical: 6),
                child: Align(
                  alignment: Alignment.centerRight,
                  child: Text(
                    'لا يوجد أفراد مرتبطون بعد — كل من يُضاف هنا يُحفظ في '
                    '«الأفراد والجهات» تلقائيًا.',
                    textAlign: TextAlign.right,
                    style: TextStyle(
                      fontSize: 11,
                      height: 1.5,
                      fontWeight: FontWeight.w600,
                      color: Color(0xFF5C6B68),
                    ),
                  ),
                ),
              )
            else
              for (final employee in item.employees)
                _AssetInfoRow(
                  label:
                      '${employee['الاسم'] ?? ''} — '
                      '${employee['الوظيفة'] ?? 'موظف'}',
                  value: (employee['الجوال'] ?? '').isEmpty
                      ? 'بلا هاتف'
                      : employee['الجوال']!,
                  icon: Icons.badge_outlined,
                  color: _kActivityColor,
                ),
            // المضافون من «+» هنا، حسب سهم الفلتر — كالعقار.
            ..._assetPeopleRows(_kActivityColor),
          ],
        );
      case 7: // الأصول والمعدات المسجّلة مع النشاط
        return _AssetUnifiedCard(
          showHeader: false,
          title: 'الأصول والمرافق',
          icon: Icons.precision_manufacturing_outlined,
          color: _kActivityColor,
          onAdd: _addActivityAsset,
          addTooltip: 'إضافة أصل أو معدة',
          children: [
            if (item.annexes.isEmpty)
              const Padding(
                padding: EdgeInsets.symmetric(vertical: 6),
                child: Align(
                  alignment: Alignment.centerRight,
                  child: Text(
                    'لا توجد أصول أو معدات مسجّلة لهذا النشاط بعد.',
                    textAlign: TextAlign.right,
                    style: TextStyle(
                      fontSize: 11,
                      fontWeight: FontWeight.w600,
                      color: Color(0xFF5C6B68),
                    ),
                  ),
                ),
              )
            else
              for (final annex in item.annexes.entries)
                _AssetInfoRow(
                  label: annex.key,
                  value: 'العدد: ${annex.value}',
                  icon: Icons.check_circle_outline_rounded,
                  color: _kActivityColor,
                ),
          ],
        );
      case 8: // إدارة الشيكات
        return _buildChequesSection();
      case 5: // المستندات — كل نوع في مكانه، وفلتر النوع في سطر العنوان
        return _documentsByType();
      default: // الملاحظات
        return _AssetUnifiedCard(
          showHeader: false,
          title: 'الملاحظات',
          icon: Icons.sticky_note_2_outlined,
          color: _kActivityColor,
          children: [
            Align(
              alignment: Alignment.centerRight,
              child: Text(
                item.description.isEmpty
                    ? 'لا توجد ملاحظات مسجّلة بعد.'
                    : item.description,
                textAlign: TextAlign.right,
                style: const TextStyle(
                  fontSize: 12,
                  color: Color(0xFF2C3B38),
                  height: 1.6,
                ),
              ),
            ),
          ],
        );
    }
  }

  // ============================================================
  // فئة "المعدات" — نفس النمط، بتبويبات مبنية على المتطلبات المنطقية
  // لتتبع أي معدة: بياناتها الفنية، صيانتها، حركتها المالية، مستنداتها.
  // ============================================================

  /// أقسام الآلية/المعدة: البيانات الفنية ثم إدارة التأجير، ولا «ملاحظات»
  /// مستقلة — الملاحظات داخل «المتابعة والتخطيط».
  static const List<DetailSectionTab> _equipmentTabs = [
