  /// تعديل بيانات الآلية/المعدة بالنموذج نفسه.
  Future<void> _editEquipment() async {
    final result = await Navigator.of(context).push<_EquipmentDraft>(
      MaterialPageRoute(
        builder: (_) => _AddEquipmentScreen(
          initial: _EquipmentDraft(
            name: _item.title,
            equipmentType:
                _item.propertyMeta[_EquipKeys.model] ?? _item.subType,
            serialNumber: _item.serialNumber,
            meta: _item.propertyMeta,
            annexes: _item.annexes,
          ),
        ),
      ),
    );
    if (result == null || !mounted) return;
    String of(String key) => (result.meta[key] ?? '').trim();
    _updateItem(
      _item.copyWith(
        title: result.name,
        subType: of(_EquipKeys.vehicleType).isNotEmpty
            ? of(_EquipKeys.vehicleType)
            : (result.equipmentType.isEmpty ? 'معدة' : result.equipmentType),
        serialNumber: result.serialNumber,
        propertyMeta: result.meta,
        annexes: result.annexes,
        endDate: of(_EquipKeys.ownershipEnd).isEmpty
            ? 'غير محدد'
            : of(_EquipKeys.ownershipEnd),
        // المستأجر من عقد التأجير القائم لا يُستبدل بتعديل بيانات المركبة.
        tenant: _equipContract != null &&
                _contractHolds(_equipContract!) &&
                _item.tenant.trim().isNotEmpty &&
                _item.tenant != 'غير محدد'
            ? _item.tenant
            : of(_EquipKeys.company).isEmpty
            ? 'غير محدد'
            : of(_EquipKeys.company),
        locationOrType: of(_EquipKeys.projectLocation).isEmpty
            ? 'غير محدد'
            : of(_EquipKeys.projectLocation),
        annualYield: of(_EquipKeys.condition).isEmpty
            ? 'غير محدد'
            : of(_EquipKeys.condition),
      ),
    );
    await _syncEquipmentReminders(result.name, result.meta);
  }

  // ================= إدارة تأجير المركبة =================
  // مثل «إدارة الإيجار» في الوحدات: عقد تأجير في جدول العقود نفسه
  // (unit_key = equipment)، ودفعاته في جدول الدفعات نفسه — فتعمل صفحة
  // الدفعات والسداد وسند القبض والمطالبة المالية والطباعة كما هي.

  /// عقود تأجير هذه الآلية، الأحدث أولًا.
  List<PropertyUnitContractRecord> get _equipContracts {
    final list = _unitContracts
        .where((contract) => contract.unitKey == _kEquipUnitKey)
        .toList();
    list.sort((a, b) {
      final da = a.startDate;
      final db = b.startDate;
      if (da == null && db == null) return 0;
      if (da == null) return 1;
      if (db == null) return -1;
      return db.compareTo(da);
    });
    return list;
  }

  /// العقد الجاري (غير المنتهي) — أو لا شيء.
  PropertyUnitContractRecord? get _equipContract {
    for (final contract in _equipContracts) {
      if (contract.status != PropertyUnitContractRecord.statusExpired) {
        return contract;
      }
    }
    return null;
  }

  /// دفعات إيجار الآلية من كل عقودها.
  List<RentPaymentEntry> get _equipPayments => _propertyPayments
      .where((entry) => entry.contract.unitKey == _kEquipUnitKey)
      .toList(growable: false);

