  /// نموذج شروط التأجير: الموقع، وقت البدء والإغلاق، على من الصيانة
  /// والوقود، ورقم التواصل.
  Future<void> _editRentalTerms() async {
    final meta = Map<String, String>.of(_item.propertyMeta);
    final locationCtrl = TextEditingController(
      text: meta[_EquipKeys.projectLocation] ?? '',
    );
    final phoneCtrl = TextEditingController(
      text: meta[_EquipKeys.contactPhone] ?? '',
    );
    final notesCtrl = TextEditingController(
      text: meta[_EquipKeys.termsNotes] ?? '',
    );
    var startDate = meta[_EquipKeys.projectStart] ?? '';
    var startTime = meta[_EquipKeys.projectStartTime] ?? '';
    var endDate = meta[_EquipKeys.projectEnd] ?? '';
    var endTime = meta[_EquipKeys.projectEndTime] ?? '';
    var maintenanceOn = meta[_EquipKeys.maintenanceOn] ?? '';
    var fuelOn = meta[_EquipKeys.fuelOn] ?? '';
    const parties = ['على المستأجر', 'على المالك'];
    final saved = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(AppTheme.rCard),
        ),
      ),
      builder: (sheetContext) => StatefulBuilder(
        builder: (sheetContext, setSheet) {
          Future<void> pickDate(void Function(String) onPicked) async {
            final picked = await showDatePicker(
              context: sheetContext,
              initialDate: DateTime.now(),
              firstDate: DateTime(2015),
              lastDate: DateTime(2070),
            );
            if (picked == null) return;
            setSheet(
              () => onPicked('${picked.day}/${picked.month}/${picked.year}'),
            );
          }

          Future<void> pickTime(void Function(String) onPicked) async {
            final picked = await showTimePicker(
              context: sheetContext,
              initialTime: TimeOfDay.now(),
            );
            if (picked == null) return;
            setSheet(
              () => onPicked(
                '${picked.hour.toString().padLeft(2, '0')}:'
                '${picked.minute.toString().padLeft(2, '0')}',
              ),
            );
          }

          Widget box(
            String text,
            IconData icon,
            VoidCallback onTap, {
            VoidCallback? onClear,
          }) =>
              InkWell(
                onTap: onTap,
                borderRadius: BorderRadius.circular(AppTheme.rInner),
                child: Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 14,
                  ),
                  decoration: BoxDecoration(
                    color: AppTheme.field,
                    borderRadius: BorderRadius.circular(AppTheme.rInner),
                    border: Border.all(color: AppTheme.line),
                  ),
                  child: Row(
                    textDirection: AppTr.uiDir,
                    children: [
                      Icon(icon, size: 17, color: _kEquipmentColor),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(
                          text,
                          textAlign: AppTr.alignEnd,
                          style: const TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.w800,
                            color: Color(0xFF022E2A),
                          ),
                        ),
                      ),
                      // بعد الاختيار: × يمسح التاريخ / الساعة.
                      if (onClear != null)
                        InkWell(
                          onTap: onClear,
                          customBorder: const CircleBorder(),
                          child: Padding(
                            padding: const EdgeInsets.all(2),
                            child: Icon(
                              Icons.close_rounded,
                              size: 16,
                              color: AppTheme.muted,
                              semanticLabel: AppTr.tr('مسح التاريخ'),
                            ),
                          ),
                        ),
                    ],
                  ),
                ),
              );

          Widget choice(
            String label,
            String value,
            ValueChanged<String> onPick,
          ) => Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              _propertyFieldLabel(label),
              const SizedBox(height: 6),
              Row(
                children: [
                  for (final option in parties) ...[
                    Expanded(
                      child: InkWell(
                        onTap: () => setSheet(() => onPick(option)),
                        borderRadius: BorderRadius.circular(AppTheme.rIcon),
                        child: Container(
                          padding: const EdgeInsets.symmetric(vertical: 11),
                          alignment: Alignment.center,
                          decoration: BoxDecoration(
                            color: value == option
                                ? _kEquipmentColor
                                : AppTheme.paper,
                            borderRadius: BorderRadius.circular(
                              AppTheme.rIcon,
                            ),
                            border: Border.all(
                              color: value == option
                                  ? _kEquipmentColor
                                  : AppTheme.hairline,
                            ),
                          ),
                          child: Text(
                            option,
                            style: TextStyle(
                              fontSize: 12,
                              fontWeight: FontWeight.w900,
                              color: value == option
                                  ? Colors.white
                                  : AppTheme.title,
                            ),
                          ),
                        ),
                      ),
                    ),
                    if (option != parties.last) const SizedBox(width: 8),
                  ],
                ],
              ),
            ],
          );

          return Directionality(
            textDirection: AppTr.uiDir,
            child: Padding(
              padding: EdgeInsets.fromLTRB(
                16,
                14,
                16,
                MediaQuery.of(sheetContext).viewInsets.bottom + 16,
              ),
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    const Text(
                      'شروط التأجير',
                      textAlign: TextAlign.right,
                      style: TextStyle(
                        fontSize: 14,
                        fontWeight: FontWeight.w900,
                        color: Color(0xFF022E2A),
                      ),
                    ),
                    const SizedBox(height: 12),
                    TextField(
                      controller: locationCtrl,
                      textAlign: AppTr.alignEnd,
                      decoration: _propertyInputDecorationShared('الموقع'),
                    ),
                    const SizedBox(height: 10),
                    _propertyFieldLabel('وقت البدء'),
                    const SizedBox(height: 6),
                    Row(
                      children: [
                        Expanded(
                          child: box(
                            startDate.isEmpty ? 'التاريخ' : startDate,
                            Icons.calendar_today_rounded,
                            () => pickDate((v) => startDate = v),
                            onClear: startDate.isEmpty
                                ? null
                                : () => setSheet(() => startDate = ''),
                          ),
                        ),
                        const SizedBox(width: 8),
                        Expanded(
                          child: box(
                            startTime.isEmpty ? 'الساعة' : startTime,
                            Icons.schedule_rounded,
                            () => pickTime((v) => startTime = v),
                            onClear: startTime.isEmpty
                                ? null
                                : () => setSheet(() => startTime = ''),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 10),
                    _propertyFieldLabel('وقت الإغلاق'),
                    const SizedBox(height: 6),
                    Row(
                      children: [
                        Expanded(
                          child: box(
                            endDate.isEmpty ? 'التاريخ' : endDate,
                            Icons.calendar_today_rounded,
                            () => pickDate((v) => endDate = v),
                            onClear: endDate.isEmpty
                                ? null
                                : () => setSheet(() => endDate = ''),
                          ),
                        ),
                        const SizedBox(width: 8),
                        Expanded(
                          child: box(
                            endTime.isEmpty ? 'الساعة' : endTime,
                            Icons.schedule_rounded,
                            () => pickTime((v) => endTime = v),
                            onClear: endTime.isEmpty
                                ? null
                                : () => setSheet(() => endTime = ''),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 12),
                    choice(
                      'على من الصيانة',
                      maintenanceOn,
                      (v) => maintenanceOn = v,
                    ),
                    const SizedBox(height: 12),
                    choice('على من الوقود', fuelOn, (v) => fuelOn = v),
                    const SizedBox(height: 12),
                    TextField(
                      controller: phoneCtrl,
                      textAlign: AppTr.alignEnd,
                      keyboardType: TextInputType.phone,
                      decoration: _propertyInputDecorationShared('رقم التواصل'),
                    ),
                    const SizedBox(height: 12),
                    TextField(
                      controller: notesCtrl,
                      textAlign: AppTr.alignEnd,
                      minLines: 2,
                      maxLines: 5,
                      decoration: _propertyInputDecorationShared('ملاحظات'),
                    ),
                    const SizedBox(height: 16),
                    FilledButton(
                      onPressed: () {
                        // الإغلاق لا يسبق البدء.
                        final from = entryParseDay(startDate);
                        final to = entryParseDay(endDate);
                        if (from != null && to != null && to.isBefore(from)) {
                          ScaffoldMessenger.of(sheetContext).showSnackBar(
                            const SnackBar(
                              content: Text(
                                'تاريخ الإغلاق قبل تاريخ البدء — صحّح التاريخين',
                              ),
                              behavior: SnackBarBehavior.floating,
                            ),
                          );
                          return;
                        }
                        Navigator.of(sheetContext).pop(true);
                      },
                      style: FilledButton.styleFrom(
                        backgroundColor: _kEquipmentColor,
                        foregroundColor: Colors.white,
                        minimumSize: const Size.fromHeight(46),
                      ),
                      child: const Text('حفظ'),
                    ),
                  ],
                ),
              ),
            ),
          );
        },
      ),
    );
    final location = locationCtrl.text.trim();
    final phone = phoneCtrl.text.trim();
    final notes = notesCtrl.text.trim();
    Future.delayed(const Duration(milliseconds: 400), () {
      locationCtrl.dispose();
      phoneCtrl.dispose();
      notesCtrl.dispose();
    });
    if (saved != true || !mounted) return;
    void put(String key, String value) {
      if (value.trim().isEmpty) {
        meta.remove(key);
      } else {
        meta[key] = value.trim();
      }
    }

    put(_EquipKeys.projectLocation, location);
    put(_EquipKeys.projectStart, startDate);
    put(_EquipKeys.projectStartTime, startTime);
    put(_EquipKeys.projectEnd, endDate);
    put(_EquipKeys.projectEndTime, endTime);
    put(_EquipKeys.maintenanceOn, maintenanceOn);
    put(_EquipKeys.fuelOn, fuelOn);
    put(_EquipKeys.contactPhone, phone);
    put(_EquipKeys.termsNotes, notes);
    _updateItem(_item.copyWith(propertyMeta: meta));
  }

  /// اختيار فرد أو جهة من «الأفراد والجهات» — المستأجرون والشركات أولًا.
  Future<PeopleDirectoryEntry?> _pickDirectoryPerson() async {
    final entries = await PeopleDirectoryStore.load();
    if (!mounted) return null;
    if (entries.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('لا يوجد أفراد أو جهات بعد — اضغط «إضافة مستأجر»'),
          behavior: SnackBarBehavior.floating,
        ),
      );
      return null;
    }
    bool isTenant(PeopleDirectoryEntry entry) =>
        entry.typeKey == PeopleDirectoryStore.typeTenant ||
        entry.typeKey == PeopleDirectoryStore.typeCompany;
    final sorted = [
      ...entries.where(isTenant),
      ...entries.where((entry) => !isTenant(entry)),
    ];
    var query = '';
    return showModalBottomSheet<PeopleDirectoryEntry>(
      context: context,
      isScrollControlled: true,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(AppTheme.rCard),
        ),
      ),
      builder: (sheetContext) => StatefulBuilder(
        builder: (sheetContext, setSheetState) {
          final q = query.trim();
          final filtered = sorted
              .where(
                (entry) =>
                    q.isEmpty ||
                    entry.fullName.contains(q) ||
                    entry.categoryName.contains(q),
              )
              .toList(growable: false);
          return Directionality(
            textDirection: AppTr.uiDir,
            child: Padding(
              padding: EdgeInsets.fromLTRB(
                16,
                14,
                16,
                MediaQuery.of(sheetContext).viewInsets.bottom + 16,
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  const Text(
                    'اختر المستأجر من الأفراد والجهات',
                    style: TextStyle(
                      fontSize: 14,
                      fontWeight: FontWeight.w900,
                      color: AppTheme.title,
                    ),
                  ),
                  const SizedBox(height: 10),
                  TextField(
                    textAlign: AppTr.alignEnd,
                    decoration: _propertyInputDecoration(
                      'ابحث بالاسم أو التصنيف',
                    ),
                    onChanged: (value) => setSheetState(() => query = value),
                  ),
                  const SizedBox(height: 10),
                  SizedBox(
                    height: 320,
                    child: ListView.separated(
                      itemCount: filtered.length,
                      separatorBuilder: (_, __) =>
                          const Divider(height: 1, color: AppTheme.line),
                      itemBuilder: (context, index) {
                        final entry = filtered[index];
                        final phone = entry.firstOf(
                          const ['رقم الجوال', 'رقم الهاتف'],
                        );
                        return ListTile(
                          dense: true,
                          contentPadding: EdgeInsets.zero,
                          leading: Icon(
                            entry.isEntity
                                ? Icons.business_rounded
                                : Icons.person_rounded,
                            color: _kEquipmentColor,
                          ),
                          title: Text(
                            entry.fullName,
                            style: const TextStyle(
                              fontSize: 13,
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                          subtitle: Text(
                            [
                              entry.categoryName,
                              if (phone.isNotEmpty) phone,
                            ].join(' · '),
                            style: const TextStyle(fontSize: 11),
                          ),
                          onTap: () => Navigator.pop(sheetContext, entry),
                        );
                      },
                    ),
                  ),
                ],
              ),
            ),
          );
        },
      ),
    );
  }

  /// بيانات المركبة كما تظهر في عقدها (مكان «بيانات العقار»).
  (List<LeaseFieldSpec>, Map<String, String>) _vehicleLeaseFields() {
    final meta = _item.propertyMeta;
    final marine = (meta[_EquipKeys.vehicleClass] ?? '') == _kVehicleMarine;
    String m(String key) => (meta[key] ?? '').trim();
    final type = m(_EquipKeys.vehicleType);
    final rows = <(String, String)>[
      ('تصنيف المركبة', meta[_EquipKeys.vehicleClass] ?? _kVehicleLand),
      ('نوع المركبة', type.isEmpty ? _item.subType : type),
      ('اسم المركبة', _item.title),
      ('الموديل', m(_EquipKeys.model)),
      if (marine)
        ('رقم التسجيل البحري', m(_EquipKeys.registration))
      else
        ('رقم اللوحة', m(_EquipKeys.plate)),
      (marine ? 'رقم الهيكل (HIN)' : 'رقم الشاصي', _item.serialNumber),
      if (marine) ('المرسى / الميناء', m(_EquipKeys.marina)),
      if (marine) ('السعة', m(_EquipKeys.capacity)),
      ('تاريخ انتهاء الملكية', m(_EquipKeys.ownershipEnd)),
      ('تاريخ انتهاء التأمين', m(_EquipKeys.insuranceEnd)),
    ];
    return (
      [for (final row in rows) LeaseFieldSpec(row.$1, row.$1)],
      {for (final row in rows) row.$1: row.$2},
    );
  }

  /// عقد تأجير المركبة بنموذج عقد العقار نفسه: بيانات المركبة مكان بيانات
  /// العقار، بلا ممثل المستأجر ولا «الغرض من الإيجار». العقود القديمة
  /// (قبل هذا النموذج) تُعدَّل بنموذجها القديم حتى لا تضيع دفعاتها.
  Future<void> _openEquipContractForm({
    PropertyUnitContractRecord? existing,
    PropertyUnitContractRecord? renewFrom,
  }) async {
    if (existing == null && _hasBlockingMaintenance) {
      _showMaintBlockNotice(
        context,
        'المركبة تحت صيانة تمنع التأجير — سجّل «انتهاء الصيانة» من قسم '
        'الصيانة أولًا.',
      );
      return;
    }
    if (existing != null && !_isLeaseContract(existing)) {
      return _openLegacyEquipContractForm(existing: existing);
    }
    final repo = widget.repository;
    final assetId = _item.id;
    if (repo == null || assetId == null || assetId.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('يجب حفظ المركبة أولاً')),
      );
      return;
    }
    final (fields, values) = _vehicleLeaseFields();
    String? template;
    if (existing == null && renewFrom == null) {
      // عقد جديد: شروط التأجير المسجّلة سابقًا على المركبة تُنقل إليه.
      final meta = _item.propertyMeta;
      String party(String? v) =>
          (v ?? '').trim() == 'على المالك' ? 'على المؤجر' : (v ?? '').trim();
      final terms = <String, String>{
        LeaseContractData.kTermsLocation:
            (meta[_EquipKeys.projectLocation] ?? '').trim(),
        LeaseContractData.kTermsMaintenanceOn:
            party(meta[_EquipKeys.maintenanceOn]),
        LeaseContractData.kTermsFuelOn: party(meta[_EquipKeys.fuelOn]),
        LeaseContractData.kTermsTransportOn:
            party(meta[_EquipKeys.transportOn]),
        LeaseContractData.kTermsPhone:
            (meta[_EquipKeys.contactPhone] ?? '').trim(),
        LeaseContractData.kTermsNotes:
            (meta[_EquipKeys.termsNotes] ?? '').trim(),
      }..removeWhere((_, v) => v.isEmpty);
      if (terms.isNotEmpty) {
        final seed = LeaseContractData.decode(null);
        seed.contract.addAll(terms);
        template = seed.encode();
      }
    }
    if (renewFrom != null) {
      if (_isLeaseContract(renewFrom)) {
        template = renewFrom.notes;
      } else {
        final seed = LeaseContractData.decode(null);
        seed.tenant[LeaseContractData.kName] = renewFrom.tenantName ?? '';
        seed.tenant[LeaseContractData.kMobile] = renewFrom.tenantPhone ?? '';
        template = seed.encode();
      }
    }
    final vehicleClass =
        _item.propertyMeta[_EquipKeys.vehicleClass] ?? _kVehicleLand;
    final saved = await Navigator.of(context).push<PropertyUnitContractRecord>(
      MaterialPageRoute(
        builder: (_) => LeaseContractFormScreen(
          repository: repo,
          assetId: assetId,
          unitKey: _kEquipUnitKey,
          unitName: _item.title,
          propertyTitle: _item.title,
          propertyMeta: values,
          existing: existing,
          vehicleFields: fields,
          title: 'عقد تأجير $vehicleClass',
          subjectLabel: 'المركبة',
          templateNotes: template,
        ),
      ),
    );
    if (saved == null || !mounted) return;
    // التجديد: العقد السابق يُعلَّم منتهيًا، والجديد يبدأ بعده.
    if (renewFrom != null && renewFrom.id != saved.id) {
      try {
        await repo.upsertUnitContract(
          renewFrom.copyWith(status: PropertyUnitContractRecord.statusExpired),
        );
      } catch (_) {}
    }
    final tenant = (saved.tenantName ?? '').trim();
    if (tenant.isNotEmpty && tenant != 'بلا اسم' && tenant != _item.tenant) {
      _updateItem(_item.copyWith(tenant: tenant));
    }
    await _loadUnitContractsFromRemote();
  }

  /// النموذج القديم المختصر — لتعديل عقود المركبات القديمة فقط.
  Future<void> _openLegacyEquipContractForm({
    PropertyUnitContractRecord? existing,
    PropertyUnitContractRecord? renewFrom,
  }) async {
    final repo = widget.repository;
    final assetId = _item.id;
    if (repo == null || assetId == null || assetId.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('يجب حفظ المركبة أولاً')),
      );
      return;
    }
    final source = existing ?? renewFrom;
    final extra = source == null
        ? <String, String>{}
        : _equipContractExtra(source);
    final meta = _item.propertyMeta;
    final companyCtrl = TextEditingController(
      text: source?.tenantName ?? meta[_EquipKeys.company] ?? '',
    );
    final phoneCtrl = TextEditingController(text: source?.tenantPhone ?? '');
    final rateCtrl = TextEditingController(text: extra['rate'] ?? '');
    final noteCtrl = TextEditingController(
      text: existing == null ? '' : (extra['note'] ?? ''),
    );
    DateTime? start;
    DateTime? end;
    if (existing != null) {
      start = existing.startDate;
      end = existing.endDate;
    } else if (renewFrom != null) {
      final oldStart = renewFrom.startDate;
      final oldEnd = renewFrom.endDate;
      final from = oldEnd == null
          ? DateTime.now()
          : oldEnd.add(const Duration(days: 1));
      final renewStart = DateTime(from.year, from.month, from.day);
      start = renewStart;
      if (oldStart != null && oldEnd != null) {
        end = renewStart.add(oldEnd.difference(oldStart));
      }
    } else {
      start =
          AppRemindersStore.parseDisplayDate(
            meta[_EquipKeys.projectStart] ?? '',
          ) ??
          DateTime.now();
    }
    var basis = extra['basis'] ?? (meta[_EquipKeys.operation] ?? 'شهري');
    if (!_kEquipRentBases.contains(basis)) basis = 'شهري';
    final hasPayments =
        existing != null &&
        _equipPayments.any((entry) => entry.contract.id == existing.id);
    var autoPay = !hasPayments;
    final title = existing != null
        ? 'تعديل عقد التأجير'
        : renewFrom != null
        ? 'تجديد عقد التأجير'
        : 'عقد تأجير المركبة';

    final confirmed = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (sheetContext) => StatefulBuilder(
        builder: (sheetContext, setSheet) {
          Future<void> pick(bool isStart) async {
            final picked = await showDatePicker(
              context: sheetContext,
              initialDate: (isStart ? start : end) ?? start ?? DateTime.now(),
              firstDate: DateTime(2000),
              lastDate: DateTime(2070),
            );
            if (picked == null) return;
            setSheet(() {
              if (isStart) {
                start = picked;
              } else {
                end = picked;
              }
            });
          }

          Widget field(
            String label,
            TextEditingController controller, {
            bool numeric = false,
            String hint = '',
          }) => Padding(
            padding: const EdgeInsets.only(bottom: 12),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                _propertyFieldLabel(label),
                const SizedBox(height: 6),
                TextField(
                  controller: controller,
                  textAlign: AppTr.alignEnd,
                  keyboardType: numeric
                      ? TextInputType.number
                      : TextInputType.text,
                  decoration: _propertyInputDecoration(hint),
                ),
              ],
            ),
          );

          Widget dateBox(String label, bool isStart) => Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              _propertyFieldLabel(label),
              const SizedBox(height: 6),
              InkWell(
                onTap: () => pick(isStart),
                borderRadius: BorderRadius.circular(12),
                child: InputDecorator(
                  decoration: _propertyInputDecoration(
                    '',
                  ).copyWith(suffixIcon: const Icon(Icons.event_rounded, size: 19)),
                  child: Text(
                    (isStart ? start : end) == null
                        ? 'اختر التاريخ'
                        : _equipDate(isStart ? start : end),
                    textAlign: TextAlign.right,
                  ),
                ),
              ),
            ],
          );

          final per = _equipRatePer(basis);
          return Directionality(
            textDirection: AppTr.uiDir,
            child: Padding(
              padding: EdgeInsets.only(
                bottom: MediaQuery.of(sheetContext).viewInsets.bottom,
              ),
              child: SafeArea(
                top: false,
                child: SingleChildScrollView(
                  padding: const EdgeInsets.fromLTRB(16, 16, 16, 18),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      Text(
                        title,
                        textAlign: TextAlign.center,
                        style: const TextStyle(
                          fontSize: 16,
                          fontWeight: FontWeight.w900,
                          color: Color(0xFF022E2A),
                        ),
                      ),
                      const SizedBox(height: 16),
                      field('المستأجر (فرد أو جهة)', companyCtrl),
                      // كالعقار: المستأجر يُضاف في «الأفراد والجهات» ثم
                      // يُجلب هنا، فيُعبّأ اسمه وجواله.
                      Row(
                        textDirection: AppTr.uiDir,
                        children: [
                          Expanded(
                            child: OutlinedButton.icon(
                              onPressed: () async {
                                final entry = await _pickDirectoryPerson();
                                if (entry == null) return;
                                setSheet(() {
                                  companyCtrl.text = entry.fullName;
                                  final phone = entry.firstOf(
                                    const ['رقم الجوال', 'رقم الهاتف'],
                                  );
                                  if (phone.isNotEmpty) phoneCtrl.text = phone;
                                });
                              },
                              icon: const Icon(
                                Icons.person_search_rounded,
                                size: 18,
                              ),
                              label: const Text('جلب من الأفراد والجهات'),
                              style: OutlinedButton.styleFrom(
                                foregroundColor: _kEquipmentColor,
                                minimumSize: const Size.fromHeight(44),
                              ),
                            ),
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child: OutlinedButton.icon(
                              onPressed: _openQuickPersonSheet,
                              icon: const Icon(
                                Icons.person_add_alt_1_rounded,
                                size: 18,
                              ),
                              label: const Text('إضافة مستأجر'),
                              style: OutlinedButton.styleFrom(
                                foregroundColor: _kEquipmentColor,
                                minimumSize: const Size.fromHeight(44),
                              ),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 12),
                      field(
                        'رقم الهاتف (اختياري)',
                        phoneCtrl,
                        numeric: true,
                      ),
                      Row(
                        textDirection: AppTr.uiDir,
                        children: [
                          Expanded(child: dateBox('بداية العقد', true)),
                          const SizedBox(width: 10),
                          Expanded(child: dateBox('نهاية العقد', false)),
                        ],
                      ),
                      const SizedBox(height: 12),
                      _propertyFieldLabel('طريقة التأجير'),
                      const SizedBox(height: 6),
                      DropdownButtonFormField<String>(
                        key: ValueKey('equip-basis-$basis'),
                        initialValue: basis,
                        isExpanded: true,
                        decoration: _propertyInputDecoration(''),
                        items: [
                          for (final option in _kEquipRentBases)
                            DropdownMenuItem(
                              value: option,
                              child: Text(option),
                            ),
                        ],
                        onChanged: (value) {
                          if (value == null) return;
                          setSheet(() => basis = value);
                        },
                      ),
                      const SizedBox(height: 12),
                      field(
                        'المبلغ المتفق عليه لكل $per',
                        rateCtrl,
                        numeric: true,
                        hint: AppSettings.currencySuffix,
                      ),
                      if (basis == 'شهري' && !hasPayments)
                        CheckboxListTile(
                          value: autoPay,
                          onChanged: (value) =>
                              setSheet(() => autoPay = value ?? false),
                          contentPadding: EdgeInsets.zero,
                          controlAffinity: ListTileControlAffinity.leading,
                          activeColor: _kEquipmentColor,
                          title: const Text(
                            'توليد الدفعات الشهرية تلقائيًا من بداية العقد '
                            'إلى نهايته',
                            style: TextStyle(
                              fontSize: 12,
                              fontWeight: FontWeight.w700,
                            ),
                          ),
                        ),
                      field('ملاحظات', noteCtrl),
                      const SizedBox(height: 6),
                      ElevatedButton(
                        onPressed: start == null
                            ? null
                            : () => Navigator.pop(sheetContext, true),
                        style: ElevatedButton.styleFrom(
                          backgroundColor: _kEquipmentColor,
                          foregroundColor: Colors.white,
                          minimumSize: const Size.fromHeight(50),
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(12),
                          ),
                        ),
                        child: Text(
                          renewFrom != null ? 'تجديد العقد' : 'حفظ العقد',
                          style: const TextStyle(
                            fontSize: 15,
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          );
        },
      ),
    );

    final company = companyCtrl.text.trim();
    final phone = phoneCtrl.text.trim();
    final rateText = rateCtrl.text.trim();
    final note = noteCtrl.text.trim();
    Future.delayed(const Duration(milliseconds: 400), () {
      companyCtrl.dispose();
      phoneCtrl.dispose();
      rateCtrl.dispose();
      noteCtrl.dispose();
    });
    final s = start;
    final e = end;
    if (confirmed != true || s == null || !mounted) return;

    final rate =
        double.tryParse(rateText.replaceAll(',', '').replaceAll('٬', '')) ?? 0;
    final months = _equipMonthsBetween(s, e);
    final total = basis == 'شهري' && months > 0 ? rate * months : rate;
    final notes = jsonEncode(<String, dynamic>{
      '__equip__': 1,
      'basis': basis,
      'rate': rateText,
      'note': note,
    });
    try {
      if (renewFrom != null) {
        // التجديد: العقد السابق يُعلَّم منتهيًا، ويبدأ عقد جديد بعده.
        await repo.upsertUnitContract(
          renewFrom.copyWith(status: PropertyUnitContractRecord.statusExpired),
        );
      }
      final base =
          existing ??
          PropertyUnitContractRecord(assetId: assetId, unitKey: _kEquipUnitKey);
      final saved = await repo.upsertUnitContract(
        base.copyWith(
          unitName: _item.title,
          tenantName: company,
          tenantPhone: phone,
          annualRent: total,
          paymentCycle: basis,
          startDate: s,
          endDate: e,
          status: existing?.status ?? PropertyUnitContractRecord.statusActive,
          notes: notes,
        ),
      );
      final contractId = saved.id;
      if (autoPay &&
          basis == 'شهري' &&
          rate > 0 &&
          e != null &&
          contractId != null &&
          contractId.isNotEmpty) {
        for (var i = 0; i < months; i++) {
          var due = DateTime(s.year, s.month + i + 1, s.day);
          if (due.isAfter(e)) due = e;
          await repo.upsertUnitPayment(
            PropertyUnitPaymentRecord(
              contractId: contractId,
              dueDate: due,
              amountDue: rate,
              notes: encodePayExtra(<String, String>{
                kPayKind: kPayKindRent,
                kPayName: 'إيجار الشهر ${i + 1}',
              }),
            ),
          );
        }
      }
      if (company.isNotEmpty && company != _item.tenant) {
        _updateItem(_item.copyWith(tenant: company));
      }
      await _loadUnitContractsFromRemote();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            renewFrom != null
                ? 'تم تجديد عقد التأجير'
                : existing != null
                ? 'تم تعديل عقد التأجير'
                : 'تم حفظ عقد التأجير',
          ),
        ),
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('تعذّر حفظ عقد التأجير: $error')),
      );
    }
  }

  /// ملخص دفعات العقد الجاري (مثل صندوق «إدارة الإيجار» في الوحدة)؛
  /// القائمة نفسها وسدادها في «الحركات المالية».
  /// فلتر صفحة دفعات المركبة.
  String _equipPayFilter = 'الكل';

  /// «عرض / سداد الدفعات» للمركبة: صفحة الدفعات نفسها في العقار.
  Future<void> _openEquipPaymentsPage(PropertyUnitContractRecord c) async {
    final repo = widget.repository;
    if (repo == null) return;
    List<RentPaymentEntry> of() => _equipPayments
        .where((entry) => entry.contract.id == c.id)
        .toList(growable: false);
    await Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => _UnitPaymentsPage(
          title: 'دفعات تأجير المركبة — ${_item.title}',
          repository: repo,
          assetTitle: _item.title,
          initial: of(),
          initialFilter: _equipPayFilter,
          onFilterChanged: (value) {
            if (mounted) setState(() => _equipPayFilter = value);
          },
          reload: () async {
            await _loadPropertyPayments();
            return of();
          },
        ),
      ),
    );
    if (mounted) setState(() {});
  }

  /// سجل العقود السابقة (المنتهية أو الملغاة) ومتبقّي كل منها — في
  /// «الحركات المالية» للعقار والنشاط والمركبة، لمتابعة من عليه مبالغ.
  /// مستحقات متأخرة على عقود منتهية أو ملغاة لم تُسوَّ — علامة حمراء على
  /// «السجل التاريخي» وعلى رابطه في الحركات المالية.
  double get _historyDues {
    final today = DateUtils.dateOnly(DateTime.now());
    // العنصر الملغى: كل أموره صارت في «السجل التاريخي»، ومنها عقوده التي
    // لم تُغلق بعد.
    final cancelled = _isCancelledAsset(_item);
    var total = 0.0;
    for (final entry in _propertyPayments) {
      final c = entry.contract;
      if (!cancelled && !_contractClosed(c) && !_contractEndedByDate(c)) {
        continue;
      }
      if (LeaseContractData.isSettled(c.notes)) continue;
      final due = entry.payment.dueDate;
      if (due == null || DateUtils.dateOnly(due).isAfter(today)) continue;
      total += payRemaining(entry.payment);
    }
    return total;
  }

  bool get _historyNeedsAttention =>
      _historyDues > 0.009 ||
      _oldDuesCount > 0 ||
      // عنصر ملغى وعليه عقد ساري لم يُسوَّ ويُغلق: يحتاج متابعة.
      (_isCancelledAsset(_item) &&
          _unitContracts.any(
            (c) =>
                !_contractClosed(c) &&
                c.status != PropertyUnitContractRecord.statusPending,
          ));

  /// العقود السابقة ومبالغها صارت في «السجل التاريخي»: هنا رابط واضح إليه
  /// (أحمر إن كانت هناك مبالغ متأخرة تحتاج تسوية).
  Widget _historyLinkCard(Color color) {
    final today = DateUtils.dateOnly(DateTime.now());
    final hasPast = _unitContracts.any(
      (c) =>
          _contractClosed(c) ||
          (c.endDate != null && DateUtils.dateOnly(c.endDate!).isBefore(today)),
    );
    if (!hasPast) return const SizedBox.shrink();
    final dues = _historyDues;
    final alert = dues > 0.009;
    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: InkWell(
        onTap: () => _openRecordsTab('السجل التاريخي'),
        borderRadius: BorderRadius.circular(AppTheme.rInner),
        child: Container(
          padding: const EdgeInsets.all(12),
          decoration: BoxDecoration(
            color: alert ? AppTheme.dangerSoft : AppTheme.surface,
            borderRadius: BorderRadius.circular(AppTheme.rInner),
            border: Border.all(
              color: alert
                  ? AppTheme.danger.withValues(alpha: 0.5)
                  : AppTheme.hairline,
            ),
          ),
          child: Row(
            textDirection: AppTr.uiDir,
            children: [
              Icon(
                Icons.history_edu_outlined,
                size: 22,
                color: alert ? AppTheme.danger : color,
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    const Text(
                      'عقود سابقة',
                      style: TextStyle(
                        fontSize: 12.5,
                        fontWeight: FontWeight.w900,
                        color: Color(0xFF022E2A),
                      ),
                    ),
                    const SizedBox(height: 2),
                    Text(
                      alert
                          ? '${AppTr.tr('مبالغ متأخرة تحتاج تسوية')}: '
                                '${formatMoneyValue(dues)} '
                                '${AppSettings.currencySuffix}'
                          : AppTr.tr('اضغط لعرض العقود المنتهية والملغاة'),
                      style: TextStyle(
                        fontSize: 11,
                        fontWeight: FontWeight.w800,
                        color: alert ? AppTheme.danger : AppTheme.muted,
                      ),
                    ),
                  ],
                ),
              ),
              Icon(
                Icons.chevron_left_rounded,
                color: alert ? AppTheme.danger : color,
              ),
            ],
          ),
        ),
      ),
    );
  }

  Widget _closedContractsFollowUp(Color color) {
    final today = DateUtils.dateOnly(DateTime.now());
    final closed = _unitContracts
        .where(
          (c) =>
              _contractClosed(c) ||
              (c.endDate != null &&
                  DateUtils.dateOnly(c.endDate!).isBefore(today) &&
                  c.unitKey != _kEquipUnitKey),
        )
        .toList();
    if (closed.isEmpty) return const SizedBox.shrink();
    closed.sort(
      (a, b) => (b.endDate ?? DateTime(1900)).compareTo(
        a.endDate ?? DateTime(1900),
      ),
    );
    String money(double value) =>
        '${formatMoneyValue(value)} ${AppSettings.currencySuffix}';
    var totalLeft = 0.0;
    final rows = <Widget>[];
    for (final contract in closed) {
      var left = 0.0;
      for (final entry in _propertyPayments) {
        if (entry.contract.id != contract.id) continue;
        left += payRemaining(entry.payment);
      }
      totalLeft += left;
      final unit = (contract.unitName ?? '').trim();
      final tenant = (contract.tenantName ?? '').trim();
      rows.add(
        Padding(
          padding: const EdgeInsets.only(top: 8),
          child: Row(
            textDirection: AppTr.uiDir,
            children: [
              Icon(
                left > 0 ? Icons.error_outline_rounded : Icons.check_circle,
                size: 18,
                color: left > 0 ? AppTheme.danger : const Color(0xFF34A894),
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      [
                        tenant.isEmpty ? 'مستأجر سابق' : tenant,
                        if (unit.isNotEmpty) unit,
                      ].join(' · '),
                      maxLines: 3,
                      style: const TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.w800,
                        color: Color(0xFF022E2A),
                      ),
                    ),
                    Text(
                      '${_equipDate(contract.startDate)} - '
                      '${_equipDate(contract.endDate)}',
                      style: const TextStyle(
                        fontSize: 10.5,
                        fontWeight: FontWeight.w600,
                        color: AppTheme.muted,
                      ),
                    ),
                  ],
                ),
              ),
              Text(
                left > 0
                    ? 'متبقٍ ${money(left)}'
                    : LeaseContractData.isSettled(contract.notes)
                    ? 'تمت التسوية'
                    : 'مسدد بالكامل',
                style: TextStyle(
                  fontSize: 11,
                  fontWeight: FontWeight.w900,
                  color: left > 0 ? AppTheme.danger : const Color(0xFF34A894),
                ),
              ),
            ],
          ),
        ),
      );
    }
    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: AppTheme.surface,
        borderRadius: BorderRadius.circular(AppTheme.rInner),
        border: Border.all(
          color: totalLeft > 0
              ? AppTheme.danger.withValues(alpha: 0.4)
              : AppTheme.hairline,
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            textDirection: AppTr.uiDir,
            children: [
              Icon(Icons.history_rounded, size: 18, color: color),
              const SizedBox(width: 6),
              const Expanded(
                child: Text(
                  'سجل العقود السابقة والمبالغ المتبقية',
                  style: TextStyle(
                    fontSize: 12.5,
                    fontWeight: FontWeight.w900,
                    color: Color(0xFF022E2A),
                  ),
                ),
              ),
            ],
          ),
          if (totalLeft > 0) ...[
            const SizedBox(height: 6),
            Text(
              'مبالغ تحتاج متابعة: ${money(totalLeft)}',
              style: const TextStyle(
                fontSize: 12,
                fontWeight: FontWeight.w900,
                color: AppTheme.danger,
              ),
            ),
          ],
          ...rows,
        ],
      ),
    );
  }

  /// تمديد عقد المركبة: يبقى العقد نفسه برقمه، وتُمدَّد نهايته.
  Future<void> _extendEquipContract(PropertyUnitContractRecord contract) async {
    final repo = widget.repository;
    if (repo == null) return;
    final by = await _pickExtension(context);
    if (by == null || !mounted) return;
    final isLease = _isLeaseContract(contract);
    final lease = isLease ? LeaseContractData.decode(contract.notes) : null;
    final endTime = lease?.contract[LeaseContractData.kEndTime];
    final withTime = by.hours > 0 || (endTime ?? '').trim().isNotEmpty;
    final from = _endWithTime(contract.endDate ?? DateTime.now(), endTime);
    final newEnd = _extendedEnd(from, by);
    if (!await _confirmExtension(
          context,
          by: by,
          start: contract.startDate,
          oldEnd: from,
          newEnd: newEnd,
          withTime: withTime,
        ) ||
        !mounted) {
      return;
    }
    final end = DateUtils.dateOnly(newEnd);
    var notes = contract.notes;
    if (lease != null) {
      lease.contract[LeaseContractData.kEndDate] = _actIso(end);
      if (withTime) {
        lease.contract[LeaseContractData.kEndTime] =
            '${newEnd.hour.toString().padLeft(2, '0')}:'
            '${newEnd.minute.toString().padLeft(2, '0')}';
      }
      notes = lease.encode();
    }
    try {
      await repo.upsertUnitContract(
        contract.copyWith(
          endDate: end,
          status: contract.status == PropertyUnitContractRecord.statusPending
              ? contract.status
              : PropertyUnitContractRecord.statusActive,
          notes: notes,
        ),
      );
      await _loadUnitContractsFromRemote();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('مُدِّد العقد حتى ${_equipDate(end)}')),
      );
    } catch (_) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذر تمديد العقد')),
      );
    }
  }

  /// سند قبض (ما سُدِّد) أو مطالبة مالية (ما بقي) لدفعات عقد المركبة.
  void _shareEquipDocument(
    PropertyUnitContractRecord contract, {
    required bool receipt,
  }) {
    final entries = _equipPayments
        .where((entry) => entry.contract.id == contract.id)
        .toList(growable: false);
    String money(double value) =>
        '${formatMoneyValue(value)} ${AppSettings.currencySuffix}';
    final buffer = StringBuffer()
      ..writeln(receipt ? 'سند قبض' : 'مطالبة مالية')
      ..writeln('المركبة: ${_item.title}')
      ..writeln('المستأجر: ${contract.tenantName ?? '—'}')
      ..writeln('التاريخ: ${_equipDate(DateTime.now())}')
      ..writeln('');
    var total = 0.0;
    for (final entry in entries) {
      final payment = entry.payment;
      final amount = receipt ? payment.amountPaid : payRemaining(payment);
      if (amount <= 0) continue;
      total += amount;
      buffer.writeln(
        '- ${entry.title}: ${money(amount)}'
        '${payment.dueDate == null ? '' : ' — استحقاق ${_equipDate(payment.dueDate)}'}',
      );
    }
    if (total <= 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            receipt ? 'لا توجد مبالغ مسددة بعد' : 'لا توجد مبالغ مستحقة',
          ),
          behavior: SnackBarBehavior.floating,
        ),
      );
      return;
    }
    buffer
      ..writeln('')
      ..writeln('${receipt ? 'إجمالي المسدد' : 'إجمالي المستحق'}: ${money(total)}');
    Share.share(buffer.toString());
  }

  /// إنهاء العقد — مثل العقارات: لا يُنهى قبل التسوية (لك/عليك وملاحظاتها).
  /// بعدها يُعلَّم العقد منتهيًا وتصير المركبة شاغرة، ثم خيار أرشفتها أو
  /// إلغائها.
  Future<void> _endEquipContract(PropertyUnitContractRecord contract) async {
    final repo = widget.repository;
    if (repo == null) return;
    final today = DateUtils.dateOnly(DateTime.now());
    final cheques = <String>[];
    var deposit = 0.0;
    var owed = 0.0;
    for (final entry in _equipPayments) {
      if (entry.contract.id != contract.id) continue;
      final payment = entry.payment;
      final extra = decodePayExtra(payment.notes);
      final remaining = payRemaining(payment);
      if ((extra[kPayKind] ?? '') == kPayKindDeposit) {
        deposit += payment.amountPaid;
        continue;
      }
      final cheque = (extra[kPayCheque] ?? '').trim();
      if (remaining > 0 && cheque.isNotEmpty) cheques.add(cheque);
      final due = payment.dueDate;
      if (remaining > 0 &&
          due != null &&
          !DateUtils.dateOnly(due).isAfter(today)) {
        owed += remaining;
      }
    }
    String money(double value) =>
        '${formatMoneyValue(value)} ${AppSettings.currencySuffix}';
    Widget head(String label, Color color) => Padding(
      padding: const EdgeInsets.only(bottom: 4),
      child: Text(
        label,
        textAlign: TextAlign.right,
        style: TextStyle(
          fontSize: 13,
          fontWeight: FontWeight.w900,
          color: color,
        ),
      ),
    );
    Widget line(String text) => Text(
      '• $text',
      textAlign: TextAlign.right,
      style: const TextStyle(height: 1.7, fontSize: 12.5),
    );
    final notesCtrl = TextEditingController();
    var settledMoney = false;
    var withoutSettlement = false;
    final settled = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: AlertDialog(
          title: const Text('إلغاء العقد — التسوية'),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                head('لك', const Color(0xFF0E7161)),
                line(
                  owed > 0
                      ? 'على المستأجر مبلغ: ${money(owed)}'
                      : 'لا مبالغ مستحقة على المستأجر.',
                ),
                const SizedBox(height: 10),
                head('عليك', AppTheme.danger),
                line(
                  deposit > 0
                      ? 'ردّ التأمين للمستأجر: ${money(deposit)}'
                      : 'لا يوجد تأمين مستلم.',
                ),
                line(
                  cheques.isEmpty
                      ? 'لا توجد شيكات لإرجاعها.'
                      : 'إرجاع الشيكات (${cheques.length}): '
                            '${cheques.join('، ')}',
                ),
                if (owed > 0)
                  StatefulBuilder(
                    builder: (context, setBox) => CheckboxListTile(
                      value: settledMoney,
                      onChanged: (value) =>
                          setBox(() => settledMoney = value ?? false),
                      contentPadding: EdgeInsets.zero,
                      controlAffinity: ListTileControlAffinity.leading,
                      title: const Text(
                        'حُصّلت المبالغ أو تمت تسويتها (بلا متابعة بعدها)',
                        style: TextStyle(fontSize: 12),
                      ),
                    ),
                  ),
                const SizedBox(height: 12),
                TextField(
                  controller: notesCtrl,
                  minLines: 2,
                  maxLines: 4,
                  textAlign: TextAlign.right,
                  decoration: InputDecoration(
                    labelText: AppTr.tr('ملاحظات التسوية'),
                    hintText: AppTr.tr('اكتب ما تم الاتفاق عليه في التسوية'),
                    border: const OutlineInputBorder(),
                  ),
                ),
                const SizedBox(height: 10),
                Text(
                  owed > 0
                      ? 'إن لم تتم التسوية (مثل قضية لدى المحكمة) اختر «إلغاء '
                            'بدون تسوية»: يُلغى العقد وتبقى المستحقات في «السجل '
                            'التاريخي» بعلامة حمراء للمتابعة.'
                      : 'يرجى الإلغاء بعد عمل التسوية.',
                  textAlign: TextAlign.right,
                  style: const TextStyle(
                    height: 1.5,
                    fontWeight: FontWeight.w800,
                    color: AppTheme.danger,
                  ),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(false),
              child: const Text('رجوع'),
            ),
            // المستأجر لم يدفع (قضية مثلًا): يُلغى العقد وتبقى المستحقات.
            if (owed > 0)
              OutlinedButton(
                style: OutlinedButton.styleFrom(
                  foregroundColor: AppTheme.danger,
                ),
                onPressed: () {
                  withoutSettlement = true;
                  settledMoney = false;
                  Navigator.of(dialogContext).pop(true);
                },
                child: const Text('إلغاء بدون تسوية'),
              ),
            FilledButton(
              style: FilledButton.styleFrom(backgroundColor: AppTheme.danger),
              onPressed: () => Navigator.of(dialogContext).pop(true),
              child: const Text('تم عمل تسوية'),
            ),
          ],
        ),
      ),
    );
    final notes = notesCtrl.text.trim();
    Future.delayed(const Duration(milliseconds: 600), notesCtrl.dispose);
    if (settled != true || !mounted) return;
    final end = contract.endDate;
    var ended = contract.copyWith(
      status: PropertyUnitContractRecord.statusExpired,
      endDate: end == null || end.isAfter(today) ? today : end,
    );
    // ملاحظات التسوية وتاريخها داخل بيانات العقد نفسه.
    if (_isLeaseContract(contract)) {
      final lease = LeaseContractData.decode(contract.notes);
      lease.contract[_kSettleNotesKey] = notes;
      lease.contract[_kCancelDateKey] =
          '${today.year.toString().padLeft(4, '0')}-'
          '${today.month.toString().padLeft(2, '0')}-'
          '${today.day.toString().padLeft(2, '0')}';
      if (settledMoney) lease.contract[LeaseContractData.kSettled] = 'نعم';
      if (withoutSettlement) lease.contract[_kNoSettlementKey] = 'نعم';
      ended = ended.copyWith(notes: lease.encode());
    } else if (settledMoney) {
      ended = ended.copyWith(notes: _withSettledFlag(contract.notes));
    }
    try {
      await repo.upsertUnitContract(ended);
      await _loadUnitContractsFromRemote();
    } catch (_) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذّر إنهاء العقد')),
      );
      return;
    }
    if (!mounted) return;
    // المركبة شاغرة الآن: تبقى كذلك، أو تُؤرشف، أو تُلغى.
    final next = await showDialog<String>(
      context: context,
      builder: (dialogContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: AlertDialog(
          title: const Text('أصبحت المركبة شاغرة'),
          content: Text(
            withoutSettlement
                ? 'أُلغي عقد التأجير بدون تسوية، والمركبة الآن شاغرة وتستطيع '
                      'تأجيرها. المستحقات في «السجل التاريخي» للمتابعة.'
                : 'انتهى عقد التأجير بعد التسوية، والمركبة الآن شاغرة '
                      'وتستطيع تأجيرها.',
            textAlign: TextAlign.right,
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop('keep'),
              child: const Text('إبقاؤها شاغرة'),
            ),
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop('archive'),
              child: const Text('أرشفة'),
            ),
          ],
        ),
      ),
    );
    if (!mounted) return;
    if (next == 'archive') {
      _onTopMenuAction(ThreeDotMenuAction.archive);
    } else if (next == 'cancel') {
      _onTopMenuAction(ThreeDotMenuAction.delete);
    } else {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('انتهى عقد التأجير وأصبحت المركبة شاغرة')),
      );
    }
  }

  /// نص العقد كاملًا — للعرض والمشاركة.
  List<(String, String)> _equipContractLines(
    PropertyUnitContractRecord contract,
  ) {
    final extra = _equipContractExtra(contract);
    final meta = _item.propertyMeta;
    final payments = _equipPayments
        .where((entry) => entry.contract.id == contract.id)
        .toList(growable: false);
    var due = 0.0;
    var paid = 0.0;
    for (final entry in payments) {
      due += entry.payment.amountDue;
      paid += entry.payment.amountPaid;
    }
    final rate = double.tryParse(extra['rate'] ?? '') ?? 0;
    final basis = extra['basis'] ?? contract.paymentCycle;
    final money = AppSettings.currencySuffix;
    final operator = [
      meta[_EquipKeys.operatorName] ?? '',
      meta[_EquipKeys.operatorNationality] ?? '',
    ].where((v) => v.trim().isNotEmpty).join(' · ');
    final projectStart = [
      meta[_EquipKeys.projectStart] ?? '',
      meta[_EquipKeys.projectStartTime] ?? '',
    ].where((v) => v.trim().isNotEmpty).join(' · الساعة ');
    return <(String, String)>[
      ('المركبة', _item.title),
      ('الموديل / النوع / الحجم', _item.subType),
      ('رقم الشاصي / الرقم التسلسلي', _item.serialNumber),
      ('الشركة المستأجرة', contract.tenantName ?? ''),
      ('رقم الهاتف', contract.tenantPhone ?? ''),
      ('بداية العقد', _equipDate(contract.startDate)),
      ('نهاية العقد', _equipDate(contract.endDate)),
      ('طريقة التأجير', basis),
      (
        'المبلغ المتفق عليه',
        rate > 0
            ? '${formatMoneyValue(rate)} $money / ${_equipRatePer(basis)}'
            : '',
      ),
      if (basis == 'شهري' && contract.annualRent > 0)
        (
          'إجمالي العقد',
          '${formatMoneyValue(contract.annualRent)} $money',
        ),
      ('الموقع', meta[_EquipKeys.projectLocation] ?? ''),
      ('وقت البدء', projectStart),
      (
        'وقت الإغلاق',
        [
          meta[_EquipKeys.projectEnd] ?? '',
          meta[_EquipKeys.projectEndTime] ?? '',
        ].where((v) => v.trim().isNotEmpty).join(' · الساعة '),
      ),
      ('على من الصيانة', meta[_EquipKeys.maintenanceOn] ?? ''),
      ('على من الوقود', meta[_EquipKeys.fuelOn] ?? ''),
      ('رقم التواصل', meta[_EquipKeys.contactPhone] ?? ''),
      ('نقل المعدة', meta[_EquipKeys.transportOn] ?? ''),
      ('مشغل المعدة', operator),
      ('عدد الدفعات', '${payments.length}'),
      ('المستحق', '${formatMoneyValue(due)} $money'),
      ('المسدد', '${formatMoneyValue(paid)} $money'),
      ('المتبقي', '${formatMoneyValue(due - paid)} $money'),
      ('ملاحظات', extra['note'] ?? ''),
    ].where((line) => line.$2.trim().isNotEmpty && line.$2 != 'غير محدد').toList();
  }

  /// «العقد كامل»: كل بنود العقد في صفحة واحدة، مع المشاركة.
  Future<void> _openEquipFullContract(
    PropertyUnitContractRecord contract,
  ) async {
    // عقد التأجير: عرض فقط بنموذج العقد المعتمد (PDF) مع الطباعة والمشاركة
    // كملف PDF — التعديل من ⋮ «تعديل عقد التأجير» في «إدارة التأجير».
    if (_isLeaseContract(contract)) {
      final lease = LeaseContractData.decode(contract.notes);
      final vehicleClass =
          _item.propertyMeta[_EquipKeys.vehicleClass] ?? _kVehicleLand;
      final title = 'عقد تأجير $vehicleClass';
      final (_, assetMeta) = _vehicleLeaseFields();
      final no = leaseContractNumber(contract);
      await Navigator.of(context).push(
        MaterialPageRoute<void>(
          builder: (_) => TemplatePrintScreen(
            title: title,
            fileName: no.isEmpty ? title : '$title-$no',
            buildPdf: (format) => buildLeasePdf(
              lease,
              format,
              title: title,
              assetMeta: assetMeta,
            ),
          ),
        ),
      );
      return;
    }
    final lines = _equipContractLines(contract);
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (sheetContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: SafeArea(
          top: false,
          child: ConstrainedBox(
            constraints: BoxConstraints(
              maxHeight: MediaQuery.of(sheetContext).size.height * 0.85,
            ),
            child: ListView(
              shrinkWrap: true,
              padding: const EdgeInsets.fromLTRB(16, 16, 16, 18),
              children: [
                const Text(
                  'عقد تأجير المركبة',
                  textAlign: TextAlign.center,
                  style: TextStyle(
                    fontSize: 16,
                    fontWeight: FontWeight.w900,
                    color: Color(0xFF022E2A),
                  ),
                ),
                const SizedBox(height: 14),
                for (final line in lines)
                  Container(
                    padding: const EdgeInsets.symmetric(vertical: 9),
                    decoration: const BoxDecoration(
                      border: Border(
                        bottom: BorderSide(color: Color(0xFFEFF3F2)),
                      ),
                    ),
                    child: Row(
                      textDirection: AppTr.uiDir,
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        SizedBox(
                          width: 130,
                          child: Text(
                            line.$1,
                            style: const TextStyle(
                              fontSize: 11.5,
                              fontWeight: FontWeight.w700,
                              color: Color(0xFF7A8A87),
                            ),
                          ),
                        ),
                        Expanded(
                          child: Text(
                            line.$2,
                            style: const TextStyle(
                              fontSize: 12.5,
                              fontWeight: FontWeight.w900,
                              color: Color(0xFF022E2A),
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                const SizedBox(height: 16),
                ElevatedButton.icon(
                  onPressed: () {
                    final buffer = StringBuffer()
                      ..writeln('عقد تأجير المركبة')
                      ..writeln('');
                    for (final line in lines) {
                      buffer.writeln('${line.$1}: ${line.$2}');
                    }
                    Share.share(buffer.toString());
                  },
                  style: ElevatedButton.styleFrom(
                    backgroundColor: _kEquipmentColor,
                    foregroundColor: Colors.white,
                    minimumSize: const Size.fromHeight(48),
                    shape: RoundedRectangleBorder(
                      borderRadius: BorderRadius.circular(12),
                    ),
                  ),
                  icon: const Icon(Icons.ios_share_rounded, size: 18),
                  label: const Text('مشاركة العقد'),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }

  /// «إضافة دفعة» على عقد التأجير: الاسم والمبلغ وتاريخ الاستحقاق.
  /// «تسجيل دفعة تأجير»: تأجير مباشر بالساعة أو اليوم بلا عقد — المستأجر،
  /// السعر × المدة (والمبلغ قابل للتعديل)، التاريخ، طريقة الدفع، ومرفق.
  /// تُحفظ دفعةً مستلمة في سجل «التأجير المباشر» للمركبة.
  Future<void> _addWalkInRental() async {
    final repo = widget.repository;
    final assetId = _item.id;
    if (repo == null || assetId == null || assetId.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('يجب حفظ المركبة أولاً')),
      );
      return;
    }
    final renterCtrl = TextEditingController();
    final rateCtrl = TextEditingController();
    final qtyCtrl = TextEditingController(text: '1');
    final amountCtrl = TextEditingController();
    var unit = 'ساعة';
    var method = 'نقدًا';
    var date = DateTime.now();
    var attachment = '';
    void recalc() {
      final rate = double.tryParse(rateCtrl.text.replaceAll(',', '').trim()) ?? 0;
      final qty = double.tryParse(qtyCtrl.text.trim()) ?? 0;
      if (rate > 0 && qty > 0) {
        final total = rate * qty;
        amountCtrl.text = total == total.roundToDouble()
            ? total.toStringAsFixed(0)
            : total.toStringAsFixed(2);
      }
    }

    final saved = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(AppTheme.rCard),
        ),
      ),
      builder: (sheetContext) => StatefulBuilder(
        builder: (sheetContext, setSheet) {
          Widget chips(
            List<String> options,
            String value,
            ValueChanged<String> onPick,
          ) => Row(
            children: [
              for (final option in options) ...[
                Expanded(
                  child: InkWell(
                    onTap: () => setSheet(() => onPick(option)),
                    borderRadius: BorderRadius.circular(AppTheme.rIcon),
                    child: Container(
                      padding: const EdgeInsets.symmetric(vertical: 10),
                      alignment: Alignment.center,
                      decoration: BoxDecoration(
                        color: value == option
                            ? _kEquipmentColor
                            : AppTheme.paper,
                        borderRadius: BorderRadius.circular(AppTheme.rIcon),
                        border: Border.all(
                          color: value == option
                              ? _kEquipmentColor
                              : AppTheme.hairline,
                        ),
                      ),
                      child: Text(
                        option,
                        style: TextStyle(
                          fontSize: 12,
                          fontWeight: FontWeight.w900,
                          color: value == option
                              ? Colors.white
                              : AppTheme.title,
                        ),
                      ),
                    ),
                  ),
                ),
                if (option != options.last) const SizedBox(width: 8),
              ],
            ],
          );

          return Directionality(
            textDirection: AppTr.uiDir,
            child: Padding(
              padding: EdgeInsets.fromLTRB(
                16,
                14,
                16,
                MediaQuery.of(sheetContext).viewInsets.bottom + 16,
              ),
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    const Text(
                      'تسجيل دفعة تأجير',
                      textAlign: TextAlign.right,
                      style: TextStyle(
                        fontSize: 14,
                        fontWeight: FontWeight.w900,
                        color: Color(0xFF022E2A),
                      ),
                    ),
                    const SizedBox(height: 12),
                    TextField(
                      controller: renterCtrl,
                      textAlign: AppTr.alignEnd,
                      decoration: _propertyInputDecorationShared('المستأجر'),
                    ),
                    const SizedBox(height: 10),
                    _propertyFieldLabel('التأجير'),
                    const SizedBox(height: 6),
                    chips(const ['ساعة', 'يوم'], unit, (v) => unit = v),
                    const SizedBox(height: 10),
                    Row(
                      children: [
                        Expanded(
                          child: TextField(
                            controller: rateCtrl,
                            textAlign: AppTr.alignEnd,
                            keyboardType: const TextInputType.numberWithOptions(
                              decimal: true,
                            ),
                            onChanged: (_) => setSheet(recalc),
                            decoration: _propertyInputDecorationShared(
                              'السعر لكل $unit',
                            ),
                          ),
                        ),
                        const SizedBox(width: 8),
                        Expanded(
                          child: TextField(
                            controller: qtyCtrl,
                            textAlign: AppTr.alignEnd,
                            keyboardType: const TextInputType.numberWithOptions(
                              decimal: true,
                            ),
                            onChanged: (_) => setSheet(recalc),
                            decoration: _propertyInputDecorationShared(
                              unit == 'ساعة' ? 'عدد الساعات' : 'عدد الأيام',
                            ),
                          ),
                        ),
                      ],
                    ),
                    const SizedBox(height: 10),
                    TextField(
                      controller: amountCtrl,
                      textAlign: AppTr.alignEnd,
                      keyboardType: const TextInputType.numberWithOptions(
                        decimal: true,
                      ),
                      decoration: _propertyInputDecorationShared('المبلغ *'),
                    ),
                    const SizedBox(height: 10),
                    InkWell(
                      onTap: () async {
                        final picked = await showDatePicker(
                          context: sheetContext,
                          initialDate: date,
                          firstDate: DateTime(2015),
                          lastDate: DateTime(2070),
                        );
                        if (picked != null) setSheet(() => date = picked);
                      },
                      child: InputDecorator(
                        decoration: _propertyInputDecorationShared('التاريخ'),
                        child: Text(
                          _equipDate(date),
                          textAlign: TextAlign.right,
                        ),
                      ),
                    ),
                    const SizedBox(height: 10),
                    _propertyFieldLabel('طريقة الدفع'),
                    const SizedBox(height: 6),
                    chips(
                      const ['نقدًا', 'تحويل', 'شيك'],
                      method,
                      (v) => method = v,
                    ),
                    const SizedBox(height: 10),
                    AppRemovableAttachment(
                      attached: attachment.isNotEmpty,
                      onRemove: () => setSheet(() => attachment = ''),
                      child: OutlinedButton.icon(
                      onPressed: () async {
                        final path = await DocumentStore.pickAndStore(context: context);
                        if (path == null) return;
                        setSheet(() => attachment = path);
                      },
                      style: OutlinedButton.styleFrom(
                        foregroundColor: _kEquipmentColor,
                        minimumSize: const Size.fromHeight(44),
                      ),
                      icon: const Icon(Icons.attach_file_rounded, size: 18),
                      label: Text(
                        attachment.isEmpty
                            ? 'إرفاق مستند'
                            : DocumentStore.fileName(attachment),
                        maxLines: 3,
                      ),
                    ),
                    ),
                    const SizedBox(height: 14),
                    FilledButton(
                      onPressed: () => Navigator.of(sheetContext).pop(true),
                      style: FilledButton.styleFrom(
                        backgroundColor: _kEquipmentColor,
                        foregroundColor: Colors.white,
                        minimumSize: const Size.fromHeight(46),
                      ),
                      child: const Text('حفظ'),
                    ),
                  ],
                ),
              ),
            ),
          );
        },
      ),
    );
    final renter = renterCtrl.text.trim();
    final qty = qtyCtrl.text.trim();
    final amount =
        double.tryParse(amountCtrl.text.replaceAll(',', '').trim()) ?? 0;
    Future.delayed(const Duration(milliseconds: 400), () {
      renterCtrl.dispose();
      rateCtrl.dispose();
      qtyCtrl.dispose();
      amountCtrl.dispose();
    });
    if (saved != true || !mounted) return;
    if (amount <= 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('أدخل المبلغ')),
      );
      return;
    }
    try {
      // سجل «التأجير المباشر» يُنشأ مرة واحدة لكل مركبة.
      PropertyUnitContractRecord? walkIn;
      for (final c in _unitContracts) {
        if (c.unitKey == _kEquipWalkInKey) walkIn = c;
      }
      walkIn ??= await repo.upsertUnitContract(
        PropertyUnitContractRecord(
          assetId: assetId,
          unitKey: _kEquipWalkInKey,
          unitName: 'تأجير مباشر',
          tenantName: 'تأجير مباشر',
          paymentCycle: 'بالساعات',
        ),
      );
      final contractId = walkIn.id;
      if (contractId == null || contractId.isEmpty) return;
      await repo.upsertUnitPayment(
        PropertyUnitPaymentRecord(
          contractId: contractId,
          dueDate: date,
          amountDue: amount,
          amountPaid: amount,
          paidAt: date,
          status: PropertyUnitPaymentRecord.statusPaid,
          notes: encodePayExtra(<String, String>{
            kPayKind: kPayKindRent,
            kPayName: [
              'تأجير $qty $unit',
              if (renter.isNotEmpty) renter,
            ].join(' — '),
            kPayMethod: method,
            if (attachment.isNotEmpty) 'المرفق': attachment,
          }),
        ),
      );
      await _loadUnitContractsFromRemote();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('سُجّلت دفعة التأجير')),
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('تعذّر حفظ الدفعة: $error')),
      );
    }
  }

  Future<void> _addEquipPayment(PropertyUnitContractRecord contract) async {
    final repo = widget.repository;
    final contractId = contract.id;
    if (repo == null || contractId == null || contractId.isEmpty) return;
    final extra = _equipContractExtra(contract);
    // نفس حقول «تسجيل دفعة» في العقد: الاسم، القيمة، طريقة التحصيل وتحتها
    // تاريخ الاستحقاق (مع «شيك» يحلّ تاريخ الشيك محلّه)، ثم التذكير،
    // وملاحظات.
    final nameCtrl = TextEditingController();
    final amountCtrl = TextEditingController(text: extra['rate'] ?? '');
    final chequeCtrl = TextEditingController();
    final bankCtrl = TextEditingController();
    final daysCtrl = TextEditingController();
    final notesCtrl = TextEditingController();
    var due = DateTime.now();
    DateTime? chequeDate;
    var method = LeaseContractData.collectMethods.first;
    var reminder = LeaseContractData.reminderNone;
    var error = '';
    double amountOf() =>
        double.tryParse(
          amountCtrl.text.trim().replaceAll(',', '').replaceAll('٬', ''),
        ) ??
        0;
    final ok = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(AppTheme.rCard),
        ),
      ),
      builder: (sheetContext) => StatefulBuilder(
        builder: (sheetContext, setSheet) {
          Widget dateBox(DateTime? value, ValueChanged<DateTime> onPick) =>
              InkWell(
                onTap: () async {
                  final picked = await showDatePicker(
                    context: sheetContext,
                    initialDate: value ?? DateTime.now(),
                    firstDate: DateTime(2000),
                    lastDate: DateTime(2070),
                  );
                  if (picked != null) setSheet(() => onPick(picked));
                },
                child: InputDecorator(
                  decoration: _propertyInputDecoration('').copyWith(
                    suffixIcon: const Icon(Icons.event_rounded, size: 19),
                  ),
                  child: Text(
                    value == null ? 'غير محدد' : _equipDate(value),
                    textAlign: TextAlign.right,
                  ),
                ),
              );
          Widget select(
            String value,
            List<String> options,
            ValueChanged<String> onPick,
          ) => DropdownButtonFormField<String>(
            initialValue: value,
            isExpanded: true,
            decoration: _propertyInputDecoration(''),
            items: [
              for (final option in options)
                DropdownMenuItem<String>(
                  value: option,
                  child: Text(
                    option,
                    maxLines: 3,
                  ),
                ),
            ],
            onChanged: (picked) {
              if (picked != null) setSheet(() => onPick(picked));
            },
          );
          Widget field(String label, Widget child, {bool required = false}) =>
              Padding(
                padding: const EdgeInsets.only(bottom: 12),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    _propertyFieldLabel(label, required: required),
                    const SizedBox(height: 6),
                    child,
                  ],
                ),
              );
          final cheque = method == 'شيك';
          // حجم ثابت (نحو نصف الشاشة) لا يتغيّر عند الكتابة، كنافذة دفعة العقد.
          final media = MediaQuery.of(sheetContext);
          final keyboard = media.viewInsets.bottom;
          final room = media.size.height - keyboard - media.padding.top - 24;
          final preferred = media.size.height * 0.46;
          return Padding(
            padding: EdgeInsets.only(bottom: keyboard),
            child: SizedBox(
            height: room < preferred ? room : preferred,
            child: Directionality(
            textDirection: AppTr.uiDir,
            child: Padding(
              padding: const EdgeInsets.fromLTRB(16, 14, 16, 16),
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Row(
                      textDirection: AppTr.uiDir,
                      children: [
                        const Expanded(
                          child: Text(
                            'إضافة دفعة',
                            textAlign: TextAlign.right,
                            style: TextStyle(
                              fontSize: 14,
                              fontWeight: FontWeight.w900,
                              color: AppTheme.title,
                            ),
                          ),
                        ),
                        IconButton(
                          tooltip: AppTr.tr('إغلاق'),
                          visualDensity: VisualDensity.compact,
                          onPressed: () => Navigator.pop(sheetContext, false),
                          icon: const Icon(Icons.close_rounded, size: 22),
                        ),
                      ],
                    ),
                    const SizedBox(height: 12),
                    field(
                      'اسم الدفعة',
                      TextField(
                        controller: nameCtrl,
                        textAlign: AppTr.alignEnd,
                        decoration: _propertyInputDecoration(
                          'مثال: إيجار شهر 3، أو 40 ساعة',
                        ),
                      ),
                      required: true,
                    ),
                    field(
                      'قيمة الدفعة',
                      TextField(
                        controller: amountCtrl,
                        textAlign: AppTr.alignEnd,
                        keyboardType: const TextInputType.numberWithOptions(
                          decimal: true,
                        ),
                        decoration: _propertyInputDecoration(
                          AppSettings.currencySuffix,
                        ),
                      ),
                      required: true,
                    ),
                    field(
                      'طريقة التحصيل',
                      select(
                        method,
                        LeaseContractData.collectMethods,
                        (value) => method = value,
                      ),
                    ),
                    if (!cheque)
                      field(
                        'تاريخ الاستحقاق',
                        dateBox(due, (value) => due = value),
                      )
                    else ...[
                      field(
                        'رقم الشيك',
                        TextField(
                          controller: chequeCtrl,
                          textAlign: AppTr.alignEnd,
                          decoration: _propertyInputDecoration('رقم الشيك'),
                        ),
                      ),
                      field(
                        'تاريخ الشيك',
                        dateBox(chequeDate, (value) => chequeDate = value),
                        required: true,
                      ),
                      field(
                        'اسم البنك',
                        TextField(
                          controller: bankCtrl,
                          textAlign: AppTr.alignEnd,
                          decoration: _propertyInputDecoration('اسم البنك'),
                        ),
                      ),
                    ],
                    field(
                      'التذكير',
                      select(
                        reminder,
                        LeaseContractData.paymentReminders,
                        (value) => reminder = value,
                      ),
                    ),
                    if (reminder == LeaseContractData.reminderCustom)
                      field(
                        'التذكير قبل الاستحقاق بكم يوم',
                        TextField(
                          controller: daysCtrl,
                          textAlign: AppTr.alignEnd,
                          keyboardType: TextInputType.number,
                          decoration: _propertyInputDecoration('عدد الأيام'),
                        ),
                      ),
                    field(
                      'ملاحظات',
                      TextField(
                        controller: notesCtrl,
                        textAlign: AppTr.alignEnd,
                        minLines: 2,
                        maxLines: 4,
                        decoration: _propertyInputDecoration('ملاحظات'),
                      ),
                    ),
                    if (error.isNotEmpty) ...[
                      Text(
                        error,
                        textAlign: TextAlign.right,
                        style: const TextStyle(
                          fontSize: 11.5,
                          fontWeight: FontWeight.w800,
                          color: AppTheme.danger,
                        ),
                      ),
                      const SizedBox(height: 8),
                    ],
                    FilledButton(
                      onPressed: () {
                        if (nameCtrl.text.trim().isEmpty) {
                          setSheet(() => error = 'اكتب اسم الدفعة أولًا.');
                          return;
                        }
                        if (amountOf() <= 0) {
                          setSheet(() => error = 'أدخل مبلغًا أكبر من صفر.');
                          return;
                        }
                        if (cheque && chequeDate == null) {
                          setSheet(() => error = 'اختر تاريخ الشيك.');
                          return;
                        }
                        Navigator.pop(sheetContext, true);
                      },
                      style: FilledButton.styleFrom(
                        backgroundColor: _kEquipmentColor,
                        foregroundColor: Colors.white,
                        minimumSize: const Size.fromHeight(48),
                      ),
                      child: const Text('حفظ'),
                    ),
                  ],
                ),
              ),
            ),
            ),
            ),
          );
        },
      ),
    );
    final name = nameCtrl.text.trim();
    final amount = amountOf();
    final chequeNo = chequeCtrl.text.trim();
    final bank = bankCtrl.text.trim();
    final note = notesCtrl.text.trim();
    final days = LeaseContractData.reminderDaysOf(<String, String>{
      LeaseContractData.kPaymentReminder: reminder,
      LeaseContractData.kPaymentReminderDays: daysCtrl.text,
    });
    Future.delayed(const Duration(milliseconds: 400), () {
      for (final controller in [
        nameCtrl,
        amountCtrl,
        chequeCtrl,
        bankCtrl,
        daysCtrl,
        notesCtrl,
      ]) {
        controller.dispose();
      }
    });
    if (ok != true || !mounted) return;
    final isCheque = method == 'شيك';
    final dueDate = isCheque ? (chequeDate ?? due) : due;
    final count = _equipPayments
        .where((entry) => entry.contract.id == contractId)
        .length;
    try {
      final saved = await repo.upsertUnitPayment(
        PropertyUnitPaymentRecord(
          contractId: contractId,
          dueDate: dueDate,
          amountDue: amount,
          referenceNo: isCheque && chequeNo.isNotEmpty ? chequeNo : null,
          notes: encodePayExtra(<String, String>{
            kPayKind: kPayKindRent,
            // اسم رقمي يُعرض «الدفعة N».
            kPayName: name.isEmpty ? '${count + 1}' : name,
            kPayMethod: method,
            if (isCheque && chequeNo.isNotEmpty) kPayCheque: chequeNo,
            if (isCheque && bank.isNotEmpty)
              LeaseContractData.kPaymentBank: bank,
            if (note.isNotEmpty) 'ملاحظات': note,
          }),
        ),
      );
      if (days > 0) {
        try {
          await AppRemindersStore.upsert(
            AppReminder(
              id: 'equip_payment_'
                  '${saved.id ?? '$contractId-${dueDate.millisecondsSinceEpoch}'}',
              title: 'استحقاق ${name.isEmpty ? 'دفعة إيجار' : name}'
                  ' — ${_item.title}',
              module: 'المركبات ووسائل النقل',
              expiryDate: dueDate,
              remindBeforeDays: days,
            ),
          );
        } catch (_) {
          // فشل التذكير لا يُفشل حفظ الدفعة.
        }
      }
      await _loadPropertyPayments();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('أُضيفت الدفعة')),
      );
    } catch (error) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('تعذّر حفظ الدفعة: $error')),
      );
    }
  }

  /// قسم «إدارة التأجير» للآلية/المعدة — بنفس ترتيب «إدارة الإيجار».
  Widget _equipmentRentalSection(_AssetItem item) {
    final repo = widget.repository;
    if (repo == null || (item.id ?? '').isEmpty) {
      return const _DetailHintCard(
        message: 'يجب حفظ المركبة أولاً لإدارة التأجير.',
      );
    }
    final contract = _equipContract;
    final payments = _equipPayments;

    // شاغرة: التنبيه وحده. دفعات العقود السابقة ومتبقّيها في «الحركات
    // المالية» (سجل العقود السابقة والمبالغ المتبقية).
    if (contract == null) {
      return _DetailHintCard(
        message: _equipContracts.isEmpty
            ? 'المركبة غير مؤجرة — اضغط + لبدء عملية التأجير وإنشاء عقد.'
            : 'المركبة شاغرة — آخر عقد منتهٍ. اضغط + لبدء عملية التأجير '
                  'وإنشاء عقد.',
      );
    }

    final extra = _equipContractExtra(contract);
    final rate = double.tryParse(extra['rate'] ?? '') ?? 0;
    final basis = extra['basis'] ?? contract.paymentCycle;
    final isDraft = contract.status == PropertyUnitContractRecord.statusPending;
    final overdue = payments.any(
      (entry) =>
          entry.contract.id == contract.id &&
          rentPaymentStatusLabel(entry.payment) == 'متأخرة',
    );
    // حالة العقد وحده: ملغي / منتهي / مسودة / نشط. التأخير يخصّ الدفعات
    // ويظهر في صندوقها، لا في حالة العقد.
    final endedByDate = _contractEndedByDate(contract);
    final eqCancelled = contract.status == _kContractCancelled;
    final eqClosed = _contractClosed(contract);
    final statusLabel = eqCancelled
        ? 'ملغي'
        : eqClosed
        ? 'منتهي'
        : isDraft
        ? 'مسودة'
        : endedByDate
        ? 'منتهي'
        : 'نشط';
    final statusColor = eqCancelled
        ? const Color(0xFF8C3A32)
        : eqClosed
        ? const Color(0xFF8C9A97)
        : isDraft
        ? AppTheme.goldDark
        : endedByDate
        ? const Color(0xFFC4392E)
        : _kEquipmentColor;

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        // ===== سطر العقد: الحالة + «العقد كامل» =====
        Row(
          textDirection: AppTr.uiDir,
          children: [
            Container(
              padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 5),
              decoration: BoxDecoration(
                color: statusColor.withValues(alpha: 0.12),
                borderRadius: BorderRadius.circular(999),
              ),
              child: Text(
                statusLabel,
                style: TextStyle(
                  fontSize: 10,
                  fontWeight: FontWeight.w900,
                  color: statusColor,
                ),
              ),
            ),
            const Spacer(),
            InkWell(
              onTap: () => _openEquipFullContract(contract),
              borderRadius: BorderRadius.circular(AppTheme.rIcon),
              child: Container(
                padding: const EdgeInsets.symmetric(
                  horizontal: 14,
                  vertical: 10,
                ),
                decoration: BoxDecoration(
                  color: _kEquipmentColor,
                  borderRadius: BorderRadius.circular(AppTheme.rIcon),
                ),
                child: Row(
                  textDirection: AppTr.uiDir,
                  children: const [
                    Icon(
                      Icons.open_in_full_rounded,
                      size: 15,
                      color: Colors.white,
                    ),
                    SizedBox(width: 6),
                    Text(
                      'العقد كامل',
                      style: TextStyle(
                        fontSize: 11.5,
                        fontWeight: FontWeight.w900,
                        color: Colors.white,
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ],
        ),
        const SizedBox(height: 14),

        // ===== مدة العقد وإجراءاته — مثل «إدارة الإيجار» في العقار =====
        _equipBox('مدة العقد', Icons.calendar_month_outlined, [
          if (endedByDate && !eqClosed)
            _endedContractAlert(
              'انتهت مدة العقد — يُرجى إلغاء العقد لتصبح المركبة شاغرة، '
              'أو تجديده.',
            ),
          Row(
            textDirection: AppTr.uiDir,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Expanded(
                child: _equipCell('بداية العقد', _equipDate(contract.startDate)),
              ),
              const SizedBox(width: 12),
              Expanded(
                child: _equipCell('نهاية العقد', _equipDate(contract.endDate)),
              ),
            ],
          ),
          const SizedBox(height: 12),
          Row(
            textDirection: AppTr.uiDir,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Expanded(
                child: _equipCell('المستأجر', contract.tenantName ?? ''),
              ),
              const SizedBox(width: 12),
              Expanded(
                child: _isLeaseContract(contract)
                    ? _equipCell(
                        'قيمة العقد',
                        '${formatMoneyValue(contract.annualRent)} '
                            '${AppSettings.currencySuffix}',
                      )
                    : _equipCell(
                        'المبلغ المتفق عليه',
                        rate > 0
                            ? '${formatMoneyValue(rate)} '
                                  '${AppSettings.currencySuffix}'
                                  ' / ${_equipRatePer(basis)}'
                            : basis,
                      ),
              ),
            ],
          ),
          const SizedBox(height: 14),
          // تمديد / تعديل / إلغاء — وبعد انتهاء المدة «تجديد العقد» مكان
          // التمديد والتعديل (مثل العقار).
          Row(
            children: [
              if (contract.endDate != null &&
                  DateUtils.dateOnly(contract.endDate!)
                      .isBefore(DateUtils.dateOnly(DateTime.now())))
                Expanded(
                  flex: 2,
                  child: _equipActionButton(
                    'تجديد العقد',
                    Icons.autorenew_rounded,
                    () => _openEquipContractForm(renewFrom: contract),
                  ),
                )
              else
                // التعديل من الثلاث نقاط أعلى الصفحة.
                Expanded(
                  child: _equipActionButton(
                    'تمديد العقد',
                    Icons.more_time_rounded,
                    () => _extendEquipContract(contract),
                  ),
                ),
              const SizedBox(width: 7),
              Expanded(
                child: _equipActionButton(
                  'إلغاء العقد',
                  Icons.cancel_outlined,
                  () => _endEquipContract(contract),
                  color: AppTheme.danger,
                ),
              ),
            ],
          ),
        ]),

        // ===== الدفعات: نفس صندوق العقار وأزراره =====
        _equipBox(
          'الدفعات الإيجارية + الدفعات الإدارية + التأمين',
          Icons.payments_outlined,
          [
            _sharedDuesBox(
              context: context,
              entries: _equipPayments
                  .where((entry) => entry.contract.id == contract.id)
                  .toList(growable: false),
              accent: _kEquipmentColor,
              onOpen: () => _openEquipPaymentsPage(contract),
            ),
            const SizedBox(height: 10),
            OutlinedButton.icon(
              onPressed: () => _addEquipPayment(contract),
              style: OutlinedButton.styleFrom(
                foregroundColor: _kEquipmentColor,
                minimumSize: const Size.fromHeight(44),
              ),
              icon: const Icon(Icons.add_rounded, size: 18),
              label: const Text('إضافة دفعة'),
            ),
            const SizedBox(height: 8),
            Row(
              children: [
                Expanded(
                  child: _equipActionButton(
                    'سند قبض',
                    Icons.receipt_long_outlined,
                    () => _shareEquipDocument(contract, receipt: true),
                  ),
                ),
                const SizedBox(width: 7),
                Expanded(
                  child: _equipActionButton(
                    'مطالبة مالية',
                    Icons.request_page_outlined,
                    () => _shareEquipDocument(contract, receipt: false),
                  ),
                ),
              ],
            ),
          ],
        ),

        // «شروط التأجير» صارت داخل عقد المركبة نفسه؛ «القبطان والرخصة» آخر
        // الصفحة بمستطيل صغير.
        _equipOperatorBox(),
      ],
    );
  }

  /// عناوين القبطان/السائق/المشغل وشهادتيه حسب نوع المركبة.
  ({String title, String cert, String safety}) _equipOperatorLabels() {
    final meta = _item.propertyMeta;
    if ((meta[_EquipKeys.vehicleClass] ?? '') == _kVehicleMarine) {
      return (
        title: 'القبطان والرخصة البحرية',
        cert: 'رخصة القيادة البحرية',
        safety: 'شهادة السلامة البحرية',
      );
    }
    final type = (meta[_EquipKeys.vehicleType] ?? '').trim();
    if (type.isEmpty || type.startsWith('معدات')) {
      return (
        title: 'مشغل المعدة والشهادة',
        cert: 'شهادة مشغل المعدة',
        safety: 'شهادة سلامة المعدة',
      );
    }
    return (
      title: 'السائق والرخصة',
      cert: 'رخصة القيادة',
      safety: 'شهادة الفحص الدوري',
    );
  }

  /// «إدارة التأجير»: القبطان/السائق/المشغل وشهاداته، مع تعديلها.
  Widget _equipOperatorBox() {
    final meta = _item.propertyMeta;
    final labels = _equipOperatorLabels();
    final rows = <Widget?>[
      _equipRow(
        'الاسم',
        [
          meta[_EquipKeys.operatorName] ?? '',
          meta[_EquipKeys.operatorNationality] ?? '',
        ].where((v) => v.trim().isNotEmpty).join(' · '),
        Icons.badge_outlined,
      ),
      _equipCertRow(
        labels.cert,
        _EquipKeys.operatorCert,
        _EquipKeys.operatorCertEnd,
      ),
      _equipCertRow(
        labels.safety,
        _EquipKeys.safetyCert,
        _EquipKeys.safetyCertEnd,
      ),
    ].whereType<Widget>().toList(growable: false);
    final operatorName = (meta[_EquipKeys.operatorName] ?? '').trim();
    return _equipFold(
      'operator',
      labels.title,
      Icons.engineering_outlined,
      rows.isEmpty
          ? 'لم تُسجَّل بعد'
          : (operatorName.isEmpty ? '${rows.length} بنود' : operatorName),
      [
      if (rows.isEmpty)
        const Text(
          'لم تُسجَّل البيانات بعد.',
          style: TextStyle(
            fontSize: 11.5,
            fontWeight: FontWeight.w700,
            color: AppTheme.muted,
          ),
        )
      else
        ...rows,
      const SizedBox(height: 10),
      OutlinedButton.icon(
        onPressed: _editEquipOperator,
        style: OutlinedButton.styleFrom(
          foregroundColor: _kEquipmentColor,
          minimumSize: const Size.fromHeight(44),
        ),
        icon: Icon(
          rows.isEmpty ? Icons.add_rounded : Icons.edit_outlined,
          size: 18,
        ),
        label: Text(rows.isEmpty ? 'إضافة البيانات' : 'تعديل البيانات'),
      ),
    ],
    );
  }

  Future<void> _editEquipOperator() async {
    final meta = _item.propertyMeta;
    final labels = _equipOperatorLabels();
    final name = TextEditingController(
      text: meta[_EquipKeys.operatorName] ?? '',
    );
    final nationality = TextEditingController(
      text: meta[_EquipKeys.operatorNationality] ?? '',
    );
    final values = <String, String>{
      for (final key in [
        _EquipKeys.operatorCert,
        _EquipKeys.operatorCertEnd,
        _EquipKeys.operatorCertReminder,
        _EquipKeys.safetyCert,
        _EquipKeys.safetyCertEnd,
        _EquipKeys.safetyCertReminder,
      ])
        key: meta[key] ?? '',
    };
    const certReminders = [
      'بلا تذكير',
      'قبل يوم',
      'قبل 3 أيام',
      'قبل أسبوع',
      'قبل شهر',
    ];
    InputDecoration deco(String label) => InputDecoration(
      labelText: AppTr.tr(label),
      isDense: true,
      filled: true,
      fillColor: AppTheme.field,
      border: OutlineInputBorder(
        borderRadius: BorderRadius.circular(AppTheme.rField),
        borderSide: BorderSide.none,
      ),
    );
    final saved = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(AppTheme.rCard),
        ),
      ),
      builder: (sheetContext) => StatefulBuilder(
        builder: (sheetContext, setSheet) {
          Widget certificate(
            String label,
            String fileKey,
            String endKey,
            String reminderKey,
          ) {
            final path = values[fileKey] ?? '';
            final end = values[endKey] ?? '';
            final reminder = certReminders.contains(values[reminderKey])
                ? values[reminderKey]!
                : 'قبل شهر';
            return Container(
              margin: const EdgeInsets.only(bottom: 10),
              padding: const EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: AppTheme.surface,
                borderRadius: BorderRadius.circular(AppTheme.rInner),
                border: Border.all(color: AppTheme.hairline),
              ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Text(
                    label,
                    style: const TextStyle(
                      fontSize: 12.5,
                      fontWeight: FontWeight.w900,
                      color: Color(0xFF022E2A),
                    ),
                  ),
                  const SizedBox(height: 8),
                  AppRemovableAttachment(
                    attached: path.isNotEmpty,
                    onRemove: () => setSheet(() => values.remove(fileKey)),
                    child: OutlinedButton.icon(
                    onPressed: () async {
                      final picked = await DocumentStore.pickAndStore(context: context);
                      if (picked == null) return;
                      setSheet(() => values[fileKey] = picked);
                    },
                    icon: Icon(
                      path.isEmpty
                          ? Icons.attach_file_rounded
                          : Icons.check_circle_outline_rounded,
                      size: 18,
                    ),
                    label: Text(
                      path.isEmpty
                          ? 'إرفاق مستند'
                          : DocumentStore.shortName(path, max: 24),
                      maxLines: 3,
                    ),
                    style: OutlinedButton.styleFrom(
                      foregroundColor: _kEquipmentColor,
                      minimumSize: const Size.fromHeight(44),
                    ),
                  ),
                  ),
                  const SizedBox(height: 8),
                  // تاريخ الانتهاء والتذكير جنب بعض.
                  Row(
                    textDirection: AppTr.uiDir,
                    children: [
                      Expanded(
                        child: OutlinedButton.icon(
                          onPressed: () async {
                            final now = DateTime.now();
                            final picked = await showDatePicker(
                              context: sheetContext,
                              initialDate:
                                  AppRemindersStore.parseDisplayDate(end) ??
                                  now,
                              firstDate: DateTime(now.year - 10),
                              lastDate: DateTime(now.year + 30),
                              helpText: AppTr.tr('تاريخ الانتهاء'),
                            );
                            if (picked == null) return;
                            setSheet(
                              () => values[endKey] =
                                  '${picked.day.toString().padLeft(2, '0')}/'
                                  '${picked.month.toString().padLeft(2, '0')}/'
                                  '${picked.year}',
                            );
                          },
                          icon: const Icon(Icons.event_outlined, size: 18),
                          label: FittedBox(
                            fit: BoxFit.scaleDown,
                            child: Text(end.isEmpty ? 'تاريخ الانتهاء' : end),
                          ),
                          style: OutlinedButton.styleFrom(
                            foregroundColor: _kEquipmentColor,
                            minimumSize: const Size.fromHeight(48),
                            padding: const EdgeInsets.symmetric(horizontal: 8),
                          ),
                        ),
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: DropdownButtonFormField<String>(
                          initialValue: reminder,
                          isExpanded: true,
                          decoration: deco('التذكير'),
                          items: [
                            for (final option in certReminders)
                              DropdownMenuItem(
                                value: option,
                                child: FittedBox(fit: BoxFit.scaleDown, alignment: AlignmentDirectional.centerStart, child: Text(
                                  option,
                                  maxLines: 1,
                                )),
                              ),
                          ],
                          onChanged: (value) => setSheet(
                            () => values[reminderKey] = value ?? 'قبل شهر',
                          ),
                        ),
                      ),
                    ],
                  ),
                ],
              ),
            );
          }

          return Directionality(
            textDirection: AppTr.uiDir,
            child: Padding(
              padding: EdgeInsets.fromLTRB(
                16,
                16,
                16,
                MediaQuery.of(sheetContext).viewInsets.bottom + 18,
              ),
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text(
                      labels.title,
                      style: const TextStyle(
                        fontSize: 15,
                        fontWeight: FontWeight.w900,
                        color: AppTheme.title,
                      ),
                    ),
                    const SizedBox(height: 12),
                    TextField(
                      controller: name,
                      textDirection: AppTr.uiDir,
                      decoration: deco('الاسم'),
                    ),
                    const SizedBox(height: 10),
                    TextField(
                      controller: nationality,
                      textDirection: AppTr.uiDir,
                      decoration: deco('الجنسية'),
                    ),
                    const SizedBox(height: 12),
                    certificate(
                      labels.cert,
                      _EquipKeys.operatorCert,
                      _EquipKeys.operatorCertEnd,
                      _EquipKeys.operatorCertReminder,
                    ),
                    certificate(
                      labels.safety,
                      _EquipKeys.safetyCert,
                      _EquipKeys.safetyCertEnd,
                      _EquipKeys.safetyCertReminder,
                    ),
                    const SizedBox(height: 6),
                    FilledButton.icon(
                      onPressed: () => Navigator.pop(sheetContext, true),
                      icon: const Icon(Icons.save_outlined, size: 19),
                      label: const Text(
                        'حفظ',
                        style: TextStyle(fontWeight: FontWeight.w900),
                      ),
                      style: FilledButton.styleFrom(
                        backgroundColor: _kEquipmentColor,
                        foregroundColor: Colors.white,
                        minimumSize: const Size.fromHeight(50),
                      ),
                    ),
                  ],
                ),
              ),
            ),
          );
        },
      ),
    );
    final nameText = name.text.trim();
    final nationalityText = nationality.text.trim();
    Future.delayed(const Duration(milliseconds: 600), () {
      name.dispose();
      nationality.dispose();
    });
    if (saved != true || !mounted) return;
    final updatedMeta = Map<String, String>.of(_item.propertyMeta)
      ..[_EquipKeys.operatorName] = nameText
      ..[_EquipKeys.operatorNationality] = nationalityText
      ..addAll(values)
      ..removeWhere((key, value) => value.trim().isEmpty);
    _updateItem(_item.copyWith(propertyMeta: updatedMeta));
    await _syncEquipmentReminders(_item.title, updatedMeta);
  }

  /// سطر بيانات بقيمته، يُخفى إن كان فارغًا.
  Widget? _equipRow(String label, String? value, IconData icon) {
    final text = (value ?? '').trim();
    if (text.isEmpty || text == 'غير محدد') return null;
    return _AssetInfoRow(
      label: label,
      value: text,
      icon: icon,
      color: _kEquipmentColor,
    );
  }

  /// سطر شهادة: تاريخ انتهائها وزر فتح المستند المرفق.
  Widget? _equipCertRow(String label, String fileKey, String endKey) {
    final meta = _item.propertyMeta;
    final path = (meta[fileKey] ?? '').trim();
    final end = (meta[endKey] ?? '').trim();
    if (path.isEmpty && end.isEmpty) return null;
    return Row(
      textDirection: AppTr.uiDir,
      children: [
        Expanded(
          child: _AssetInfoRow(
            label: label,
            value: end.isEmpty ? 'بلا تاريخ انتهاء' : 'ينتهي $end',
            icon: Icons.verified_outlined,
            color: _kEquipmentColor,
          ),
        ),
        if (path.isNotEmpty)
          IconButton(
            tooltip: AppTr.tr('فتح المستند'),
            onPressed: () => _openAssetStoredFile(path),
            icon: const Icon(
              Icons.open_in_new_rounded,
              size: 18,
              color: _kEquipmentColor,
            ),
          ),
      ],
    );
  }

  /// سطر مستند من «إرفاق مستندات أخرى» مع زر فتحه.
  Widget _equipDocRow(String path) => Row(
    textDirection: AppTr.uiDir,
    children: [
      Expanded(
        child: _AssetInfoRow(
          label: 'مستند مرفق',
          value: DocumentStore.shortName(path),
          icon: Icons.description_outlined,
          color: _kEquipmentColor,
        ),
      ),
      IconButton(
        tooltip: AppTr.tr('فتح المستند'),
        onPressed: () => _openAssetStoredFile(path),
        icon: const Icon(
          Icons.open_in_new_rounded,
          size: 18,
          color: _kEquipmentColor,
        ),
      ),
    ],
  );

  void _cycleEquipmentCondition() {
    const order = ['تعمل', 'تحت الصيانة', 'متوقفة'];
    final currentIndex = order.indexOf(_item.status);
    final next = order[(currentIndex + 1) % order.length];
    _updateItem(
      _item.copyWith(status: next, needsAttention: next == 'تحت الصيانة'),
    );
  }

