              _sectionsHeaderBar(
                count: _equipmentTabCount(),
                showItems: _selectedTab >= 0,
              ),
            Expanded(
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  if (!_detailNavCollapsed)
                    SizedBox(
                      width: _kNavWidth,
                      child: _DetailSideNav(
                        tabs: _equipmentTabs,
                        alertLabels: _historyNeedsAttention
                            ? const {'السجل التاريخي'}
                            : const <String>{},
                        notes: _navNotes,
                        selectedIndex: _selectedTab,
                        color: _kEquipmentColor,
                        onSelect: (i) {
                          // «السجل» و«السجل التاريخي» صفحتان مستقلتان.
                          if (_openRecordsTab(_equipmentTabs[i].label)) return;
