  Widget _buildEquipmentTabContent(_AssetItem item) {
    if (_selectedTab < 0) return const _ChooseHint();
    final meta = item.propertyMeta;
    switch (_selectedTab) {
      case 0: // ملخص عام — البيانات الفنية
        final ownerReminder = meta[_EquipKeys.ownershipReminder] == 'مخصص'
            ? 'قبل ${meta[_EquipKeys.ownershipCustom] ?? ''} يوم'
            : (meta[_EquipKeys.ownershipReminder] ?? '');
        final warrantyReminder = meta[_EquipKeys.warrantyReminder] == 'مخصص'
            ? 'قبل ${meta[_EquipKeys.warrantyCustom] ?? ''} يوم'
            : (meta[_EquipKeys.warrantyReminder] ?? '');
        final operation = meta[_EquipKeys.operation] ?? '';
        final monthReminder = meta[_EquipKeys.monthReminder] == 'مخصص'
            ? 'قبل ${meta[_EquipKeys.monthCustom] ?? ''} يوم'
            : (meta[_EquipKeys.monthReminder] ?? '');
        final otherDocs = (meta[_EquipKeys.otherDocs] ?? '')
            .split('\n')
            .map((line) => line.trim())
            .where((line) => line.isNotEmpty)
            .toList(growable: false);
        return _withEquipLeaseButton(_AssetUnifiedCard(
          showHeader: false,
          title: 'البيانات الفنية',
          icon: Icons.precision_manufacturing_outlined,
          color: _kEquipmentColor,
          children: [
            ...<Widget?>[
              _equipRow(
                'التصنيف',
                [
                  // السجلات القديمة (قبل التصنيف) معدات برية.
                  meta[_EquipKeys.vehicleClass] ?? _kVehicleLand,
