class _AssetCard extends StatelessWidget {
  const _AssetCard({required this.item, required this.onTap});

  final _AssetItem item;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    const healthyStatuses = {'نشط', 'تعمل'};
    final statusColor = healthyStatuses.contains(item.status)
        ? const Color(0xFF34A894)
        : const Color(0xFFC4392E);
    final progress =
        ((item.contractProgress +
                    item.paymentProgress +
                    item.documentsProgress) /
                3)
            .clamp(0.0, 1.0);
    return InkWell(
      borderRadius: BorderRadius.circular(12),
      onTap: onTap,
      child: Container(
        padding: const EdgeInsets.all(12),
        decoration: BoxDecoration(
            color: AppTheme.surface,
            borderRadius: BorderRadius.circular(AppTheme.rField),
          ),
        child: Column(
          children: [
            Row(
              textDirection: AppTr.uiDir,
              children: [
                Container(
                  width: 44,
                  height: 44,
                  decoration: BoxDecoration(
                    color: statusColor.withValues(alpha: 0.12),
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: Icon(_assetIcon(item.category), color: statusColor),
                ),
                const SizedBox(width: 10),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.end,
                    children: [
                      Text(
                        item.title,
                        style: const TextStyle(
                          fontSize: 13,
                          fontWeight: FontWeight.w800,
                          color: Color(0xFF022E2A),
                        ),
                      ),
                      const SizedBox(height: 4),
                      Text(
                        '${item.subType} · ${item.locationOrType}',
                        style: const TextStyle(
                          fontSize: 11,
                          color: Color(0xFF5C6B68),
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                    ],
                  ),
                ),
                const SizedBox(width: 8),
                Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      item.amountLabel,
                      style: const TextStyle(
                        fontSize: 12,
                        fontWeight: FontWeight.w800,
                        color: Color(0xFF04413B),
                      ),
                    ),
                    Text(
                      item.status,
                      style: TextStyle(
                        fontSize: 10,
                        fontWeight: FontWeight.w800,
                        color: statusColor,
                      ),
                    ),
                  ],
                ),
              ],
            ),
            const SizedBox(height: 12),
            ClipRRect(
              borderRadius: BorderRadius.circular(999),
              child: LinearProgressIndicator(
                value: progress,
                minHeight: 6,
                backgroundColor: const Color(0xFFE4EAE8),
                valueColor: AlwaysStoppedAnimation<Color>(statusColor),
              ),
            ),
          ],
        ),
      ),
    );
  }

  IconData _assetIcon(String category) {
    if (category == 'real_estate') return Icons.apartment_rounded;
    if (category == 'project') return Icons.account_tree_rounded;
    return Icons.storefront_rounded;
  }
}

