/// القائمة الجانبية اليمنى لشاشات تفاصيل العقار/النشاط/المعدة — بنفس
/// أسلوب شاشة "إضافة الوحدات والمرافق": الاسم أعلاها ثم أقسام الشاشة،
/// والضغط على أي قسم يعرض محتواه في الجهة الأخرى.
class _DetailSideNav extends StatelessWidget {
  const _DetailSideNav({
    required this.tabs,
    required this.selectedIndex,
    required this.color,
    required this.onSelect,
    this.alertLabels = const <String>{},
    this.notes = const <String, (String, Color)>{},
  });

  /// سطر ملاصق تحت اسم القسم بلونه («مفوَّض أنا بإدارته» تحت «ملخص عام»).
  final Map<String, (String, Color)> notes;

  /// أقسام عليها نقطة حمراء (مثل «السجل التاريخي» بمستحقات متأخرة).
  final Set<String> alertLabels;

  final List<DetailSectionTab> tabs;
  final int selectedIndex;
  final Color color;
  final ValueChanged<int> onSelect;

  /// الاسم كاملًا في سطر واحد — عمود الأقسام أعرض لذلك.
  String _displayLabel(String label) => label;

  @override
  Widget build(BuildContext context) {
    return ListView(
      padding: const EdgeInsets.only(top: 2, bottom: 24),
      children: [
        for (var i = 0; i < tabs.length; i++) ...[
          InkWell(
            key: ValueKey('detail-side-nav-${tabs[i].label}'),
            onTap: () => onSelect(i),
            child: Container(
              color: selectedIndex == i
                  ? color.withValues(alpha: 0.08)
                  : Colors.transparent,
              padding: const EdgeInsetsDirectional.fromSTEB(0, 11, 10, 11),
              child: Row(
                textDirection: AppTr.uiDir,
                children: [
                  // مؤشر برتقالي على حافة القسم المفتوح.
                  AnimatedContainer(
                    duration: const Duration(milliseconds: 180),
                    width: 3,
                    height: 26,
                    margin: const EdgeInsetsDirectional.only(end: 7),
                    decoration: BoxDecoration(
                      color: selectedIndex == i
                          ? AppTheme.gold
                          : Colors.transparent,
                      borderRadius: BorderRadius.circular(AppTheme.rPill),
                    ),
                  ),
                  Icon(
                    tabs[i].icon,
                    size: 15,
                    color: selectedIndex == i ? color : AppTheme.muted,
                  ),
                  const SizedBox(width: 6),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        Text(
                          _displayLabel(tabs[i].label),
                          maxLines: 4,
                          textAlign: TextAlign.right,
                          style: TextStyle(
                            fontSize: 10,
                            height: 1.25,
                            fontWeight: selectedIndex == i
                                ? FontWeight.w900
                                : FontWeight.w700,
                            color: selectedIndex == i
                                ? color
                                : AppTheme.title,
                          ),
                        ),
                        // ملاصق للاسم: «يحتاج متابعة» بالأحمر (مستحقات قديمة
                        // في «السجل التاريخي» مثلًا).
                        if (alertLabels.contains(tabs[i].label))
                          const Text(
                            'يحتاج متابعة',
                            textAlign: TextAlign.right,
                            style: TextStyle(
                              fontSize: 9.5,
                              height: 1.3,
                              fontWeight: FontWeight.w900,
                              color: AppTheme.danger,
                            ),
                          ),
                        // بنفس طريقة «يحتاج متابعة»: ملاصق تحت الاسم بلونه
                        // (البنفسجي للتفويض) بلا أيقونة، والضغط يفتح القسم.
                        if (notes[tabs[i].label] case final note?)
                          Text(
                            note.$1,
                            textAlign: TextAlign.right,
                            style: TextStyle(
                              fontSize: 9.5,
                              height: 1.3,
                              fontWeight: FontWeight.w900,
                              color: note.$2,
                            ),
                          ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          ),
        ],
      ],
    );
  }
}

