class _AssetHero extends StatelessWidget {
  const _AssetHero({
    required this.item,
    required this.baseColor,
    required this.gradientEnd,
    required this.categoryLabel,
  });

  final _AssetItem item;
  final Color baseColor;
  final Color gradientEnd;
  final String categoryLabel;

  @override
  Widget build(BuildContext context) {
    final progress =
        ((item.contractProgress +
                    item.paymentProgress +
                    item.documentsProgress) /
                3)
            .clamp(0.0, 1.0);
    final progressText = '${(progress * 100).toStringAsFixed(0)}%';

    return Container(
      decoration: BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topRight,
          end: Alignment.bottomLeft,
          colors: [baseColor, gradientEnd],
        ),
      ),
      padding: const EdgeInsets.fromLTRB(20, 74, 20, 16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.end,
        mainAxisAlignment: MainAxisAlignment.end,
        children: [
          Row(
            children: [
              Container(
                width: 46,
                height: 46,
                decoration: BoxDecoration(
                  color: Colors.white.withValues(alpha: 0.16),
                  borderRadius: BorderRadius.circular(12),
                  border: Border.all(
                    color: Colors.white.withValues(alpha: 0.24),
                  ),
                ),
                child: Icon(
                  _assetIcon(item.category),
                  color: Colors.white,
                  size: 22,
                ),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      item.title,
                      style: const TextStyle(
                        color: Colors.white,
                        fontSize: 17,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                    const SizedBox(height: 2),
                    Text(
                      '$categoryLabel • ${item.subType}',
                      style: TextStyle(
                        color: Colors.white.withValues(alpha: 0.85),
                        fontSize: 11,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ],
                ),
              ),
              Container(
                padding: const EdgeInsets.symmetric(
                  horizontal: 10,
                  vertical: 5,
                ),
                decoration: BoxDecoration(
                  color: Colors.white.withValues(alpha: 0.18),
                  borderRadius: BorderRadius.circular(999),
                ),
                child: Text(
                  item.status,
                  style: const TextStyle(
                    color: Colors.white,
                    fontSize: 11,
                    fontWeight: FontWeight.w800,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 12),
          Row(
            children: [
              Expanded(
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(999),
                  child: LinearProgressIndicator(
                    value: progress,
                    minHeight: 6,
                    backgroundColor: Colors.white.withValues(alpha: 0.22),
                    valueColor: const AlwaysStoppedAnimation<Color>(
                      Colors.white,
                    ),
                  ),
                ),
              ),
              const SizedBox(width: 10),
              Text(
                'التقدم $progressText',
                style: const TextStyle(
                  color: Colors.white,
                  fontSize: 11,
                  fontWeight: FontWeight.w700,
                ),
              ),
            ],
          ),
          const SizedBox(height: 8),
          Text(
            '${item.locationOrType}  •  ${item.amountLabel}',
            style: TextStyle(
              color: Colors.white.withValues(alpha: 0.9),
              fontSize: 11,
              fontWeight: FontWeight.w700,
            ),
          ),
        ],
      ),
    );
  }

  IconData _assetIcon(String category) {
    if (category == 'real_estate') return Icons.apartment_rounded;
    if (category == 'project') return Icons.account_tree_rounded;
    return Icons.storefront_rounded;
  }
}

class _EntryGroupCard extends StatelessWidget {
  const _EntryGroupCard({
    required this.group,
    required this.entries,
    required this.onAdd,
    required this.onEdit,
    required this.onDelete,
    this.onOpenFile,
    this.showHeader = true,
    this.emptyText,
  });

  /// نص القائمة الفارغة — افتراضًا «لا توجد <اسم المجموعة> بعد».
  final String? emptyText;

  final _ActionGroup group;
  final List<Map<String, String>> entries;
  final VoidCallback onAdd;
  final ValueChanged<int> onEdit;
  final ValueChanged<int> onDelete;

  /// إخفاء ترويسة البطاقة حين يحمل عنوان القسم فوقها الاسم نفسه.
  final bool showHeader;

  /// فتح المستند المرفق بالعنصر — يُمرَّر من شاشة تفاصيل العقار.
  final ValueChanged<String>? onOpenFile;

  @override
  Widget build(BuildContext context) {
    return Container(
      width: double.infinity,
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: AppTheme.paper,
        borderRadius: BorderRadius.circular(AppTheme.rInner),
        border: Border.all(color: AppTheme.hairline),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          if (showHeader)
          Row(
            children: [
              Container(
                width: 34,
                height: 34,
                decoration: BoxDecoration(
                  color: group.color.withValues(alpha: 0.12),
                  borderRadius: BorderRadius.circular(12),
                ),
                child: Icon(group.icon, color: group.color, size: 18),
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Text(
                  group.title,
                  style: const TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w800,
                    color: Color(0xFF022E2A),
                  ),
                ),
              ),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 3),
                decoration: BoxDecoration(
                  color: group.color.withValues(alpha: 0.10),
                  borderRadius: BorderRadius.circular(999),
                ),
                child: Text(
                  '${entries.length}',
                  style: TextStyle(
                    color: group.color,
                    fontSize: 11,
                    fontWeight: FontWeight.w800,
                  ),
                ),
              ),
              const SizedBox(width: 6),
              InkWell(
                borderRadius: BorderRadius.circular(12),
                onTap: onAdd,
                child: Container(
                  padding: const EdgeInsets.all(6),
                  decoration: BoxDecoration(
                    color: group.color,
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: const Icon(
                    Icons.add_rounded,
                    size: 18,
                    color: Colors.white,
                  ),
                ),
              ),
            ],
          ),
          if (entries.isEmpty) ...[
            const SizedBox(height: 10),
            Text(
              emptyText ?? 'لا توجد ${group.title} بعد — اضغط + للإضافة',
              textAlign: TextAlign.right,
              style: const TextStyle(
                fontSize: 11,
                color: Color(0xFF8C9A97),
                fontWeight: FontWeight.w600,
              ),
            ),
          ] else ...[
            const SizedBox(height: 10),
            for (var i = 0; i < entries.length; i++) ...[
              _EntryTile(
                entry: entries[i],
                color: group.color,
                primaryLabel: group.fields.first.label,
                secondaryLabels: group.fields
                    .skip(1)
                    .map((f) => f.label)
                    .toList(growable: false),
                onEdit: () => onEdit(i),
                onDelete: () => onDelete(i),
                canDelete: !_kNoDeleteEntryKinds.contains(group.kind),
                onOpenFile: onOpenFile,
              ),
              if (i < entries.length - 1)
                Divider(
                  height: 14,
                  thickness: 0.6,
                  color: const Color(0xFFE4EAE8).withValues(alpha: 0.8),
                ),
            ],
          ],
        ],
      ),
    );
  }
}

class _EntryTile extends StatelessWidget {
  const _EntryTile({
    required this.entry,
    required this.color,
    required this.primaryLabel,
    required this.secondaryLabels,
    required this.onEdit,
    required this.onDelete,
    this.onOpenFile,
    this.canDelete = true,
  });

  /// false: بلا زر الحذف (العقود والحركات المالية).
  final bool canDelete;

  final Map<String, String> entry;
  final Color color;
  final String primaryLabel;
  final List<String> secondaryLabels;
  final VoidCallback onEdit;
  final VoidCallback onDelete;

  /// يُستدعى بمسار الملف المرفق عند الضغط على «فتح».
  final ValueChanged<String>? onOpenFile;

  @override
  Widget build(BuildContext context) {
    final title = (entry[primaryLabel] ?? '').isNotEmpty
        ? entry[primaryLabel]!
        : 'بدون عنوان';
    final filePath = (entry[DocumentStore.kFileField] ?? '').trim();
    final subtitle = [
      ...secondaryLabels
          .where((label) => label != DocumentStore.kFileField)
          .map((label) => entry[label] ?? '')
          .where((v) => v.trim().isNotEmpty)
          .take(3),
      if (filePath.isNotEmpty) DocumentStore.shortName(filePath),
    ].join(' • ');

    return InkWell(
      onTap: onEdit,
      borderRadius: BorderRadius.circular(12),
      child: Padding(
        padding: const EdgeInsets.symmetric(vertical: 4),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Container(
              width: 8,
              height: 8,
              margin: const EdgeInsets.only(top: 6),
              decoration: BoxDecoration(
                color: color,
                borderRadius: BorderRadius.circular(8),
              ),
            ),
            const SizedBox(width: 8),
            Expanded(
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    title,
                    style: const TextStyle(
                      fontSize: 12,
                      fontWeight: FontWeight.w800,
                      color: Color(0xFF022E2A),
                    ),
                  ),
                  if (subtitle.isNotEmpty) ...[
                    const SizedBox(height: 2),
                    Text(
                      subtitle,
                      style: const TextStyle(
                        fontSize: 10,
                        color: Color(0xFF5C6B68),
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ],
                ],
              ),
            ),
            if (filePath.isNotEmpty && onOpenFile != null)
              IconButton(
                onPressed: () => onOpenFile!(filePath),
                icon: Icon(
                  DocumentStore.existsSync(filePath)
                      ? Icons.open_in_new_rounded
                      : Icons.report_gmailerrorred_rounded,
                  size: 18,
                  color: DocumentStore.existsSync(filePath)
                      ? color
                      : const Color(0xFFC4392E),
                ),
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 32, minHeight: 32),
                tooltip: AppTr.tr('فتح المستند'),
              ),
            IconButton(
              onPressed: onEdit,
              icon: Icon(Icons.edit_outlined, size: 18, color: color),
              padding: EdgeInsets.zero,
              constraints: const BoxConstraints(minWidth: 32, minHeight: 32),
              tooltip: AppTr.tr('تعديل'),
            ),
            if (canDelete)
              IconButton(
                onPressed: onDelete,
                icon: const Icon(
                  Icons.delete_outline_rounded,
                  size: 18,
                  color: Color(0xFFC4392E),
                ),
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 32, minHeight: 32),
                tooltip: AppTr.tr('حذف'),
              ),
          ],
        ),
      ),
    );
  }
}

class _ActionGroup {
