class _FieldDef {
  const _FieldDef(
    this.label,
    this.isNumeric, {
    this.isDate = false,
    this.multiline = false,
    this.isFile = false,
    this.options,
    this.required = false,
    this.display,
  });

  /// حقل إلزامي: يُعلَّم بنجمة ولا يُحفظ النموذج بدونه.
  final bool required;

  /// الاسم الظاهر إن اختلف عن مفتاح الحفظ (البيانات القديمة بمفتاحها).
  final String? display;

  final String label;
  final bool isNumeric;
  final bool isDate;
  final bool multiline;

  /// حقل مرفق: يُرفع فيه ملف ويُحفظ مساره بدل الكتابة اليدوية.
  final bool isFile;
  final List<String>? options;
}

class _PropertyAnnexesEditor extends StatelessWidget {
  const _PropertyAnnexesEditor({
    required this.counts,
    required this.otherController,
    required this.onCountChanged,
  });

  final Map<String, int> counts;
  final TextEditingController otherController;
  final void Function(String label, int count) onCountChanged;

  @override
  Widget build(BuildContext context) {
    final selectedCount = counts.values.where((count) => count > 0).length;
    return Container(
      decoration: BoxDecoration(
            color: AppTheme.surface,
            borderRadius: BorderRadius.circular(AppTheme.rField),
          ),
      child: ExpansionTile(
        tilePadding: const EdgeInsets.symmetric(horizontal: 12),
        childrenPadding: const EdgeInsets.fromLTRB(10, 0, 10, 12),
        title: const Text(
          'ملحقات العقار',
          style: TextStyle(fontWeight: FontWeight.w800),
        ),
        subtitle: Text(
          selectedCount == 0
              ? 'حدد الممرات والغرف والمرافق التابعة للعقار'
              : 'تم تحديد $selectedCount من الملحقات',
        ),
        children: [
          for (final label in _propertyAnnexLabels)
            Row(
              children: [
                Checkbox(
                  value: (counts[label] ?? 0) > 0,
                  onChanged: (selected) =>
                      onCountChanged(label, selected == true ? 1 : 0),
                ),
                Expanded(child: Text(label)),
                if ((counts[label] ?? 0) > 0) ...[
                  IconButton(
                    onPressed: () => onCountChanged(
                      label,
                      ((counts[label] ?? 1) - 1).clamp(0, 99),
                    ),
                    icon: const Icon(Icons.remove_circle_outline_rounded),
                  ),
                  SizedBox(
                    width: 28,
                    child: Text(
                      '${counts[label]}',
                      textAlign: TextAlign.center,
                      style: const TextStyle(fontWeight: FontWeight.w900),
                    ),
                  ),
                  IconButton(
                    onPressed: () => onCountChanged(
                      label,
                      ((counts[label] ?? 0) + 1).clamp(0, 99),
                    ),
                    icon: const Icon(Icons.add_circle_outline_rounded),
                  ),
                ],
              ],
            ),
          const SizedBox(height: 6),
          TextField(
            controller: otherController,
            textDirection: AppTr.uiDir,
            decoration: InputDecoration(
              labelText: AppTr.tr('إضافة ملحق آخر'),
              hintText: AppTr.tr('مثال: غرفة حارس، مستودع خارجي'),
              border: OutlineInputBorder(),
              isDense: true,
            ),
          ),
        ],
      ),
    );
  }
}

// ============================================================
// أنواع الوحدات داخل العقار ومنطق كل نوع، معرّفة في مكان واحد حتى تبقى
// كل الشاشات متسقة:
//   • شقة    : سكنية بعدد غرف ودورات مياه وموقف ومساحة.
//   • استديو : سكنية مفتوحة — لها دورات مياه وموقف ومساحة، لكن بلا عدد
//              غرف مستقل لأن الغرفة واحدة بطبيعتها (تُحفظ rooms = 1).
//   • محل    : تجاري — مساحة فقط (بلا غرف/دورات مياه/موقف).
// ============================================================
const String _kUnitApartment = 'شقة';
const String _kUnitStudio = 'استديو';
const String _kUnitShop = 'محل';
const String _kUnitOffice = 'مكتب';
const String _kUnitWarehouse = 'مستودع';
const String _kUnitRoom = 'غرفة';
const String _kUnitParking = 'موقف خاص';
const String _kUnitFullFloor = 'دور كامل';
const String _kUnitShowroom = 'معرض';
const String _kUnitMezzanine = 'ميزانين';
// وحدات أنواع العقار الجديدة (ملف أنواع العقارات المعتمد).
const String _kUnitLand = 'أرض';
const String _kUnitChalet = 'شاليه';
const String _kUnitStation = 'محطة بترول';
const String _kUnitAdSpace = 'مساحة إعلانية';
const String _kUnitRoofSpace = 'مساحة على سطح العمارة';
const String _kUnitTelecomSite = 'موقع أجهزة اتصال';
const List<String> _kUnitTypes = [
  _kUnitApartment,
  _kUnitStudio,
  _kUnitFullFloor,
  _kUnitRoom,
  _kUnitShop,
  _kUnitOffice,
  _kUnitShowroom,
  _kUnitMezzanine,
  _kUnitWarehouse,
  _kUnitParking,
  _kUnitLand,
  _kUnitChalet,
  _kUnitStation,
  _kUnitAdSpace,
  _kUnitRoofSpace,
  _kUnitTelecomSite,
];

/// هل يملك هذا النوع عدد غرف قابلًا للإدخال؟ (الشقة والمكتب والشاليه).
bool _unitTypeHasRooms(String type) =>
    type == _kUnitApartment ||
    type == _kUnitOffice ||
    type == _kUnitFullFloor ||
    type == _kUnitChalet;

/// هل لهذا النوع دورات مياه وموقف؟ السكني والمكتب نعم، أما المحل
/// والمستودع والموقف فلا.
bool _unitTypeIsResidential(String type) =>
    type == _kUnitApartment ||
    type == _kUnitStudio ||
    type == _kUnitRoom ||
    type == _kUnitOffice ||
    type == _kUnitFullFloor ||
    type == _kUnitChalet;

/// عدد الغرف المنطقي المخزَّن لكل نوع: الاستديو والغرفة غرفة واحدة دائمًا.
int _unitTypeRoomsFor(String type, int enteredRooms) {
  if (type == _kUnitStudio || type == _kUnitRoom) return 1;
  if (type == _kUnitApartment ||
      type == _kUnitOffice ||
      type == _kUnitFullFloor ||
      type == _kUnitChalet) {
    return enteredRooms;
  }
  return 0;
}

/// سهم طيّ الجانب: أكبر من السابق ويومض بلطف حتى يلاحظه المستخدم.
class _BlinkingCollapseButton extends StatefulWidget {
  const _BlinkingCollapseButton({
    required this.collapsed,
    required this.onTap,
  });

  final bool collapsed;
  final VoidCallback onTap;

  @override
  State<_BlinkingCollapseButton> createState() =>
      _BlinkingCollapseButtonState();
}

class _BlinkingCollapseButtonState extends State<_BlinkingCollapseButton>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller = AnimationController(
    vsync: this,
    duration: const Duration(milliseconds: 900),
  )..repeat(reverse: true);

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return InkWell(
      onTap: widget.onTap,
      borderRadius: BorderRadius.circular(AppTheme.rIcon),
      child: FadeTransition(
        opacity: Tween<double>(begin: 0.45, end: 1.0).animate(
          CurvedAnimation(parent: _controller, curve: Curves.easeInOut),
        ),
        child: Container(
          width: 22,
          height: 40,
          decoration: BoxDecoration(
            color: AppTheme.gold,
            borderRadius: BorderRadius.circular(AppTheme.rIcon),
          ),
          child: Icon(
            // الاتجاه معكوس: السهم يشير إلى الجهة التي سينتقل إليها
            // الجانب عند الضغط.
            widget.collapsed
                ? Icons.chevron_right_rounded
                : Icons.chevron_left_rounded,
            size: 20,
            color: Colors.white,
          ),
        ),
      ),
    );
  }
}

IconData _unitTypeIcon(String type) {
  switch (type) {
    case _kUnitShop:
      return Icons.storefront_rounded;
    case _kUnitStudio:
      return Icons.single_bed_rounded;
    case _kUnitOffice:
      return Icons.business_center_rounded;
    case _kUnitWarehouse:
      return Icons.warehouse_rounded;
    case _kUnitRoom:
      return Icons.meeting_room_rounded;
    case _kUnitParking:
      return Icons.local_parking_rounded;
    case _kUnitFullFloor:
      return Icons.layers_rounded;
    case _kUnitMezzanine:
      return Icons.unfold_less_double_rounded;
    case _kUnitShowroom:
      return Icons.store_mall_directory_rounded;
    case _kUnitLand:
      return Icons.terrain_rounded;
    case _kUnitChalet:
      return Icons.cottage_rounded;
    case _kUnitStation:
      return Icons.local_gas_station_rounded;
    case _kUnitAdSpace:
      return Icons.campaign_outlined;
    case _kUnitRoofSpace:
      return Icons.roofing_rounded;
    case _kUnitTelecomSite:
      return Icons.cell_tower_rounded;
    default:
      return Icons.apartment_rounded;
  }
}

class _PropertyUnit {
  const _PropertyUnit({
    required this.type,
    required this.name,
    this.unitNumber = '',
    this.area = '',
    this.rooms = 0,
    this.halls = 0,
    this.balconies = 0,
    this.bathrooms = 0,
    this.parkingCount = 0,
    this.hasParking = false,
    this.notes = '',
    this.status = 'شاغرة',
    this.extras = const {},
  });

  final String type;
  final String name;
  final String unitNumber;
  final String area;
  final int rooms;

  /// عدد الصالات والبلكونات وموقف السيارات الخاصة والملاحظات — من نموذج
  /// "إضافة الوحدات والمرافق العامة".
  final int halls;
  final int balconies;
  final int bathrooms;
  final int parkingCount;
  final bool hasParking;
  final String notes;
  final String status;

  /// بيانات إضافية مفتوحة للوحدة (مكان الوحدة، رقم عداد الكهرباء، شروط
  /// الإيجار، بيانات شركة المستأجر، سجل الصيانة...) — تُخزَّن مع الوحدة
  /// في unitsJson فلا تحتاج أي تعديل على قاعدة البيانات.
  final Map<String, String> extras;

  /// معرّف مستقر لهذه الوحدة داخل العقار، يُستخدم للربط مع عقود/دفعات
  /// الإيجار في property_unit_contracts (عمود unit_key). لا يُخزَّن بشكل
  /// منفصل؛ يُشتق من الحقول الحالية حتى لا يتغير عند إعادة القراءة من
  /// الخادم.
  /// مفتاح الوحدة الذي تُربط به عقودها ودفعاتها وحركاتها.
  ///
  /// يُحسب من «النوع|الاسم|الرقم» ما لم يُثبَّت؛ وعند أول تعديل للاسم أو
  /// الرقم يُثبَّت المفتاح القديم في [kPinnedKey]، فتبقى الروابط كما هي.
  String get unitKey {
    final pinned = (extras[kPinnedKey] ?? '').trim();
    return pinned.isNotEmpty ? pinned : '$type|$name|$unitNumber';
  }

  static const kPinnedKey = '__key';

  _PropertyUnit copyWith({
    String? type,
    String? name,
    String? unitNumber,
    String? area,
    int? rooms,
    int? halls,
    int? balconies,
    int? bathrooms,
    int? parkingCount,
    bool? hasParking,
    String? notes,
    String? status,
    Map<String, String>? extras,
  }) => _PropertyUnit(
    type: type ?? this.type,
    name: name ?? this.name,
    unitNumber: unitNumber ?? this.unitNumber,
    area: area ?? this.area,
    rooms: rooms ?? this.rooms,
    halls: halls ?? this.halls,
    balconies: balconies ?? this.balconies,
    bathrooms: bathrooms ?? this.bathrooms,
    parkingCount: parkingCount ?? this.parkingCount,
    hasParking: hasParking ?? this.hasParking,
    notes: notes ?? this.notes,
    status: status ?? this.status,
    extras: extras ?? this.extras,
  );

  Map<String, dynamic> toMap() => {
    'type': type,
    'name': name,
    'unitNumber': unitNumber,
    'area': area,
    'rooms': rooms,
    'halls': halls,
    'balconies': balconies,
    'bathrooms': bathrooms,
    'parkingCount': parkingCount,
    'hasParking': hasParking,
    'notes': notes,
    'status': status,
    'extras': extras,
  };

  factory _PropertyUnit.fromMap(Map<String, dynamic> map) => _PropertyUnit(
    type: (map['type'] ?? _kUnitApartment).toString(),
    name: (map['name'] ?? '').toString(),
    unitNumber: (map['unitNumber'] ?? '').toString(),
    area: (map['area'] ?? '').toString(),
    rooms: (map['rooms'] as num?)?.toInt() ?? 0,
    halls: (map['halls'] as num?)?.toInt() ?? 0,
    balconies: (map['balconies'] as num?)?.toInt() ?? 0,
    bathrooms: (map['bathrooms'] as num?)?.toInt() ?? 0,
    parkingCount: (map['parkingCount'] as num?)?.toInt() ?? 0,
    hasParking: map['hasParking'] == true,
    notes: (map['notes'] ?? '').toString(),
    status: (map['status'] ?? 'شاغرة').toString(),
    extras: map['extras'] is Map
        ? (map['extras'] as Map).map(
            (key, value) => MapEntry('$key', '${value ?? ''}'),
          )
        : const {},
  );
}

