];

/// أرقام عدادات العقار أو الوحدة: «عدد العدادات» أولًا، ثم تحته خانة لكل
/// عداد بقدر العدد المكتوب (2 ← خانتان). العدد في [countKey]، والأرقام سطر
/// لكل عداد في [numbersKey].
const String _kElectricCountKey = 'عدد عدادات الكهرباء';
const String _kElectricMetersKey = 'عدادات الكهرباء';
const String _kWaterCountKey = 'عدد عدادات المياه';
const String _kWaterMetersKey = 'عدادات المياه';

/// (مفتاح العدد، مفتاح الأرقام، عنوان العدد، عنوان الرقم، الأيقونة).
const List<(String, String, String, String, IconData)> _kMeterCountFields = [
  (
    _kElectricCountKey,
    _kElectricMetersKey,
    'عدد عدادات الكهرباء',
    'رقم عداد الكهرباء',
