/// الوسم الثابت للتفويض: «مفوَّض أنا بإدارته» لما فوّضني به غيري،
/// و«فوّضت غيري بإدارته» لما فوّضته أنا — null إن لا تفويض.
String? _delegationBadgeOf(String? assetId) {
  if (DelegatedAssets.isDelegated(assetId)) return 'مفوَّض أنا بإدارته';
  if (OutgoingDelegations.of(assetId).isNotEmpty) {
    return 'فوّضت غيري بإدارته';
  }
  return null;
}

/// المفوَّض يلغي التفويض من عنده: يفقد الوصول فورًا، ويُشعَر صاحبه،
/// ويستطيع العودة من «أشخاص فوّضوني» ما دام صاحبه لم يُنهِه.
Future<void> _withdrawFromDelegation(
  BuildContext context,
  _AssetItem item,
) async {
  final delegation = DelegatedAssets.of(item.id);
  if (delegation == null || delegation.delegationIds.isEmpty) return;
  final ok = await confirmAction(
    context,
    title: 'إلغاء التفويض',
    message:
        '${AppTr.tr('ستتوقف عن إدارة')} «${item.title}» '
        '${AppTr.tr('فورًا، ويصل لصاحبه إشعار بإلغائك للتفويض. تستطيع العودة إليه من «المزيد ← التفويضات ← أشخاص فوّضوني» ما دام صاحبه لم يُنهِه. هل تريد المتابعة؟')}',
    confirmLabel: 'إلغاء التفويض',
    danger: true,
  );
  if (!ok || !context.mounted) return;
  final messenger = ScaffoldMessenger.of(context);
  final navigator = Navigator.of(context);
  try {
    for (final id in delegation.delegationIds) {
      await SupabaseDelegationsRepository().setIncomingAnswer(id, 'withdrawn');
    }
    messenger.showSnackBar(
      SnackBar(
        content: Text(
          '${AppTr.tr('تم إلغاء التفويض وإشعار')} ${delegation.owner}',
        ),
        behavior: SnackBarBehavior.floating,
      ),
    );
    await navigator.maybePop();
    DelegatedAssets.changed.value++;
  } catch (_) {
    messenger.showSnackBar(
      const SnackBar(
        content: Text('تعذّر إلغاء التفويض. حاول مرة أخرى.'),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }
}

