  'expense',
};

/// عقار/نشاط/مركبة ملغى — منه فقط يظهر «حذف» إلى السلة.
bool _isCancelledAsset(_AssetItem item) => item.status.contains('ملغ');

String _assetDeleteLabel(_AssetItem item) =>
    _isCancelledAsset(item) ? 'حذف' : 'إلغاء';

IconData _assetDeleteIcon(_AssetItem item) => _isCancelledAsset(item)
    ? Icons.delete_outline_rounded
    : Icons.cancel_outlined;

String _assetDeleteMessage(_AssetItem item) => _isCancelledAsset(item)
    ? 'سيُنقل «${item.title}» إلى سلة المهملات، ومنها يمكن استعادته أو '
          'حذفه نهائيًا. هل تريد المتابعة؟'
    : 'إذا ألغيت «${item.title}» فلن تستطيع استعادته: يصبح «ملغي» وتنتقل '
          'كل أموره (العقود والدفعات والمستندات) إلى «السجل التاريخي». '
          'هل تريد الإلغاء؟';

String _assetDeleteConfirm(_AssetItem item) =>
    _isCancelledAsset(item) ? 'نقل إلى السلة' : 'إلغاء العنصر';

String _trashStamp() {
  final now = DateTime.now();
  return '${now.year}/${now.month.toString().padLeft(2, '0')}/'
      '${now.day.toString().padLeft(2, '0')} '
      '${now.hour.toString().padLeft(2, '0')}:'
      '${now.minute.toString().padLeft(2, '0')}';
}

/// يوم/شهر/سنة — الترتيب الذي يكتبه المستخدم ويقرؤه، برقمين للثبات.
///
/// كانت التواريخ تُكتب بصيغ مختلفة في كل شاشة (بلا تصفير، وأحيانًا
/// سنة/شهر/يوم)، فيقرأ المستخدم 3/8 و8/3 ولا يعرف أيّهما اليوم.
/// مبلغ بفواصل الآلاف وبلا كسور صفرية — «4,800» لا «4800.0».
String formatMoneyValue(double value) {
  final rounded = value.roundToDouble() == value
      ? value.toStringAsFixed(0)
      : value.toStringAsFixed(2);
  final parts = rounded.split('.');
  final digits = parts.first;
  final buffer = StringBuffer();
  for (var i = 0; i < digits.length; i++) {
    if (i > 0 && (digits.length - i) % 3 == 0) buffer.write(',');
    buffer.write(digits[i]);
  }
  return parts.length > 1 ? '$buffer.${parts[1]}' : buffer.toString();
}

/// شريط المتابعة داخل صندوق العقار/الوحدة: الطلبات، والمستحقات،
/// والمستندات — الرقم فوق الكلمة كما في مراكز المتابعة، وسهم يفتحه.
Widget followUpStripRow({
  required int requests,
