  required int docs,
  int oldDues = 0,
  int other = 0,
}) {
  Widget item(String label, int count) {
    final color = count > 0 ? const Color(0xFFA6691A) : const Color(0xFF5C6B68);
    return Expanded(
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(
            '$count',
            style: TextStyle(
              fontSize: 15,
              fontWeight: FontWeight.w900,
              color: count > 0 ? color : const Color(0xFF022E2A),
            ),
          ),
          const SizedBox(height: 2),
          Text(
            label,
            textAlign: TextAlign.center,
            maxLines: 2,
            softWrap: true,
            style: TextStyle(
              fontSize: 10,
              height: 1.25,
              fontWeight: FontWeight.w800,
              color: color,
            ),
          ),
        ],
      ),
    );
  }

  return Row(
    textDirection: AppTr.uiDir,
    children: [
      item('الطلبات', requests),
      item('مستحقات للمتابعة', dues),
      // مستحقات مستأجر سابق — تظهر فقط إن وُجدت.
      if (oldDues > 0) item('مستحقات قديمة', oldDues),
      item('مستندات للمتابعة', docs),
      // العقود المنتهية/القريبة من الانتهاء والصيانة المفتوحة.
      if (other > 0) item('عقود وصيانة', other),
