/// حالة الشيك كما تُعرض: المسجّلة، وإلا «مستلم» ما دام مكتوبًا في العقد.
/// حالة الشيك كما تُعرض: «مستلم (لم يُصرف)» — «مستلم» وحدها تُفهم أن
/// المبلغ استُلم.
String chequeStateLabel(String state) =>
    state == LeaseContractData.chequeReceived ? 'مستلم (لم يُصرف)' : state;

String chequeStateOf(Map<String, String> row) {
  final state = (row[LeaseContractData.kChequeState] ?? '').trim();
  if (state.isNotEmpty) return state;
  return (row[LeaseContractData.kPaymentStatus] ?? '') == 'مسددة'
      ? LeaseContractData.chequeCleared
      : LeaseContractData.chequeReceived;
}

Color chequeStateColor(String state) => switch (state) {
  LeaseContractData.chequeCleared => const Color(0xFF0E7161),
  LeaseContractData.chequeAtBank => const Color(0xFF2F6FB0),
  LeaseContractData.chequeCancelled => const Color(0xFFC4392E),
  LeaseContractData.chequeReplaced => const Color(0xFF8C9A97),
  LeaseContractData.chequeRejected => const Color(0xFFB0452E),
  LeaseContractData.chequeReturned => const Color(0xFFB0452E),
  _ => const Color(0xFFA6691A),
};

String _isoDay(DateTime date) =>
    '${date.year.toString().padLeft(4, '0')}-'
    '${date.month.toString().padLeft(2, '0')}-'
    '${date.day.toString().padLeft(2, '0')}';

/// يجد سطر الشيك في نسخة حديثة من العقد: بمعرّف السطر إن وُجد، وإلا
/// برقم الشيك وتاريخ استحقاقه ومبلغه معًا.
Map<String, String>? _findChequeRow(
  LeaseContractData lease,
  Map<String, String> shown,
) {
  final rid = (shown[LeaseContractData.kRowId] ?? '').trim();
  for (final row in lease.payments) {
    if (rid.isNotEmpty) {
      if ((row[LeaseContractData.kRowId] ?? '').trim() == rid) return row;
      continue;
    }
    if ((row[LeaseContractData.kPaymentCheque] ?? '') ==
            (shown[LeaseContractData.kPaymentCheque] ?? '') &&
        (row[LeaseContractData.kPaymentDue] ?? '') ==
            (shown[LeaseContractData.kPaymentDue] ?? '') &&
        (row[LeaseContractData.kPaymentAmount] ?? '') ==
            (shown[LeaseContractData.kPaymentAmount] ?? '')) {
      return row;
    }
  }
  return null;
}

/// الإجراءات المتاحة للشيك بحسب حالته.
///
/// الملغى يُعاد نشاطه فقط. المحصَّل والمستبدل انتهى دورهما. المرفوض يُعاد
/// إرساله إلى البنك أو يُستبدل أو يُلغى. والرفض لا يكون إلا لشيك في البنك.
List<String> _chequeActionsFor(String state) {
  switch (state) {
    case LeaseContractData.chequeCancelled:
      return const [_chqActReactivate];
    case LeaseContractData.chequeCleared:
    case LeaseContractData.chequeReplaced:
      return const [];
    case LeaseContractData.chequeRejected:
    case LeaseContractData.chequeReturned:
      return const [_chqActBank, _chqActReplace, _chqActCancel];
  }
  return [
    // «مستلم (لم يُصرف)» أول الإجراءات دائمًا.
    _chqActReceived,
    if (state != LeaseContractData.chequeAtBank) _chqActBank,
    _chqActCleared,
    if (state == LeaseContractData.chequeAtBank) _chqActRejected,
    // «مرتجع» متاح للشيك المستلم والمرسل إلى البنك.
    _chqActReturned,
    _chqActReplace,
    _chqActNumber,
    _chqActDate,
    _chqActCancel,
  ];
}

/// عنوان حقل تاريخ الإجراء — «متى حدث»، لا تاريخ اليوم بالضرورة: الشيك
/// قد يُستلم أو يُحصَّل بعد تاريخه بيوم أو أكثر.
String _chequeActionDateLabel(String action) => switch (action) {
  _chqActReceived => 'تاريخ الاستلام',
  _chqActBank => 'تاريخ الإرسال إلى البنك',
  _chqActCleared => 'تاريخ استلام المبلغ',
  _chqActRejected => 'تاريخ الرفض',
  _chqActReturned => 'تاريخ الإرجاع',
  _chqActCancel => 'تاريخ الإلغاء',
  _chqActReactivate => 'تاريخ إعادة النشاط',
  _chqActReplace => 'تاريخ استلام الشيك البديل',
  _ => '',
};

/// نافذة الشيك: بياناته وحالته، وتحتها «الإجراء» قائمة منسدلة. اختيار
/// إجراء يُظهر حقوله وتاريخه، ثم «متابعة» ← تأكيد يقول ما سيحدث ← حفظ.
///
/// تعيد `true` إن تغيّر شيء، فيعيد المستدعي تحميل الشاشة.
/// «إدارة الشيكات» لشيك دفعة من صفحة السداد: نفس نافذة الشيك (حالته
/// وإجراءاته وسجله) في إدارة الشيكات.
Future<bool> openEntryChequeManager(
  BuildContext context,
  ProjectAssetsRepository repository,
  RentPaymentEntry entry,
) async {
  final found = payLeaseRow(entry);
  if (found == null || found.kind != 0) return false;
  return openChequeActions(
    context: context,
    repository: repository,
    contract: entry.contract,
    row: found.row,
    holder: (entry.contract.tenantName ?? '').trim(),
  );
}

Future<bool> openChequeActions({
  required BuildContext context,
  required ProjectAssetsRepository repository,
  required PropertyUnitContractRecord contract,
  required Map<String, String> row,
  required String holder,
}) async {
  final state = chequeStateOf(row);
  final actions = _chequeActionsFor(state);
  // سجل الشيك: كل إجراء بتاريخه، يُعرض أسفل النافذة.
  final log = (row[LeaseContractData.kChequeLog] ?? '').trim();
  final oldNumber = (row[LeaseContractData.kPaymentCheque] ?? '').trim();
  final oldChequeDate = DateTime.tryParse(
    (row[LeaseContractData.kPaymentChequeDate] ?? '').trim(),
  );
  String show(String key) {
    final value = (row[key] ?? '').trim();
    if (value.isEmpty) return '—';
    final date = DateTime.tryParse(value);
    return date == null ? value : formatDayMonthYear(date);
  }

  // مبلغ الشيك شاملًا الضريبة.
  final chequeAmount = formatMoneyValue(
    LeaseContractData.decode(contract.notes).paymentTotalOf(row),
  );

  final now = DateTime.now();
  String? action;
  var actionDate = DateTime(now.year, now.month, now.day);
  DateTime? newChequeDate;
  final numberCtrl = TextEditingController();
  final bankCtrl = TextEditingController(
    text: row[LeaseContractData.kPaymentBank] ?? '',
  );
  final reasonCtrl = TextEditingController();
  var error = '';

  Widget dateField(
    BuildContext sheetContext,
    String label,
    DateTime? value,
    ValueChanged<DateTime> onPicked,
  ) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: InkWell(
        borderRadius: BorderRadius.circular(AppTheme.rInner),
        onTap: () async {
          final picked = await showDatePicker(
            context: sheetContext,
            initialDate: value ?? DateTime.now(),
            firstDate: DateTime(2015),
            lastDate: DateTime(2070),
            helpText: label,
          );
          if (picked != null) onPicked(picked);
        },
        child: InputDecorator(
          decoration: _propertyInputDecorationShared(label),
          child: Text(
            value == null ? 'اختر التاريخ' : formatDayMonthYear(value),
            style: TextStyle(
              fontSize: 12.5,
              fontWeight: FontWeight.w800,
              color: value == null
                  ? const Color(0xFFA9B4B1)
                  : const Color(0xFF022E2A),
            ),
          ),
        ),
      ),
    );
  }

  Widget textField(TextEditingController controller, String label) => Padding(
    padding: const EdgeInsets.only(bottom: 10),
    child: TextField(
      controller: controller,
      textAlign: AppTr.alignEnd,
      decoration: _propertyInputDecorationShared(label),
    ),
  );

  final proceed = await showModalBottomSheet<bool>(
    context: context,
    isScrollControlled: true,
    backgroundColor: AppTheme.page,
    shape: const RoundedRectangleBorder(
      borderRadius: BorderRadius.vertical(top: Radius.circular(AppTheme.rCard)),
    ),
    builder: (sheetContext) => Directionality(
      textDirection: AppTr.uiDir,
      child: StatefulBuilder(
        builder: (sheetContext, setSheet) {
          final picked = action;
          return Padding(
            padding: EdgeInsets.only(
              bottom: MediaQuery.of(sheetContext).viewInsets.bottom,
            ),
            child: DraggableScrollableSheet(
              expand: false,
              initialChildSize: 0.75,
              maxChildSize: 0.95,
              builder: (context, controller) => ListView(
                controller: controller,
                padding: const EdgeInsets.fromLTRB(16, 14, 16, 24),
                children: [
                  Row(
                    textDirection: AppTr.uiDir,
                    children: [
                      const Icon(
                        Icons.request_quote_outlined,
                        size: 20,
                        color: _kPropertyColor,
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: Text(
                          'شيك $oldNumber',
                          style: const TextStyle(
                            fontSize: 15,
                            fontWeight: FontWeight.w900,
                            color: Color(0xFF022E2A),
                          ),
                        ),
                      ),
                      Container(
                        padding: const EdgeInsets.symmetric(
                          horizontal: 9,
                          vertical: 5,
                        ),
                        decoration: BoxDecoration(
                          color: chequeStateColor(state).withValues(
                            alpha: 0.12,
                          ),
                          borderRadius: BorderRadius.circular(999),
                        ),
                        child: Text(
                          chequeStateLabel(state),
                          style: TextStyle(
                            fontSize: 11,
                            fontWeight: FontWeight.w900,
                            color: chequeStateColor(state),
                          ),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 10),
                  Container(
                    padding: const EdgeInsets.all(12),
                    decoration: BoxDecoration(
                      color: Colors.white,
                      borderRadius: BorderRadius.circular(AppTheme.rInner),
                      border: Border.all(color: AppTheme.hairline),
                    ),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        for (final (label, value) in [
                          ('المستفيد', holder.isEmpty ? '—' : holder),
                          ('الدفعة', show(LeaseContractData.kPaymentFee)),
                          ('المبلغ', chequeAmount),
                          (
                            'تاريخ الشيك',
                            show(LeaseContractData.kPaymentChequeDate),
                          ),
                          (
                            'تاريخ الاستحقاق',
                            show(LeaseContractData.kPaymentDue),
                          ),
                          ('البنك', show(LeaseContractData.kPaymentBank)),
                        ])
                          Padding(
                            padding: const EdgeInsets.symmetric(vertical: 3),
                            child: Row(
                              textDirection: AppTr.uiDir,
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                SizedBox(
                                  width: 104,
                                  child: Text(
                                    label,
                                    style: const TextStyle(
                                      fontSize: 11,
                                      fontWeight: FontWeight.w700,
                                      color: Color(0xFF5C6B68),
                                    ),
                                  ),
                                ),
                                Expanded(
                                  child: Text(
                                    value,
                                    style: const TextStyle(
                                      fontSize: 12,
                                      fontWeight: FontWeight.w900,
                                      color: Color(0xFF022E2A),
                                    ),
                                  ),
                                ),
                              ],
                            ),
                          ),
                      ],
                    ),
                  ),
                  const SizedBox(height: 14),
                  // «الإجراء» وبجانبه سهم: الإجراءات خيارات داخل القائمة، لا
                  // قائمة طويلة تحت النافذة.
                  if (actions.isEmpty)
                    Text(
                      state == LeaseContractData.chequeReplaced
                          ? 'استُبدل هذا الشيك — الإجراءات على الشيك البديل.'
                          : 'حُصِّل مبلغ هذا الشيك — لا إجراء عليه بعد اليوم.',
                      style: const TextStyle(
                        fontSize: 11.5,
                        height: 1.6,
                        fontWeight: FontWeight.w700,
                        color: Color(0xFF5C6B68),
                      ),
                    )
                  else
                    Row(
                      textDirection: AppTr.uiDir,
                      children: [
                        const Text(
                          'الإجراء',
                          style: TextStyle(
                            fontSize: 13,
                            fontWeight: FontWeight.w900,
                            color: Color(0xFF022E2A),
                          ),
                        ),
                        const SizedBox(width: 12),
                        Expanded(
                          child: DropdownButtonFormField<String>(
                            initialValue: picked,
                            isExpanded: true,
                            hint: const Text(
                              'اختر الإجراء',
                              style: TextStyle(fontSize: 12.5),
                            ),
                            decoration: _propertyInputDecorationShared(''),
                            items: [
                              for (final option in actions)
                                DropdownMenuItem(
                                  value: option,
                                  child: Text(
                                    chequeStateLabel(option),
                                    style: TextStyle(
                                      fontSize: 12.5,
                                      fontWeight: FontWeight.w800,
                                      color: option == _chqActCancel ||
                                              option == _chqActRejected ||
                                              option == _chqActReturned
                                          ? AppTheme.danger
                                          : const Color(0xFF022E2A),
                                    ),
                                  ),
                                ),
                            ],
                            onChanged: (value) => setSheet(() {
                              action = value;
                              error = '';
                            }),
                          ),
                        ),
                      ],
                    ),
                  if (picked != null) ...[
                    const SizedBox(height: 12),
                    // حقول الإجراء المختار.
                    if (picked == _chqActReplace) ...[
                      textField(numberCtrl, 'رقم الشيك البديل'),
                      dateField(
                        sheetContext,
                        'تاريخ الشيك البديل',
                        newChequeDate,
                        (value) => setSheet(() => newChequeDate = value),
                      ),
                      textField(bankCtrl, 'بنك الشيك البديل'),
                    ],
                    if (picked == _chqActNumber)
                      textField(numberCtrl, 'رقم الشيك الجديد'),
                    if (picked == _chqActDate)
                      dateField(
                        sheetContext,
                        'تاريخ الشيك الجديد',
                        newChequeDate,
                        (value) => setSheet(() => newChequeDate = value),
                      ),
                    if (_chequeActionDateLabel(picked).isNotEmpty)
                      dateField(
                        sheetContext,
                        _chequeActionDateLabel(picked),
                        actionDate,
                        (value) => setSheet(() => actionDate = value),
                      ),
                    if (picked == _chqActCancel ||
                        picked == _chqActRejected ||
                        picked == _chqActReturned)
                      textField(reasonCtrl, 'السبب (اختياري)'),
                    if (error.isNotEmpty) ...[
                      Text(
                        error,
                        style: const TextStyle(
                          fontSize: 11.5,
                          height: 1.6,
                          fontWeight: FontWeight.w800,
                          color: AppTheme.danger,
                        ),
                      ),
                      const SizedBox(height: 8),
                    ],
                    FilledButton(
                      onPressed: () {
                        final number = numberCtrl.text.trim();
                        if ((picked == _chqActReplace ||
                                picked == _chqActNumber) &&
                            number.isEmpty) {
                          setSheet(() => error = 'اكتب رقم الشيك.');
                          return;
                        }
                        if (picked == _chqActNumber && number == oldNumber) {
                          setSheet(
                            () => error = 'الرقم الجديد هو نفس الرقم الحالي.',
                          );
                          return;
                        }
                        if ((picked == _chqActReplace ||
                                picked == _chqActDate) &&
                            newChequeDate == null) {
                          setSheet(() => error = 'اختر تاريخ الشيك.');
                          return;
                        }
                        Navigator.of(sheetContext).pop(true);
                      },
                      style: FilledButton.styleFrom(
                        backgroundColor: _kPropertyColor,
                        minimumSize: const Size.fromHeight(48),
                      ),
                      child: const Text('متابعة'),
                    ),
                  ],
                  if (log.isNotEmpty) ...[
                    const SizedBox(height: 16),
                    const Text(
                      'سجل الشيك',
                      style: TextStyle(
                        fontSize: 12.5,
                        fontWeight: FontWeight.w900,
                        color: Color(0xFF022E2A),
                      ),
                    ),
                    const SizedBox(height: 6),
                    Text(
                      log,
                      style: const TextStyle(
                        fontSize: 11.5,
                        height: 1.8,
                        fontWeight: FontWeight.w600,
                        color: Color(0xFF46534F),
                      ),
                    ),
                  ],
                ],
              ),
            ),
          );
        },
      ),
    ),
  );

  final chosen = action;
  final number = numberCtrl.text.trim();
  final bank = bankCtrl.text.trim();
  final reason = reasonCtrl.text.trim();
  Future.delayed(const Duration(milliseconds: 600), () {
    numberCtrl.dispose();
    bankCtrl.dispose();
    reasonCtrl.dispose();
  });
  if (proceed != true || chosen == null || !context.mounted) return false;

  // تأكيد يقول ما سيحدث بالضبط قبل أن يحدث.
  final when = formatDayMonthYear(actionDate);
  final amount = chequeAmount;
  final fee = show(LeaseContractData.kPaymentFee);
  final message = switch (chosen) {
    _chqActReceived =>
      'سيُسجَّل أن الشيك $oldNumber استُلم بتاريخ $when، وتصبح حالته '
          '«${LeaseContractData.chequeReceived}».',
    _chqActBank =>
      'سيُسجَّل أن الشيك $oldNumber أُرسل إلى البنك بتاريخ $when، وتصبح '
          'حالته «${LeaseContractData.chequeAtBank}». تبقى الدفعة مستحقة حتى '
          'يُستلم المبلغ.',
    _chqActCleared =>
      'سيُسجَّل أن مبلغ الشيك $oldNumber ($amount) وصل بتاريخ $when، '
          'وتُسدَّد الدفعة «$fee» بكامل قيمتها، وتصبح حالة الشيك '
          '«${LeaseContractData.chequeCleared}».',
    _chqActRejected =>
      'سيُسجَّل أن البنك رفض الشيك $oldNumber بتاريخ $when. تبقى الدفعة '
          '«$fee» مستحقة، ويمكن بعدها إعادة إرساله أو استبداله.',
    _chqActReturned =>
      'سيُسجَّل أن الشيك $oldNumber أُرجع (مرتجع) بتاريخ $when. تبقى الدفعة '
          '«$fee» مستحقة، ويمكن بعدها إعادة إرساله أو استبداله.',
    _chqActCancel =>
      'سيُلغى الشيك $oldNumber بتاريخ $when، وتبقى الدفعة «$fee» مستحقة '
          'حتى تُسدَّد بطريقة أخرى. يمكن إعادة نشاطه إن كان الإلغاء خطأ.',
    _chqActReactivate =>
      'سيعود الشيك $oldNumber نشطًا بتاريخ $when بحالة '
          '«${LeaseContractData.chequeReceived}».',
    _chqActReplace =>
      'سيُستبدل الشيك $oldNumber بالشيك $number بتاريخ شيك '
          '${formatDayMonthYear(newChequeDate!)}، استُلم في $when. يحلّ '
          'البديل محلّه على الدفعة «$fee» نفسها.',
    _chqActNumber => 'سيتغيّر رقم الشيك من $oldNumber إلى $number.',
    _chqActDate =>
      'سيتغيّر تاريخ الشيك من '
          '${oldChequeDate == null ? '—' : formatDayMonthYear(oldChequeDate)}'
          ' إلى ${formatDayMonthYear(newChequeDate!)}.',
    _ => '',
  };
  final danger = chosen == _chqActCancel ||
      chosen == _chqActRejected ||
      chosen == _chqActReturned;
  final ok = await confirmAction(
    context,
    title: 'تأكيد: $chosen',
    message: message,
    confirmLabel: 'تأكيد',
    danger: danger,
  );
  if (!ok || !context.mounted) return false;

  // نسخة حديثة من العقد: ما عُرض قد يكون أقدم مما في الخادم.
  final fresh =
      (await repository.fetchUnitContracts(contract.assetId)).firstWhere(
        (c) => c.id == contract.id,
        orElse: () => contract,
      );
  final lease = LeaseContractData.decode(fresh.notes);
  final target = _findChequeRow(lease, row);
  if (target == null) {
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('تعذّر العثور على الشيك في العقد — أعد فتح الصفحة'),
          behavior: SnackBarBehavior.floating,
        ),
      );
    }
    return false;
  }

  String entry;
  switch (chosen) {
    case _chqActReceived:
      target[LeaseContractData.kChequeState] = LeaseContractData.chequeReceived;
      entry = 'استُلم الشيك';
    case _chqActBank:
      target[LeaseContractData.kChequeState] = LeaseContractData.chequeAtBank;
      entry = 'أُرسل إلى البنك';
    case _chqActCleared:
      target[LeaseContractData.kChequeState] = LeaseContractData.chequeCleared;
      target[LeaseContractData.kPaymentStatus] = 'مسددة';
      entry = 'استُلم مبلغ الشيك';
    case _chqActRejected:
      target[LeaseContractData.kChequeState] =
          LeaseContractData.chequeRejected;
      entry = 'رفضه البنك${reason.isEmpty ? '' : ' ($reason)'}';
    case _chqActReturned:
      target[LeaseContractData.kChequeState] =
          LeaseContractData.chequeReturned;
      entry = 'أُرجع الشيك (مرتجع)${reason.isEmpty ? '' : ' ($reason)'}';
    case _chqActCancel:
      target[LeaseContractData.kChequeState] =
          LeaseContractData.chequeCancelled;
      entry = 'أُلغي الشيك${reason.isEmpty ? '' : ' ($reason)'}';
    case _chqActReactivate:
      target[LeaseContractData.kChequeState] = LeaseContractData.chequeReceived;
      entry = 'أُعيد نشاط الشيك';
    case _chqActNumber:
      target[LeaseContractData.kPaymentCheque] = number;
      entry = 'تبديل الرقم من $oldNumber إلى $number';
    case _chqActDate:
      target[LeaseContractData.kPaymentChequeDate] = _isoDay(newChequeDate!);
      entry = 'تبديل التاريخ إلى ${formatDayMonthYear(newChequeDate!)}';
    case _chqActReplace:
      target[LeaseContractData.kPaymentCheque] = number;
      target[LeaseContractData.kPaymentChequeDate] = _isoDay(newChequeDate!);
      if (bank.isNotEmpty) target[LeaseContractData.kPaymentBank] = bank;
      target[LeaseContractData.kChequeState] = LeaseContractData.chequeReceived;
      entry = 'استُبدل الشيك $oldNumber بالشيك $number';
    default:
      return false;
  }
  // السجل يُحفظ داخل سطر الدفعة ويُعرض أسفل نافذة الإجراء.
  final previousLog = (target[LeaseContractData.kChequeLog] ?? '').trim();
  target[LeaseContractData.kChequeLog] = [
    if (previousLog.isNotEmpty) previousLog,
    '$when — $entry',
  ].join('\n');

  try {
    final saved = await repository.upsertUnitContract(
      fresh.copyWith(notes: lease.encode()),
    );
    // الرقم والتاريخ الجديدان يصلان إلى سجل الدفعة.
    await syncLeasePaymentRecords(repository: repository, contract: saved);
    if (chosen == _chqActCleared) {
      // المبلغ وصل: الدفعة المرتبطة تُسدَّد بكامل قيمتها، بتاريخ وصوله.
      final rid = (target[LeaseContractData.kRowId] ?? '').trim();
      final payments = await repository.fetchUnitPayments(saved.id!);
      for (final payment in payments) {
        final extra = decodePayExtra(payment.notes);
        if (rid.isEmpty || (extra[kPayRowId] ?? '') != rid) continue;
        await repository.upsertUnitPayment(
          payment.copyWith(
            amountPaid: payment.amountDue,
            paidAt: actionDate,
            status: PropertyUnitPaymentRecord.statusPaid,
            notes: encodePayExtra(<String, String>{
              ...extra,
              kPayMethod: 'شيك',
              kPayCheque: target[LeaseContractData.kPaymentCheque] ?? '',
            }),
          ),
        );
      }
    }
  } catch (error) {
    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('تعذّر حفظ إجراء الشيك: $error'),
          duration: const Duration(seconds: 8),
          behavior: SnackBarBehavior.floating,
        ),
      );
    }
    return false;
  }
  if (context.mounted) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('تم تحويل المعاملة إلى «$chosen»'),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }
  return true;
}

/// «طباعة / مشاركة» العقد كامل: نموذج العقد المعتمد (PDF) في معاينة
/// الطباعة، ومنها الطباعة أو المشاركة كملف PDF — على أندرويد والآيفون.
/// العقد القديم بلا بيانات تفصيلية يُشارك نصًّا كما كان.
Future<void> printOrShareLeaseContract(
  BuildContext context, {
  required PropertyUnitContractRecord contract,
  required String text,
  required String fileName,
  bool activity = false,
  Map<String, String> assetMeta = const <String, String>{},
}) async {
  final lease = LeaseContractData.decode(contract.notes);
  if (lease.isEmpty) {
    await Share.share(text);
    return;
  }
  final title = activity
      ? 'عقد إيجار النشاط التجاري'
      : (lease.isInvestor ? 'عقد مستثمر' : 'عقد الإيجار');
  final clean = fileName.replaceAll(RegExp(r'[\\/:*?"<>|\n\r]+'), '-').trim();
  await Navigator.of(context).push(
    MaterialPageRoute<void>(
      builder: (_) => TemplatePrintScreen(
        title: title,
        fileName: clean.isEmpty ? title : clean,
        buildPdf: (format) => buildLeasePdf(
          lease,
          format,
          title: title,
          activity: activity,
          assetMeta: assetMeta,
        ),
      ),
    ),
  );
}

/// رقم العقد كما يُعرض: المكتوب في العقد، وإلا رقم مشتق من معرّفه.
/// «تحميل» العقد كامل: ملف PDF بالعقد يُفتح له نافذة النظام فيُحفظ في
/// الملفات/التنزيلات أو يُرسل. كان يُكتب ملفًا نصيًّا داخل مساحة التطبيق
/// الخاصة فلا يجده المستخدم، ورسالة التأكيد تختفي خلف النافذة.
Future<void> downloadLeaseContract(
  BuildContext context, {
  required PropertyUnitContractRecord contract,
  required String text,
  required String fileName,
  bool activity = false,
  Map<String, String> assetMeta = const <String, String>{},
}) async {
  final clean = fileName.replaceAll(RegExp(r'[\\/:*?"<>|\n\r]+'), '-').trim();
  final name = clean.isEmpty ? 'عقد' : clean;
  try {
    final lease = LeaseContractData.decode(contract.notes);
    if (!lease.isEmpty) {
      final bytes = await buildLeasePdf(
        lease,
        PdfPageFormat.a4,
        title: activity
            ? 'عقد إيجار النشاط التجاري'
            : (lease.isInvestor ? 'عقد مستثمر' : 'عقد الإيجار'),
        activity: activity,
        assetMeta: assetMeta,
      );
      await Printing.sharePdf(bytes: bytes, filename: '$name.pdf');
      return;
    }
    // عقد قديم بلا بيانات تفصيلية: نصّه ملفًا يُحفظ أو يُرسل.
    final path = await DocumentStore.saveText('$name.txt', text);
    if (path != null) {
      await SharePlus.instance.share(ShareParams(files: [XFile(path)]));
      return;
    }
  } catch (_) {
    // يُبلَّغ أدناه.
  }
  if (!context.mounted) return;
  ScaffoldMessenger.of(context).showSnackBar(
    const SnackBar(
      content: Text('تعذّر تحميل العقد'),
      behavior: SnackBarBehavior.floating,
    ),
  );
}

String leaseContractNumber(PropertyUnitContractRecord contract) {
  final written = (LeaseContractData.decode(contract.notes)
              .contract[LeaseContractData.kNewNo] ??
          '')
      .trim();
  if (written.isNotEmpty) return written;
  final id = contract.id;
  if (id == null) return '';
  final digitsOnly = id.replaceAll(RegExp('[^0-9]'), '');
  final source = digitsOnly.isEmpty ? id.replaceAll('-', '') : digitsOnly;
  return source.length <= 11 ? source : source.substring(0, 11);
}

int chequeActiveFilterCount(Map<String, String> filters) =>
    filters.values.where((v) => v.trim().isNotEmpty).length;

/// هل يطابق الشيك الفلاتر والبحث السريع؟
bool chequeRowMatches(
  Map<String, String> filters,
  String query,
  Map<String, String> row, {
  required String personName,
  required String contractNo,
}) {
  bool has(String key) => (filters[key] ?? '').trim().isNotEmpty;
  String f(String key) => (filters[key] ?? '').trim();

  if (has(_kChqPerson) &&
      !personName.contains(f(_kChqPerson)) &&
      !(row[LeaseContractData.kPaymentBank] ?? '').contains(f(_kChqPerson))) {
    return false;
  }
  if (has(_kChqNo) &&
      !(row[LeaseContractData.kPaymentCheque] ?? '').contains(f(_kChqNo))) {
    return false;
  }
  if (has(_kChqContract) && !contractNo.contains(f(_kChqContract))) {
    return false;
  }
  final chequeDate = DateTime.tryParse(
    (row[LeaseContractData.kPaymentChequeDate] ?? '').trim(),
  );
  if (has(_kChqFrom)) {
    final from = DateTime.tryParse(f(_kChqFrom));
    if (from != null && (chequeDate == null || chequeDate.isBefore(from))) {
      return false;
    }
  }
  if (has(_kChqTo)) {
    final to = DateTime.tryParse(f(_kChqTo));
    if (to != null && (chequeDate == null || chequeDate.isAfter(to))) {
      return false;
    }
  }
  if (has(_kChqCollect)) {
    final due = (row[LeaseContractData.kPaymentDue] ?? '').trim();
    if (!due.startsWith(f(_kChqCollect))) return false;
  }
  final quick = query.trim();
  if (quick.isNotEmpty) {
    final haystack = <String>[
      personName,
      contractNo,
      row[LeaseContractData.kPaymentCheque] ?? '',
      row[LeaseContractData.kPaymentBank] ?? '',
      row[LeaseContractData.kPaymentAmount] ?? '',
      row[LeaseContractData.kPaymentStatus] ?? '',
      row[LeaseContractData.kChequeState] ?? '',
      row[LeaseContractData.kPaymentChequeDate] ?? '',
      row[LeaseContractData.kPaymentDue] ?? '',
      row[LeaseContractData.kPaymentFee] ?? '',
    ].join(' ');
    if (!haystack.contains(quick)) return false;
  }
  return true;
}

/// حقل داخل نافذة الفلاتر — نصي أو تاريخ.
Widget _chequeFilterFieldBox(
  BuildContext sheetContext,
  String label,
  String value,
  ValueChanged<String> onChanged, {
  bool isDate = false,
}) {
  return Column(
    crossAxisAlignment: CrossAxisAlignment.stretch,
    children: [
      Text(
        label,
        textAlign: AppTr.alignEnd,
        style: const TextStyle(
          fontSize: 11,
          fontWeight: FontWeight.w900,
          color: Color(0xFF46534F),
        ),
      ),
      const SizedBox(height: 5),
      if (isDate)
        InkWell(
          onTap: () async {
            final picked = await showDatePicker(
              context: sheetContext,
              initialDate: DateTime.tryParse(value) ?? DateTime.now(),
              firstDate: DateTime(2015),
              lastDate: DateTime(2100),
            );
            if (picked == null) return;
            onChanged(
              '${picked.year.toString().padLeft(4, '0')}-'
              '${picked.month.toString().padLeft(2, '0')}-'
              '${picked.day.toString().padLeft(2, '0')}',
            );
          },
          borderRadius: BorderRadius.circular(AppTheme.rInner),
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 13),
            decoration: BoxDecoration(
              color: AppTheme.field,
              borderRadius: BorderRadius.circular(AppTheme.rInner),
              border: Border.all(color: AppTheme.line),
            ),
            child: Row(
              textDirection: AppTr.uiDir,
              children: [
                const Icon(
                  Icons.calendar_today_rounded,
                  size: 15,
                  color: _kPropertyColor,
                ),
                const SizedBox(width: 7),
                Expanded(
                  child: Text(
                    value.isEmpty
                        ? 'اختر التاريخ'
                        : (DateTime.tryParse(value) == null
                              ? value
                              : formatDayMonthYear(DateTime.parse(value))),
                    textAlign: AppTr.alignEnd,
                    style: TextStyle(
                      fontSize: 12,
                      fontWeight: FontWeight.w800,
                      color: value.isEmpty
                          ? const Color(0xFFA9B4B1)
                          : const Color(0xFF022E2A),
                    ),
                  ),
                ),
                if (value.isNotEmpty)
                  InkWell(
                    onTap: () => onChanged(''),
                    child: const Icon(
                      Icons.close_rounded,
                      size: 16,
                      color: Color(0xFF8C9A97),
                    ),
                  ),
              ],
            ),
          ),
        )
      else
        TextFormField(
          initialValue: value,
          textAlign: AppTr.alignEnd,
          onChanged: onChanged,
          decoration: _propertyInputDecorationShared(label),
        ),
    ],
  );
}

