String formatDayMonthYear(DateTime date) {
  final day = date.day.toString().padLeft(2, '0');
  final month = date.month.toString().padLeft(2, '0');
  return '$day/$month/${date.year}';
}

/// العدد الفعلي للوحدات المراد توليدها.
///
/// عند تفعيل التسجيل التلقائي وإدخال مدى («من 1 إلى 30») يُحسب العدد من
/// المدى مباشرة فتُنشأ 30 وحدة مرقّمة، وإلا يُؤخذ حقل «العدد» كما هو.
/// يربط العدد بمدى الترقيم: كتابة «2» في العدد تملأ «إلى رقم» تلقائيًا،
/// وتعديل «إلى رقم» يدويًا يُصحّح العدد. كان على المستخدم أن يحسبهما بنفسه.
void _syncCountToRange(_UnitEntryForm form) {
  final quantity = int.tryParse(form.count.text.trim()) ?? 0;
  final first = int.tryParse(form.firstNumber.text.trim()) ?? 1;
  form.lastNumber.text = quantity > 1 ? '${first + quantity - 1}' : '';
}

void _syncRangeToCount(_UnitEntryForm form) {
  final first = int.tryParse(form.firstNumber.text.trim()) ?? 1;
  final last = int.tryParse(form.lastNumber.text.trim()) ?? 0;
  if (last >= first) form.count.text = '${last - first + 1}';
}

int _rangeUnitCount(_UnitEntryForm form) {
  final first = int.tryParse(form.firstNumber.text.trim()) ?? 1;
  final last = int.tryParse(form.lastNumber.text.trim()) ?? 0;
  if (form.quickAdd && last >= first && last > 0) return last - first + 1;
  return int.tryParse(form.count.text.trim()) ?? 0;
}

Map<String, String> _decodePropertyMeta(List<String> logs) {
  for (final line in logs) {
    if (!line.startsWith(_kPropertyMetaPrefix)) continue;
    try {
      final decoded = jsonDecode(line.substring(_kPropertyMetaPrefix.length));
      if (decoded is! Map) continue;
      final out = <String, String>{};
      decoded.forEach((key, value) {
        final text = '${value ?? ''}'.trim();
        if (text.isNotEmpty) out['$key'] = text;
      });
      return out;
    } catch (_) {
      continue;
    }
  }
  return <String, String>{};
}

/// سجل النشاط كما يراه المستخدم: بلا سطر البيانات الرسمية المخفي.
List<String> _stripPropertyMeta(List<String> logs) =>
    logs.where((line) => !line.startsWith(_kPropertyMetaPrefix)).toList();

List<String> _logsWithPropertyMeta(
  Map<String, String> meta,
  List<String> logs,
) {
  final clean = _stripPropertyMeta(logs);
  if (meta.isEmpty) return clean;
  return <String>['$_kPropertyMetaPrefix${jsonEncode(meta)}', ...clean];
}

