                        borderRadius: BorderRadius.circular(12),
                        border: Border.all(
                          color: selected
                              ? _kPropertyColor
                              : const Color(0xFFE4EAE8),
                          width: selected ? 1.6 : 1,
                        ),
                      ),
                      child: Column(
                        mainAxisAlignment: MainAxisAlignment.center,
                        children: [
                          Icon(
                            icon,
                            size: 26,
                            color: selected
                                ? _kPropertyColor
                                : const Color(0xFF5C6B68),
                          ),
                          const SizedBox(height: 8),
                          Padding(
                            padding: const EdgeInsets.symmetric(horizontal: 4),
                            child: AppFitText(
                              label,
                              textAlign: TextAlign.center,
                              alignment: Alignment.center,
                              style: TextStyle(
                                fontSize: 11.5,
                                fontWeight: FontWeight.w800,
                                color: selected
                                    ? _kPropertyColor
                                    : const Color(0xFF0F1F1C),
                              ),
                            ),
                          ),
                        ],
                      ),
                    ),
                  );
                },
              ),
            ),
            Padding(
              padding: const EdgeInsets.fromLTRB(16, 0, 16, 20),
              child: ElevatedButton(
                onPressed: _selected == null
                    ? null
                    : () => Navigator.of(context).pop(_selected),
                style: ElevatedButton.styleFrom(
                  backgroundColor: _kPropertyColor,
                  foregroundColor: Colors.white,
                  disabledBackgroundColor: const Color(0xFFD5DEDB),
                  minimumSize: const Size.fromHeight(50),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(12),
                  ),
                ),
                child: const Text(
                  'التالي',
                  style: TextStyle(fontSize: 15, fontWeight: FontWeight.w800),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
}


/// أنواع الوحدات المنطقية التي يمكن إضافتها داخل كل نوع عقار — شقة لا
/// تحتوي "محل"، واستديو لا يحتوي إلا البسيط، والعمارة تحتوي الجميع.
List<String> _unitTypesForPropertyType(String type) {
  final approved = _kPropertyTypeUnits[type];
  if (approved != null) return approved;
  switch (type) {
    // العمارة والمجمع التجاري: كل أنواع الوحدات واردة.
    case 'عمارة':
      return const [
        _kUnitApartment,
        _kUnitStudio,
        _kUnitFullFloor,
        _kUnitRoom,
        _kUnitOffice,
        _kUnitShop,
        _kUnitShowroom,
        _kUnitMezzanine,
        _kUnitWarehouse,
        _kUnitParking,
      ];
    case 'مجمع سكني':
      return const [
        _kUnitApartment,
        _kUnitStudio,
        _kUnitFullFloor,
        _kUnitRoom,
        _kUnitShop,
        _kUnitWarehouse,
        _kUnitParking,
      ];
    case 'مجمع صناعي':
      return const [
        _kUnitWarehouse,
        _kUnitOffice,
        _kUnitShop,
        _kUnitShowroom,
        _kUnitMezzanine,
        _kUnitParking,
      ];
    case 'مجمع تجاري':
      return const [
        _kUnitShop,
        _kUnitShowroom,
        _kUnitOffice,
        _kUnitFullFloor,
        _kUnitMezzanine,
        _kUnitWarehouse,
        _kUnitParking,
      ];
    // الشقة: الشقة نفسها ودور كامل وغرفة وما يتبعها.
    case 'شقة':
      return const [
        _kUnitApartment,
        _kUnitFullFloor,
        _kUnitRoom,
        _kUnitWarehouse,
        _kUnitParking,
      ];
    case 'دور':
      return const [
        _kUnitFullFloor,
        _kUnitApartment,
        _kUnitStudio,
        _kUnitRoom,
        _kUnitWarehouse,
        _kUnitParking,
      ];
    case 'فيلا':
      return const [
        _kUnitApartment,
        _kUnitStudio,
        _kUnitFullFloor,
        _kUnitRoom,
        _kUnitWarehouse,
        _kUnitParking,
      ];
    // أنواع بسيطة: العقار نفسه هو الوحدة.
    case 'استديو':
      return const [_kUnitStudio];
    case 'غرفة':
      return const [_kUnitRoom];
    case 'محل':
      return const [_kUnitShop];
    case 'معرض':
      return const [_kUnitShowroom];
    case 'مستودع':
      return const [_kUnitWarehouse, _kUnitOffice, _kUnitMezzanine];
    case 'محطة':
      return const [
        _kUnitShop,
        _kUnitOffice,
        _kUnitWarehouse,
        _kUnitParking,
      ];
    // «شاليه» واحد للشاليه والشاليهات: العدد يُكتب من الداخل.
    case 'شاليه':
    case 'شاليهات':
      return const [
        _kUnitStudio,
        _kUnitRoom,
        _kUnitApartment,
        _kUnitParking,
      ];
    case 'أرض':
      return const [_kUnitWarehouse, _kUnitParking];
    default:
      return const [_kUnitRoom, _kUnitWarehouse, _kUnitParking];
  }
}

/// المرافق العامة — قائمة واحدة ثابتة تظهر مع كل أنواع العقارات.
const List<String> _kCommonFacilities = [
  'مواقف سيارات عامة',
  'المصعد',
  'الدرج',
  'المداخل / اللوبي',
  'الممرات',
  'السطح',
  'الحوش / الساحة',
  'غرفة الحارس',
  'غرفة الكهرباء',
  'غرفة الاتصالات',
  'غرفة المياه والمضخات',
  'خزانات المياه',
  'غرفة النفايات',
  'النادي الرياضي',
  'المسبح',
  'مستودع تخزين',
  'مكتب إداري',
  'ميزانين',
  'غرفة الخدمات',
  'أخرى',
];

/// تحت عنوان «المرافق العامة» في القوائم الجانبية: ليست وحدات للإيجار.
Widget _facilitiesNotForRentNote() => const Padding(
  padding: EdgeInsets.fromLTRB(10, 0, 10, 4),
  child: Text(
    'ليست للإيجار',
    style: TextStyle(
      fontSize: 9.5,
      fontWeight: FontWeight.w800,
      color: AppTheme.danger,
    ),
  ),
);

/// المرافق العامة لأي نوع عقار — تُعاد القائمة الثابتة نفسها.
List<String> _facilitiesForPropertyType(String type) {
  // ثابتة لكل أنواع العقارات — المرافق العامة لا تتغيّر بتغيّر النوع.
  return _kCommonFacilities;
}

class _AddPropertyStep1Screen extends StatefulWidget {
  const _AddPropertyStep1Screen({required this.propertyType});

  /// نوع العقار المختار في الخطوة السابقة — يظهر أعلى القائمة الجانبية
  /// وتُبنى عليه قوائم الوحدات والمرافق المنطقية.
  final String propertyType;

  @override
  State<_AddPropertyStep1Screen> createState() =>
      _AddPropertyStep1ScreenState();
}

/// شاشة بيانات العقار بشقّين — كما في شاشة إضافة الوحدات داخل التفاصيل:
/// على اليمين نوع العقار ثم "الوحدات" المنطقية له ثم "المرافق العامة"
/// المنطقية له، وعلى اليسار نموذج الإدخال للعنصر المضغوط: بيانات العقار،
/// أو نموذج وحدة (عدد + إعدادات)، أو نموذج مرفق (العدد والملاحظات).
class _AddPropertyStep1ScreenState extends State<_AddPropertyStep1Screen> {
  static const _kEntryData = '__بيانات العقار__';

  String _selectedEntry = _kEntryData;

  final _nameCtrl = TextEditingController();
  final _descriptionCtrl = TextEditingController();
  final _addressCtrl = TextEditingController();
  final _mapLinkCtrl = TextEditingController();

  /// الوحدات المضافة حتى الآن.
  final List<_PropertyUnit> _units = [];

  /// المرافق المضافة (المرفق ← العدد) وملاحظاتها.
  final Map<String, int> _facilityCounts = {};
  final Map<String, String> _facilityNotes = {};

  /// حقول بيانات العقار الرسمية — نفس حقول عقد الإيجار الرسمي، فتُملأ
  /// تلقائيًا عند إنشاء أي عقد لهذا العقار.
  final Map<String, TextEditingController> _officialCtrls = {};

  TextEditingController _officialCtrl(String key) =>
      _officialCtrls.putIfAbsent(key, TextEditingController.new);

  Map<String, String> get _officialMeta {
    final out = <String, String>{};
    _officialCtrls.forEach((key, controller) {
      final value = controller.text.trim();
      if (value.isNotEmpty) out[key] = value;
    });
    return out;
  }

  /// نماذج الإدخال الحيّة لكل عنصر (وحدة أو مرفق) — لا تضيع عند التنقل.
  final Map<String, _UnitEntryForm> _forms = {};

  List<String> get _unitTypes =>
      _unitTypesForPropertyType(widget.propertyType);

  List<String> get _facilities =>
      _facilitiesForPropertyType(widget.propertyType);

  bool get _entryIsFacility => _facilities.contains(_selectedEntry);

  _UnitEntryForm get _form => _forms.putIfAbsent(
    _selectedEntry,
    () => _UnitEntryForm()
      ..firstNumber.text = '${_nextUnitNumber(_units, _selectedEntry)}',
  );

  @override
  void dispose() {
    _nameCtrl.dispose();
    _descriptionCtrl.dispose();
    _addressCtrl.dispose();
    _mapLinkCtrl.dispose();
    for (final controller in _officialCtrls.values) {
      Future.delayed(const Duration(milliseconds: 600), controller.dispose);
    }
    for (final form in _forms.values) {
      form.dispose();
    }
    super.dispose();
  }

  int _intOf(TextEditingController controller) =>
      int.tryParse(controller.text.trim()) ?? 0;

  /// إضافة وحدات النوع المفتوح من نموذجه إلى قائمة العقار.
  Future<void> _commitUnit() async {
    final type = _selectedEntry;
    final form = _form;
    final count = _rangeUnitCount(form);
    if (count <= 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('أدخل العدد أولًا')),
      );
      return;
    }
    final countOnly = type == _kUnitParking || type == _kUnitMezzanine;
    if (!countOnly && form.name.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('اكتب اسم $type — الاسم إلزامي')),
      );
      return;
    }
    final first = int.tryParse(form.firstNumber.text.trim()) ?? 1;
    final baseName = form.name.text.trim().isEmpty
        ? type
        : form.name.text.trim();
    final duplicates = _duplicateUnitNames(_units, type, baseName, first, count);
    if (duplicates.isNotEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            'موجودة مسبقًا: ${duplicates.take(5).join('، ')} — '
            'غيّر رقم البداية (المتاح ${_nextUnitNumber(_units, type)})',
          ),
          behavior: SnackBarBehavior.floating,
        ),
      );
      return;
    }
    final showFull = type == _kUnitFullFloor;
    final residential = _unitTypeIsResidential(type);
    final hasRooms = _unitTypeHasRooms(type);

    final review = <(String, String)>[
      ('النوع', type),
      ('العدد', '$count'),
      if (!countOnly) ('الاسم', baseName),
      if (!countOnly && count > 1)
        ('الترقيم', 'من $first إلى ${first + count - 1}')
      else if (!countOnly)
        ('الرقم', '$first'),
      if (!countOnly && form.area.text.trim().isNotEmpty)
        ('مساحة كل وحدة', '${form.area.text.trim()} متر مربع'),
      if (!countOnly && hasRooms) ('عدد الغرف', '${_intOf(form.rooms)}'),
      if (!countOnly && (hasRooms || showFull))
        ('عدد البلكونات', '${_intOf(form.balconies)}'),
      if (!countOnly && showFull) ('عدد الصالات', '${_intOf(form.halls)}'),
      if (!countOnly && residential)
        ('عدد الحمامات', '${_intOf(form.bathrooms)}'),
      if (!countOnly && residential)
        ('مواقف السيارات الخاصة', '${_intOf(form.parking)}'),
      if (form.notes.text.trim().isNotEmpty)
        ('الملاحظات', form.notes.text.trim()),
    ];
    final confirmed = await _confirmUnitEntry(context, type, review);
    if (!confirmed || !mounted) return;

    setState(() {
      _units.addAll([
        for (var i = 0; i < count; i++)
          _PropertyUnit(
            type: type,
            name: count == 1 ? baseName : '$baseName ${first + i}',
            unitNumber: '${first + i}',
            area: countOnly ? '' : form.area.text.trim(),
            rooms: _unitTypeRoomsFor(type, _intOf(form.rooms)),
            halls: showFull ? _intOf(form.halls) : 0,
            balconies: _intOf(form.balconies),
            bathrooms: _unitTypeIsResidential(type)
                ? _intOf(form.bathrooms)
                : 0,
            parkingCount: _unitTypeIsResidential(type)
                ? _intOf(form.parking)
                : 0,
            hasParking:
                _unitTypeIsResidential(type) && _intOf(form.parking) > 0,
            notes: form.notes.text.trim(),
            extras: _meterExtrasFrom(form.meters, withNumbers: count == 1),
          ),
      ]);
      _forms.remove(type)?.dispose();
      // إغلاق اللوح قبل إتلاف متحكّماته: الحقول تختفي من الشجرة في نفس
      // الإطار، فلا تُبنى على متحكّم متلَف.
      _selectedEntry = _kEntryData;
    });
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('أُضيف $count × $type — المجموع ${_units.length} وحدة'),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  /// نموذج وحدة فيه بيانات لم تُضف بعد بزر «إضافة».
  bool get _unitFormInProgress {
    if (_selectedEntry == _kEntryData || _entryIsFacility) return false;
    final form = _forms[_selectedEntry];
    if (form == null) return false;
    return [
      form.count,
      form.name,
      form.area,
      form.rooms,
      form.halls,
      form.balconies,
      form.bathrooms,
      form.parking,
      form.notes,
    ].any((controller) => controller.text.trim().isNotEmpty);
  }

  /// قبل ترك نموذج وحدة لم تُضف: «اضغط إضافة … أولًا».
  Future<bool> _finishOpenUnit() async {
    if (!_unitFormInProgress) return true;
    final type = _selectedEntry;
    final add = await confirmAction(
      context,
      title: 'لم تُضف $type بعد',
      message:
          'اضغط «إضافة $type» أولًا ليتسنى لك إضافة وحدة أخرى، وتستطيع التعديل في أي وقت.',
      confirmLabel: 'إضافة $type الآن',
      cancelLabel: 'رجوع',
    );
    if (!add || !mounted) return false;
    await _commitUnit();
    return mounted && !_unitFormInProgress;
  }

  Future<void> _selectEntry(String key) async {
    if (key == _selectedEntry) return;
    if (!await _finishOpenUnit()) return;
    if (mounted) setState(() => _selectedEntry = key);
  }

  /// إضافة المرفق المفتوح (العدد + الملاحظات).
  void _commitFacility() {
    final facility = _selectedEntry;
    final form = _form;
    final count = _intOf(form.count);
    if (count <= 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('أدخل العدد أولًا')),
      );
      return;
    }
    setState(() {
      _facilityCounts[facility] = (_facilityCounts[facility] ?? 0) + count;
      final note = form.notes.text.trim();
      if (note.isNotEmpty) _facilityNotes[facility] = note;
      _forms.remove(facility)?.dispose();
      _selectedEntry = _kEntryData;
    });
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text('أُضيف المرفق: $facility'),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  /// مرفق كُتب عدده ولم يُضغط «إضافة»: يُضاف تلقائيًا، فكل مرفق سُجّل
  /// يظهر في «المرافق العامة» بعد الحفظ.
  void _commitPendingFacilities() {
    for (final facility in _facilities) {
      final form = _forms[facility];
      if (form == null) continue;
      final count = _intOf(form.count);
      if (count <= 0) continue;
      _facilityCounts[facility] = (_facilityCounts[facility] ?? 0) + count;
      final note = form.notes.text.trim();
      if (note.isNotEmpty) _facilityNotes[facility] = note;
      _forms.remove(facility)?.dispose();
      if (_selectedEntry == facility) _selectedEntry = _kEntryData;
    }
  }

  void _goNext() async {
    if (!await _finishOpenUnit()) return;
    setState(_commitPendingFacilities);
    // اسم العقار إلزامي.
    if (_nameCtrl.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('أدخل اسم العقار'),
          behavior: SnackBarBehavior.floating,
        ),
      );
      return;
    }
    // المدينة والمنطقة ونوع العين إلزامية.
    final missingMeta = [
      for (final key in _kRequiredPropertyMeta)
        if (_officialCtrl(key).text.trim().isEmpty) key,
    ];
    if (missingMeta.isNotEmpty) {
      setState(() => _selectedEntry = _kEntryData);
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('أكمل الحقول الإلزامية: ${missingMeta.join('، ')}'),
          behavior: SnackBarBehavior.floating,
        ),
      );
      return;
    }
    // لا يُكمَل العقار بلا وحدة واحدة على الأقل.
    if (_units.isEmpty) {
      // بدل شريط سفلي يختفي: يُفتح أول نوع وحدة فورًا، والشرط مكتوب
      // دائمًا فوق الزر في [_buildNextBar].
      if (_unitTypes.isNotEmpty) {
        setState(() => _selectedEntry = _unitTypes.first);
      }
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            _unitTypes.isEmpty
                ? 'لا توجد أنواع وحدات لهذا النوع من العقارات'
                : 'أضف وحدة واحدة على الأقل — فُتح نموذج '
                      '«${_unitTypes.first}» لك',
          ),
          behavior: SnackBarBehavior.floating,
        ),
      );
      return;
    }
    final result = await Navigator.of(context).push<_PropertyDraft>(
      MaterialPageRoute(
        builder: (_) => _PropertyReviewScreen(
          description: _descriptionCtrl.text.trim(),
          // المختار من الخريطة: عنوانه ورابطه. المكتوب بلا اختيار: الرابط
          // رابطًا، واسم المنطقة عنوانًا.
          address: _addressCtrl.text.trim().isNotEmpty
              ? _addressCtrl.text.trim()
              : (_looksLikeLink(_mapLinkCtrl.text)
                    ? ''
                    : _mapLinkCtrl.text.trim()),
          mapLink: _looksLikeLink(_mapLinkCtrl.text)
              ? _mapLinkCtrl.text.trim()
              : '',
          quickAddEnabled: true,
          units: List<_PropertyUnit>.from(_units),
          name: _nameCtrl.text.trim(),
          propertyTypeLabel: widget.propertyType,
          facilities: {..._facilityCounts},
          officialMeta: _officialMeta,
        ),
      ),
    );
    if (result == null || !mounted) return;
    Navigator.of(context).pop(
      _PropertyDraft(
        name: _nameCtrl.text.trim(),
        description: result.description,
        address: result.address,
        mapLink: result.mapLink,
        quickAddEnabled: result.quickAddEnabled,
        units: result.units,
        facilities: {..._facilityCounts},
        facilityNotes: {..._facilityNotes},
        officialMeta: _officialMeta,
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppTheme.page,
      appBar: AppBar(
        toolbarHeight: 60,
        backgroundColor: Colors.white,
        surfaceTintColor: Colors.transparent,
        foregroundColor: const Color(0xFF0F1F1C),
        elevation: 0,
        centerTitle: true,
        title: const Text(
          'إضافة عقار',
          style: TextStyle(
            fontSize: 17,
            fontWeight: FontWeight.w900,
            color: Color(0xFF0F1F1C),
          ),
        ),
        leading: IconButton(
          tooltip: AppTr.tr('رجوع'),
          onPressed: () => Navigator.pop(context),
          icon: const Icon(Icons.arrow_back_ios_new_rounded, size: 20),
        ),
      ),
      body: Directionality(
        textDirection: AppTr.uiDir,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            _buildTopSummaryBar(),
            const Divider(height: 1, thickness: 1, color: Color(0xFFE4EAE8)),
            Expanded(
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  SizedBox(width: 132, child: _buildSidePane()),
                  const VerticalDivider(width: 1, color: Color(0xFFE4EAE8)),
                  Expanded(child: _buildFormPane()),
                ],
              ),
            ),
            _buildNextBar(),
          ],
        ),
      ),
    );
  }

  /// شريط المتابعة الثابت — يُرى من أي لوح، ويقول شرطه قبل الضغط.
  Widget _buildNextBar() {
    final ready = _units.isNotEmpty;
    return Container(
      padding: const EdgeInsets.fromLTRB(14, 10, 14, 12),
      decoration: const BoxDecoration(
        color: Colors.white,
        border: Border(top: BorderSide(color: Color(0xFFE4EAE8))),
      ),
      child: Column(
        mainAxisSize: MainAxisSize.min,
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Text(
            ready
                ? 'المضاف: ${_units.length} وحدة · '
                      '${_facilityCounts.length} مرفق'
                : 'أضف وحدة واحدة على الأقل من القائمة على اليمين، '
                      'ثم تابِع.',
            textAlign: TextAlign.right,
            style: TextStyle(
              fontSize: 11,
              height: 1.5,
              fontWeight: FontWeight.w800,
              color: ready
                  ? const Color(0xFF0E7161)
                  : const Color(0xFFA6691A),
            ),
          ),
          const SizedBox(height: 8),
          ElevatedButton(
            onPressed: _goNext,
            style: ElevatedButton.styleFrom(
              backgroundColor: ready
                  ? _kPropertyColor
                  : const Color(0xFF9BA8A5),
              foregroundColor: Colors.white,
              minimumSize: const Size.fromHeight(48),
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(12),
              ),
            ),
            child: const Text(
              'التالي — مراجعة وحفظ',
              style: TextStyle(fontSize: 15, fontWeight: FontWeight.w800),
            ),
          ),
        ],
      ),
    );
  }

  // ===== المستطيل الثابت أعلى الصفحة: نوع العقار واسم العقار =====

  /// يفتح خرائط جوجل: على الرابط الملصوق إن كان رابطًا، وإلا بحثًا عن
  /// العنوان المكتوب في حقل العنوان.
  /// رابط المكان المختار من الخريطة (فارغ: لم يُختر أو عُدِّل الحقل بعده).
  String _pickedLink = '';

  /// المكتوب رابط لا اسم منطقة؟
  static bool _looksLikeLink(String text) {
    final t = text.trim().toLowerCase();
    return t.startsWith('http') ||
        t.startsWith('www.') ||
        t.contains('maps.') ||
        t.contains('goo.gl') ||
        _parseLatLngFromMapLink(t) != null;
  }

  /// الخريطة داخل التطبيق: يُبحث فيها عن المكتوب (أو يُفتح على الرابط)،
  /// ويُثبَّت الدبوس، ثم «اختيار» يعيد العنوان والرابط والمدينة والمنطقة.
  Future<void> _pickPropertyLocation() async {
    FocusScope.of(context).unfocus();
    final raw = _mapLinkCtrl.text.trim();
    final coords = _parseLatLngFromMapLink(raw);
    final picked = await showLocationPicker(
      context,
      query: _looksLikeLink(raw) ? '' : raw,
      lat: coords?.$1,
      lng: coords?.$2,
    );
    if (picked == null || !mounted) return;
    setState(() {
      _pickedLink = picked.link;
      _mapLinkCtrl.text = picked.link;
      _addressCtrl.text = picked.address.isNotEmpty
          ? picked.address
          : '${picked.lat.toStringAsFixed(6)}, ${picked.lng.toStringAsFixed(6)}';
      // المدينة والمنطقة في «بيانات العقار الرسمية» إن كانتا فارغتين.
      final city = _officialCtrl('المدينة');
      if (city.text.trim().isEmpty && picked.city.isNotEmpty) {
        city.text = picked.city;
      }
      final area = _officialCtrl('المنطقة');
      if (area.text.trim().isEmpty && picked.area.isNotEmpty) {
        area.text = picked.area;
      }
    });
  }

  Future<void> _openMapsForProperty() async {
    final link = _mapLinkCtrl.text.trim();
    final address = _addressCtrl.text.trim();
    Uri? target;
    if (link.isNotEmpty) {
      final normalized = link.startsWith('http') ? link : 'https://$link';
      target = Uri.tryParse(normalized);
    } else if (address.isNotEmpty) {
      target = Uri.parse(
        'https://www.google.com/maps/search/?api=1&query='
        '${Uri.encodeComponent(address)}',
      );
    }
    if (target == null) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('اكتب العنوان أو الصق رابط الخريطة أولًا'),
          behavior: SnackBarBehavior.floating,
        ),
      );
      return;
    }
    final opened = await launchUrl(
      target,
      mode: LaunchMode.externalApplication,
    );
    if (opened || !mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('تعذّر فتح خرائط جوجل'),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

