  // ===== الشقّ الأيمن: نوع العقار ← الوحدات ← المرافق =====

  Widget _buildSidePane() {
    Widget header(String text) => Padding(
      padding: const EdgeInsets.fromLTRB(10, 12, 10, 4),
      child: Text(
        text,
        style: const TextStyle(
          fontSize: 11,
          fontWeight: FontWeight.w900,
          color: AppTheme.muted,
        ),
      ),
    );

    Widget entry({
      required String keyValue,
      required String label,
      required IconData icon,
      int badge = 0,
    }) {
      final selected = _selectedEntry == keyValue;
      return InkWell(
        key: ValueKey('property-entry-$keyValue'),
        onTap: () => _selectEntry(keyValue),
        child: Container(
          color: selected
              ? _kPropertyColor.withValues(alpha: 0.08)
              : Colors.transparent,
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 11),
          child: Row(
            children: [
              Icon(
                icon,
                size: 16,
                color: selected ? _kPropertyColor : AppTheme.muted,
              ),
              const SizedBox(width: 6),
              Expanded(
                child: Text(
                  label,
                  maxLines: 4,
                  style: TextStyle(
                    fontSize: 11,
                    height: 1.25,
                    fontWeight: selected ? FontWeight.w900 : FontWeight.w700,
                    color: selected ? _kPropertyColor : AppTheme.title,
                  ),
                ),
              ),
              if (badge > 0)
                Text(
                  '$badge',
                  style: const TextStyle(
                    fontSize: 10,
                    fontWeight: FontWeight.w900,
                    color: Color(0xFF0E7161),
