  Widget _field(
    String label,
    TextEditingController controller, {
    bool number = true,
    int maxLines = 1,
    String hint = '',
    VoidCallback? onLive,
  }) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: TextField(
        controller: controller,
        keyboardType: number ? TextInputType.number : TextInputType.text,
        maxLines: maxLines,
        textAlign: AppTr.alignEnd,
        // الحقول التي يتوقّف عليها شكل النموذج (العدد والترقيم) تُعيد
        // بناءه مع كل حرف: كتابة «2» في العدد كانت لا تُظهر حقول الترقيم
        // لأن الشاشة لا تُبنى إلا عند حدث آخر.
        onChanged: onLive == null
            ? null
            : (_) => setState(onLive),
        decoration: _propertyInputDecorationShared(label).copyWith(
          hintText: hint.isEmpty ? null : hint,
        ),
      ),
    );
  }

