  Widget _buildUnitForm() {
    final type = _selectedEntry;
    final form = _form;
    // الموقف والميزانين: عدد وملاحظات فقط.
    final countOnly = type == _kUnitParking || type == _kUnitMezzanine;
    final hasRooms = _unitTypeHasRooms(type);
    final residential = _unitTypeIsResidential(type);
    final showFull = type == _kUnitFullFloor;
    final count = _rangeUnitCount(form);
    final first = int.tryParse(form.firstNumber.text.trim()) ?? 1;

    return ListView(
      key: ValueKey('property-unit-form-$type'),
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 28),
      children: [
        Row(
          children: [
            Icon(_unitTypeIcon(type), size: 18, color: _kPropertyColor),
            const SizedBox(width: 7),
            Expanded(
              child: Text(
                'إضافة $type',
                style: const TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w900,
                  color: Color(0xFF022E2A),
                ),
              ),
            ),
          ],
        ),
        const SizedBox(height: 4),
        // شرح حقل العدد قبل ملئه: كان المستخدم يرى حقول ترقيم لا يعرف
        // من أين جاءت ولا لماذا ظهرت.
        Padding(
          padding: const EdgeInsets.only(bottom: 10),
          child: Text(
            'اكتب العدد أولًا. إن كان أكبر من واحد يُفتح لك الترقيم '
            'التلقائي ليضيفها كلها دفعة واحدة، وإن كان واحدًا فلا ترقيم.',
            textAlign: TextAlign.right,
            style: const TextStyle(
              fontSize: 11,
              height: 1.5,
              fontWeight: FontWeight.w600,
              color: Color(0xFF5C6B68),
            ),
          ),
        ),
        _field(
          'العدد',
          form.count,
          onLive: () => _syncCountToRange(form),
        ),
        if (!countOnly) ...[
          // الترتيب: العدد ثم رقم أول ثم إلى رقم، ورا بعض، ثم الاسم.
          if (count > 1) ...[
            _field(
              'رقم أول $type',
              form.firstNumber,
              onLive: () => _syncCountToRange(form),
            ),
            _field(
              'إلى رقم (تسجيل تلقائي)',
              form.lastNumber,
              onLive: () => _syncRangeToCount(form),
            ),
            Padding(
              padding: const EdgeInsets.only(bottom: 10),
              child: Text(
                'الرقم من $first إلى ${first + count - 1} — سيتم تسجيل '
                'الوحدات تلقائيًا، وتستطيع تعديل البيانات بعد عملية الحفظ.',
                textAlign: TextAlign.right,
                style: const TextStyle(
                  fontSize: 11,
                  height: 1.5,
                  fontWeight: FontWeight.w700,
                  color: Color(0xFF5C6B68),
                ),
              ),
            ),
          ] else
            _field(
              'رقم $type',
              form.firstNumber,
              onLive: () => _syncCountToRange(form),
            ),
          _field('اسم $type *', form.name, number: false),
          _field('مساحة كل وحدة (متر مربع)', form.area),
          if (hasRooms) _field('عدد الغرف', form.rooms),
          // البلكونات لكل وحدة سكنية لا للدور الكامل وحده.
          if (hasRooms || showFull) _field('عدد البلكونات', form.balconies),
          if (showFull) _field('عدد الصالات', form.halls),
          if (residential) _field('عدد الحمامات', form.bathrooms),
          if (residential)
            _field('عدد مواقف السيارات الخاصة', form.parking),
        ],
        // عدادات الكهرباء والمياه لكل وحدة (لا للمرافق ولا للمواقف).
        if (type != _kUnitParking) ...[
          ..._meterFieldsFor(form.meters),
          _meterBatchHint(),
        ],
        _field('الملاحظات', form.notes, number: false, maxLines: 3),
        const SizedBox(height: 6),
        FilledButton.icon(
          key: ValueKey('property-unit-commit-$type'),
          onPressed: _commitUnit,
          icon: const Icon(Icons.check_rounded, size: 18),
          label: Text('إضافة $type'),
          style: FilledButton.styleFrom(
            backgroundColor: _kPropertyColor,
            foregroundColor: Colors.white,
            minimumSize: const Size.fromHeight(46),
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(AppTheme.rField),
            ),
          ),
        ),
      ],
    );
  }

