class _StepperMini extends StatelessWidget {
  const _StepperMini({
    required this.label,
    required this.value,
    required this.onChanged,
  });

  final String label;
  final int value;
  final ValueChanged<int> onChanged;

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        Text(
          label,
          style: const TextStyle(
            fontSize: 11,
            fontWeight: FontWeight.w700,
            color: Color(0xFF5C6B68),
          ),
        ),
        const SizedBox(height: 6),
        Row(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            InkWell(
              onTap: () => onChanged(value + 1),
              child: const Icon(
                Icons.add_circle_outline_rounded,
                size: 20,
                color: Color(0xFF0E7161),
              ),
            ),
            SizedBox(
              width: 28,
              child: Text(
                '$value',
                textAlign: TextAlign.center,
                style: const TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w900,
                ),
              ),
            ),
            InkWell(
              onTap: value > 0 ? () => onChanged(value - 1) : null,
              child: Icon(
                Icons.remove_circle_outline_rounded,
                size: 20,
                color: value > 0
                    ? const Color(0xFF5C6B68)
                    : const Color(0xFFD5DEDB),
              ),
            ),
          ],
        ),
      ],
    );
  }
}

class _YesNoToggle extends StatelessWidget {
  const _YesNoToggle({required this.value, required this.onChanged});

  final bool value;
  final ValueChanged<bool> onChanged;

  @override
  Widget build(BuildContext context) {
    Widget option(String label, bool selected, VoidCallback onTap) {
      return InkWell(
        onTap: onTap,
        borderRadius: BorderRadius.circular(8),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),
          decoration: BoxDecoration(
            color: selected ? _kPropertyColor : Colors.white,
            borderRadius: BorderRadius.circular(8),
            border: Border.all(
              color: selected ? _kPropertyColor : const Color(0xFFD5DEDB),
            ),
          ),
          child: Text(
            label,
            style: TextStyle(
              fontSize: 12,
              fontWeight: FontWeight.w800,
              color: selected ? Colors.white : const Color(0xFF5C6B68),
            ),
          ),
        ),
      );
    }

    return Row(
      children: [
        option('نعم', value, () => onChanged(true)),
        const SizedBox(width: 6),
        option('لا', !value, () => onChanged(false)),
      ],
    );
  }
}

