class _PropertyReviewScreen extends StatelessWidget {
  const _PropertyReviewScreen({
    required this.description,
    required this.address,
    required this.mapLink,
    required this.quickAddEnabled,
    required this.units,
    this.name = '',
    this.propertyTypeLabel = '',
    this.facilities = const {},
    this.officialMeta = const {},
  });

  /// اسم العقار كما كُتب، ونوعه المختار، ومرافقه، وبياناته الرسمية —
  /// تُعرض كلها قبل التأكيد.
  final String name;
  final String propertyTypeLabel;
  final Map<String, int> facilities;
  final Map<String, String> officialMeta;

  /// سطر وحدة: الاسم والرقم والمساحة والغرف وغيرها مما أُدخل.
  static String _unitLine(_PropertyUnit u) => [
    u.name,
    if (u.unitNumber.isNotEmpty) 'رقم ${u.unitNumber}',
    if (u.area.isNotEmpty) '${u.area} م²',
    if (u.rooms > 0) '${u.rooms} غرف',
    if (u.halls > 0) '${u.halls} صالات',
    if (u.balconies > 0) '${u.balconies} بلكونات',
    if (u.bathrooms > 0) '${u.bathrooms} حمامات',
    if (u.parkingCount > 0) '${u.parkingCount} مواقف',
    if (u.notes.isNotEmpty) u.notes,
  ].join(' · ');

  final String description;
  final String address;
  final String mapLink;
  final bool quickAddEnabled;
  final List<_PropertyUnit> units;

  String get _propertyType {
    if (propertyTypeLabel.isNotEmpty) return propertyTypeLabel;
    if (units.length > 1) return 'عمارة';
    if (units.length == 1) return units.first.type;
    return _kUnitApartment;
  }

  void _confirm(BuildContext context) {
    final draft = _PropertyDraft(
      description: description,
      address: address,
      mapLink: mapLink,
      quickAddEnabled: quickAddEnabled,
      units: units,
    );
    Navigator.of(context).pop(draft);
  }

  @override
  Widget build(BuildContext context) {
    final apartments = units.where((u) => u.type == _kUnitApartment).length;
    final studios = units.where((u) => u.type == _kUnitStudio).length;
    final shops = units.where((u) => u.type == _kUnitShop).length;
    return Scaffold(
      backgroundColor: AppTheme.page,
      appBar: AppBar(
        toolbarHeight: 60,
        backgroundColor: Colors.white,
        surfaceTintColor: Colors.transparent,
        foregroundColor: const Color(0xFF0F1F1C),
        elevation: 0,
        centerTitle: true,
        title: const Text(
          'مراجعة البيانات',
          style: TextStyle(
            fontSize: 17,
            fontWeight: FontWeight.w900,
            color: Color(0xFF0F1F1C),
          ),
        ),
        leading: IconButton(
          tooltip: AppTr.tr('رجوع'),
          onPressed: () => Navigator.pop(context),
          icon: const Icon(Icons.arrow_back_ios_new_rounded, size: 20),
        ),
      ),
      body: Directionality(
        textDirection: AppTr.uiDir,
        child: ListView(
          padding: const EdgeInsets.fromLTRB(16, 16, 16, 24),
          children: [
            const Text(
              'مراجعة تفاصيل العقار قبل الإرسال',
              textAlign: TextAlign.right,
              style: TextStyle(
                fontSize: 12,
                fontWeight: FontWeight.w700,
                color: Color(0xFF5C6B68),
              ),
            ),
            const SizedBox(height: 12),
            Container(
              padding: const EdgeInsets.all(14),
              decoration: BoxDecoration(
            color: AppTheme.surface,
            borderRadius: BorderRadius.circular(AppTheme.rField),
          ),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Row(
                    textDirection: AppTr.uiDir,
                    children: [
                      Container(
                        width: 44,
                        height: 44,
                        decoration: BoxDecoration(
                          color: _kPropertyColor.withValues(alpha: 0.1),
                          borderRadius: BorderRadius.circular(8),
                        ),
                        child: const Icon(
                          Icons.apartment_rounded,
                          color: _kPropertyColor,
                        ),
                      ),
                      const SizedBox(width: 10),
                      Expanded(
                        child: Text(
                          name.isNotEmpty
                              ? name
                              : (description.isEmpty ? 'بدون اسم' : description),
                          textAlign: TextAlign.right,
                          style: const TextStyle(
                            fontSize: 15,
                            fontWeight: FontWeight.w900,
                          ),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 10),
                  _propertyReviewRow('نوع العقار', _propertyType),
                  _propertyReviewRow(
                    'الموقع',
                    address.isEmpty ? 'غير محدد' : address,
                  ),
                  if (mapLink.isNotEmpty)
                    _propertyReviewRow('رابط الخريطة', mapLink),
                  if (name.isNotEmpty && description.isNotEmpty)
                    _propertyReviewRow('الوصف', description),
                  for (final entry in officialMeta.entries)
                    _propertyReviewRow(
                      LeaseContractData.metaLabel(entry.key),
                      entry.value,
                    ),
                  const SizedBox(height: 6),
                  const Divider(height: 1, color: Color(0xFFF2F6F5)),
                  const SizedBox(height: 10),
                  // كل وحدة بتفاصيلها، مجمّعة حسب النوع.
                  for (final type in {for (final u in units) u.type}) ...[
                    Padding(
                      padding: const EdgeInsets.only(top: 4, bottom: 4),
