  final double? assetLongitude;

  /// بيانات العقار الرسمية — تُملأ تلقائيًا في عقد الإيجار.
  final Map<String, String> propertyMeta;

  /// إنشاء عقد يشمل عدة وحدات — يُنفَّذ في صفحة العقار بعد إغلاق الوحدة.
  final VoidCallback? onCreateMultiUnitContract;

  @override
  State<_UnitDetailsScreen> createState() => _UnitDetailsScreenState();
}

class _UnitDetailsScreenState extends State<_UnitDetailsScreen> {
  /// نسخة حيّة من الوحدة تعكس التعديلات فورًا قبل عودة الشاشة السابقة.
  late _PropertyUnit _unit = widget.unit;
  bool _loading = true;
  String? _error;
  PropertyUnitContractRecord? _contract;
  List<PropertyUnitPaymentRecord> _payments = const [];
  List<PropertyUnitTransactionRecord> _transactions = const [];

  /// تبويب الحركة المالية: 0 الدفعات الإيجارية، 1 دخل إضافي، 2 المصاريف.
  int _financeTab = 0;

  /// -1 يعني أن الصفحة مفتوحة على حالة «اختر إحدى الفئات».
  int _selectedTab = -1;

  /// طيّ عمود الأقسام بعد اختيار قسم لتتوسّع منطقة المحتوى.
  bool _navCollapsed = false;

  static const List<DetailSectionTab> _unitTabs = [
    DetailSectionTab(label: 'ملخص عام', icon: Icons.dashboard_customize_outlined),
    DetailSectionTab(label: 'إدارة الإيجار', icon: Icons.assignment_outlined),
    DetailSectionTab(
      label: 'الحركات المالية',
      icon: Icons.account_balance_wallet_outlined,
    ),
    DetailSectionTab(
      label: 'المتابعة والتخطيط',
      icon: Icons.event_note_outlined,
    ),
    DetailSectionTab(label: 'الصيانة', icon: Icons.build_outlined),
    DetailSectionTab(label: 'المستندات', icon: Icons.folder_copy_outlined),
    DetailSectionTab(
      label: 'الأفراد والجهات',
      icon: Icons.people_alt_outlined,
    ),
    DetailSectionTab(
      label: 'المرافق العامة',
      icon: Icons.chair_alt_outlined,
    ),
    DetailSectionTab(
      label: 'إدارة الشيكات',
      icon: Icons.request_quote_outlined,
    ),
  ];

  // مفاتيح فلاتر إدارة الشيكات.
  static const _kChequePerson = 'person';
  static const _kChequeNo = 'cheque';
  static const _kChequeContract = 'contract';
  static const _kChequeFrom = 'from';
  static const _kChequeTo = 'to';
  static const _kChequeCollect = 'collect';

  /// الفلاتر المطبَّقة فعلًا (لا تتغيّر إلا بالضغط على «ابحث»).
  final Map<String, String> _chequeFilters = <String, String>{};

  /// فلتر حالة الشيك في سطر عنوان «إدارة الشيكات».
  String _unitChequeState = 'الكل';

  /// عند التمرير لأسفل في محتوى القسم يُطوى الصندوق العلوي: يبقى الاسم
  /// والشعار والحالة والثلاث نقاط والموقع، ويختفي البحث وشريط المتابعة.
  bool _compactHeader = false;

  bool _onContentScroll(ScrollNotification notification) {
    if (notification.depth != 0) return false;
    final offset = notification.metrics.pixels;
    final compact = _compactHeader ? offset > 8 : offset > 48;
    if (compact != _compactHeader) setState(() => _compactHeader = compact);
    return false;
  }

  String _chequeQuery = '';

  @override
  void initState() {
    super.initState();
    openPaymentChequeManager = openEntryChequeManager;
    _load();
    _loadUnitPeople();
  }

  Future<void> _load() async {
    final repo = widget.repository;
    final assetId = widget.assetId;
    if (repo == null || assetId == null) {
      setState(() => _loading = false);
      return;
    }
    setState(() {
      _loading = true;
      _error = null;
    });
    try {
      final contracts = await repo.fetchUnitContracts(assetId);
      // العقد الملغى بالتسوية لا يعود عقدًا للوحدة: الوحدة شاغرة للتأجير.
      final mine = contracts
          .where(
            (c) =>
                c.unitKey == _unit.unitKey && c.status != _kContractCancelled,
          )
          .toList();
      var active = mine.isNotEmpty ? mine.first : null;
      List<PropertyUnitPaymentRecord> payments = const [];
      String? syncIssue;
      if (active != null && active.id != null) {
        payments = await repo.fetchUnitPayments(active.id!);
        // عقود كُتبت قبل الربط لها دفعات في نصّها بلا سجلات: تُولَّد هنا
        // مرة واحدة، ثم لا يُكتب شيء ما لم يتغيّر العقد.
        final current = active;
        // الربط والنقل لا يُسقطان الشاشة إن فشلا: العقد والدفعات الحالية
        // تُعرض، والسبب يُقال في شريط سفلي، ويُعاد الربط في التحميل التالي.
        try {
          final wrote = await syncLeasePaymentRecords(
            repository: repo,
            contract: current,
            existing: payments,
          );
          if (wrote) {
            final refreshed = await repo.fetchUnitContracts(assetId);
            final updated = refreshed.firstWhere(
              (c) => c.id == current.id,
              orElse: () => current,
            );
            active = updated;
            payments = await repo.fetchUnitPayments(updated.id!);
          }
          // رسوم وتأمينات سُجِّلت داخل الوحدة قبل التوحيد تُنقل إلى الجدول.
          final contractNow = active;
          if (await _migrateUnitCharges(repo, contractNow, payments)) {
            payments = await repo.fetchUnitPayments(contractNow.id!);
          }
        } catch (error) {
          syncIssue = '$error';
        }
      }
      // تُجلب الحركات المالية في محاولة مستقلة: فشلها (مثلاً لأن جدول
      // property_unit_transactions لم يُنشأ بعد على الخادم) يجب ألا يُسقط
      // شاشة الوحدة كلها ويُخفي بيانات العقد والدفعات السليمة.
      List<PropertyUnitTransactionRecord> transactions = const [];
      try {
        transactions = await repo.fetchUnitTransactions(
          assetId,
          unitKey: _unit.unitKey,
        );
      } catch (_) {
        transactions = const [];
      }
      if (!mounted) return;
      setState(() {
        _contract = active;
        _payments = payments;
        _transactions = transactions;
        _loading = false;
      });
      if (syncIssue != null) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('تعذّر ربط دفعات العقد بالجدول: $syncIssue'),
            duration: const Duration(seconds: 8),
            behavior: SnackBarBehavior.floating,
          ),
        );
      }
    } catch (e) {
      if (!mounted) return;
      setState(() {
        _loading = false;
        _error = 'تعذّر تحميل بيانات الوحدة: $e';
      });
    }
  }

  /// رسوم وتأمينات سُجِّلت داخل الوحدة قبل توحيد الجدول تُنقل إليه مرة
  /// واحدة ثم تُفرَّغ من الوحدة — فلا تُحسب مرتين ولا تضيع.
  ///
  /// آمنة للتكرار: لكل سطر معرّف ثابت، فالمنقول لا يُنقل ثانية لو انقطع
  /// النقل في منتصفه وأُعيد في تحميل لاحق.
  Future<bool> _migrateUnitCharges(
    ProjectAssetsRepository repo,
    PropertyUnitContractRecord contract,
    List<PropertyUnitPaymentRecord> existing,
  ) async {
    final contractId = contract.id;
    if (contractId == null || contractId.isEmpty) return false;
    final known = <String>{
      for (final payment in existing)
        (decodePayExtra(payment.notes)[kPayRowId] ?? '').trim(),
    };
    var wrote = false;
    for (final (store, kind) in [
      (_kUnitFees, kPayKindFee),
      (_kUnitDeposits, kPayKindDeposit),
    ]) {
      final rows = _extraList(store);
      if (rows.isEmpty) continue;
      for (var i = 0; i < rows.length; i++) {
        final row = rows[i];
        final amount = _numOf(row[_kRowAmount]);
        if (amount <= 0) continue;
        final rowId = 'unit-$store-$i';
        if (known.contains(rowId)) continue;
        final paid = _numOf(row[_kRowPaid]).clamp(0, amount).toDouble();
        final item = (row[_kRowItem] ?? '').trim();
        final note = (row[_kRowNote] ?? '').trim();
        await repo.upsertUnitPayment(
          PropertyUnitPaymentRecord(
            contractId: contractId,
            dueDate: DateTime.tryParse((row[_kRowDue] ?? '').trim()),
            amountDue: amount,
            amountPaid: paid,
            paidAt: paid > 0 ? DateTime.now() : null,
            status: payStatusFor(amount, paid),
            notes: encodePayExtra(<String, String>{
              kPayKind: kind,
              kPayName: item.isEmpty ? kind : item,
              kPayRowId: rowId,
              if (note.isNotEmpty) 'ملاحظة': note,
            }),
          ),
        );
        wrote = true;
      }
      if (!mounted) return wrote;
      _saveExtraList(store, const <Map<String, String>>[]);
    }
    return wrote;
  }

  double get _totalDue =>
      _payments.fold<double>(0, (sum, p) => sum + p.amountDue);
  double get _totalPaid =>
      _payments.fold<double>(0, (sum, p) => sum + p.amountPaid);
  double get _totalRemaining => (_totalDue - _totalPaid).clamp(
    0,
    double.infinity,
  );

  bool get _hasOverdue => _payments.any(
    (p) =>
        p.status != PropertyUnitPaymentRecord.statusPaid &&
        p.dueDate != null &&
        p.dueDate!.isBefore(DateTime.now()),
  );

  /// نموذج إضافة/تعديل حركة مالية (إيراد أو مصروف) على هذه الوحدة.
  /// يُحفظ فعليًا في property_unit_transactions مرتبطًا بمفتاح الوحدة.
  Future<void> _openTransactionForm({
    required String kind,
    PropertyUnitTransactionRecord? existing,
  }) async {
    final repo = widget.repository;
    final assetId = widget.assetId;
    if (repo == null || assetId == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('يجب حفظ العقار أولاً قبل تسجيل حركة مالية'),
        ),
      );
      return;
    }
    final income = kind == PropertyUnitTransactionRecord.kindIncome;
    final amountCtrl = TextEditingController(
      text: existing == null || existing.amount == 0
          ? ''
          : existing.amount.toStringAsFixed(2),
    );
    final noteCtrl = TextEditingController(text: _txNoteText(existing?.note));
    var attachment = _txFilePath(existing?.note);
    DateTime? occurredOn = existing?.occurredOn ?? DateTime.now();
    final accent = income ? const Color(0xFF34A894) : const Color(0xFFD95A4E);
    // التصنيف سهم وداخله الخيارات.
    final suggestions = <String>[
      ...(income
          ? const [
              'إيجار',
              'تأمين مسترد',
              'رسوم خدمات',
              'دخل آخر',
              'إيرادات أخرى',
            ]
          : const [
              'صيانة',
              'كهرباء وماء',
              'رسوم حكومية',
              'تنظيف',
              'مصروف آخر',
            ]),
    ];
    String? category = (existing?.category ?? '').trim().isEmpty
        ? null
        : existing!.category!.trim();
    // تصنيف قديم كُتب يدويًا يبقى ظاهرًا ضمن الخيارات.
    if (category != null && !suggestions.contains(category)) {
      suggestions.add(category);
    }

    final saved = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (sheetContext) {
        return Directionality(
          textDirection: AppTr.uiDir,
          child: StatefulBuilder(
            builder: (sheetContext, setSheetState) {
              return Padding(
                padding: EdgeInsets.fromLTRB(
                  18,
                  16,
                  18,
                  MediaQuery.of(sheetContext).viewInsets.bottom + 18,
                ),
                child: SingleChildScrollView(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      Row(
                        children: [
                          Icon(
                            income
                                ? Icons.trending_up_rounded
                                : Icons.trending_down_rounded,
                            color: accent,
                            size: 20,
                          ),
                          const SizedBox(width: 8),
                          Text(
                            existing == null
                                ? (income ? 'إضافة إيراد' : 'إضافة مصروف')
                                : (income ? 'تعديل إيراد' : 'تعديل مصروف'),
                            style: const TextStyle(
                              fontSize: 15,
                              fontWeight: FontWeight.w900,
                              color: Color(0xFF022E2A),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 14),
                      TextField(
                        controller: amountCtrl,
                        textAlign: AppTr.alignEnd,
                        keyboardType: const TextInputType.numberWithOptions(
                          decimal: true,
                        ),
                        decoration: _propertyInputDecorationShared('المبلغ *'),
                      ),
                      const SizedBox(height: 10),
                      OutlinedButton.icon(
                        onPressed: () async {
                          final picked = await showDatePicker(
                            context: sheetContext,
                            initialDate: occurredOn ?? DateTime.now(),
                            firstDate: DateTime(2015),
                            lastDate: DateTime(2060),
                          );
                          if (picked != null) {
                            setSheetState(() => occurredOn = picked);
                          }
                        },
                        icon: const Icon(Icons.event_outlined, size: 18),
                        label: Text(
                          occurredOn == null
                              ? 'تاريخ الحركة'
                              : '${occurredOn!.year}/${occurredOn!.month}/${occurredOn!.day}',
                        ),
                      ),
                      const SizedBox(height: 10),
                      DropdownButtonFormField<String>(
                        initialValue: category,
                        isExpanded: true,
                        decoration: _propertyInputDecorationShared('التصنيف *'),
                        items: [
                          for (final s in suggestions)
                            DropdownMenuItem(
                              value: s,
                              child: Text(
                                s,
                                style: const TextStyle(fontSize: 12.5),
                              ),
                            ),
                        ],
                        onChanged: (value) =>
                            setSheetState(() => category = value),
                      ),
                      const SizedBox(height: 10),
                      TextField(
                        controller: noteCtrl,
                        textAlign: AppTr.alignEnd,
                        maxLines: 2,
                        decoration: _propertyInputDecoration('ملاحظات'),
                      ),
                      const SizedBox(height: 10),
                      // إرفاق مستند: فاتورة أو إيصال.
                      AppRemovableAttachment(
                        attached: attachment.isNotEmpty,
                        onRemove: () => setSheetState(() => attachment = ''),
                        child: OutlinedButton.icon(
                        onPressed: () async {
                          final path = await DocumentStore.pickAndStore(context: context);
                          if (path == null) return;
                          setSheetState(() => attachment = path);
                        },
                        style: OutlinedButton.styleFrom(
                          foregroundColor: accent,
                          minimumSize: const Size.fromHeight(46),
                        ),
                        icon: const Icon(Icons.attach_file_rounded, size: 18),
                        label: Text(
                          attachment.isEmpty
                              ? 'إرفاق مستند'
                              : DocumentStore.fileName(attachment),
                          maxLines: 3,
                        ),
                      ),
                      ),
                      const SizedBox(height: 16),
                      ElevatedButton(
                        style: ElevatedButton.styleFrom(
                          backgroundColor: accent,
                          foregroundColor: Colors.white,
                          padding: const EdgeInsets.symmetric(vertical: 14),
                          shape: RoundedRectangleBorder(
                            borderRadius: BorderRadius.circular(12),
                          ),
                        ),
                        onPressed: () async {
                          final amount = double.tryParse(
                                amountCtrl.text.replaceAll(',', '').trim(),
                              ) ??
                              0;
                          // المبلغ والتصنيف إلزاميان.
                          final missing = [
                            if (amount <= 0) 'المبلغ',
                            if (category == null) 'التصنيف',
                          ];
                          if (missing.isNotEmpty) {
                            await showDialog<void>(
                              context: sheetContext,
                              builder: (dialogContext) => Directionality(
                                textDirection: AppTr.uiDir,
                                child: AlertDialog(
                                  title: const Text('تنبيه'),
                                  content: Text(
                                    'أكمل: ${missing.join('، ')}',
                                    textAlign: TextAlign.right,
                                  ),
                                  actions: [
                                    FilledButton(
                                      onPressed: () =>
                                          Navigator.of(dialogContext).pop(),
                                      child: const Text('حسنًا'),
                                    ),
                                  ],
                                ),
                              ),
                            );
                            return;
                          }
                          if (!sheetContext.mounted) return;
                          // صفحة مراجعة بالمعلومات، ثم «حفظ».
                          final confirmed = await _confirmUnitEntry(
                            sheetContext,
                            income ? 'الإيراد' : 'المصروف',
                            [
                              ('المبلغ', _money(amount)),
                              (
                                'التاريخ',
                                occurredOn == null
                                    ? '—'
                                    : _fmtShortDate(occurredOn),
                              ),
                              ('التصنيف', category!),
                              if (noteCtrl.text.trim().isNotEmpty)
                                ('ملاحظات', noteCtrl.text.trim()),
                              if (attachment.isNotEmpty)
                                (
                                  'المستند المرفق',
                                  DocumentStore.fileName(attachment),
                                ),
                            ],
                            confirmLabel: 'حفظ',
                          );
                          if (!confirmed || !sheetContext.mounted) return;
                          final record = PropertyUnitTransactionRecord(
                            id: existing?.id,
                            assetId: assetId,
                            unitKey: _unit.unitKey,
                            kind: kind,
                            amount: amount,
                            occurredOn: occurredOn,
                            category: category,
                            note: _txEncodeNote(
                              noteCtrl.text.trim(),
                              attachment,
                            ),
                          );
                          try {
                            await repo.upsertUnitTransaction(record);
                            if (!sheetContext.mounted) return;
                            Navigator.of(sheetContext).pop(true);
                          } catch (e) {
                            if (!sheetContext.mounted) return;
                            ScaffoldMessenger.of(sheetContext).showSnackBar(
                              const SnackBar(
                                content: Text('تعذر حفظ الحركة المالية'),
                              ),
                            );
                          }
                        },
                        child: Text(
                          existing == null ? 'حفظ' : 'حفظ التعديل',
                        ),
                      ),
                    ],
                  ),
                ),
              );
            },
          ),
        );
      },
    );
    if (saved == true) {
      await _load();
    }
  }

  Future<void> _deleteTransaction(PropertyUnitTransactionRecord t) async {
    final repo = widget.repository;
    if (repo == null || t.id == null) return;
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: AlertDialog(
          title: const Text('حذف الحركة المالية'),
          content: const Text('سيتم حذف هذه الحركة نهائيًا. هل تريد المتابعة؟'),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(false),
              child: const Text('إلغاء'),
            ),
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(true),
              child: const Text(
                'حذف',
                style: TextStyle(color: Color(0xFFD95A4E)),
              ),
            ),
          ],
        ),
      ),
    );
    if (confirmed != true) return;
    try {
      await repo.deleteUnitTransaction(t.id!);
      await _load();
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('تعذر حذف الحركة المالية')));
    }
  }

  /// اختيار نوع العقد: لهذه الوحدة وحدها أم عقد يشمل عدة وحدات.
  Future<void> _openContractChoice() async {
    // صيانة «تمنع التأجير» مفتوحة: لا عقد حتى تنتهي.
    if (_unitMaintBlocksLease(_unit)) {
      _showMaintBlockNotice(
        context,
        'الوحدة تحت صيانة تمنع التأجير — سجّل «انتهاء الصيانة» من قسم '
        'الصيانة أولًا.',
      );
      return;
    }
    final multi = widget.onCreateMultiUnitContract;
    if (multi == null) {
      await _openFullLeaseContract();
      return;
    }
    final choice = await showModalBottomSheet<String>(
      context: context,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(AppTheme.rCard)),
      ),
      builder: (sheetContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: SafeArea(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              const SizedBox(height: 10),
              const Text(
                'نوع العقد',
                style: TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w900,
                  color: Color(0xFF022E2A),
                ),
              ),
              const SizedBox(height: 6),
              ListTile(
                leading: const Icon(
                  Icons.description_rounded,
                  color: _kPropertyColor,
                ),
                title: const Text('عقد إيجار لهذه الوحدة'),
                subtitle: const Text(
                  'بيانات العقد والعقار والمؤجر والمستأجر والدفعات',
                  style: TextStyle(fontSize: 11),
                ),
                onTap: () => Navigator.of(sheetContext).pop('single'),
              ),
              ListTile(
                leading: const Icon(
                  Icons.layers_rounded,
                  color: _kPropertyColor,
                ),
                title: const Text('عقد متعدد الوحدات'),
                subtitle: const Text(
                  'عقد واحد يشمل هذه الوحدة ووحدات أخرى من العقار',
                  style: TextStyle(fontSize: 11),
                ),
                onTap: () => Navigator.of(sheetContext).pop('multi'),
              ),
              const SizedBox(height: 8),
            ],
          ),
        ),
      ),
    );
    if (choice == 'single') {
      await _openFullLeaseContract();
    } else if (choice == 'multi' && mounted) {
      Navigator.of(context).pop();
      multi();
    }
  }

  /// بيانات العقار لعقد الإيجار، وعدادات هذه الوحدة (عددها وأرقامها) فوق
  /// عدادات العقار إن سُجّلت للوحدة.
  Map<String, String> get _leaseMeta => {
    ...widget.propertyMeta,
    for (final m in _kMeterCountFields) ...{
      if ((_unit.extras[m.$1] ?? '').trim().isNotEmpty) m.$1: _unit.extras[m.$1]!,
      if ((_unit.extras[m.$2] ?? '').trim().isNotEmpty) m.$2: _unit.extras[m.$2]!,
    },
  };

  /// عقد الإيجار الكامل بكل أقسامه الرسمية (العقد، العقار، المؤجر،
  /// المستأجر، ممثل المستأجر، التأمين، ودفعات الإيجار بالشيكات).
  Future<void> _openFullLeaseContract() async {
    final repo = widget.repository;
    final assetId = widget.assetId;
    if (repo == null || assetId == null) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('يجب حفظ العقار أولاً قبل إنشاء عقد')),
      );
      return;
    }
    final saved = await Navigator.of(context).push<PropertyUnitContractRecord>(
      MaterialPageRoute(
        builder: (_) => LeaseContractFormScreen(
          repository: repo,
          assetId: assetId,
          unitKey: _unit.unitKey,
          unitName: _unit.name,
          propertyTitle: widget.assetTitle,
          propertyType: widget.assetType,
          unitType: _unit.type,
          propertyMeta: _leaseMeta,
          existing: _contract,
        ),
      ),
    );
    if (saved == null || !mounted) return;
    setState(() => _contract = saved);
    widget.onUnitStatusChanged(
      saved.status == PropertyUnitContractRecord.statusPending
          ? 'مسودة'
          : 'مؤجرة',
    );
    await _load();
  }


  Future<void> _openPaymentForm({
    PropertyUnitPaymentRecord? existing,
    String? kind,
