                          setSheetState(() => dueDate = picked);
                        }
                      },
                      child: Text(
                        dueDate == null
                            ? 'تاريخ الاستحقاق'
                            : 'تاريخ الاستحقاق: ${_fmtShortDate(dueDate)}',
                      ),
                    ),
                    const SizedBox(height: 10),
                    TextField(
                      controller: dueCtrl,
                      textAlign: AppTr.alignEnd,
                      keyboardType: TextInputType.number,
                      decoration: _propertyInputDecoration('المبلغ المستحق'),
                    ),
                    const SizedBox(height: 10),
                    TextField(
                      controller: paidCtrl,
                      textAlign: AppTr.alignEnd,
                      keyboardType: TextInputType.number,
