                        final paid = _numOf(paidCtrl.text);
                        // بند بلا مستحق كان يُقبل ما دام فيه مسدد — فيدخل
                        // الإجماليات بصفر مستحق ويُحسب «مسددًا» بلا أصل.
                        if (due <= 0) {
                          setSheetState(
                            () => formError =
                                'أدخل المبلغ المستحق — لا يُحفظ بند بلا قيمة.',
                          );
                          return;
                        }
                        if (paid > due + 0.009) {
                          setSheetState(
                            () => formError =
                                'المسدد أكبر من المستحق — راجع المبلغين.',
                          );
                          return;
                        }
                        final status = payStatusFor(due, paid);
                        final record = PropertyUnitPaymentRecord(
                          id: existing?.id,
                          contractId: contract!.id!,
                          dueDate: dueDate,
                          amountDue: due,
                          amountPaid: paid,
                          paidAt: paid > 0
                              ? (existing?.paidAt ?? DateTime.now())
                              : null,
                          status: status,
                          referenceNo: refCtrl.text.trim().isEmpty
                              ? null
                              : refCtrl.text.trim(),
                          notes: encodePayExtra(<String, String>{
                            ...existingExtra,
                            kPayKind: itemKind,
                            kPayName: nameCtrl.text.trim().isEmpty
                                ? itemKind
                                : nameCtrl.text.trim(),
                          }),
                        );
                        try {
                          await repo.upsertUnitPayment(record);
                          if (!sheetContext.mounted) return;
                          Navigator.of(sheetContext).pop(true);
                        } catch (e) {
                          if (!sheetContext.mounted) return;
                          setSheetState(
                            () => formError = 'تعذّر حفظ الدفعة: $e',
                          );
                        }
                      },
                      child: Text(
                        existing == null ? 'حفظ الدفعة' : 'حفظ التعديل',
                      ),
                    ),
                    if (formError.isNotEmpty) ...[
                      const SizedBox(height: 8),
                      Text(
                        formError,
                        textAlign: TextAlign.right,
                        style: const TextStyle(
                          fontSize: 11.5,
                          height: 1.6,
                          fontWeight: FontWeight.w800,
                          color: AppTheme.danger,
                        ),
                      ),
                    ],
                  ],
                ),
              ),
            );
          },
        );
      },
    );
    Future.delayed(const Duration(milliseconds: 600), nameCtrl.dispose);
    if (saved == true) {
      await _load();
    }
  }

  /// أوامر قائمة الثلاث نقاط في رأس الوحدة.
  ///
  /// كلها تعمل على [_unit] وحدها وتُبلَّغ إلى صفحة العقار عبر
  /// [widget.onUnitUpdated] و[widget.onUnitDeleted]، فلا يمسّ أيٌّ منها
  /// بقية الوحدات ولا بيانات البناية.
  Future<void> _onUnitMenuAction(ThreeDotMenuAction action) async {
    switch (action) {
      case ThreeDotMenuAction.edit:
        {
          final edit = widget.onEditInProperty;
          if (edit == null) {
            await _openUnitInfoSheet();
          } else {
            final updated = await edit();
            if (updated != null && mounted) setState(() => _unit = updated);
          }
        }
      case ThreeDotMenuAction.share:
        _shareUnitSummary();
      case ThreeDotMenuAction.archive:
        // لا أرشفة قبل التسوية: وحدة عليها عقد قائم يُلغى عقدها أولًا
        // (نفس «إلغاء العقد»)، والشاغرة تُؤرشف مباشرة بعد التأكيد.
        if (_hasOpenContract) {
          final cancelled = await _cancelContract(confirmed: true);
          if (!cancelled || !mounted) return;
        }
        widget.onUnitUpdated(
          _unit.copyWith(
            status: _kUnitArchived,
            extras: {..._unit.extras, _kArchivedAtKey: _isoToday()},
          ),
        );
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('أُرشفت ${_unit.name} — تجدها في صفحة «الأرشيف»'),
            behavior: SnackBarBehavior.floating,
          ),
        );
        Navigator.of(context).pop();
      case ThreeDotMenuAction.freeze:
        final frozen = _unit.status == 'مجمّدة';
        setState(
          () => _unit = _unit.copyWith(status: frozen ? 'شاغرة' : 'مجمّدة'),
        );
        widget.onUnitUpdated(_unit);
      case ThreeDotMenuAction.pinHome:
        // لا تثبيت للوحدات في الرئيسية: المثبَّت هو العقار.
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('التثبيت في الرئيسية يكون للعقار لا للوحدة'),
            behavior: SnackBarBehavior.floating,
          ),
        );
      case ThreeDotMenuAction.delete:
        // «إلغاء» هو «إلغاء العقد» نفسه: تسوية ثم عقد ملغي ووحدة شاغرة.
        // حذف الوحدة نفسها من الأرشيف فقط.
        if (!_hasOpenContract) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text('الوحدة شاغرة ولا يوجد عقد لإلغائه'),
              behavior: SnackBarBehavior.floating,
            ),
          );
          return;
        }
        await _cancelContract(confirmed: true);
    }
  }

  /// عقد قائم لم يُغلق بعد (ولو مرّ تاريخ نهايته) — يحتاج تسوية قبل
  /// إلغائه أو أرشفة الوحدة.
  bool get _hasOpenContract {
    final contract = _contract;
    return contract != null && !_contractClosed(contract);
  }

  /// ملخّص الوحدة نصًّا — ما يحتاجه من يسأل عنها خارج التطبيق.
  void _shareUnitSummary() {
    final contract = _contract;
    final lines = <String>[
      'بيانات الوحدة',
      'العقار: ${widget.assetTitle}',
      'الوحدة: ${_unit.name}',
      if (_unit.unitNumber.trim().isNotEmpty) 'رقم الوحدة: ${_unit.unitNumber}',
      'النوع: ${_unit.type}',
      if (_unit.area.trim().isNotEmpty) 'المساحة: ${_unit.area} م²',
      'الحالة: ${_unit.status}',
      if (contract != null) 'المستأجر: ${contract.tenantName ?? '—'}',
      if (contract?.endDate != null)
        'انتهاء العقد: ${formatDayMonthYear(contract!.endDate!)}',
      if (_totalRemaining > 0)
        'المتبقي على الوحدة: ${_totalRemaining.toStringAsFixed(0)}',
    ];
    Share.share(lines.join('\n'));
  }

  void _shareFinancialClaim() {
    final contract = _contract;
    if (contract == null) return;
    Share.share(
      'مطالبة مالية\n'
      'العقار: ${widget.assetTitle}\n'
      'الوحدة: ${_unit.name}\n'
      'المستأجر: ${contract.tenantName ?? '—'}\n'
      'الإيجار السنوي: ${contract.annualRent.toStringAsFixed(0)}\n'
      'إجمالي المستحق: ${_totalDue.toStringAsFixed(0)}\n'
      'إجمالي المسدد: ${_totalPaid.toStringAsFixed(0)}\n'
      'المتبقي: ${_totalRemaining.toStringAsFixed(0)}',
    );
  }

  void _shareReceiptVoucher() {
    final contract = _contract;
    if (contract == null || _payments.isEmpty) return;
    final lastPaid = _payments.lastWhere(
      (p) => p.amountPaid > 0,
      orElse: () => _payments.first,
    );
    Share.share(
      'سند قبض\n'
      'العقار: ${widget.assetTitle}\n'
      'الوحدة: ${_unit.name}\n'
      'المستأجر: ${contract.tenantName ?? '—'}\n'
      'المبلغ المسدد: ${lastPaid.amountPaid.toStringAsFixed(0)}\n'
      'المرجع: ${lastPaid.referenceNo ?? '—'}\n'
      'التاريخ: ${lastPaid.paidAt != null ? '${lastPaid.paidAt!.year}/${lastPaid.paidAt!.month}/${lastPaid.paidAt!.day}' : '—'}',
    );
  }


  /// رقم عقد مختصر ومستقر مُشتق من معرّف العقد الفعلي في قاعدة البيانات
  /// (وليس رقمًا وهميًا) — لعرضه بنفس شكل "رقم العقد" في الشاشات المرجعية.
  String _contractNumber(PropertyUnitContractRecord contract) {
    final id = contract.id;
    if (id == null) return '—';
    final digitsOnly = id.replaceAll(RegExp('[^0-9]'), '');
    final source = digitsOnly.isEmpty ? id.replaceAll('-', '') : digitsOnly;
    return source.length <= 11 ? source : source.substring(0, 11);
  }

  String _cycleDetailLabel(PropertyUnitContractRecord contract) {
    final count = _payments.length;
    final cyclePart = switch (contract.paymentCycle) {
      'شهري' => 'كل شهر',
      'ربع سنوي' => 'كل 3 أشهر',
      'نصف سنوي' => 'كل 6 أشهر',
      'سنوي' => 'سنويًا',
      _ => contract.paymentCycle,
    };
    return count == 0 ? cyclePart : '$cyclePart ($count دفعات)';
  }




  /// عدد الدفعات التي تحتاج متابعة في هذه الوحدة (مستحقة أو متأخرة).
  int get _unitDueFollowUpCount => _payments
      .where((payment) {
        final label = rentPaymentStatusLabel(payment);
        return label == 'مستحقة' || label == 'متأخرة';
      })
      .length;

  /// مستندات الوحدة التي تحتاج متابعة: عقد ينتهي خلال 60 يومًا، وشهادة
  /// دفاع مدني غير مسجّلة للمستودعات.
  List<String> get _unitDocsFollowUp {
    final out = <String>[];
    final end = _contract?.endDate;
    if (end != null) {
      final days = end.difference(DateTime.now()).inDays;
      if (days <= 60) {
        out.add(
          days < 0
              ? 'انتهى عقد الإيجار بتاريخ ${_fmtShortDate(end)}'
              : 'عقد الإيجار ينتهي خلال $days يومًا (${_fmtShortDate(end)})',
        );
      }
    }
    if (_unit.type == _kUnitWarehouse &&
        _extra('شهادة الدفاع المدني').isEmpty) {
      out.add('شهادة الدفاع المدني غير مسجّلة');
    }
    return out;
  }

  void _openUnitFollowUpBox() {
    final dues = _payments.where((payment) {
      final label = rentPaymentStatusLabel(payment);
      return label == 'مستحقة' || label == 'متأخرة';
    }).toList(growable: false);
    final docs = _unitDocsFollowUp;
    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(AppTheme.rCard)),
      ),
      builder: (sheetContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: DraggableScrollableSheet(
          expand: false,
          initialChildSize: 0.55,
          maxChildSize: 0.9,
          builder: (context, controller) => ListView(
            controller: controller,
            padding: const EdgeInsets.fromLTRB(16, 14, 16, 24),
            children: [
              const Text(
                'ما يحتاج متابعة في هذه الوحدة',
                textAlign: TextAlign.right,
                style: TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w900,
                  color: Color(0xFF022E2A),
                ),
              ),
              const SizedBox(height: 12),
              Text(
                'مستحقات (${dues.length})',
                textAlign: TextAlign.right,
                style: const TextStyle(
                  fontSize: 12,
                  fontWeight: FontWeight.w900,
                  color: Color(0xFFA6691A),
                ),
              ),
              const SizedBox(height: 6),
              if (dues.isEmpty)
                const Text(
                  'لا توجد مستحقات قريبة.',
                  textAlign: TextAlign.right,
                  style: TextStyle(fontSize: 11, color: Color(0xFF5C6B68)),
                )
              else
                for (var i = 0; i < dues.length; i++)
                  Container(
                    margin: const EdgeInsets.only(bottom: 6),
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: AppTheme.paper,
                      borderRadius: BorderRadius.circular(AppTheme.rInner),
                      border: Border.all(color: AppTheme.hairline),
                    ),
                    child: Text(
                      'الدفعة ${i + 1} · ${_money(dues[i].amountDue)} · '
                      '${rentPaymentStatusLabel(dues[i])} · '
                      'استحقاق ${fmtPayDate(dues[i].dueDate)}',
                      textAlign: TextAlign.right,
                      style: const TextStyle(
                        fontSize: 11,
                        height: 1.5,
                        fontWeight: FontWeight.w700,
                        color: Color(0xFF022E2A),
                      ),
                    ),
                  ),
              const SizedBox(height: 14),
              Text(
                'مستندات (${docs.length})',
                textAlign: TextAlign.right,
                style: const TextStyle(
                  fontSize: 12,
                  fontWeight: FontWeight.w900,
                  color: Color(0xFFA6691A),
                ),
              ),
              const SizedBox(height: 6),
              if (docs.isEmpty)
                const Text(
                  'لا توجد مستندات تحتاج متابعة.',
                  textAlign: TextAlign.right,
                  style: TextStyle(fontSize: 11, color: Color(0xFF5C6B68)),
                )
              else
                for (final doc in docs)
                  Container(
                    margin: const EdgeInsets.only(bottom: 6),
                    padding: const EdgeInsets.all(10),
                    decoration: BoxDecoration(
                      color: AppTheme.paper,
                      borderRadius: BorderRadius.circular(AppTheme.rInner),
                      border: Border.all(color: AppTheme.hairline),
                    ),
                    child: Text(
                      doc,
                      textAlign: TextAlign.right,
                      style: const TextStyle(
                        fontSize: 11,
                        height: 1.5,
                        fontWeight: FontWeight.w700,
                        color: Color(0xFF022E2A),
                      ),
                    ),
                  ),
            ],
          ),
        ),
      ),
    );
  }

  /// «تفويض آخرين» على هذه الوحدة بعينها.
  Future<void> _delegateUnit() async {
    final open = openDelegationForTarget;
    final assetId = widget.assetId;
    if (open == null || assetId == null || assetId.isEmpty) {
      await openDelegationFormForPerson?.call(context, '');
      return;
    }
    final target = DelegationTargets.unit(
      assetId: assetId,
      building: widget.assetTitle,
      name: _unit.name,
      number: _unit.unitNumber,
      type: _unit.type,
    );
    await open(context, sub: target.sub, target: target);
  }

  /// الصندوق الثابت أعلى صفحة الوحدة: الاسم والحالة والعقار ومكان الوحدة،
  /// ومستطيل «مستحقات/مستندات تحتاج متابعة» بسهم يفتحه.
  Widget _unitHeaderCard(bool leased) {
    // عقد محفوظ كمسودة: الوحدة «مسودة» لا «مؤجرة».
    final draft = leased &&
        _contract?.status == PropertyUnitContractRecord.statusPending;
    // حالة الوحدة: شاغرة / مؤجرة / مسودة / منتهي العقد. تأخر الدفعات لا
    // يغيّر حالة الوحدة — يظهر في «مستحقات تحتاج متابعة».
    final endedOpen = leased && !draft && _contractEndedOpen(_contract);
    // صيانة مفتوحة تُضاف إلى الحالة: «مؤجرة / صيانة» أو «شاغرة / صيانة».
    final inMaint = _unitMaintOpen(_unit);
    final statusColor = inMaint
        ? const Color(0xFFC4392E)
        : draft
        ? AppTheme.goldDark
        : endedOpen
        ? const Color(0xFFC4392E)
        : leased
        ? const Color(0xFF0E7161)
        : _kVacantColor;
    final baseLabel = draft
        ? 'مسودة'
        : endedOpen
        ? 'منتهي العقد'
        : leased
        ? 'مؤجرة'
        : 'شاغرة';
    final statusLabel = inMaint ? '$baseLabel / صيانة' : baseLabel;
    final place = _extra('مكان الوحدة');
    // اسم المستأجر من العقد الساري — مقابل الموقع في الجهة اليسرى، فيُعرف
    // من يشغل الوحدة من نظرة دون فتح «إدارة الإيجار».
    final tenant = (_contract?.tenantName ?? '').trim();
    final showTenant =
        leased &&
        tenant.isNotEmpty &&
        tenant != 'مسودة بلا مستأجر' &&
        tenant != 'بلا اسم';
    return Container(
      decoration: BoxDecoration(
        color: AppTheme.surface,
        borderRadius: BorderRadius.circular(AppTheme.rField),
      ),
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 12),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            textDirection: AppTr.uiDir,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Container(
                width: 44,
                height: 44,
                decoration: BoxDecoration(
                  color: _kPropertyColor.withValues(alpha: 0.12),
                  borderRadius: BorderRadius.circular(8),
                ),
                child: Icon(
                  _unitTypeIcon(_unit.type),
                  color: _kPropertyColor,
                ),
              ),
              const SizedBox(width: 11),
              Expanded(
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text(
                      '${AppTr.tr('الاسم')}: ${_unit.name}',
                      textAlign: TextAlign.right,
                      maxLines: 3,
                      style: const TextStyle(
                        fontSize: 15,
                        fontWeight: FontWeight.w900,
                        color: Color(0xFF022E2A),
                      ),
                    ),
                    const SizedBox(height: 3),
                    Text(
                      '${AppTr.tr('النوع')}: ${_unit.type}',
                      textAlign: TextAlign.right,
                      maxLines: 3,
                      style: const TextStyle(
                        fontSize: 11,
                        fontWeight: FontWeight.w800,
                        color: Color(0xFF46534F),
                      ),
                    ),
                  ],
                ),
              ),
              // الحالة، وتحتها نوع الوحدة (دور، شاليه، محل...) ليُعرف من
              // نظرة نوع ما يُجرى عليه.
              Column(
                crossAxisAlignment: CrossAxisAlignment.center,
                children: [
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 8,
                      vertical: 5,
                    ),
                    decoration: BoxDecoration(
                      color: statusColor.withValues(alpha: 0.1),
                      borderRadius: BorderRadius.circular(8),
                    ),
                    child: Text(
                      statusLabel,
                      style: TextStyle(
                        fontSize: 10,
                        fontWeight: FontWeight.w800,
                        color: statusColor,
                      ),
                    ),
                  ),
                  // النوع مكتوب في سطر «الاسم / النوع» فلا يتكرر هنا.
                ],
              ),
              // أوامر الوحدة وحدها — لا العقار. انظر [_onUnitMenuAction].
              // «إلغاء» = إلغاء العقد بالتسوية، والحذف من أرشيف الوحدات.
              ThreeDotMenu(
                tooltip: AppTr.tr('خيارات الوحدة'),
                // العقد المنتهي لا يُعدَّل: يُلغى أو يُجدَّد.
                showEdit: !_contractEndedOpen(_contract),
                freezeLabel: 'تجميد / إلغاء تجميد الوحدة',
                pinLabel: 'تثبيت الوحدة',
                deleteLabel: 'إلغاء',
                deleteIcon: Icons.cancel_outlined,
                deleteMessage: 'سيُلغى عقد الإيجار بعد عمل التسوية، ويصبح '
                    'العقد «ملغي» والوحدة شاغرة. هل تريد المتابعة؟\n\n'
                    'العقد الملغى لا يُحذف: ينتقل إلى «السجل التاريخي» '
                    'وتبقى مستحقاته غير المسوّاة للمتابعة.',
                deleteConfirmLabel: 'إلغاء العقد',
                onAction: _onUnitMenuAction,
                // تفويض شخص على هذه الوحدة وحدها، بصلاحيات تحددها — لصاحب
                // العقار (أو لمفوَّض له منح تفويض فرعي).
                trailingActions: [
                  if (DelegatedAssets.of(widget.assetId) == null ||
                      DelegatedAssets.of(widget.assetId)!.canSubDelegate)
                    ThreeDotExtraAction(
                      label: 'تفويض آخرين',
                      icon: Icons.how_to_reg_outlined,
                      onSelected: _delegateUnit,
                    ),
                ],
                // الأرشفة لصاحب العقار وحده.
                showArchive: !DelegatedAssets.isDelegated(widget.assetId),
              ),
            ],
          ),
          // مكان الوحدة (الطابق الأول مثلًا).
          const SizedBox(height: 6),
          Row(
            textDirection: AppTr.uiDir,
            children: [
              const Icon(
                Icons.location_on_outlined,
                size: 15,
                color: Color(0xFF8C9A97),
              ),
              const SizedBox(width: 5),
              Expanded(
                child: Text(
                  // الوحدة داخل العقار: مكانها مكانه. «مكان الوحدة» القديم
                  // يُقرأ فقط إن لم يكن للعقار موقع.
                  (widget.assetLocation ?? '').trim().isNotEmpty &&
                          widget.assetLocation != 'غير محدد'
                      ? widget.assetLocation!
                      : place.isNotEmpty
                      ? place
                      : 'مكان الوحدة غير محدد',
                  maxLines: 4,
                  textAlign: AppTr.alignEnd,
                  style: const TextStyle(
                    fontSize: 11,
                    height: 1.4,
                    fontWeight: FontWeight.w700,
                    color: Color(0xFF5C6B68),
                  ),
                ),
              ),
              if (showTenant) ...[
                const SizedBox(width: 10),
                // مرن لا ممتد: يأخذ عرض الاسم وحده ويلتصق بالطرف الأيسر،
                // والموقع يملأ ما بقي.
                Flexible(
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    textDirection: AppTr.uiDir,
                    children: [
                      const Icon(
                        Icons.person_outline_rounded,
                        size: 15,
                        color: _kPropertyColor,
                      ),
                      const SizedBox(width: 4),
                      Flexible(
                        child: Text(
                          tenant,
                          maxLines: 4,
                          style: const TextStyle(
                            fontSize: 11,
                            height: 1.4,
                            fontWeight: FontWeight.w900,
                            color: Color(0xFF022E2A),
                          ),
                        ),
                      ),
                    ],
                  ),
                ),
              ],
            ],
          ),
          if (!_compactHeader) ...[
          const SizedBox(height: 10),
          InkWell(
            onTap: _openUnitFollowUpBox,
            borderRadius: BorderRadius.circular(AppTheme.rIcon),
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 8),
              decoration: BoxDecoration(
                color: AppTheme.page,
                borderRadius: BorderRadius.circular(AppTheme.rIcon),
                border: Border.all(color: AppTheme.hairline),
              ),
              child: followUpStripRow(
                requests: 0,
                dues: _unitDueFollowUpCount,
                docs: _unitDocsFollowUp.length,
              ),
            ),
          ),
          ],
        ],
      ),
    );
  }

  /// عدد عناصر القسم المفتوح — يظهر في شريط «الفئات | العناصر».
  int _unitSectionCount() => switch (_selectedTab) {
    // مفاتيح داخلية (تبدأ بـ «__») ليست عناصر يراها المستخدم.
    0 => _unit.extras.keys.where((k) => !k.startsWith('__')).length,
    1 => _contract == null ? 0 : 1 + _payments.length,
    2 => _financeTab == 0
        ? _payments.where(_matchesUnitPaymentFilter).length
        : _transactions
              .where((t) => t.isIncome == (_financeTab == 1))
              .length,
    3 => _unitFollowUpRows().length,
    4 => _maintenanceEntries.length,
    5 => _extraList(_kUnitDocuments).length,
    6 => _unitPeopleRows().length,
    7 => _extraList(_kUnitAssets).length,
    8 => _contract == null
        ? 0
        : LeaseContractData.decode(_contract!.notes).cheques.length,
    9 => _extraList(_kUnitNotes).length,
    _ => 0,
  };

