  /// قائمة عناصر مخزّنة داخل بيانات الوحدة (بلا هجرة قاعدة بيانات).
  List<Map<String, String>> _extraList(String key) {
    final raw = _extra(key);
    if (raw.isEmpty) return const [];
    try {
      final decoded = jsonDecode(raw);
      if (decoded is! List) return const [];
      return decoded
          .whereType<Map>()
          .map(
            (entry) =>
                entry.map((k, value) => MapEntry('$k', '${value ?? ''}')),
          )
          .toList(growable: false);
    } catch (_) {
      return const [];
    }
  }

  void _saveExtraList(String key, List<Map<String, String>> rows) {
    _saveExtras({key: rows.isEmpty ? '' : jsonEncode(rows)});
  }

