  /// فتح مستند محفوظ داخل التطبيق.
  Future<void> _openStoredFile(String path) async {
    final error = await DocumentStore.open(path);
    if (!mounted || error == null) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(error), behavior: SnackBarBehavior.floating),
    );
  }

  /// زر «فتح» يظهر بجانب أي عنصر له ملف مرفق.
  Widget? _openFileButton(String path) {
    if (path.trim().isEmpty) return null;
    return IconButton(
      tooltip: AppTr.tr('فتح المستند'),
      onPressed: () => _openStoredFile(path),
      icon: Icon(
        DocumentStore.existsSync(path)
            ? Icons.open_in_new_rounded
            : Icons.report_gmailerrorred_rounded,
        size: 19,
        color: DocumentStore.existsSync(path)
            ? AppTheme.brandMid
            : AppTheme.danger,
      ),
    );
  }

