  /// نموذج عام لإضافة/تعديل عنصر بحقول نصية بسيطة.
  Future<void> _openUnitItemForm({
    required String title,
    required List<String> fields,
    Map<String, String>? existing,
    List<String> multiline = const [],
    List<String> numeric = const [],
    List<String> dates = const [],
    bool withFile = false,
    required void Function(Map<String, String> row) onSave,
  }) async {
    final ctrls = <String, TextEditingController>{
      for (final field in fields)
        field: TextEditingController(text: existing?[field] ?? ''),
    };
    var filePath = existing?[DocumentStore.kFileField] ?? '';
    final saved = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(AppTheme.rCard),
        ),
      ),
      builder: (sheetContext) => StatefulBuilder(
        builder: (sheetContext, setSheetState) => Directionality(
          textDirection: AppTr.uiDir,
          child: Padding(
            padding: EdgeInsets.fromLTRB(
              16,
              14,
              16,
              MediaQuery.of(sheetContext).viewInsets.bottom + 16,
            ),
            child: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Text(
                    title,
                    textAlign: AppTr.alignEnd,
                    style: const TextStyle(
                      fontSize: 13,
                      fontWeight: FontWeight.w900,
                      color: Color(0xFF022E2A),
                    ),
                  ),
                  const SizedBox(height: 12),
                  for (final field in fields) ...[
                    TextField(
                      controller: ctrls[field],
                      textAlign: AppTr.alignEnd,
                      readOnly: dates.contains(field),
                      maxLines: multiline.contains(field) ? 3 : 1,
                      keyboardType: numeric.contains(field)
                          ? const TextInputType.numberWithOptions(decimal: true)
                          : TextInputType.text,
                      onTap: !dates.contains(field)
                          ? null
                          : () async {
                              final picked = await showDatePicker(
                                context: sheetContext,
                                initialDate: DateTime.now(),
                                firstDate: DateTime(2015),
                                lastDate: DateTime(2100),
                              );
                              if (picked == null) return;
                              setSheetState(() {
                                ctrls[field]!.text = _fmtShortDate(picked);
                              });
                            },
                      // أول خانة هي الاسم/العنوان: إلزامية بنجمة حمراء.
                      decoration: _propertyInputDecorationShared(
                        field == fields.first ? '$field *' : field,
                      ),
                    ),
                    const SizedBox(height: 9),
                  ],
                  if (withFile) ...[
                    Container(
                      padding: const EdgeInsets.all(12),
                      decoration: BoxDecoration(
                        color: AppTheme.paper,
                        borderRadius: BorderRadius.circular(AppTheme.rInner),
                        border: Border.all(color: AppTheme.hairline),
                      ),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.stretch,
                        children: [
                          Row(
                            textDirection: AppTr.uiDir,
                            children: [
                              const Icon(
                                Icons.attach_file_rounded,
                                size: 17,
                                color: _kPropertyColor,
                              ),
                              const SizedBox(width: 7),
                              Expanded(
                                child: Text(
                                  filePath.isEmpty
                                      ? 'لا يوجد ملف مرفق'
                                      : DocumentStore.fileName(filePath),
                                  textAlign: AppTr.alignEnd,
                                  maxLines: 3,
                                  style: TextStyle(
                                    fontSize: 11,
                                    fontWeight: FontWeight.w800,
                                    color: filePath.isEmpty
                                        ? const Color(0xFF8C9A97)
                                        : const Color(0xFF022E2A),
                                  ),
                                ),
                              ),
                            ],
                          ),
                          const SizedBox(height: 9),
                          Row(
                            children: [
                              Expanded(
                                child: AppRemovableAttachment(
                                  attached: filePath.isNotEmpty,
                                  onRemove: () => setSheetState(() => filePath = ''),
                                  child: OutlinedButton.icon(
                                  onPressed: () async {
                                    final stored =
                                        await DocumentStore.pickAndStore(context: context);
                                    if (stored == null) return;
                                    setSheetState(() => filePath = stored);
                                  },
                                  icon: const Icon(
                                    Icons.upload_file_rounded,
                                    size: 17,
                                  ),
                                  label: Text(
                                    filePath.isEmpty
                                        ? 'رفع مستند'
                                        : 'استبدال المستند',
                                  ),
                                ),
                                ),
                              ),
                              if (filePath.isNotEmpty) ...[
                                const SizedBox(width: 8),
                                Expanded(
                                  child: OutlinedButton.icon(
                                    onPressed: () => _openStoredFile(filePath),
                                    icon: const Icon(
                                      Icons.open_in_new_rounded,
                                      size: 17,
                                    ),
                                    label: const Text('فتح'),
                                  ),
                                ),
                              ],
                            ],
                          ),
                        ],
                      ),
                    ),
                    const SizedBox(height: 12),
                  ],
                  const SizedBox(height: 5),
                  FilledButton(
                    onPressed: () async {
                      if (ctrls[fields.first]!.text.trim().isEmpty) {
                        await showDialog<void>(
                          context: sheetContext,
                          builder: (dialogContext) => Directionality(
                            textDirection: AppTr.uiDir,
                            child: AlertDialog(
                              title: const Text('تنبيه'),
                              content: Text(
                                'أكمل: ${fields.first}',
                                textAlign: TextAlign.right,
                              ),
                              actions: [
                                FilledButton(
                                  onPressed: () =>
                                      Navigator.of(dialogContext).pop(),
                                  child: const Text('حسنًا'),
                                ),
                              ],
                            ),
                          ),
                        );
                        return;
                      }
                      if (sheetContext.mounted) {
                        Navigator.of(sheetContext).pop(true);
                      }
                    },
                    style: FilledButton.styleFrom(
                      backgroundColor: _kPropertyColor,
                      foregroundColor: Colors.white,
                      minimumSize: const Size.fromHeight(46),
                    ),
                    child: const Text('حفظ'),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
    final row = <String, String>{
      for (final field in fields) field: ctrls[field]!.text.trim(),
      if (withFile && filePath.isNotEmpty) DocumentStore.kFileField: filePath,
    };
    for (final controller in ctrls.values) {
      Future.delayed(const Duration(milliseconds: 600), controller.dispose);
    }
    if (saved != true) return;
    if (row.values.every((value) => value.isEmpty)) return;
    onSave(row);
  }

  // ===== ملخص عام للوحدة =====


  /// نص عقد الإيجار كاملًا — يُستعمل في «طباعة عقد الإيجار».
  String _fullContractText() {
    final contract = _contract;
    if (contract == null) return '';
    final lease = LeaseContractData.decode(contract.notes);
    final buffer = StringBuffer()
      ..writeln('عقد إيجار')
      ..writeln('العقار: ${widget.assetTitle}')
      ..writeln('الوحدة: ${_unit.name} (${_unit.type})')
      ..writeln('رقم العقد: ${_contractNumber(contract)}')
      ..writeln('المستأجر: ${contract.tenantName ?? '—'}')
      ..writeln(
        'الفترة: ${_fmtShortDate(contract.startDate)} - '
        '${_fmtShortDate(contract.endDate)}',
      )
      ..writeln('الإيجار السنوي: ${_money(contract.annualRent)}')
      ..writeln('دورية السداد: ${_cycleDetailLabel(contract)}')
      ..writeln('');
    if (!lease.isEmpty) {
      buffer.writeln(lease.toShareText());
    }
    if (_payments.isNotEmpty) {
      buffer
        ..writeln('')
        ..writeln('جدول الدفعات:');
      for (var i = 0; i < _payments.length; i++) {
        final payment = _payments[i];
        buffer.writeln(
          '${i + 1}) استحقاق ${fmtPayDate(payment.dueDate)} — '
          'مستحق ${_money(payment.amountDue)} — '
          'مسدد ${_money(payment.amountPaid)} — '
          '${rentPaymentStatusLabel(payment)}',
        );
      }
      buffer
        ..writeln('')
        ..writeln('إجمالي المستحق: ${_money(_totalDue)}')
        ..writeln('إجمالي المسدد: ${_money(_totalPaid)}')
        ..writeln('المتبقي: ${_money(_totalRemaining)}');
    }
    return buffer.toString();
  }

  /// معاينة العقد كاملًا مع إمكانية الطباعة/المشاركة.
  void _printLeaseContract() {
    final text = _fullContractText();
    if (text.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('لا يوجد عقد إيجار لهذه الوحدة'),
          behavior: SnackBarBehavior.floating,
        ),
      );
      return;
    }
    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(AppTheme.rCard),
        ),
      ),
      builder: (sheetContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: DraggableScrollableSheet(
          expand: false,
          initialChildSize: 0.85,
          maxChildSize: 0.95,
          builder: (context, controller) => Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 14, 16, 8),
                child: Row(
                  textDirection: AppTr.uiDir,
                  children: [
                    const Icon(
                      Icons.print_outlined,
                      size: 19,
                      color: _kPropertyColor,
                    ),
                    const SizedBox(width: 8),
                    const Expanded(
                      child: Text(
                        'عقد الإيجار كاملًا',
                        style: TextStyle(
                          fontSize: 13,
                          fontWeight: FontWeight.w900,
                          color: Color(0xFF022E2A),
                        ),
                      ),
                    ),
                    FilledButton.icon(
                      style: FilledButton.styleFrom(
                        backgroundColor: AppTheme.gold,
                        foregroundColor: Colors.white,
                      ),
                      onPressed: () => printOrShareLeaseContract(
                        sheetContext,
                        contract: _contract!,
                        text: text,
                        fileName: 'عقد-${_unit.name}',
                        assetMeta: widget.propertyMeta,
                      ),
                      icon: const Icon(Icons.ios_share_rounded, size: 17),
                      label: const Text('طباعة / مشاركة'),
                    ),
                  ],
                ),
              ),
              const Divider(height: 1, color: AppTheme.line),
              Expanded(
                child: ListView(
                  controller: controller,
                  padding: const EdgeInsets.fromLTRB(16, 12, 16, 24),
                  children: [
                    Container(
                      padding: const EdgeInsets.all(14),
                      decoration: BoxDecoration(
                        color: AppTheme.paper,
