  // ===== بيانات الوحدة وشروط الإيجار — تُحفظ في الوحدة نفسها =====

  /// حفظ حقول إضافية في الوحدة (دمجًا) وإبلاغ شاشة العقار لتخزينها.
  void _saveExtras(Map<String, String> updates) {
    final merged = {..._unit.extras};
    updates.forEach((key, value) {
      if (value.trim().isEmpty) {
        merged.remove(key);
      } else {
        merged[key] = value.trim();
      }
    });
    setState(() => _unit = _unit.copyWith(extras: merged));
    widget.onUnitUpdated(_unit);
  }

  String _extra(String key) => _unit.extras[key] ?? '';

  /// نافذة «تعديل بيانات الوحدة»: الاسم والرقم والمساحة وعداد الكهرباء
  /// والمرافق والملاحظات — وللمستودع تفاصيله الخاصة.
  ///
  /// بلا «مكان الوحدة»: الوحدة داخل العقار، ومكانها مكانه.
  Future<void> _openUnitInfoSheet() async {
    final isWarehouse = _unit.type == _kUnitWarehouse;
    final hasRooms = _unitTypeHasRooms(_unit.type);
    final isFullFloor = _unit.type == _kUnitFullFloor;
    String count(int value) => value > 0 ? '$value' : '';

    final nameCtrl = TextEditingController(text: _unit.name);
    final numberCtrl = TextEditingController(text: _unit.unitNumber);
    final areaCtrl = TextEditingController(text: _unit.area);
    final meterCtrl = TextEditingController(
      text: _extra('رقم عداد الكهرباء'),
    );
    final roomsCtrl = TextEditingController(text: count(_unit.rooms));
    final hallsCtrl = TextEditingController(text: count(_unit.halls));
    final balconiesCtrl = TextEditingController(text: count(_unit.balconies));
    final bathroomsCtrl = TextEditingController(text: count(_unit.bathrooms));
    final parkingCtrl = TextEditingController(text: count(_unit.parkingCount));
    final otherFacilitiesCtrl = TextEditingController(
      text: _extra('مرافق أخرى'),
    );
    final notesCtrl = TextEditingController(text: _unit.notes);
    final whRoomsCtrl = TextEditingController(
      text: _extra('عدد الغرف الداخلية'),
    );
    final civilDefenseCtrl = TextEditingController(
      text: _extra('شهادة الدفاع المدني'),
    );
    var whOffice = _extra('مكتب داخلي') == 'نعم';
    var whBathroom = _extra('حمام داخلي') == 'نعم';
    var error = '';

    Widget field(
      String label,
      TextEditingController controller, {
      bool number = false,
      int maxLines = 1,
    }) => Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: TextField(
        controller: controller,
        textAlign: AppTr.alignEnd,
        maxLines: maxLines,
        keyboardType: number
            ? const TextInputType.numberWithOptions(decimal: true)
            : TextInputType.text,
        decoration: _propertyInputDecorationShared(label),
      ),
    );

    Widget sectionTitle(String title) => Padding(
      padding: const EdgeInsets.only(top: 4, bottom: 8),
      child: Text(
        title,
        style: const TextStyle(
          fontSize: 13,
          fontWeight: FontWeight.w900,
          color: Color(0xFF022E2A),
        ),
      ),
    );

    final saved = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.white,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),
      ),
      builder: (sheetContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: StatefulBuilder(
          builder: (sheetContext, setSheetState) => Padding(
            padding: EdgeInsets.fromLTRB(
              18,
              16,
              18,
              MediaQuery.of(sheetContext).viewInsets.bottom + 18,
            ),
            child: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Text(
                    'تعديل بيانات الوحدة — ${_unit.name}',
                    style: const TextStyle(
                      fontSize: 15,
                      fontWeight: FontWeight.w900,
                      color: Color(0xFF022E2A),
                    ),
                  ),
                  const SizedBox(height: 4),
                  Text(
                    'النوع: ${_unit.type} · التعديل يخص هذه الوحدة وحدها.',
                    style: const TextStyle(
                      fontSize: 11,
                      height: 1.5,
                      fontWeight: FontWeight.w700,
                      color: Color(0xFF5C6B68),
                    ),
                  ),
                  const SizedBox(height: 14),
                  sectionTitle('البيانات الأساسية'),
                  Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Expanded(flex: 3, child: field('اسم الوحدة *', nameCtrl)),
                      const SizedBox(width: 8),
                      Expanded(
                        flex: 2,
                        child: field('رقم الوحدة', numberCtrl),
                      ),
                    ],
                  ),
                  Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Expanded(
                        child: field(
                          'المساحة (م²)',
                          areaCtrl,
                          number: true,
                        ),
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: field('رقم عداد الكهرباء', meterCtrl),
                      ),
                    ],
                  ),
                  sectionTitle('المرافق'),
                  Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      if (hasRooms) ...[
                        Expanded(
                          child: field('الغرف', roomsCtrl, number: true),
                        ),
                        const SizedBox(width: 8),
                      ],
                      Expanded(
                        child: field('الحمامات', bathroomsCtrl, number: true),
                      ),
                      const SizedBox(width: 8),
                      Expanded(
                        child: field('المواقف', parkingCtrl, number: true),
                      ),
                    ],
                  ),
                  if (hasRooms || isFullFloor)
                    Row(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        if (isFullFloor) ...[
                          Expanded(
                            child: field('الصالات', hallsCtrl, number: true),
                          ),
                          const SizedBox(width: 8),
                        ],
                        Expanded(
                          child: field(
                            'البلكونات',
                            balconiesCtrl,
                            number: true,
                          ),
                        ),
                      ],
                    ),
                  field(
                    'مرافق أخرى (مثال: مطبخ، مخزن خلفي، واجهة زجاجية)',
                    otherFacilitiesCtrl,
                    maxLines: 2,
                  ),
                  if (isWarehouse) ...[
                    sectionTitle('تفاصيل المستودع'),
                    field(
                      'عدد الغرف الداخلية (0 = بلا غرف)',
                      whRoomsCtrl,
                      number: true,
                    ),
                    SwitchListTile.adaptive(
                      contentPadding: EdgeInsets.zero,
                      dense: true,
                      title: const Text(
                        'يوجد مكتب داخلي',
                        style: TextStyle(
                          fontSize: 12,
                          fontWeight: FontWeight.w800,
                        ),
                      ),
                      value: whOffice,
                      onChanged: (v) => setSheetState(() => whOffice = v),
                    ),
                    SwitchListTile.adaptive(
                      contentPadding: EdgeInsets.zero,
                      dense: true,
                      title: const Text(
                        'يوجد حمام',
