  // ===== صيانة الوحدة: على المؤجر / على المستأجر =====

  List<Map<String, String>> get _maintenanceEntries {
    final raw = _extra('سجل الصيانة');
    if (raw.isEmpty) return const [];
    try {
      final decoded = jsonDecode(raw);
      if (decoded is! List) return const [];
      return decoded
          .whereType<Map>()
          .map(
            (entry) => entry.map(
              (key, value) => MapEntry('$key', '${value ?? ''}'),
            ),
          )
          .toList(growable: false);
    } catch (_) {
      return const [];
    }
  }

  void _saveMaintenance(List<Map<String, String>> entries) {
    _saveExtras({'سجل الصيانة': entries.isEmpty ? '' : jsonEncode(entries)});
  }


  /// صف عرض بسيط (عنوان ← قيمة) داخل بطاقات الإيجار.
  Widget _leaseInfoRow(String label, String value, {Color? valueColor}) =>
      _infoRowShared(label, value, valueColor: valueColor);

  /// نموذج الصيانة: نفس النموذج في البناية ([_showMaintenanceSheetShared]).
  Future<void> _openMaintenanceSheet({
    Map<String, String>? existing,
    int? index,
  }) async {
    final sheet = await _showMaintenanceSheetShared(context, existing: existing);
    if (sheet == null || !mounted) return;
    // التعديل يحمل معرّفات البند (التذكير...) فلا يتكرر.
    final row = <String, String>{
      ...sheet,
      for (final key in const ['_id', '_reminder_id'])
        if ((existing?[key] ?? '').isNotEmpty && (sheet[key] ?? '').isEmpty)
          key: existing![key]!,
    };
    final list = [..._maintenanceEntries];
    if (index == null) {
      list.add(row);
    } else {
      list[index] = row;
    }
    _saveMaintenance(list);
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(index == null ? 'تم حفظ الصيانة' : 'تم حفظ التعديل'),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  /// «انتهاء الصيانة»: تُغلق باليوم والوقت والملاحظة، فتزول «صيانة» من
  /// حالة الوحدة ويُتاح تأجيرها.
  Future<void> _finishUnitMaintenance(int index) async {
    final list = [..._maintenanceEntries];
    if (index < 0 || index >= list.length) return;
    final done = await _finishMaintenanceShared(context, list[index]);
    if (done == null || !mounted) return;
    list[index] = done;
    _saveMaintenance(list);
    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('تم تسجيل انتهاء الصيانة'),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  /// تبويب الصيانة: عنوان و«+»، وكل عنصر في سطرين مع سهم للتفاصيل.
  Widget _buildMaintenanceTab() {
    final entries = _maintenanceEntries;
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _unitSectionHead(
          'الصيانة',
          trailingText: '${entries.length}',
          onAdd: () => _openMaintenanceSheet(),
          tooltip: AppTr.tr('إضافة صيانة'),
        ),
        if (entries.isEmpty)
          _unitEmptyState(
            Icons.build_circle_outlined,
            'لا توجد أعمال صيانة بعد',
            'أضف أول عملية صيانة وحدّد من يتحمّلها: المؤجر أم المستأجر.',
          )
        else
          for (var i = 0; i < entries.length; i++)
            _unitItemRow(
              icon: Icons.build_circle_outlined,
              accent: (entries[i]['النوع'] ?? '') == 'على المستأجر'
                  ? AppTheme.gold
                  : _kPropertyColor,
              line1: [
                (entries[i]['الوصف'] ?? '').isEmpty
                    ? 'صيانة'
                    : entries[i]['الوصف']!,
                if ((entries[i]['المبلغ'] ?? '').isNotEmpty)
                  '${entries[i]['المبلغ']} ${AppSettings.currencySuffix}',
              ].join(' · '),
              line2: [
                if (_maintIsOpen(entries[i])) _kMaintOpen,
                if ((entries[i]['التاريخ'] ?? '').isNotEmpty)
                  entries[i]['التاريخ']!,
                if ((entries[i]['الشركة المنفذة'] ?? '').isNotEmpty)
                  entries[i]['الشركة المنفذة']!,
                entries[i]['النوع'] ?? '',
              ].where((part) => part.isNotEmpty).join(' · '),
              onTap: () => _openUnitItemDetails(
                title: (entries[i]['الوصف'] ?? '').isEmpty
                    ? 'صيانة'
                    : entries[i]['الوصف']!,
                icon: Icons.build_circle_outlined,
                row: entries[i],
                onEdit: () =>
                    _openMaintenanceSheet(existing: entries[i], index: i),
                onFinishMaintenance: () => _finishUnitMaintenance(i),
                onDelete: () {
                  final list = [...entries]..removeAt(i);
                  _saveMaintenance(list);
                },
              ),
            ),
      ],
    );
  }


  // ============================================================
  // الحركة المالية للوحدة — ثلاثة أبواب: «الدفعات الإيجارية»
  // و«دخل إضافي» و«المصاريف». عرض الدفعات نفسه مشترك مع صفحة
  // العقار (RentPaymentsView) فيبقى الشكل والمنطق واحدًا.
  // ============================================================

  String _money(double value) =>
      '${value.toStringAsFixed(2)} ${AppSettings.currencySuffix}';

