    final selected = _financeTab == index;
    return Expanded(
      child: InkWell(
        onTap: () => setState(() => _financeTab = index),
        borderRadius: BorderRadius.circular(AppTheme.rIcon),
        child: Container(
          padding: const EdgeInsets.symmetric(vertical: 9, horizontal: 6),
          decoration: BoxDecoration(
            color: selected ? _kPropertyColor : AppTheme.paper,
            borderRadius: BorderRadius.circular(AppTheme.rIcon),
            border: Border.all(
              color: selected ? _kPropertyColor : AppTheme.hairline,
            ),
          ),
          child: Row(
            mainAxisAlignment: MainAxisAlignment.center,
            children: [
              Icon(
                icon,
                size: 15,
                color: selected ? Colors.white : _kPropertyColor,
