  /// دفعات هذه الوحدة بشكل موحّد مع صفحة العقار.
  List<RentPaymentEntry> _unitPaymentEntries() {
    final contract = _contract;
    if (contract == null) return const <RentPaymentEntry>[];
    return <RentPaymentEntry>[
      for (var i = 0; i < _payments.length; i++)
        RentPaymentEntry(
          contract: contract,
          payment: _payments[i],
          unitName: _unit.name,
          order: i + 1,
          totalInContract: _payments.length,
        ),
    ];
  }

