  // ---------------- دخل إضافي / المصاريف ----------------

  Widget _buildTransactionsBlock(bool income) {
    final items = _transactions
        .where((t) => t.isIncome == income)
        .toList(growable: false);
    final total = items.fold<double>(0, (sum, t) => sum + t.amount);
    final color = income ? const Color(0xFF0E7161) : const Color(0xFFC4392E);
    final title = income ? 'دخل إضافي' : 'المصاريف';
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _unitSectionHead(
          income ? 'إجمالي الدخل الإضافي' : 'إجمالي المصاريف',
          trailingText: _money(total),
          onAdd: () => _openTransactionForm(
            kind: income
                ? PropertyUnitTransactionRecord.kindIncome
                : PropertyUnitTransactionRecord.kindExpense,
          ),
          tooltip: income ? 'إضافة دخل إضافي' : 'إضافة مصروف',
        ),
        if (items.isEmpty)
          _unitEmptyState(
            income
                ? Icons.trending_up_rounded
                : Icons.receipt_long_outlined,
            income ? 'لا يوجد دخل إضافي بعد' : 'لا توجد مصاريف بعد',
            income
                ? 'أضف أول دخل إضافي لتبدأ متابعة دخل هذه الوحدة.'
                : 'أضف أول مصروف لتبدأ متابعة مصاريف هذه الوحدة.',
          )
        else
          for (final item in items)
            Container(
              padding: const EdgeInsets.symmetric(vertical: 10),
              decoration: const BoxDecoration(
                border: Border(
                  bottom: BorderSide(color: AppTheme.hairline, width: 0.8),
                ),
              ),
              child: Row(
                textDirection: AppTr.uiDir,
                children: [
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          (item.category ?? '').isEmpty
                              ? (income ? 'دخل إضافي' : 'مصروف')
                              : item.category!,
                          textAlign: AppTr.alignEnd,
                          maxLines: 3,
                          style: const TextStyle(
                            fontSize: 12,
                            fontWeight: FontWeight.w900,
                            color: Color(0xFF022E2A),
                          ),
                        ),
                        const SizedBox(height: 4),
                        Text(
                          '${fmtPayDate(item.occurredOn)}'
                          '${_txNoteText(item.note).isEmpty ? '' : ' · ${_txNoteText(item.note)}'}',
                          textAlign: AppTr.alignEnd,
                          maxLines: 3,
                          style: const TextStyle(
                            fontSize: 11,
                            fontWeight: FontWeight.w600,
                            color: Color(0xFF5C6B68),
                          ),
                        ),
                      ],
                    ),
                  ),
                  Text(
                    _money(item.amount),
                    style: TextStyle(
                      fontSize: 12,
                      fontWeight: FontWeight.w900,
                      color: color,
                    ),
                  ),
                  if (_txFilePath(item.note).isNotEmpty)
                    _openFileButton(_txFilePath(item.note))!,
                  IconButton(
                    tooltip: AppTr.tr('تعديل'),
                    icon: const Icon(Icons.edit_outlined, size: 18),
                    color: AppTheme.brandMid,
                    onPressed: () =>
                        _openTransactionForm(kind: item.kind, existing: item),
                  ),
                ],
              ),
            ),
      ],
    );
  }

  // ============================================================
  // إدارة الإيجار — العقد، الدفعات، الرسوم الإدارية، التأمين
  // ============================================================

  static const _kUnitFees = 'رسوم الوحدة';
  static const _kUnitDeposits = 'تأمينات الوحدة';

  static const _kRowItem = 'البند';
  static const _kRowAmount = 'المبلغ';
  static const _kRowDue = 'تاريخ الاستحقاق';
  static const _kRowPaid = 'المسدد';
  static const _kRowNote = 'ملاحظات';
  static const _kRowSource = 'المصدر';

  double _numOf(String? raw) {
    if (raw == null) return 0;
    return double.tryParse(
          raw.replaceAll(',', '').replaceAll('٬', '').trim(),
        ) ??
        0;
  }

  LeaseContractData get _lease => _contract == null
      ? LeaseContractData()
      : LeaseContractData.decode(_contract!.notes);

  /// صفوف الرسوم الإدارية: المُسجَّل في الوحدة + رسوم خطة العقد.
  List<Map<String, String>> get _feeRows {
    final rows = <Map<String, String>>[..._extraList(_kUnitFees)];
    for (final row in _lease.payments) {
      final kind = (row[LeaseContractData.kPaymentFee] ?? '').trim();
      if (!kind.startsWith('رسوم')) continue;
      final amount = row[LeaseContractData.kPaymentAmount] ?? '';
      final paid =
          (row[LeaseContractData.kPaymentStatus] ?? '') == 'مسددة' ? amount : '';
      rows.add(<String, String>{
        _kRowItem: kind,
        _kRowAmount: amount,
        _kRowDue: row[LeaseContractData.kPaymentDue] ?? '',
        _kRowPaid: paid,
        _kRowSource: 'العقد',
      });
    }
    return rows;
  }

  /// صفوف التأمين: المُسجَّل في الوحدة + تأمينات العقد.
  List<Map<String, String>> get _depositRows {
    final rows = <Map<String, String>>[..._extraList(_kUnitDeposits)];
    final lease = _lease;
    for (final row in lease.deposits) {
      final amount = row[LeaseContractData.kDepositAmount] ?? '';
      if (amount.trim().isEmpty) continue;
      // التأمين بشيك: مستحق حتى يُحصَّل، وتاريخه تاريخ الشيك إن وُجد.
      final byCheque = (row[LeaseContractData.kCollectMethod] ?? '') == 'شيك';
      final collected = byCheque
          ? (row[LeaseContractData.kPaymentChequeDate] ?? '').trim()
          : (row['تاريخ تحصيل التأمين'] ?? '').trim();
      rows.add(<String, String>{
        _kRowItem: 'تأمين العقد',
        _kRowAmount: amount,
        _kRowDue: collected,
        _kRowPaid: byCheque || collected.isEmpty ? '' : amount,
        _kRowNote: row['ملاحظات'] ?? '',
        _kRowSource: 'العقد',
      });
    }
    for (final row in lease.payments) {
      if ((row[LeaseContractData.kPaymentFee] ?? '').trim() != 'تأمين') continue;
      final amount = row[LeaseContractData.kPaymentAmount] ?? '';
      final paid =
          (row[LeaseContractData.kPaymentStatus] ?? '') == 'مسددة' ? amount : '';
      rows.add(<String, String>{
        _kRowItem: 'تأمين ضمن خطة الدفعات',
        _kRowAmount: amount,
        _kRowDue: row[LeaseContractData.kPaymentDue] ?? '',
        _kRowPaid: paid,
        _kRowSource: 'العقد',
      });
    }
    return rows;
  }

  bool _rowIsOverdue(Map<String, String> row) {
    final remaining = _numOf(row[_kRowAmount]) - _numOf(row[_kRowPaid]);
    if (remaining <= 0.009) return false;
    final due = DateTime.tryParse((row[_kRowDue] ?? '').trim());
    if (due == null) return false;
    return due.isBefore(DateTime(
      DateTime.now().year,
      DateTime.now().month,
      DateTime.now().day,
    ));
  }

  bool _rowIsUpcoming(Map<String, String> row) {
    final remaining = _numOf(row[_kRowAmount]) - _numOf(row[_kRowPaid]);
    if (remaining <= 0.009) return false;
    return !_rowIsOverdue(row);
  }

