  /// تجديد العقد: يبدأ من نهاية العقد الحالي بمدة يختارها المستخدم.
  /// نافذة اختيار المدة (6 أشهر / سنة / سنتان) للتمديد أو التجديد.
  Future<int?> _pickContractMonths({
    required String title,
    required String hint,
    required String confirmLabel,
  }) async {
    var months = 12;
    final confirmed = await showModalBottomSheet<bool>(
      context: context,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(AppTheme.rCard),
        ),
      ),
      builder: (sheetContext) => StatefulBuilder(
        builder: (sheetContext, setSheetState) => Directionality(
          textDirection: AppTr.uiDir,
          child: SafeArea(
            top: false,
            child: Padding(
              padding: const EdgeInsets.fromLTRB(16, 16, 16, 18),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Text(
                    title,
                    textAlign: TextAlign.right,
                    style: const TextStyle(
                      fontSize: 14,
                      fontWeight: FontWeight.w900,
                      color: Color(0xFF022E2A),
                    ),
                  ),
                  const SizedBox(height: 6),
                  Text(
                    hint,
                    textAlign: TextAlign.right,
                    style: const TextStyle(
                      fontSize: 11,
                      height: 1.6,
                      fontWeight: FontWeight.w600,
                      color: Color(0xFF5C6B68),
                    ),
                  ),
                  const SizedBox(height: 14),
                  Row(
                    children: [
                      for (final option in const [
                        ('6 أشهر', 6),
                        ('سنة', 12),
                        ('سنتان', 24),
                      ]) ...[
                        Expanded(
                          child: InkWell(
                            onTap: () =>
                                setSheetState(() => months = option.$2),
                            borderRadius: BorderRadius.circular(AppTheme.rIcon),
                            child: Container(
                              margin: const EdgeInsets.only(left: 8),
                              padding: const EdgeInsets.symmetric(vertical: 12),
                              alignment: Alignment.center,
                              decoration: BoxDecoration(
                                color: months == option.$2
                                    ? _kPropertyColor
                                    : AppTheme.field,
                                borderRadius: BorderRadius.circular(
                                  AppTheme.rIcon,
                                ),
                                border: Border.all(
                                  color: months == option.$2
                                      ? _kPropertyColor
                                      : AppTheme.line,
                                ),
                              ),
                              child: Text(
                                option.$1,
                                style: TextStyle(
                                  fontSize: 12,
                                  fontWeight: FontWeight.w900,
                                  color: months == option.$2
                                      ? Colors.white
                                      : AppTheme.title,
                                ),
                              ),
                            ),
                          ),
                        ),
                      ],
                    ],
                  ),
                  const SizedBox(height: 16),
                  FilledButton(
                    onPressed: () => Navigator.of(sheetContext).pop(true),
                    style: FilledButton.styleFrom(
                      backgroundColor: _kPropertyColor,
                      foregroundColor: Colors.white,
                      minimumSize: const Size.fromHeight(48),
                    ),
                    child: Text(confirmLabel),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
    return confirmed == true ? months : null;
  }

  static String _isoDate(DateTime d) =>
      '${d.year.toString().padLeft(4, '0')}-'
      '${d.month.toString().padLeft(2, '0')}-'
      '${d.day.toString().padLeft(2, '0')}';

  /// هل انتهى العقد (بإنهائه أو بمرور تاريخ نهايته)؟
  bool get _contractEnded {
    final contract = _contract;
    if (contract == null) return false;
    if (_contractClosed(contract)) return true;
    final end = contract.endDate;
    return end != null &&
        DateUtils.dateOnly(end).isBefore(DateUtils.dateOnly(DateTime.now()));
  }

  /// تمديد العقد: نفس العقد ونفس رقمه، وتُمدَّد نهايته بالمدة المختارة.
  Future<void> _extendContract() async {
    final repo = widget.repository;
    final contract = _contract;
    if (repo == null || contract?.id == null) return;
    final by = await _pickExtension(context);
    if (by == null || !mounted) return;
    final lease = LeaseContractData.decode(contract!.notes);
    final endTime = lease.contract[LeaseContractData.kEndTime];
    final withTime = by.hours > 0 || (endTime ?? '').trim().isNotEmpty;
    final from = _endWithTime(contract.endDate ?? DateTime.now(), endTime);
    final newEnd = _extendedEnd(from, by);
    if (!await _confirmExtension(
          context,
          by: by,
          start: contract.startDate,
          oldEnd: from,
          newEnd: newEnd,
          withTime: withTime,
        ) ||
        !mounted) {
      return;
    }
    final end = DateUtils.dateOnly(newEnd);
    lease.contract[LeaseContractData.kEndDate] = _isoDate(end);
    if (withTime) {
      lease.contract[LeaseContractData.kEndTime] =
          '${newEnd.hour.toString().padLeft(2, '0')}:'
          '${newEnd.minute.toString().padLeft(2, '0')}';
    }
    try {
      final saved = await repo.upsertUnitContract(
        contract.copyWith(
          endDate: end,
          status: PropertyUnitContractRecord.statusActive,
          notes: lease.encode(),
        ),
      );
      if (!mounted) return;
      setState(() => _contract = saved);
      widget.onUnitStatusChanged('مؤجرة');
      await _load();
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('مُدِّد العقد حتى ${_fmtShortDate(end)}'),
          behavior: SnackBarBehavior.floating,
        ),
      );
    } catch (_) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('تعذر تمديد العقد')),
      );
    }
  }

  /// تجديد العقد — بعد انتهائه فقط: تُفتح صفحة العقد كاملًا بمعلوماته،
  /// ورقم العقد القديم والجديد (لا يتكرر)، والمدة الجديدة من/إلى، والمبلغ،
  /// وفي آخرها «تجديد العقد»، ثم «تم تجديد العقد».
  Future<void> _renewContract() async {
    if (_unitMaintBlocksLease(_unit)) {
      _showMaintBlockNotice(
        context,
        'الوحدة تحت صيانة تمنع التأجير — سجّل «انتهاء الصيانة» من قسم '
        'الصيانة أولًا.',
      );
      return;
    }
    final repo = widget.repository;
    final assetId = widget.assetId;
    final contract = _contract;
    if (repo == null || assetId == null || contract?.id == null) return;
    final today = DateUtils.dateOnly(DateTime.now());
    final oldEnd = contract!.endDate;
    // يبدأ الجديد في اليوم التالي لنهاية السابق (لا يتداخلان يومًا).
    final start = oldEnd != null && !DateUtils.dateOnly(oldEnd).isBefore(today)
        ? DateUtils.dateOnly(oldEnd).add(const Duration(days: 1))
        : today;
    final months = await _pickContractMonths(
      title: 'تجديد العقد',
      hint: 'يبدأ العقد الجديد من ${_fmtShortDate(start)} بالمدة المختارة، '
          'ثم تُفتح صفحة العقد كاملًا لمراجعتها قبل التجديد.',
      confirmLabel: 'متابعة',
    );
    if (months == null || !mounted) return;
    // سنة من 1/1 تنتهي 31/12.
    final end = DateTime(start.year, start.month + months, start.day - 1);
    final oldNumber = leaseContractNumber(contract);
    final saved = await Navigator.of(context).push<PropertyUnitContractRecord>(
      MaterialPageRoute(
        builder: (_) => LeaseContractFormScreen(
          repository: repo,
          assetId: assetId,
          unitKey: _unit.unitKey,
          unitName: _unit.name,
          propertyTitle: widget.assetTitle,
          propertyType: widget.assetType,
          unitType: _unit.type,
          propertyMeta: _leaseMeta,
          templateNotes: contract.notes,
          title: 'تجديد العقد',
          renewStart: start,
          renewEnd: end,
          renewOldNo: oldNumber,
        ),
      ),
    );
    if (saved == null || !mounted) return;
    setState(() => _contract = saved);
    // التجديد المحفوظ مسودة لا يجعل الوحدة مؤجرة.
    widget.onUnitStatusChanged(
      saved.status == PropertyUnitContractRecord.statusPending
          ? 'مسودة'
          : 'مؤجرة',
    );
    await _load();
    if (!mounted) return;
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          'تم تجديد العقد بنجاح — رقم العقد الجديد '
          '${leaseContractNumber(saved)} '
          '(السابق $oldNumber)',
        ),
        behavior: SnackBarBehavior.floating,
      ),
    );
  }

  /// إلغاء العقد — نفسه من زر «إلغاء العقد» ومن «إلغاء» و«أرشيف» في
  /// الثلاث نقاط. لا يُلغى قبل التسوية: ما لك وما عليك من دفعات العقد
  /// نفسه، وملاحظاتك. بعدها يصير العقد «ملغي» وتعود الوحدة شاغرة.
  ///
  /// [confirmed]: القائمة أكّدت قبلها، فلا تأكيد ثانٍ. تُعيد true إن أُلغي.
  Future<bool> _cancelContract({bool confirmed = false}) async {
    final repo = widget.repository;
    final contract = _contract;
    if (repo == null || contract?.id == null) return false;
    final today = DateUtils.dateOnly(DateTime.now());
    final cheques = <String>[];
    var deposit = 0.0;
    var owed = 0.0;
    for (final payment in _payments) {
      final extra = decodePayExtra(payment.notes);
      final remaining = payRemaining(payment);
      if ((extra[kPayKind] ?? '') == kPayKindDeposit) {
        deposit += payment.amountPaid;
        continue;
      }
      final cheque = (extra[kPayCheque] ?? '').trim();
      if (remaining > 0 && cheque.isNotEmpty) cheques.add(cheque);
      final due = payment.dueDate;
      if (remaining > 0 &&
          due != null &&
          !DateUtils.dateOnly(due).isAfter(today)) {
        owed += remaining;
      }
    }
    Widget head(String label, Color color) => Padding(
      padding: const EdgeInsets.only(bottom: 4),
      child: Text(
        label,
        textAlign: TextAlign.right,
        style: TextStyle(
          fontSize: 13,
          fontWeight: FontWeight.w900,
          color: color,
        ),
      ),
    );
    Widget line(String text) => Text(
      '• $text',
      textAlign: TextAlign.right,
      style: const TextStyle(height: 1.7, fontSize: 12.5),
    );
    final notesCtrl = TextEditingController();
    var settledMoney = false;
    var withoutSettlement = false;
    final settled = await showDialog<bool>(
      context: context,
      builder: (dialogContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: AlertDialog(
          title: const Text('إلغاء العقد — التسوية'),
          content: SingleChildScrollView(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                head('لك', const Color(0xFF0E7161)),
                line(
                  owed > 0
                      ? 'على المستأجر مبلغ: ${_money(owed)}'
                      : 'لا مبالغ مستحقة على المستأجر.',
                ),
                const SizedBox(height: 10),
                head('عليك', AppTheme.danger),
                line(
                  deposit > 0
                      ? 'ردّ التأمين للمستأجر: ${_money(deposit)}'
                      : 'لا يوجد تأمين مستلم.',
                ),
                line(
                  cheques.isEmpty
                      ? 'لا توجد شيكات لإرجاعها.'
                      : 'إرجاع الشيكات (${cheques.length}): '
                            '${cheques.join('، ')}',
                ),
                // مبالغ مستحقة: تُتابَع في الحركات المالية ما لم تُسوَّ.
                if (owed > 0)
                  StatefulBuilder(
                    builder: (context, setBox) => CheckboxListTile(
                      value: settledMoney,
                      onChanged: (value) =>
                          setBox(() => settledMoney = value ?? false),
                      contentPadding: EdgeInsets.zero,
                      controlAffinity: ListTileControlAffinity.leading,
                      title: const Text(
                        'حُصّلت المبالغ أو تمت تسويتها (بلا متابعة بعدها)',
                        style: TextStyle(fontSize: 12),
                      ),
                    ),
                  ),
                const SizedBox(height: 12),
                TextField(
                  controller: notesCtrl,
                  minLines: 2,
                  maxLines: 4,
                  textAlign: TextAlign.right,
                  decoration: InputDecoration(
                    labelText: AppTr.tr('ملاحظات التسوية'),
                    hintText: AppTr.tr('اكتب ما تم الاتفاق عليه في التسوية'),
                    border: const OutlineInputBorder(),
                  ),
                ),
                const SizedBox(height: 10),
                Text(
                  owed > 0
                      ? 'إن لم تتم التسوية (مثل قضية لدى المحكمة) اختر «إلغاء '
                            'بدون تسوية»: يُلغى العقد وتبقى المستحقات في «السجل '
                            'التاريخي» بعلامة حمراء للمتابعة.'
                      : 'يرجى الإلغاء بعد عمل التسوية.',
                  textAlign: TextAlign.right,
                  style: const TextStyle(
                    height: 1.5,
                    fontWeight: FontWeight.w800,
                    color: AppTheme.danger,
                  ),
                ),
              ],
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.of(dialogContext).pop(false),
              child: const Text('رجوع'),
            ),
            // المستأجر لم يدفع (قضية مثلًا): يُلغى العقد وتبقى المستحقات.
            if (owed > 0)
              OutlinedButton(
                style: OutlinedButton.styleFrom(
                  foregroundColor: AppTheme.danger,
                ),
                onPressed: () {
                  withoutSettlement = true;
                  settledMoney = false;
                  Navigator.of(dialogContext).pop(true);
                },
                child: const Text('إلغاء بدون تسوية'),
              ),
            FilledButton(
              style: FilledButton.styleFrom(backgroundColor: AppTheme.danger),
              onPressed: () => Navigator.of(dialogContext).pop(true),
              child: const Text('تم عمل تسوية'),
            ),
          ],
        ),
      ),
    );
    final notes = notesCtrl.text.trim();
    Future.delayed(const Duration(milliseconds: 600), notesCtrl.dispose);
    if (settled != true || !mounted) return false;
    if (!confirmed) {
      final ok = await confirmAction(
        context,
        title: 'إلغاء العقد',
        message: 'سيصبح العقد «ملغي» وتتحول الوحدة إلى شاغرة. '
            'هل تريد المتابعة؟\n\n'
            'العقد الملغى لا يُحذف: ينتقل إلى «السجل التاريخي» '
            'وتبقى مستحقاته غير المسوّاة للمتابعة.',
        confirmLabel: 'إلغاء العقد',
        danger: true,
      );
      if (!ok || !mounted) return false;
    }
    // ملاحظات التسوية وتاريخ الإلغاء تُحفظ داخل بيانات عقد الإيجار نفسه.
    final current = contract!;
    var cancelled = current.copyWith(status: _kContractCancelled);
    if (_isLeaseContract(current)) {
      final lease = LeaseContractData.decode(current.notes);
      lease.contract[_kSettleNotesKey] = notes;
      lease.contract[_kCancelDateKey] = _isoDate(DateTime.now());
      if (settledMoney) lease.contract[LeaseContractData.kSettled] = 'نعم';
      if (withoutSettlement) lease.contract[_kNoSettlementKey] = 'نعم';
      cancelled = cancelled.copyWith(notes: lease.encode());
    } else if (settledMoney) {
      cancelled = cancelled.copyWith(notes: _withSettledFlag(current.notes));
    }
    try {
      await repo.upsertUnitContract(cancelled);
      // عقد متعدد الوحدات: عقد واحد — تُلغى معه سجلات بقية وحداته.
      final group = (current.groupKey ?? '').trim();
      final assetId = widget.assetId;
      if (group.isNotEmpty && assetId != null) {
        try {
          final all = await repo.fetchUnitContracts(assetId);
          for (final other in all) {
            if (other.id == current.id ||
                (other.groupKey ?? '').trim() != group ||
                other.status == _kContractCancelled) {
              continue;
            }
            var next = other.copyWith(status: _kContractCancelled);
            if (_isLeaseContract(other)) {
              final lease = LeaseContractData.decode(other.notes);
              lease.contract[_kCancelDateKey] = _isoDate(DateTime.now());
              if (notes.isNotEmpty) lease.contract[_kSettleNotesKey] = notes;
              next = next.copyWith(notes: lease.encode());
            }
            await repo.upsertUnitContract(next);
          }
        } catch (_) {
          // العقد الرئيسي أُلغي؛ بقية الوحدات تُلغى من صفحاتها إن تعذّر.
        }
      }
      widget.onUnitStatusChanged('شاغرة');
      if (!mounted) return true;
      setState(() {
        _contract = null;
        _unit = _unit.copyWith(status: 'شاغرة');
      });
      await _load();
      if (!mounted) return true;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            withoutSettlement
                ? 'أُلغي العقد بدون تسوية وأصبحت الوحدة شاغرة — المستحقات في «السجل التاريخي» للمتابعة'
                : 'أُلغي العقد وأصبحت الوحدة شاغرة',
          ),
          behavior: SnackBarBehavior.floating,
        ),
      );
      return true;
    } catch (error) {
      if (!mounted) return false;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('تعذر إلغاء العقد: $error'),
          duration: const Duration(seconds: 8),
        ),
      );
      return false;
    }
  }

  // ---------------- البنود المستحقة: إيجار + رسوم + تأمين ----------------

  /// أرقام البنود كلها — إيجارية وإدارية وتأمين — من جدول الدفعات وحده.
  ///
  /// المتأخر والقادم يُحسبان بالمتبقي لا بالمستحق: دفعة سُدِّد نصفها
  /// تُحسب بنصفها الباقي. والمستلم مجموع ما دُفع فعلًا.
  ({
    double overdue,
    int overdueCount,
    double dueToday,
    int dueTodayCount,
    double received,
    double upcoming,
    int upcomingCount,
    DateTime? nextDue,
    PropertyUnitPaymentRecord? nextPayment,
  })
  get _duesTotals {
    final now = DateTime.now();
    final today = DateTime(now.year, now.month, now.day);
    var overdue = 0.0;
    var dueToday = 0.0;
    var received = 0.0;
    var upcoming = 0.0;
    var overdueCount = 0;
    var dueTodayCount = 0;
    var upcomingCount = 0;
    // أقرب استحقاق: أقرب بند غير مسدد من اليوم فصاعدًا، وإن لم يوجد
    // فأقدم متأخر.
    PropertyUnitPaymentRecord? nextPayment;
    DateTime? nextDay;
    PropertyUnitPaymentRecord? oldestLate;
    DateTime? oldestLateDay;
    for (final payment in _payments) {
      received += payment.amountPaid;
      final remaining = payRemaining(payment);
      if (remaining <= 0) continue;
      final due = payment.dueDate;
      final day = due == null ? null : DateTime(due.year, due.month, due.day);
      // المتأخرة: ما تعدّى تاريخ اليوم. المستحقة: تاريخها اليوم.
      if (day != null && day.isBefore(today)) {
        overdue += remaining;
        overdueCount++;
        if (oldestLateDay == null || day.isBefore(oldestLateDay)) {
          oldestLateDay = day;
          oldestLate = payment;
        }
      } else if (day != null && day == today) {
        dueToday += remaining;
        dueTodayCount++;
      } else {
        upcoming += remaining;
        upcomingCount++;
      }
      if (day != null &&
          !day.isBefore(today) &&
          (nextDay == null || day.isBefore(nextDay))) {
        nextDay = day;
        nextPayment = payment;
      }
    }
    return (
      overdue: overdue,
      overdueCount: overdueCount,
      dueToday: dueToday,
      dueTodayCount: dueTodayCount,
      received: received,
      upcoming: upcoming,
      upcomingCount: upcomingCount,
      nextDue: nextDay ?? oldestLateDay,
      nextPayment: nextPayment ?? oldestLate,
    );
  }

  /// نافذة «أقرب استحقاق»: تفاصيل البند وحدها، وX للإغلاق — بلا أزرار.
  Future<void> _showNextDuePopup(PropertyUnitPaymentRecord payment) {
    final extra = decodePayExtra(payment.notes);
    final remaining = payRemaining(payment);
    final status = rentPaymentStatusLabel(payment);
    final method = (extra[kPayMethod] ?? '').trim();
    final cheque = (extra[kPayCheque] ?? payment.referenceNo ?? '').trim();
    final kind = (extra[kPayKind] ?? '').trim();
    final rows = <(String, String)>[
      ('البند', _payItemName(payment)),
      if (kind.isNotEmpty) ('النوع', kind),
      ('تاريخ الاستحقاق', payment.dueDate == null
          ? 'لا يوجد'
          : _fmtShortDate(payment.dueDate)),
      ('المبلغ المستحق', _money(payment.amountDue)),
      if (payment.amountPaid > 0.009) ('المسدد', _money(payment.amountPaid)),
      ('المتبقي', _money(remaining)),
      ('الحالة', method.isEmpty ? status : '$status/$method'),
      if (cheque.isNotEmpty) ('رقم الشيك', cheque),
      if ((_contract?.tenantName ?? '').trim().isNotEmpty)
        ('المستأجر', _contract!.tenantName!.trim()),
    ];
    return showDialog<void>(
      context: context,
      builder: (dialogContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: Dialog(
          insetPadding: const EdgeInsets.symmetric(horizontal: 24),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(AppTheme.rCard),
          ),
          child: Padding(
            padding: const EdgeInsets.fromLTRB(16, 10, 10, 16),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Row(
                  children: [
                    const Icon(
                      Icons.notifications_active_outlined,
                      size: 20,
                      color: AppTheme.goldDark,
                    ),
                    const SizedBox(width: 8),
                    const Expanded(
                      child: Text(
                        'أقرب استحقاق',
                        style: TextStyle(
                          fontSize: 15,
                          fontWeight: FontWeight.w900,
                          color: Color(0xFF022E2A),
                        ),
                      ),
                    ),
                    IconButton(
                      tooltip: AppTr.tr('إغلاق'),
                      onPressed: () => Navigator.of(dialogContext).pop(),
                      icon: const Icon(Icons.close_rounded, size: 22),
                    ),
                  ],
                ),
                const SizedBox(height: 6),
                for (final (label, value) in rows)
                  Padding(
                    padding: const EdgeInsets.symmetric(vertical: 4),
                    child: Row(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        SizedBox(
                          width: 110,
                          child: Text(
                            label,
                            style: const TextStyle(
                              fontSize: 12,
                              fontWeight: FontWeight.w700,
                              color: Color(0xFF5C6B68),
                            ),
                          ),
                        ),
                        Expanded(
                          child: Text(
                            value,
                            style: const TextStyle(
                              fontSize: 12.5,
                              fontWeight: FontWeight.w900,
                              color: Color(0xFF022E2A),
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
              ],
            ),
          ),
        ),
      ),
    );
  }

  /// مربع أمر في صندوق العقد — كل المربعات بمقاس واحد.
  Widget _contractActionTile({
    required IconData icon,
    required String label,
