  /// اسم البند كما يُعرض — المكتوب في العقد، وإلا نوعه.
  String _payItemName(PropertyUnitPaymentRecord payment) {
    final extra = decodePayExtra(payment.notes);
    final name = (extra[kPayName] ?? '').trim();
    if (name.isNotEmpty) return name;
    return (extra[kPayKind] ?? '').trim().isEmpty
        ? 'دفعة إيجارية'
        : extra[kPayKind]!;
  }

  Widget _duesTile({
    required String label,
    required String value,
    required Color color,
    String? sub,
  }) {
    // المربعات الأربعة بمقاس واحد وخطوط واحدة: ارتفاع ثابت، وعنوان في
    // سطر واحد، وسطر فرعي دائمًا — فلا يطول مربع عن جاره.
    return Container(
      height: 92,
      padding: const EdgeInsets.fromLTRB(11, 10, 11, 10),
      decoration: BoxDecoration(
        color: color.withValues(alpha: 0.07),
        borderRadius: BorderRadius.circular(AppTheme.rInner),
        border: Border.all(color: color.withValues(alpha: 0.2)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        mainAxisAlignment: MainAxisAlignment.spaceBetween,
        children: [
          FittedBox(
            fit: BoxFit.scaleDown,
            alignment: AlignmentDirectional.centerStart,
            child: FittedBox(fit: BoxFit.scaleDown, alignment: AlignmentDirectional.centerStart, child: Text(
              label,
              maxLines: 1,
              style: TextStyle(
                fontSize: 11,
                fontWeight: FontWeight.w800,
                color: color,
              ),
            )),
          ),
          // الرقم يُصغَّر ولا يُقصّ: رقم ناقص أسوأ من رقم صغير.
          FittedBox(
            fit: BoxFit.scaleDown,
            alignment: AlignmentDirectional.centerStart,
            child: Text(
              value,
              style: const TextStyle(
                fontSize: 14,
                fontWeight: FontWeight.w900,
                color: Color(0xFF022E2A),
              ),
            ),
          ),
          FittedBox(fit: BoxFit.scaleDown, alignment: AlignmentDirectional.centerStart, child: Text(
            sub ?? '',
            maxLines: 1,
            style: const TextStyle(
              fontSize: 10,
              fontWeight: FontWeight.w700,
              color: Color(0xFF5C6B68),
            ),
          )),
        ],
      ),
    );
  }

  /// الملخص الموحّد: المتأخر، المستلم، القادم، وأقرب استحقاق، ثم «سداد
  /// دفعات». يُعرض في «الحركات المالية» وفي «إدارة الإيجار» بنفس الأرقام.
  List<Widget> _duesSummaryBody({String? caption}) {
    final captionText = caption == null
        ? null
        : Padding(
            padding: const EdgeInsets.only(bottom: 10),
            child: Text(
              caption,
              textAlign: TextAlign.right,
              style: const TextStyle(
                fontSize: 11,
                fontWeight: FontWeight.w800,
                color: Color(0xFF5C6B68),
              ),
            ),
          );
    if (_payments.isEmpty) {
      return [
        if (captionText != null) captionText,
        const Text(
          'لا توجد دفعات بعد — تُولَّد من دفعات عقد الإيجار ورسومه '
          'وتأمينه عند حفظه، أو أضفها يدويًا.',
          textAlign: TextAlign.right,
          style: TextStyle(
            fontSize: 11.5,
            height: 1.7,
            fontWeight: FontWeight.w700,
            color: Color(0xFF5C6B68),
          ),
        ),
      ];
    }
    final totals = _duesTotals;
    final nextDue = totals.nextDue;
    final grand = _payments.fold<double>(0, (sum, p) => sum + p.amountDue);
    return [
      // إجمالي الدفعات بعددها — معلومة للقراءة، لا زر: الزر الوحيد في
      // الصندوق هو «عرض / سداد الدفعات».
      Container(
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
          decoration: BoxDecoration(
            color: AppTheme.paper,
            borderRadius: BorderRadius.circular(AppTheme.rIcon),
            border: Border.all(color: AppTheme.hairline),
          ),
          child: Row(
            textDirection: AppTr.uiDir,
            children: [
              const Icon(
                Icons.receipt_long_outlined,
                size: 16,
                color: _kPropertyColor,
              ),
              const SizedBox(width: 7),
              Expanded(
                child: Text(
                  'إجمالي الدفعات ${_money(grand)}',
                  textAlign: TextAlign.right,
                  style: const TextStyle(
                    fontSize: 11.5,
                    fontWeight: FontWeight.w900,
                    color: Color(0xFF022E2A),
                  ),
                ),
              ),
              // عدد الدفعات رقمًا — بلون هادئ، فلا يُقرأ زرًّا.
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 3),
                decoration: BoxDecoration(
                  color: AppTheme.brandSoft,
                  borderRadius: BorderRadius.circular(999),
                ),
                child: Text(
                  '${_payments.length}',
                  style: const TextStyle(
                    fontSize: 11,
                    fontWeight: FontWeight.w900,
                    color: Color(0xFF022E2A),
                  ),
                ),
              ),
            ],
          ),
      ),
      const SizedBox(height: 10),
      if (captionText != null) captionText,

      // السطر الأول: المستحقة (اليوم) وبجانبها المتأخرة (تعدّت اليوم).
      Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Expanded(
            child: _duesTile(
              label: 'الدفعات المستحقة',
              value: _money(totals.dueToday),
              sub: '${totals.dueTodayCount} بند',
              color: AppTheme.goldDark,
            ),
          ),
          const SizedBox(width: 8),
          Expanded(
            child: _duesTile(
              label: 'الدفعات المتأخرة',
              value: _money(totals.overdue),
              sub: '${totals.overdueCount} بند',
              color: AppTheme.danger,
            ),
          ),
        ],
      ),
      const SizedBox(height: 8),
      // السطر الثاني: القادمة والمستلمة.
      Row(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Expanded(
            child: _duesTile(
              label: 'الدفعات القادمة',
              value: _money(totals.upcoming),
              sub: '${totals.upcomingCount} بند',
              color: _kPropertyColor,
            ),
          ),
          const SizedBox(width: 8),
          Expanded(
            child: _duesTile(
              label: 'الدفعات المستلمة',
              value: _money(totals.received),
              sub:
                  '${_payments.where((p) => p.amountPaid > 0.009).length} بند',
              color: const Color(0xFF0E7161),
            ),
          ),
        ],
      ),
      const SizedBox(height: 8),
      // «أقرب استحقاق» سطر بجرس وتاريخه؛ الضغط يعرض تفاصيل البند.
      InkWell(
        borderRadius: BorderRadius.circular(AppTheme.rIcon),
        onTap: totals.nextPayment == null
            ? null
            : () => _showNextDuePopup(totals.nextPayment!),
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),
          decoration: BoxDecoration(
            color: AppTheme.goldDark.withValues(alpha: 0.07),
            borderRadius: BorderRadius.circular(AppTheme.rIcon),
            border: Border.all(
              color: AppTheme.goldDark.withValues(alpha: 0.2),
            ),
          ),
          child: Row(
            textDirection: AppTr.uiDir,
            children: [
              const Icon(
                Icons.notifications_active_outlined,
                size: 17,
                color: AppTheme.goldDark,
              ),
              const SizedBox(width: 7),
              Expanded(
                child: Text(
                  nextDue == null
                      ? 'أقرب استحقاق: لا يوجد'
                      : 'أقرب استحقاق: ${_fmtShortDate(nextDue)}',
                  textAlign: TextAlign.right,
                  style: const TextStyle(
                    fontSize: 11.5,
                    fontWeight: FontWeight.w900,
                    color: Color(0xFF022E2A),
                  ),
                ),
              ),
              if (totals.nextPayment != null)
                const Icon(
                  Icons.chevron_left_rounded,
                  size: 20,
                  color: AppTheme.goldDark,
                ),
            ],
          ),
        ),
      ),
      const SizedBox(height: 12),
      // المكان الوحيد للسداد: يفتح الدفعات كلها بترتيبها وحالاتها، يُختار
      // منها ما يُسدَّد ثم «التالي». كان في الصفحة مكانان للسداد.
      FilledButton.icon(
        onPressed: _openUnitPaymentsPage,
        style: FilledButton.styleFrom(
          backgroundColor: _kPropertyColor,
          foregroundColor: Colors.white,
          minimumSize: const Size.fromHeight(48),
        ),
        icon: const Icon(Icons.list_alt_rounded, size: 19),
        label: const Text('عرض / سداد الدفعات'),
      ),
      // «طباعة كشف الدفعات» حُذفت من هنا: الطباعة من داخل «عرض / سداد
      // الدفعات».
    ];
  }

  /// فلتر دفعات الوحدة — في سطر «العناصر» أعلى الصفحة وفي صفحة الدفعات.
  String _unitPaymentFilter = 'الكل';

  static const _unitPaymentFilters = <String>[
    'الكل',
    'مستحقة',
    'متأخرة',
    'قادمة',
    'مدفوعة',
  ];

  bool _matchesUnitPaymentFilter(PropertyUnitPaymentRecord payment) {
    if (_unitPaymentFilter == 'الكل') return true;
    final label = rentPaymentStatusLabel(payment);
    if (_unitPaymentFilter == 'مدفوعة') {
      return label == 'مدفوعة' || label == 'مدفوعة جزئيًا';
    }
    return label == _unitPaymentFilter;
  }

  Widget _unitPaymentsFilterButton() {
    return PopupMenuButton<String>(
      tooltip: AppTr.tr('تصفية الدفعات'),
      position: PopupMenuPosition.under,
      onSelected: (value) => setState(() => _unitPaymentFilter = value),
      itemBuilder: (context) => [
        for (final option in _unitPaymentFilters)
          PopupMenuItem<String>(
            value: option,
            child: Text(
              option,
              textAlign: TextAlign.right,
              style: TextStyle(
                fontSize: 12,
                fontWeight: option == _unitPaymentFilter
                    ? FontWeight.w900
                    : FontWeight.w600,
                color: option == _unitPaymentFilter
                    ? _kPropertyColor
                    : const Color(0xFF022E2A),
              ),
            ),
          ),
      ],
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          Text(
            _unitPaymentFilter,
            style: const TextStyle(
              fontSize: 11,
              fontWeight: FontWeight.w800,
              color: Color(0xFF0E7161),
            ),
          ),
          const Icon(
            Icons.keyboard_arrow_down_rounded,
            size: 16,
            color: Color(0xFF0E7161),
          ),
        ],
      ),
    );
  }

  /// صفحة «عرض / سداد الدفعات»: كل البنود بترتيب استحقاقها وحالاتها.
  /// غير المسدد يُختار ثم «التالي» ← طريقة الدفع وكلي/جزئي لكلٍّ منها ←
  /// مراجعة وتأكيد. والمسدد بجانبه ثلاث نقاط: مشاركة أو سند قبض.
  Future<void> _openUnitPaymentsPage() async {
    final repo = widget.repository;
    if (repo == null) return;
    await Navigator.of(context).push(
      MaterialPageRoute(
        builder: (_) => _UnitPaymentsPage(
          title: 'الدفعات — ${_unit.name}',
          repository: repo,
          assetTitle: widget.assetTitle,
          initial: _unitPaymentEntries(),
          initialFilter: _unitPaymentFilter,
          onFilterChanged: (value) {
            if (mounted) setState(() => _unitPaymentFilter = value);
          },
          reload: () async {
            await _load();
            return _unitPaymentEntries();
          },
        ),
      ),
    );
  }

  // ---------------- إجراءات الدفعات ----------------

  List<PropertyUnitPaymentRecord> get _overduePayments => _payments
      .where((p) => rentPaymentStatusLabel(p) == 'متأخرة')
      .toList(growable: false);

  List<PropertyUnitPaymentRecord> get _upcomingPayments => _payments
      .where((p) {
        final label = rentPaymentStatusLabel(p);
        return label == 'مستحقة' || label == 'قادمة';
      })
      .toList(growable: false);

  Future<void> _openPaymentsListSheet(
    String title,
    List<PropertyUnitPaymentRecord> list,
  ) async {
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(AppTheme.rCard),
        ),
      ),
      builder: (sheetContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: DraggableScrollableSheet(
          expand: false,
          initialChildSize: 0.55,
          maxChildSize: 0.9,
          builder: (context, controller) => ListView(
            controller: controller,
            padding: const EdgeInsets.fromLTRB(16, 14, 16, 24),
            children: [
              Text(
                '$title (${list.length})',
                textAlign: TextAlign.right,
                style: const TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w900,
                  color: Color(0xFF022E2A),
                ),
              ),
              const SizedBox(height: 12),
              if (list.isEmpty)
                const Text(
                  'لا توجد عناصر هنا.',
                  textAlign: TextAlign.right,
                  style: TextStyle(fontSize: 11, color: Color(0xFF8C9A97)),
                )
              else
                for (final payment in list)
                  _unitItemRow(
                    icon: Icons.payments_outlined,
                    accent: rentPaymentStatusColor(
                      rentPaymentStatusLabel(payment),
                    ),
                    line1:
                        '${_money(payment.amountDue)} · '
                        '${rentPaymentStatusLabel(payment)}',
                    line2:
                        'استحقاق ${fmtPayDate(payment.dueDate)} · '
                        'مسدد ${_money(payment.amountPaid)}',
                    onTap: () {
                      Navigator.of(sheetContext).pop();
                      _settlePaymentSheet(payment);
                    },
                  ),
            ],
          ),
        ),
      ),
    );
  }

  /// دفعة من أي قائمة في الوحدة تفتح الصفحة الموحّدة نفسها.
  Future<void> _settlePaymentSheet(PropertyUnitPaymentRecord payment) async {
    final repo = widget.repository;
    final contract = _contract;
    if (repo == null || contract == null) return;
    final index = _payments.indexWhere((p) => p.id == payment.id);
    final changed = await openPaymentSettlePage(
      context: context,
      repository: repo,
      entries: [
        RentPaymentEntry(
          contract: contract,
          payment: payment,
          unitName: _unit.name,
          order: index < 0 ? 1 : index + 1,
          totalInContract: _payments.length,
        ),
      ],
    );
    if (changed && mounted) await _load();
  }

  /// «تحصيل دفعة / سداد» من الصندوق: يختار أقرب دفعة غير مسددة.
  Future<void> _collectNextPayment() async {
    final pending = <PropertyUnitPaymentRecord>[
      ..._overduePayments,
      ..._upcomingPayments,
    ];
    if (pending.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('لا توجد دفعات غير مسددة'),
          behavior: SnackBarBehavior.floating,
        ),
      );
      return;
    }
    if (pending.length == 1) {
      await _settlePaymentSheet(pending.first);
      return;
    }
    await _openPaymentsListSheet('اختر الدفعة للتحصيل', pending);
  }

  // ---------------- الرسوم والتأمين: إضافة وسداد ----------------

  Future<void> _addChargeRow(String storeKey, String title) async {
    await _openUnitItemForm(
      title: title,
      fields: const [_kRowItem, _kRowAmount, _kRowDue, _kRowNote],
      numeric: const [_kRowAmount],
      dates: const [_kRowDue],
      multiline: const [_kRowNote],
      onSave: (row) {
        final list = [..._extraList(storeKey)];
        list.add(<String, String>{...row, _kRowPaid: ''});
        _saveExtraList(storeKey, list);
      },
    );
  }

  /// سداد بند رسوم أو تأمين مسجَّل داخل الوحدة.
  Future<void> _settleChargeRow(String storeKey, String title) async {
    final list = _extraList(storeKey);
    final pending = <int>[
      for (var i = 0; i < list.length; i++)
        if (_numOf(list[i][_kRowAmount]) - _numOf(list[i][_kRowPaid]) > 0.009) i,
    ];
    if (pending.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('لا توجد بنود غير مسددة في $title'),
          behavior: SnackBarBehavior.floating,
        ),
      );
      return;
    }
    final index = pending.length == 1
        ? pending.first
        : await showModalBottomSheet<int>(
            context: context,
            backgroundColor: AppTheme.page,
            shape: const RoundedRectangleBorder(
              borderRadius: BorderRadius.vertical(
                top: Radius.circular(AppTheme.rCard),
              ),
            ),
            builder: (sheetContext) => Directionality(
              textDirection: AppTr.uiDir,
              child: SafeArea(
                top: false,
                child: ListView(
                  shrinkWrap: true,
                  padding: const EdgeInsets.fromLTRB(16, 14, 16, 18),
                  children: [
                    Text(
                      'اختر البند المراد سداده',
                      textAlign: TextAlign.right,
                      style: const TextStyle(
                        fontSize: 13,
                        fontWeight: FontWeight.w900,
                        color: Color(0xFF022E2A),
                      ),
                    ),
                    const SizedBox(height: 10),
                    for (final i in pending)
                      _unitItemRow(
                        icon: Icons.receipt_long_outlined,
                        line1:
                            '${list[i][_kRowItem] ?? ''} · '
                            '${_money(_numOf(list[i][_kRowAmount]))}',
                        line2:
                            'متبقٍ '
                            '${_money(_numOf(list[i][_kRowAmount]) - _numOf(list[i][_kRowPaid]))}'
                            '${(list[i][_kRowDue] ?? '').isEmpty ? '' : ' · استحقاق ${_fmtIsoDate(list[i][_kRowDue]!)}'}',
                        onTap: () => Navigator.of(sheetContext).pop(i),
                      ),
                  ],
                ),
              ),
            ),
          );
    if (index == null || !mounted) return;
    final row = list[index];
    final remaining = _numOf(row[_kRowAmount]) - _numOf(row[_kRowPaid]);
    final ctrl = TextEditingController(text: remaining.toStringAsFixed(2));
    final ok = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(AppTheme.rCard),
        ),
      ),
      builder: (sheetContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: Padding(
          padding: EdgeInsets.fromLTRB(
            16,
            16,
            16,
            MediaQuery.of(sheetContext).viewInsets.bottom + 18,
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Text(
                'سداد — ${row[_kRowItem] ?? ''}',
                textAlign: TextAlign.right,
                style: const TextStyle(
                  fontSize: 14,
                  fontWeight: FontWeight.w900,
                  color: Color(0xFF022E2A),
                ),
              ),
              const SizedBox(height: 12),
              TextField(
                controller: ctrl,
                textAlign: AppTr.alignEnd,
                keyboardType: const TextInputType.numberWithOptions(
                  decimal: true,
                ),
                decoration: _propertyInputDecorationShared('المبلغ المسدَّد'),
              ),
              const SizedBox(height: 14),
              FilledButton(
                onPressed: () => Navigator.of(sheetContext).pop(true),
                style: FilledButton.styleFrom(
                  backgroundColor: _kPropertyColor,
                  foregroundColor: Colors.white,
                  minimumSize: const Size.fromHeight(48),
                ),
                child: const Text('تأكيد السداد'),
              ),
            ],
          ),
        ),
      ),
    );
    final amount = _numOf(ctrl.text);
    ctrl.dispose();
    if (ok != true || amount <= 0) return;
    final updated = [...list];
    updated[index] = <String, String>{
      ...row,
      _kRowPaid: (_numOf(row[_kRowPaid]) + amount).toStringAsFixed(2),
    };
    _saveExtraList(storeKey, updated);
  }

