  /// سند قبض أو مطالبة مالية لأي مجموعة بنود.
  void _shareChargesDocument({
    required String title,
    required List<Map<String, String>> rows,
    required bool receipt,
  }) {
    final total = rows.fold<double>(0, (s, r) => s + _numOf(r[_kRowAmount]));
    final paid = rows.fold<double>(0, (s, r) => s + _numOf(r[_kRowPaid]));
    final buffer = StringBuffer()
      ..writeln(receipt ? 'سند قبض' : 'مطالبة مالية')
      ..writeln('البند: $title')
      ..writeln('العقار: ${widget.assetTitle} — ${_unit.name}')
      ..writeln('المستأجر: ${_contract?.tenantName ?? '—'}')
      ..writeln('التاريخ: ${_fmtShortDate(DateTime.now())}')
      ..writeln('');
    for (final row in rows) {
      buffer.writeln(
        '- ${row[_kRowItem] ?? ''}: '
        '${_money(_numOf(row[_kRowAmount]))} '
        '(مسدد ${_money(_numOf(row[_kRowPaid]))})'
        '${(row[_kRowDue] ?? '').isEmpty ? '' : ' — استحقاق ${_fmtIsoDate(row[_kRowDue]!)}'}',
      );
    }
    buffer
      ..writeln('')
      ..writeln('الإجمالي: ${_money(total)}')
      ..writeln('المسدد: ${_money(paid)}')
      ..writeln('المتبقي: ${_money(total - paid)}');
    Share.share(buffer.toString());
  }

  // ---------------- بناء القسم ----------------

  Widget _buildLeaseSection(bool leased) {
    if (!leased) {
      return Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          _unitSectionHead(
            'إدارة الإيجار',
            onAdd: _openContractChoice,
            tooltip: AppTr.tr('تأجير الوحدة'),
          ),
          const SizedBox(height: 10),
          const _DetailHintCard(
            message: 'اضغط + لبدء عملية التأجير وإنشاء عقد.',
          ),
        ],
      );
    }

    final contract = _contract!;
    final active = !_contractClosed(contract);
    // «نشط» لا يكون إلا لعقد مكتمل، فلا حاجة لكلمة «مكتمل»؛ والناقص «مسودة».
    final isDraft =
        contract.status == PropertyUnitContractRecord.statusPending;
    // حالة العقد وحده: ملغي / منتهي / مسودة / نشط. التأخير يخصّ الدفعات
    // ويظهر في صندوقها، لا في حالة العقد.
    final endedByDate = _contractEndedByDate(contract);
    final cancelled = contract.status == _kContractCancelled;
    final statusLabel = cancelled
        ? 'ملغي'
        : !active
        ? 'منتهي'
        : isDraft
        ? 'مسودة'
        : endedByDate
        ? 'منتهي'
        : 'نشط';
    final statusColor = cancelled
        ? const Color(0xFF8C3A32)
