  Widget _buildTabContent(bool leased) {
    switch (_selectedTab) {
      case 0:
        return _buildUnitSummarySection();
      case 1:
        return _buildLeaseSection(leased);
      case 2:
        return _buildFinancialsSection();
      case 3:
        return _buildUnitFollowUpsSection();
      case 4:
        return _buildMaintenanceTab();
      case 5:
        return _buildUnitDocumentsSection();
      case 6:
        return _buildUnitPeopleSection();
      case 7:
        return _buildUnitAssetsSection();
      case 8:
        return _buildUnitChequesSection();
      case 9:
        return _buildUnitNotesSection();
      default:
        return const _ChooseHint();
    }
  }

  String _fmtShortDate(DateTime? d) {
    if (d == null) return '—';
    return '${d.day.toString().padLeft(2, '0')}/${d.month.toString().padLeft(2, '0')}/${d.year}';
  }


}

/// صفحة «عرض / سداد الدفعات» لوحدة واحدة.
///
/// تعيد تحميل بنودها بعد كل سداد، فتتحرّك الحالات أمام المستخدم دون أن
/// يخرج ويعود.
class _UnitPaymentsPage extends StatefulWidget {
  const _UnitPaymentsPage({
    required this.title,
    required this.repository,
    required this.assetTitle,
    required this.initial,
    required this.initialFilter,
    required this.onFilterChanged,
    required this.reload,
  });

  final String title;
  final ProjectAssetsRepository repository;
  final String assetTitle;
  final List<RentPaymentEntry> initial;
  final String initialFilter;
  final ValueChanged<String> onFilterChanged;
  final Future<List<RentPaymentEntry>> Function() reload;

  @override
  State<_UnitPaymentsPage> createState() => _UnitPaymentsPageState();
}

class _UnitPaymentsPageState extends State<_UnitPaymentsPage> {
  late List<RentPaymentEntry> _entries = widget.initial;
  late String _filter = widget.initialFilter;

  Future<void> _refresh() async {
    final next = await widget.reload();
    if (mounted) setState(() => _entries = next);
  }

  @override
  Widget build(BuildContext context) {
    return Directionality(
      textDirection: AppTr.uiDir,
      child: Scaffold(
        backgroundColor: AppTheme.page,
        appBar: AppBar(
          title: Text(
            widget.title,
            style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w900),
          ),
        ),
        body: RefreshIndicator(
          onRefresh: _refresh,
          child: ListView(
            padding: const EdgeInsets.fromLTRB(16, 12, 16, 40),
            children: [
              RentPaymentsView(
                repository: widget.repository,
                assetTitle: widget.assetTitle,
                entries: _entries,
                onChanged: _refresh,
                showUnitName: false,
                filter: _filter,
                onFilterChanged: (value) {
                  setState(() => _filter = value);
                  widget.onFilterChanged(value);
                },
                emptyMessage:
                    'لا توجد دفعات بعد — تُولَّد من دفعات عقد الإيجار ورسومه '
                    'وتأمينه عند حفظه.',
              ),
            ],
          ),
        ),
      ),
    );
  }
}

