/// أيام التذكير من الاختيار (والمخصص بعدده).
int _actReminderDays(String choice, String custom) => switch (choice) {
  'قبل أسبوعين' => 14,
  'قبل شهر' => 30,
  'قبل شهرين' => 60,
  'مخصص' => int.tryParse(custom.trim()) ?? 0,
  _ => 0,
};

/// تذكيرا انتهاء الرخصة ونهاية عقد الإيجار — من شاشة الأنشطة وتفاصيل النشاط.
Future<void> _registerActivityRemindersShared(
  String assetId,
  String title,
  Map<String, String> meta,
) async {
  Future<void> one(
    String id,
    String label,
    String dateKey,
    String choiceKey,
    String daysKey,
  ) async {
    final date = AppRemindersStore.parseDisplayDate(meta[dateKey] ?? '');
    final days = _actReminderDays(meta[choiceKey] ?? '', meta[daysKey] ?? '');
    if (date == null || days <= 0) return;
    await AppRemindersStore.upsert(
      AppReminder(
        id: id,
        title: '$label — $title',
        module: 'الأنشطة التجارية',
        expiryDate: date,
        remindBeforeDays: days,
      ),
    );
  }

  try {
    await one(
      'activity_license_$assetId',
      'انتهاء الرخصة التجارية',
      _ActKeys.licenseEnd,
      _ActKeys.licenseReminder,
      _ActKeys.licenseReminderDays,
    );
    await one(
      'activity_lease_$assetId',
      'نهاية عقد إيجار النشاط',
      _ActKeys.leaseEnd,
      _ActKeys.leaseReminder,
      _ActKeys.leaseReminderDays,
    );
  } catch (_) {
    // التذكير لا يُفشل الإضافة.
  }
}


/// «سنة-شهر-يوم» ← «يوم/شهر/سنة» (والنص غير التاريخ كما هو).
String _isoToDmy(String iso) {
  final date = DateTime.tryParse(iso.trim());
  if (date == null) return iso.trim();
  return '${date.day.toString().padLeft(2, '0')}/'
      '${date.month.toString().padLeft(2, '0')}/${date.year}';
}

/// بيانات النشاط (الرخصة والعقد والتذكيران) من عقد إيجار النشاط — بنفس
/// مفاتيح [_ActKeys]، والتواريخ «يوم/شهر/سنة».
Map<String, String> _activityMetaFromLease(LeaseContractData data) {
  final out = <String, String>{};
  void put(String key, String? value, {bool date = false}) {
    final text = (value ?? '').trim();
    if (text.isEmpty) return;
    out[key] = date ? _isoToDmy(text) : text;
  }

  final l = data.license;
  final c = data.contract;
  put(_ActKeys.legalForm, l[LeaseContractData.kLegalForm]);
  put(_ActKeys.licenseNo, l[LeaseContractData.kLicenseNo]);
  put(_ActKeys.licenseIssue, l[LeaseContractData.kLicenseIssue], date: true);
  put(_ActKeys.licenseEnd, l[LeaseContractData.kLicenseEnd], date: true);
  put(_ActKeys.licenseReminder, l[LeaseContractData.kLicenseReminder]);
  put(_ActKeys.licenseReminderDays, l[LeaseContractData.kLicenseReminderDays]);
  put(_ActKeys.licenseClass, l[LeaseContractData.kLicenseClass]);
  put(_ActKeys.chamber, l[LeaseContractData.kChamber]);
  put(_ActKeys.activities, l[LeaseContractData.kActivities]);
  put(_ActKeys.capital, l[LeaseContractData.kCapital]);
  put(_ActKeys.location, l[LeaseContractData.kActivityLocation]);
  put(_ActKeys.termMode, c[LeaseContractData.kTermMode]);
  put(_ActKeys.leaseNo, c[LeaseContractData.kNewNo]);
  put(_ActKeys.leaseStart, c[LeaseContractData.kStartDate], date: true);
  put(_ActKeys.leaseEnd, c[LeaseContractData.kEndDate], date: true);
  put(_ActKeys.purpose, c[LeaseContractData.kPurpose]);
  put(_ActKeys.tenantClass, c[LeaseContractData.kTenantClass]);
  put(_ActKeys.leaseReminder, l[LeaseContractData.kLeaseReminder]);
  put(_ActKeys.leaseReminderDays, l[LeaseContractData.kLeaseReminderDays]);
  return out;
}

/// العكس: «بيانات الرخصة» لعقد جديد من بيانات النشاط المحفوظة.
Map<String, String> _activityLicenseFromMeta(
  Map<String, String> meta, {
  required String title,
  required String type,
}) {
  final out = <String, String>{};
  void put(String key, String? value, {bool date = false}) {
    final text = (value ?? '').trim();
    if (text.isEmpty || text == 'غير محدد') return;
    out[key] = date ? (_dmyToIso(text).isEmpty ? text : _dmyToIso(text)) : text;
  }

  put(LeaseContractData.kTradeName, title);
  put(LeaseContractData.kActivityClass, type);
  put(LeaseContractData.kLegalForm, meta[_ActKeys.legalForm]);
  put(LeaseContractData.kLicenseNo, meta[_ActKeys.licenseNo]);
  put(LeaseContractData.kLicenseIssue, meta[_ActKeys.licenseIssue], date: true);
  put(LeaseContractData.kLicenseEnd, meta[_ActKeys.licenseEnd], date: true);
  put(LeaseContractData.kLicenseReminder, meta[_ActKeys.licenseReminder]);
  put(
    LeaseContractData.kLicenseReminderDays,
    meta[_ActKeys.licenseReminderDays],
  );
  put(LeaseContractData.kLicenseClass, meta[_ActKeys.licenseClass]);
  put(LeaseContractData.kChamber, meta[_ActKeys.chamber]);
  put(LeaseContractData.kActivities, meta[_ActKeys.activities]);
  put(LeaseContractData.kCapital, meta[_ActKeys.capital]);
  put(LeaseContractData.kActivityLocation, meta[_ActKeys.location]);
  put(LeaseContractData.kLeaseReminder, meta[_ActKeys.leaseReminder]);
  put(LeaseContractData.kLeaseReminderDays, meta[_ActKeys.leaseReminderDays]);
  return out;
}

/// «يوم/شهر/سنة» ← «سنة-شهر-يوم» لعقد الإيجار.
String _dmyToIso(String dmy) {
  final date = AppRemindersStore.parseDisplayDate(dmy);
  if (date == null) return '';
  return '${date.year.toString().padLeft(4, '0')}-'
      '${date.month.toString().padLeft(2, '0')}-'
      '${date.day.toString().padLeft(2, '0')}';
}

