    final activities = _activityLines
        .map((c) => c.text.trim())
        .where((line) => line.isNotEmpty)
        .join('\n');
    final meta = <String, String>{
      _ActKeys.termMode: _termMode ?? '',
      _ActKeys.leaseNo: _leaseNoCtrl.text.trim(),
      _ActKeys.leaseStart: _leaseStartCtrl.text.trim(),
      _ActKeys.leaseEnd: _leaseEndCtrl.text.trim(),
      _ActKeys.purpose: _purpose ?? '',
      _ActKeys.tenantClass: _tenantClass ?? '',
      _ActKeys.leaseReminder: _leaseReminder,
      if (_leaseReminder == 'مخصص')
