      _ActKeys.legalForm: _legalForm ?? '',
      _ActKeys.licenseNo: _licenseNumberCtrl.text.trim(),
      _ActKeys.licenseIssue: _licenseIssueCtrl.text.trim(),
      _ActKeys.licenseEnd: _licenseExpiryCtrl.text.trim(),
      _ActKeys.licenseReminder: _licenseReminder,
      if (_licenseReminder == 'مخصص')
        _ActKeys.licenseReminderDays: _licenseReminderDaysCtrl.text.trim(),
      _ActKeys.licenseClass: _licenseClass ?? '',
      _ActKeys.chamber: _chamberCtrl.text.trim(),
      _ActKeys.activities: activities,
      _ActKeys.capital: _capitalCtrl.text.trim(),
    }..removeWhere((key, value) => value.isEmpty);
    final draft = _ActivityDraft(
      meta: meta,
      name: _nameCtrl.text.trim(),
      activityType: _activityType,
      licenseNumber: _licenseNumberCtrl.text.trim(),
      licenseExpiry: _licenseExpiryCtrl.text.trim(),
