// "إضافة معدة" الجديدة — نفس القالب البصري، بحقول تقنية مبنية على
// المتطلبات المنطقية لتتبع أي معدة (رقم تسلسلي، ضمان، مورد، حالة).
// ============================================================

const List<String> _equipmentConditionOptions = ['تعمل', 'تحت الصيانة', 'متوقفة'];

/// تذكير قبل الانتهاء: فترة جاهزة أو «مخصص» بعدد أيام.
const List<String> _equipReminderOptions = [
  'قبل يوم',
  'قبل 3 أيام',
  'قبل أسبوع',
  'قبل شهر',
  'مخصص',
];

/// على من: الصيانة، الوقود، نقل المعدة.
const List<String> _equipPartyOptions = [
  'على المالك',
  'على المستأجر',
  'مناصفة بين الاثنين',
];

/// أيام التذكير من الاختيار (والمخصص من عدد الأيام المكتوب).
int _equipReminderDays(String option, String customDays) {
  if (option == 'مخصص') return int.tryParse(customDays.trim()) ?? 0;
  return AppRemindersStore.reminderDaysFromLabel(option);
}

class _EquipmentDraft {
  const _EquipmentDraft({
    required this.name,
    required this.equipmentType,
    required this.serialNumber,
    required this.meta,
    this.annexes = const {},
  });

  /// إكسسوارات المركبة (النوع ← العدد) — تظهر في «إكسسوارات المركبات».
  final Map<String, int> annexes;

  /// «اسم المعدة / الآلية».
  final String name;

  /// «موديل المعدة / نوعها / حجمها».
  final String equipmentType;

  /// «رقم الشاصي / الرقم التسلسلي».
  final String serialNumber;

  /// بقية البيانات — تُحفظ مع بيانات الأصل نفسه.
  final Map<String, String> meta;
}

