};

/// كل الأنواع (لفلتر الفئات الفرعية).
List<String> get _allVehicleTypes => [
  for (final type in _vehicleTypes[_kVehicleLand]!)
    if (type != 'أخرى') type,
  for (final type in _vehicleTypes[_kVehicleMarine]!)
    if (type != 'أخرى') type,
  'أخرى',
];

/// أيقونة مركبة بعينها: من نوعها، والسجلات القديمة أيقونة المعدات.
IconData _vehicleIconOf(_AssetItem item) {
  final type = (item.propertyMeta[_EquipKeys.vehicleType] ?? '').trim();
  return type.isEmpty
      ? Icons.precision_manufacturing_rounded
      : _vehicleTypeIcon(type);
}

IconData _vehicleTypeIcon(String type) => switch (type) {
  'سيارة صغيرة' => Icons.directions_car_rounded,
  'دفع رباعي' => Icons.airport_shuttle_rounded,
  'بيك أب' => Icons.local_shipping_outlined,
  'حافلة' => Icons.directions_bus_rounded,
  'شاحنة' => Icons.local_shipping_rounded,
  'دراجة نارية' => Icons.two_wheeler_rounded,
  'معدات خفيفة' => Icons.handyman_rounded,
  'معدات متوسطة' => Icons.construction_rounded,
  'معدات ثقيلة' => Icons.precision_manufacturing_rounded,
  'قارب' => Icons.directions_boat_outlined,
  'طراد' => Icons.directions_boat_rounded,
  'يخت' => Icons.sailing_rounded,
  'جت سكي' => Icons.surfing_rounded,
  'قارب صيد' => Icons.phishing_rounded,
  'عبّارة / سفينة' => Icons.directions_ferry_rounded,
  _ => Icons.category_outlined,
};

/// منتقي «المركبات ووسائل النقل» بنفس شكل تصنيفات الالتزامات الشخصية:
/// التصنيف الرئيسي أولًا (برية / بحرية)، ثم نوعه.
Future<(String, String)?> _pickVehicleType(BuildContext context) {
  return showModalBottomSheet<(String, String)>(
    context: context,
    isScrollControlled: true,
    backgroundColor: Colors.transparent,
    builder: (sheetContext) {
      String? group;
      return StatefulBuilder(
        builder: (context, setSheet) {
          final isMarine = group == _kVehicleMarine;
          final color = isMarine
              ? const Color(0xFF178F7B)
              : const Color(0xFF0E7161);
          Widget header(String title, String subtitle, {Widget? leading}) =>
              Row(
                textDirection: AppTr.uiDir,
                children: [
                  if (leading != null) ...[leading, const SizedBox(width: 10)],
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          title,
                          style: const TextStyle(
                            fontSize: 19,
                            fontWeight: FontWeight.w800,
                            color: Color(0xFF022E2A),
                          ),
                        ),
                        const SizedBox(height: 4),
                        Text(
                          subtitle,
                          style: const TextStyle(
                            fontSize: 12.5,
                            fontWeight: FontWeight.w600,
                            color: Color(0xFF5C6B68),
                          ),
                        ),
                      ],
                    ),
                  ),
                  InkWell(
                    onTap: () => Navigator.pop(sheetContext),
                    borderRadius: BorderRadius.circular(20),
                    child: Container(
                      padding: const EdgeInsets.all(6),
                      decoration: const BoxDecoration(
                        color: Color(0xFFF2F6F5),
                        shape: BoxShape.circle,
                      ),
                      child: const Icon(
                        Icons.close_rounded,
                        size: 22,
                        color: Color(0xFF46534F),
                      ),
                    ),
                  ),
                ],
              );

          Widget tile({
            required IconData icon,
            required String title,
            String? subtitle,
            required Color tint,
            required VoidCallback onTap,
          }) => Material(
            color: Colors.white,
            borderRadius: BorderRadius.circular(16),
            child: InkWell(
              onTap: onTap,
              borderRadius: BorderRadius.circular(16),
              child: Container(
                padding: const EdgeInsets.all(10),
                decoration: BoxDecoration(
                  borderRadius: BorderRadius.circular(16),
                  border: Border.all(color: const Color(0xFFE4EAE8)),
                ),
                child: Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                    Container(
                      width: 46,
                      height: 46,
                      decoration: BoxDecoration(
                        color: tint,
                        borderRadius: BorderRadius.circular(12),
                        boxShadow: [
                          BoxShadow(
                            color: tint.withValues(alpha: 0.35),
                            blurRadius: 10,
                            offset: const Offset(0, 4),
                          ),
                        ],
                      ),
                      child: Icon(icon, color: Colors.white, size: 24),
                    ),
                    const SizedBox(height: 8),
                    Text(
                      title,
                      textAlign: TextAlign.center,
                      maxLines: 4,
                      style: const TextStyle(
                        fontSize: 12.5,
                        fontWeight: FontWeight.w900,
                        color: Color(0xFF022E2A),
                        height: 1.2,
                      ),
                    ),
                    if (subtitle != null) ...[
                      const SizedBox(height: 4),
                      Text(
                        subtitle,
                        textAlign: TextAlign.center,
                        maxLines: 4,
                        style: const TextStyle(
                          fontSize: 10.5,
                          fontWeight: FontWeight.w600,
                          color: Color(0xFF5C6B68),
                          height: 1.25,
                        ),
                      ),
                    ],
                  ],
                ),
              ),
            ),
          );

          final body = group == null
              ? GridView.count(
                  crossAxisCount: 2,
                  mainAxisSpacing: 10,
                  crossAxisSpacing: 10,
                  childAspectRatio: 0.95,
                  children: [
                    if (!_assetTypeHidden('equipment', _kVehicleLand))
                    tile(
                      icon: Icons.directions_car_rounded,
                      title: _kVehicleLand,
                      subtitle: 'سيارات وحافلات وشاحنات ومعدات',
                      tint: const Color(0xFF0E7161),
                      onTap: () => setSheet(() => group = _kVehicleLand),
                    ),
                    if (!_assetTypeHidden('equipment', _kVehicleMarine))
                    tile(
                      icon: Icons.directions_boat_rounded,
                      title: _kVehicleMarine,
                      subtitle: 'قوارب وطرادات ويخوت',
                      tint: const Color(0xFF178F7B),
                      onTap: () => setSheet(() => group = _kVehicleMarine),
                    ),
                  ],
                )
              : GridView.count(
                  crossAxisCount: 3,
                  mainAxisSpacing: 8,
                  crossAxisSpacing: 8,
                  childAspectRatio: 0.8,
                  children: [
                    for (final type in _vehicleTypes[group]!)
                      if (!_assetTypeHidden('equipment', type))
                      tile(
                        icon: _vehicleTypeIcon(type),
                        title: type,
                        tint: color,
                        onTap: () =>
                            Navigator.pop(sheetContext, (group!, type)),
                      ),
                  ],
                );

          return Container(
            height: MediaQuery.of(context).size.height * 0.72,
            decoration: const BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.vertical(
                top: Radius.circular(AppTheme.rCard),
              ),
            ),
            child: Directionality(
              textDirection: AppTr.uiDir,
              child: Padding(
                padding: const EdgeInsets.fromLTRB(16, 12, 16, 16),
                child: Column(
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Center(
                      child: Container(
                        width: 44,
                        height: 5,
                        decoration: BoxDecoration(
                          color: const Color(0xFFE4EAE8),
                          borderRadius: BorderRadius.circular(999),
                        ),
                      ),
                    ),
                    const SizedBox(height: 16),
                    group == null
                        ? header(
                            'المركبات ووسائل النقل',
                            'اختر التصنيف ثم نوع المركبة',
                          )
                        : header(
                            group!,
                            'اختر نوع المركبة',
                            leading: IconButton(
                              tooltip: AppTr.tr('رجوع'),
                              onPressed: () => setSheet(() => group = null),
                              icon: const Icon(
                                Icons.arrow_back_ios_new_rounded,
                                size: 18,
                              ),
                            ),
                          ),
                    const SizedBox(height: 16),
                    Expanded(
                      child: Container(
                        padding: const EdgeInsets.all(10),
                        decoration: BoxDecoration(
                          color: AppTheme.surface,
                          borderRadius: BorderRadius.circular(AppTheme.rField),
                        ),
                        child: body,
                      ),
                    ),
                  ],
                ),
              ),
            ),
          );
        },
      );
    },
  );
}

