class _AddEquipmentScreen extends StatefulWidget {
  const _AddEquipmentScreen({
    this.initial,
    this.vehicleClass,
    this.vehicleType,
  });

  /// عند التعديل: بيانات المركبة الحالية.
  final _EquipmentDraft? initial;

  /// التصنيف (مركبات برية / بحرية) والنوع المختاران عند الإضافة.
  final String? vehicleClass;
  final String? vehicleType;

  @override
  State<_AddEquipmentScreen> createState() => _AddEquipmentScreenState();
}

class _AddEquipmentScreenState extends State<_AddEquipmentScreen> {
  final Map<String, TextEditingController> _c = {};
  final Map<String, String> _choice = {};

  /// إكسسوارات المركبة: نوع الإكسسوار والعدد في كل سطر.
  late final List<({TextEditingController name, TextEditingController count})>
  _accessories = [
    for (final entry
        in (widget.initial?.annexes ?? const <String, int>{}).entries)
      (
        name: TextEditingController(text: entry.key),
        count: TextEditingController(text: '${entry.value}'),
      ),
    if ((widget.initial?.annexes ?? const <String, int>{}).isEmpty)
      (name: TextEditingController(), count: TextEditingController()),
  ];

  /// «إرفاق مستندات أخرى»: مسارات الملفات المرفقة.
  late final List<String> _otherDocs = [
    for (final line in (widget.initial?.meta[_EquipKeys.otherDocs] ?? '')
        .split('\n'))
      if (line.trim().isNotEmpty) line.trim(),
  ];

  TextEditingController _ctrl(String key) => _c.putIfAbsent(
    key,
    () => TextEditingController(text: widget.initial?.meta[key] ?? ''),
  );

  late final TextEditingController _nameCtrl = TextEditingController(
    text: widget.initial?.name ?? '',
  );
  late final TextEditingController _typeCtrl = TextEditingController(
    text: widget.initial?.equipmentType ?? '',
  );
  late final TextEditingController _serialCtrl = TextEditingController(
    text: widget.initial?.serialNumber ?? '',
  );

  /// التصنيف والنوع: من الاختيار عند الإضافة، أو من بيانات المركبة.
  /// السجلات القديمة (قبل التصنيف) معدات برية.
  late final String _vehicleClass =
      widget.vehicleClass ??
      widget.initial?.meta[_EquipKeys.vehicleClass] ??
      _kVehicleLand;
  late final String _vehicleType =
      widget.vehicleType ?? widget.initial?.meta[_EquipKeys.vehicleType] ?? '';

  bool get _isMarine => _vehicleClass == _kVehicleMarine;

  /// معدات (خفيفة/متوسطة/ثقيلة) أو سجل قديم بلا نوع.
  bool get _isEquipment =>
      !_isMarine && (_vehicleType.isEmpty || _vehicleType.startsWith('معدات'));

  /// سيارة/حافلة/شاحنة/دراجة.
  bool get _isRoadVehicle => !_isMarine && !_isEquipment;

  String _pick(String key, String fallback) =>
      _choice[key] ??
      ((widget.initial?.meta[key] ?? '').isEmpty
          ? fallback
          : widget.initial!.meta[key]!);

  @override
  void dispose() {
    _nameCtrl.dispose();
    _typeCtrl.dispose();
    _serialCtrl.dispose();
    for (final controller in _c.values) {
      controller.dispose();
    }
    for (final row in _accessories) {
      row.name.dispose();
      row.count.dispose();
    }
    super.dispose();
  }

  Future<void> _pickDate(TextEditingController controller) async {
    final date = await showDatePicker(
      context: context,
      initialDate: DateTime.now(),
      firstDate: DateTime(2000),
      lastDate: DateTime(2070),
    );
    if (date != null) {
      setState(
        () => controller.text = '${date.day}/${date.month}/${date.year}',
      );
    }
  }

  Future<void> _pickTime(TextEditingController controller) async {
    final time = await showTimePicker(
      context: context,
      initialTime: TimeOfDay.now(),
    );
    if (time != null) {
      setState(
        () => controller.text =
            '${time.hour.toString().padLeft(2, '0')}:'
            '${time.minute.toString().padLeft(2, '0')}',
      );
    }
  }

  Future<void> _attach(String key) async {
    final path = await DocumentStore.pickAndStore(context: context);
    if (path == null || !mounted) return;
    setState(() => _ctrl(key).text = path);
  }

  Future<void> _attachOther() async {
    final path = await DocumentStore.pickAndStore(context: context);
    if (path == null || !mounted) return;
    setState(() => _otherDocs.add(path));
  }

  /// «مخصص»: نافذة صغيرة يُكتب فيها عدد الأيام.
  Future<void> _askCustomDays(String reminderKey, String customKey) async {
    final ctrl = TextEditingController(text: _ctrl(customKey).text);
    final days = await showDialog<String>(
      context: context,
      builder: (dialogContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: AlertDialog(
          title: const Text('تذكير مخصص'),
          content: TextField(
            controller: ctrl,
            autofocus: true,
            keyboardType: TextInputType.number,
            textAlign: AppTr.alignEnd,
            decoration: _propertyInputDecoration('عدد الأيام قبل الانتهاء'),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(dialogContext),
              child: const Text('إلغاء'),
            ),
            FilledButton(
              onPressed: () => Navigator.pop(dialogContext, ctrl.text.trim()),
              child: const Text('حفظ'),
            ),
          ],
        ),
      ),
    );
    Future.delayed(const Duration(milliseconds: 400), ctrl.dispose);
    if (!mounted) return;
    final value = int.tryParse(days ?? '');
    if (value == null || value <= 0) {
      // بلا عدد صحيح: يبقى الاختيار السابق.
      setState(() {});
      return;
    }
    setState(() {
      _choice[reminderKey] = 'مخصص';
      _ctrl(customKey).text = '$value';
    });
  }

  /// كل ما أُدخل في النموذج للمراجعة قبل الحفظ.
  List<(String, String)> _reviewRows(Map<String, String> meta) {
    String show(String key, String value) {
      final text = value.trim();
      // مرفق: اسم الملف فقط لا مساره (التواريخ 22/10/2026 تبقى كما هي).
      if ((text.contains('/') || text.contains('\\')) &&
          RegExp(r'\.[A-Za-z0-9]{2,5}$').hasMatch(text)) {
        return text.split(RegExp(r'[\\/]')).last;
      }
      return text;
    }

    final rows = <(String, String)>[
      ('تصنيف المركبة', _vehicleClass),
      if (_vehicleType.isNotEmpty) ('نوع المركبة', _vehicleType),
      ('الاسم', _nameCtrl.text.trim()),
      if (_typeCtrl.text.trim().isNotEmpty) ('الموديل', _typeCtrl.text.trim()),
      if (_serialCtrl.text.trim().isNotEmpty)
        (
          _isMarine ? 'رقم الهيكل (HIN)' : 'رقم الشاصي / الرقم التسلسلي',
          _serialCtrl.text.trim(),
        ),
    ];
    const skip = {
      _EquipKeys.vehicleClass,
      _EquipKeys.vehicleType,
      _EquipKeys.model,
      _EquipKeys.otherDocs,
    };
    meta.forEach((key, value) {
      if (skip.contains(key) || value.trim().isEmpty) return;
      rows.add((key, show(key, value)));
    });
    for (final row in _accessories) {
      final name = row.name.text.trim();
      if (name.isEmpty) continue;
      rows.add(('إكسسوار', '$name × ${row.count.text.trim().isEmpty ? '1' : row.count.text.trim()}'));
    }
    if (_otherDocs.isNotEmpty) {
      rows.add(('مستندات أخرى', '${_otherDocs.length}'));
    }
    return rows;
  }

  Future<void> _submit() async {
    if (_nameCtrl.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('أدخل اسم المركبة')),
      );
      return;
    }
    // رقم التواصل والبريد الإلكتروني إلزاميان.
    final missing = [
      if (_ctrl(_EquipKeys.contactPhone).text.trim().isEmpty) 'رقم التواصل',
      if (_ctrl(_EquipKeys.contactEmail).text.trim().isEmpty)
        'البريد الإلكتروني',
    ];
    if (missing.isNotEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('أكمل: ${missing.join('، ')}')),
      );
      return;
    }
    final meta = <String, String>{
      // بيانات سابقة غير موجودة في هذا النموذج تبقى كما هي.
      ...?widget.initial?.meta,
      for (final entry in _c.entries) entry.key: entry.value.text.trim(),
      _EquipKeys.ownershipReminder: _pick(
        _EquipKeys.ownershipReminder,
        'قبل شهر',
      ),
      _EquipKeys.warrantyReminder: _pick(_EquipKeys.warrantyReminder, 'قبل شهر'),
      if (!_isEquipment)
        _EquipKeys.insuranceReminder: _pick(
          _EquipKeys.insuranceReminder,
          'قبل شهر',
        ),
      _EquipKeys.vehicleClass: _vehicleClass,
      _EquipKeys.vehicleType: _vehicleType,
      _EquipKeys.model: _typeCtrl.text.trim(),
      _EquipKeys.otherDocs: _otherDocs.join('\n'),
    }..removeWhere((key, value) => value.isEmpty);
    // الإكسسوارات: النوع ← العدد (الأسطر الفارغة تُترك).
    final annexes = <String, int>{};
    for (final row in _accessories) {
      final name = row.name.text.trim();
      if (name.isEmpty) continue;
      final count = int.tryParse(row.count.text.trim()) ?? 1;
      annexes[name] = (annexes[name] ?? 0) + (count < 1 ? 1 : count);
    }
    // كل المعلومات أمام المستخدم، ثم «هل أنت متأكد؟» قبل الحفظ.
    final editing = widget.initial != null;
    final ok = await _confirmUnitEntry(
      context,
      'المركبة',
      _reviewRows(meta),
      title: editing ? 'مراجعة تعديل المركبة' : 'مراجعة المركبة قبل الإضافة',
      question: editing
          ? 'هل أنت متأكد من حفظ التعديل بهذه البيانات؟'
          : 'هل أنت متأكد من إضافة المركبة بهذه البيانات؟',
      confirmLabel: editing ? 'نعم، احفظ التعديل' : 'نعم، أضف المركبة',
    );
    if (!ok || !mounted) return;
    Navigator.of(context).pop(
      _EquipmentDraft(
        name: _nameCtrl.text.trim(),
        equipmentType: _typeCtrl.text.trim(),
        serialNumber: _serialCtrl.text.trim(),
        meta: meta,
        annexes: annexes,
      ),
    );
  }

  // ---------------- عناصر النموذج ----------------

  Widget _title(String text) => Padding(
    padding: const EdgeInsets.only(top: 18, bottom: 10),
    child: Row(
      textDirection: AppTr.uiDir,
      children: [
        Container(
          width: 4,
          height: 18,
          margin: const EdgeInsetsDirectional.only(end: 8),
          decoration: BoxDecoration(
            color: AppTheme.gold,
            borderRadius: BorderRadius.circular(AppTheme.rPill),
          ),
        ),
        Expanded(
          child: Text(
            text,
            style: const TextStyle(
              fontSize: 14,
              fontWeight: FontWeight.w900,
              color: Color(0xFF022E2A),
            ),
          ),
        ),
      ],
    ),
  );

  Widget _text(
    String label,
    TextEditingController controller, {
    bool numeric = false,
    String hint = '',
    bool required = false,
  }) => Column(
    crossAxisAlignment: CrossAxisAlignment.stretch,
    children: [
      _propertyFieldLabel(label, required: required),
      const SizedBox(height: 6),
      TextField(
        controller: controller,
        textAlign: AppTr.alignEnd,
        keyboardType: numeric ? TextInputType.number : TextInputType.text,
        decoration: _propertyInputDecoration(hint),
      ),
    ],
  );

  Widget _picker(
    String label,
    TextEditingController controller,
    String hint,
    IconData icon,
    VoidCallback onTap,
  ) => Column(
    crossAxisAlignment: CrossAxisAlignment.stretch,
    children: [
      _propertyFieldLabel(label),
      const SizedBox(height: 6),
      TextField(
        controller: controller,
        readOnly: true,
