        textAlign: AppTr.alignEnd,
        // بعد الاختيار: زر × يمسح التاريخ (كلها اختيارية في نموذج المركبة).
        decoration: _propertyInputDecoration(hint).copyWith(
          suffixIcon: ValueListenableBuilder<TextEditingValue>(
            valueListenable: controller,
            builder: (context, value, _) => value.text.trim().isEmpty
                ? Icon(icon, size: 19)
                : clearDateSuffix(
                    controller,
                    onCleared: () => setState(() {}),
                  ),
          ),
        ),
      ),
    ],
  );

  Widget _date(String label, TextEditingController controller) => _picker(
    label,
    controller,
    'التاريخ',
    Icons.event_rounded,
    () => _pickDate(controller),
  );

  /// قائمة منسدلة ▼ — و«مخصص» يفتح نافذة عدد الأيام.
  Widget _dropdown(
    String label,
    String key,
    List<String> options,
    String def, {
    String? customKey,
  }) {
    final current = options.contains(_pick(key, def)) ? _pick(key, def) : def;
    final customDays = customKey == null ? '' : _ctrl(customKey).text.trim();
    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        _propertyFieldLabel(label),
        const SizedBox(height: 6),
        DropdownButtonFormField<String>(
          key: ValueKey('$key-$current-$customDays'),
          initialValue: current,
          isExpanded: true,
          decoration: _propertyInputDecoration(''),
          items: [
            for (final option in options)
              DropdownMenuItem(
                value: option,
                child: Text(
                  option == 'مخصص' && customDays.isNotEmpty
                      ? 'مخصص ($customDays يوم)'
                      : option,
                ),
              ),
          ],
          onChanged: (value) {
            if (value == null) return;
            if (value == 'مخصص' && customKey != null) {
              _askCustomDays(key, customKey);
              return;
            }
            setState(() => _choice[key] = value);
          },
        ),
      ],
    );
  }

