/// تذكيرات الآلية/المعدة: انتهاء الملكية والضمان والشهادات، ونهاية شهر
/// التشغيل — في مركز التذكيرات نفسه الذي تستعمله المستندات.
Future<void> _syncEquipmentReminders(String name, Map<String, String> meta) async {
  final base = 'equip-${name.hashCode}';
  Future<void> one(String id, String title, DateTime? date, int days) async {
    if (date == null) {
      await AppRemindersStore.remove('$base-$id');
      return;
    }
    await AppRemindersStore.upsert(
      AppReminder(
        id: '$base-$id',
        title: '$name — $title',
        module: 'المركبات ووسائل النقل',
        expiryDate: date,
        remindBeforeDays: days,
      ),
    );
  }

  DateTime? dateOf(String key) =>
      AppRemindersStore.parseDisplayDate(meta[key] ?? '');

  await one(
    'owner',
    'انتهاء الملكية',
    dateOf(_EquipKeys.ownershipEnd),
    _equipReminderDays(
      meta[_EquipKeys.ownershipReminder] ?? '',
      meta[_EquipKeys.ownershipCustom] ?? '',
    ),
  );
  await one(
    'warranty',
    'انتهاء الضمان',
    dateOf(_EquipKeys.warrantyEnd),
    _equipReminderDays(
      meta[_EquipKeys.warrantyReminder] ?? '',
      meta[_EquipKeys.warrantyCustom] ?? '',
    ),
  );
  await one(
    'insurance',
    'انتهاء التأمين',
    dateOf(_EquipKeys.insuranceEnd),
    _equipReminderDays(
      meta[_EquipKeys.insuranceReminder] ?? '',
      meta[_EquipKeys.insuranceCustom] ?? '',
    ),
  );
  // الشهادتان: التذكير المختار (الافتراضي قبل شهر)، أو بلا تذكير.
  int certDays(String key) {
    final value = meta[key] ?? '';
    return value.isEmpty ? 30 : _equipReminderDays(value, '');
  }

  DateTime? certDate(String endKey, String reminderKey) =>
      meta[reminderKey] == 'بلا تذكير' ? null : dateOf(endKey);
  await one(
    'safety',
    'شهادة السلامة',
    certDate(_EquipKeys.safetyCertEnd, _EquipKeys.safetyCertReminder),
    certDays(_EquipKeys.safetyCertReminder),
  );
  await one(
    'operator',
    'شهادة المشغل',
    certDate(_EquipKeys.operatorCertEnd, _EquipKeys.operatorCertReminder),
    certDays(_EquipKeys.operatorCertReminder),
  );
  // شهادة الضمان من النموذج السابق — تبقى إن كانت محفوظة.
  await one('wcert', 'شهادة الضمان', dateOf(_EquipKeys.warrantyCertEnd), 30);

  // التشغيل الشهري: تذكير قبل نهاية الشهر الجاري من تاريخ بدء المشروع.
  DateTime? monthEnd;
  if ((meta[_EquipKeys.operation] ?? '') == 'شهري') {
    final start = dateOf(_EquipKeys.projectStart) ?? DateTime.now();
    final today = DateTime.now();
    var next = DateTime(start.year, start.month + 1, start.day);
    while (!next.isAfter(today)) {
      next = DateTime(next.year, next.month + 1, next.day);
    }
    monthEnd = next;
  }
  await one(
    'month',
    'نهاية شهر التشغيل',
    monthEnd,
    _equipReminderDays(
      meta[_EquipKeys.monthReminder] ?? '',
      meta[_EquipKeys.monthCustom] ?? '',
    ),
  );
}

/// مفتاح عقود الآليات/المعدات في جدول العقود (بدل مفتاح الوحدة).
const String _kEquipUnitKey = 'equipment';

/// سجل «التأجير المباشر» للمركبة: دفعات بالساعة أو اليوم بلا عقد.
const String _kEquipWalkInKey = 'equipment_walkin';

/// عقد مركبة محفوظ بنموذج عقد الإيجار الكامل (لا بالنموذج القديم المختصر).
bool _isLeaseContract(PropertyUnitContractRecord contract) {
  final notes = contract.notes ?? '';
  return notes.contains('"__lease__"') && !notes.contains('"__equip__"');
}

/// طريقة التأجير في العقد.
const List<String> _kEquipRentBases = ['شهري', 'يومي', 'بالساعات'];

String _equipRatePer(String basis) => switch (basis) {
  'يومي' => 'يوم',
  'بالساعات' => 'ساعة',
  _ => 'شهر',
};

/// بيانات عقد الآلية المحفوظة في ملاحظات العقد: الأساس والمبلغ والملاحظة.
Map<String, String> _equipContractExtra(PropertyUnitContractRecord contract) {
  final text = (contract.notes ?? '').trim();
  if (!text.startsWith('{')) {
    return <String, String>{if (text.isNotEmpty) 'note': text};
  }
  try {
    final decoded = jsonDecode(text);
    if (decoded is! Map) return <String, String>{};
    final out = <String, String>{};
    decoded.forEach((key, value) {
      if (key == '__equip__') return;
      out['$key'] = '${value ?? ''}'.trim();
    });
    return out;
  } catch (_) {
    return <String, String>{};
  }
}

/// عدد الأشهر من بداية العقد حتى نهايته (لتوليد الدفعات الشهرية).
int _equipMonthsBetween(DateTime start, DateTime? end) {
  if (end == null || !end.isAfter(start)) return 0;
  var months = 0;
  var cursor = start;
  while (cursor.isBefore(end) && months < 120) {
    months++;
    cursor = DateTime(start.year, start.month + months, start.day);
  }
  return months;
}

// ============================================================
// شاشة "إضافة الوحدات والمرافق العامة" — حسب ملف "ادخال الوحدات":
// القائمة على اليمين ثابتة (أنواع الوحدات ثم المرافق العامة)، والضغط على
// أي بند يفتح نموذجه في اللوحة على اليسار. لكل نوع زر حفظ خاص به، ومسودة
// تُحفظ تلقائيًا كل دقيقتين حتى لا تضيع الإدخالات الكثيرة.
// ============================================================

const List<String> _kFacilityLabels = [
  'مواقف سيارات عامة',
  'المصعد',
  'الدرج',
  'المداخل / اللوبي',
  'الممرات',
  'السطح',
  'الحوش / الساحة',
  'غرفة الحارس',
  'غرفة الكهرباء',
  'غرفة الاتصالات',
  'غرفة المياه والمضخات',
  'خزانات المياه',
  'غرفة النفايات',
  'النادي الرياضي',
  'المسبح',
  'غرفة الخدمات',
  'أخرى',
];

/// تاريخ الأصل بصيغة سنة-شهر-يوم للخادم، من يوم/شهر/سنة أو سنة/شهر/يوم.
String? _isoAssetDate(String raw) {
  final text = raw.trim();
  if (text.isEmpty) return null;
  final parts = text.split(RegExp(r'[/-]'));
  if (parts.length != 3) return null;
  final a = int.tryParse(parts[0]);
  final b = int.tryParse(parts[1]);
  final c = int.tryParse(parts[2].split(' ').first);
  if (a == null || b == null || c == null) return null;
  final d = a > 31 ? DateTime(a, b, c) : DateTime(c, b, a);
  String two(int v) => v.toString().padLeft(2, '0');
  return '${d.year}-${two(d.month)}-${two(d.day)}';
}

/// أول رقم متاح لنوع وحدة: بعد أكبر رقم موجود منه (1 إن لم يوجد) — فلا
/// تُنشأ «شقة 1» مرة ثانية بنفس هوية الموجودة.
int _nextUnitNumber(Iterable<_PropertyUnit> units, String type) {
  var max = 0;
  for (final unit in units) {
    if (unit.type != type) continue;
    final n = int.tryParse(unit.unitNumber.trim()) ?? 0;
    if (n > max) max = n;
  }
  return max + 1;
}

/// الوحدات الجديدة التي لها هوية وحدة موجودة (النوع والاسم والرقم) — تشترك
/// معها في العقود والدفعات والصيانة إن أُضيفت.
List<String> _duplicateUnitNames(
  Iterable<_PropertyUnit> existing,
  String type,
  String baseName,
  int first,
  int count,
) {
  final keys = {for (final unit in existing) unit.unitKey};
  return [
    for (var i = 0; i < count; i++)
      if (keys.contains(
        '$type|${count == 1 ? baseName : '$baseName ${first + i}'}|${first + i}',
      ))
        count == 1 ? baseName : '$baseName ${first + i}',
  ];
}

/// حقول نموذج نوع واحد (وحدة أو مرفق) — تبقى حيّة عند التنقل بين الأنواع.
class _UnitEntryForm {
  final count = TextEditingController();
  final name = TextEditingController();
  final firstNumber = TextEditingController(text: '1');

  /// نهاية مدى الترقيم التلقائي: «من 1 إلى 30» يولّد 30 وحدة دفعة واحدة.
  final lastNumber = TextEditingController();
  final area = TextEditingController();
  final rooms = TextEditingController();
  final halls = TextEditingController();
  final balconies = TextEditingController();
  final bathrooms = TextEditingController();
  final parking = TextEditingController();
  final notes = TextEditingController();
  bool quickAdd = true;

  /// عدد عدادات الكهرباء والمياه وأرقامها.
  final Map<String, TextEditingController> meters = _meterControllers();

  void dispose() {
    for (final controller in [...controllers, ...meters.values]) {
      Future.delayed(const Duration(milliseconds: 600), controller.dispose);
    }
  }

  List<TextEditingController> get controllers => [
    count,
    name,
    firstNumber,
    lastNumber,
    area,
    rooms,
    halls,
    balconies,
    bathrooms,
    parking,
    notes,
  ];

  Map<String, dynamic> toDraft() => {
    'count': count.text,
    'name': name.text,
    'firstNumber': firstNumber.text,
    'lastNumber': lastNumber.text,
    'area': area.text,
    'rooms': rooms.text,
    'halls': halls.text,
    'balconies': balconies.text,
    'bathrooms': bathrooms.text,
    'parking': parking.text,
    'notes': notes.text,
    'quickAdd': quickAdd,
  };

  void restore(Map<String, dynamic> draft) {
    count.text = (draft['count'] ?? '').toString();
    name.text = (draft['name'] ?? '').toString();
    firstNumber.text = (draft['firstNumber'] ?? '1').toString();
    lastNumber.text = (draft['lastNumber'] ?? '').toString();
    area.text = (draft['area'] ?? '').toString();
    rooms.text = (draft['rooms'] ?? '').toString();
    halls.text = (draft['halls'] ?? '').toString();
    balconies.text = (draft['balconies'] ?? '').toString();
    bathrooms.text = (draft['bathrooms'] ?? '').toString();
    parking.text = (draft['parking'] ?? '').toString();
    notes.text = (draft['notes'] ?? '').toString();
    quickAdd = draft['quickAdd'] != false;
  }
}

class _UnitsEntryScreen extends StatefulWidget {
  const _UnitsEntryScreen({
    required this.assetKey,
    required this.existingUnits,
    required this.existingAnnexes,
    required this.onCommit,
    this.facilitiesOnly = false,
    this.propertyType = '',
  });

  /// نوع العقار المختار عند إضافته — فارغ للعقارات القديمة (كل الأنواع).
  final String propertyType;

  /// معرّف ثابت للعقار تُخزَّن به المسودة محليًا.
  final String assetKey;
  final List<_PropertyUnit> existingUnits;
  final Map<String, int> existingAnnexes;

  /// من «المرافق العامة»: تظهر المرافق العامة وحدها بلا أنواع الوحدات.
  final bool facilitiesOnly;

  /// يُستدعى عند كل حفظ نوع: وحدات جديدة تُضاف، ومرافق تُحدَّث أعدادها،
  /// وسطر سجل يوثّق ما حدث (يشمل ملاحظات المرافق).
  final void Function(
    List<_PropertyUnit> newUnits,
    Map<String, int> annexes,
    String logLine,
  )
  onCommit;

  @override
  State<_UnitsEntryScreen> createState() => _UnitsEntryScreenState();
}

class _UnitsEntryScreenState extends State<_UnitsEntryScreen> {
  final Map<String, _UnitEntryForm> _forms = {};
  late String _selected =
      widget.facilitiesOnly ? _kFacilityLabels.first : _kUnitApartment;
  Timer? _autoSaveTimer;
  DateTime? _lastAutoSave;
  final Set<String> _savedTypes = {};

  /// الوحدات التي أُضيفت فعلًا خلال هذه الجلسة — تُعرض أسفل النموذج
  /// فور حفظها (مثلًا: فعّلت الإضافة السريعة وأضفت شقة أخرى فتظهر تحت).
  final List<_PropertyUnit> _addedThisSession = [];

  static const _draftPrefix = 'units_entry_draft_v1_';

  bool get _isFacility => _kFacilityLabels.contains(_selected);

  _UnitEntryForm get _form => _forms.putIfAbsent(
    _selected,
    () => _UnitEntryForm()
      ..firstNumber.text =
          '${_nextUnitNumber([...widget.existingUnits, ..._addedThisSession], _selected)}',
  );

  @override
  void initState() {
    super.initState();
    _restoreDraft();
    // حفظ تلقائي كل دقيقتين — مع عدد كبير من الوحدات لا يضيع المدخل
    // شيئًا لو خرج أو انقطع التطبيق.
    _autoSaveTimer = Timer.periodic(
      const Duration(minutes: 2),
      (_) => _saveDraft(),
    );
  }

  @override
  void dispose() {
    _autoSaveTimer?.cancel();
    // حفظ أخير عند الخروج بدل انتظار الدورة القادمة.
    _saveDraft();
    for (final form in _forms.values) {
      form.dispose();
    }
    super.dispose();
  }

  Future<void> _saveDraft() async {
    try {
      // تُلتقط القيم قبل أي await: عند الاستدعاء من dispose تكون الحقول
      // على وشك التخلص منها، فلا يصح قراءتها بعد الانتظار.
      final data = {
        for (final entry in _forms.entries) entry.key: entry.value.toDraft(),
      };
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(
        '$_draftPrefix${widget.assetKey}',
        jsonEncode(data),
      );
      if (!mounted) return;
      setState(() => _lastAutoSave = DateTime.now());
    } catch (_) {
      // فشل الحفظ المحلي لا يوقف الإدخال.
    }
  }

  Future<void> _restoreDraft() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString('$_draftPrefix${widget.assetKey}');
      if (raw == null || raw.isEmpty) return;
      final decoded = jsonDecode(raw);
      if (decoded is! Map) return;
      for (final entry in decoded.entries) {
        if (entry.value is Map) {
          _forms
              .putIfAbsent(entry.key.toString(), _UnitEntryForm.new)
              .restore(Map<String, dynamic>.from(entry.value as Map));
        }
      }
      if (mounted) setState(() {});
    } catch (_) {
      // مسودة تالفة تُتجاهل.
    }
  }

  Future<void> _clearDraftFor(String type) async {
    // بعد حفظ النوع في العقار تُصفَّر خاناته حتى لا يُضاف مرتين بالخطأ.
    _forms[type]?.dispose();
    _forms.remove(type);
    await _saveDraft();
  }

  int _intOf(TextEditingController controller) =>
      int.tryParse(controller.text.trim()) ?? 0;

  /// حفظ النوع المفتوح: وحدات تُولَّد وتُضاف للعقار، ومرفق يُحدَّث عدده.
  Future<void> _commitSelected() async {
    final form = _form;
    final type = _selected;
    final count = _isFacility ? _intOf(form.count) : _rangeUnitCount(form);
    if (count <= 0) {
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('أدخل العدد أولًا')),
      );
      return;
    }

    if (!_isFacility &&
        type != _kUnitParking &&
        form.name.text.trim().isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text('اكتب اسم $type — الاسم إلزامي')),
      );
      return;
    }

    // مراجعة ما أُدخل قبل الحفظ — نفس نافذة معالج إضافة العقار.
    {
      final firstNo = int.tryParse(form.firstNumber.text.trim()) ?? 1;
      final name = form.name.text.trim().isEmpty
          ? type
          : form.name.text.trim();
      if (!_isFacility) {
        final all = [...widget.existingUnits, ..._addedThisSession];
        final duplicates =
            _duplicateUnitNames(all, type, name, firstNo, count);
        if (duplicates.isNotEmpty) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(
                'موجودة مسبقًا: ${duplicates.take(5).join('، ')} — '
                'غيّر رقم البداية (المتاح ${_nextUnitNumber(all, type)})',
              ),
              behavior: SnackBarBehavior.floating,
            ),
          );
          return;
        }
      }
      final full = type == _kUnitApartment || type == _kUnitFullFloor;
      final rooms = _unitTypeHasRooms(type);
      final home = _unitTypeIsResidential(type);
      final confirmed = await _confirmUnitEntry(context, type, [
        ('النوع', type),
        ('العدد', '$count'),
        if (!_isFacility) ('الاسم', name),
        if (!_isFacility && count > 1)
          ('الترقيم', 'من $firstNo إلى ${firstNo + count - 1}')
        else if (!_isFacility)
          ('الرقم', '$firstNo'),
        if (!_isFacility && form.area.text.trim().isNotEmpty)
          ('مساحة كل وحدة', '${form.area.text.trim()} متر مربع'),
        if (!_isFacility && rooms) ('عدد الغرف', '${_intOf(form.rooms)}'),
        if (!_isFacility && (rooms || full))
          ('عدد البلكونات', '${_intOf(form.balconies)}'),
        if (!_isFacility && full) ('عدد الصالات', '${_intOf(form.halls)}'),
        if (!_isFacility && home)
          ('عدد الحمامات', '${_intOf(form.bathrooms)}'),
        if (form.notes.text.trim().isNotEmpty)
          ('الملاحظات', form.notes.text.trim()),
      ]);
      if (!confirmed || !mounted) return;
    }

    if (_isFacility) {
      final note = form.notes.text.trim();
      widget.onCommit(
        const [],
        {type: count},
        'تمت إضافة مرفق: $type (العدد $count)'
        '${note.isEmpty ? '' : ' — $note'}',
      );
    } else {
      final first = int.tryParse(form.firstNumber.text.trim()) ?? 1;
      final baseName = form.name.text.trim().isEmpty
          ? type
          : form.name.text.trim();
      final showFull = type == _kUnitApartment || type == _kUnitFullFloor;
      final units = <_PropertyUnit>[
        for (var i = 0; i < count; i++)
          _PropertyUnit(
            type: type,
            name: count == 1 ? baseName : '$baseName ${first + i}',
            unitNumber: '${first + i}',
            area: form.area.text.trim(),
            rooms: _unitTypeRoomsFor(type, _intOf(form.rooms)),
            halls: showFull ? _intOf(form.halls) : 0,
            balconies: _intOf(form.balconies),
            bathrooms: _unitTypeIsResidential(type)
                ? _intOf(form.bathrooms)
                : 0,
            parkingCount: _unitTypeIsResidential(type)
                ? _intOf(form.parking)
                : 0,
            hasParking:
                _unitTypeIsResidential(type) && _intOf(form.parking) > 0,
            notes: form.notes.text.trim(),
            extras: _meterExtrasFrom(form.meters, withNumbers: count == 1),
          ),
      ];
      widget.onCommit(
        units,
        const {},
        'تمت إضافة $count × $type من نموذج إدخال الوحدات',
      );
      _addedThisSession.addAll(units);
    }
    setState(() {
      _savedTypes.add(type);
    });
    _clearDraftFor(type);
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text('تم حفظ $type في العقار')),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Directionality(
      textDirection: AppTr.uiDir,
      child: Scaffold(
        backgroundColor: AppTheme.page,
        appBar: AppBar(
          title: Text(
            widget.facilitiesOnly
                ? 'إضافة المرافق العامة'
                : 'إضافة الوحدات والمرافق العامة',
            style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w900),
          ),
          centerTitle: true,
          backgroundColor: AppTheme.page,
          surfaceTintColor: Colors.transparent,
          elevation: 0,
          leading: IconButton(
            onPressed: () => Navigator.of(context).pop(),
            icon: Icon(
              AppTr.isEnglish
                  ? Icons.arrow_back_ios_new_rounded
                  : Icons.arrow_forward_ios_rounded,
              size: 18,
            ),
          ),
          actions: [
            // زر حفظ المسودة يدويًا — نفس ما يفعله المؤقّت كل دقيقتين.
            IconButton(
              key: const ValueKey('units-entry-save-draft'),
              tooltip: AppTr.tr('حفظ المسودة الآن'),
              onPressed: _saveDraft,
              icon: const Icon(Icons.save_outlined, size: 20),
            ),
          ],
        ),
        body: Column(
          children: [
            if (_lastAutoSave != null)
              Container(
                width: double.infinity,
                color: const Color(0xFFF2F6F5),
                padding: const EdgeInsets.symmetric(
                  horizontal: 14,
                  vertical: 5,
                ),
                child: Text(
                  'آخر حفظ تلقائي للمسودة: '
                  '${_lastAutoSave!.hour.toString().padLeft(2, '0')}:${_lastAutoSave!.minute.toString().padLeft(2, '0')}'
                  ' — يتكرر كل دقيقتين',
                  style: const TextStyle(
                    fontSize: 10,
                    fontWeight: FontWeight.w700,
                    color: Color(0xFF0E7161),
                  ),
                ),
              ),
            Expanded(
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  // القائمة الثابتة على اليمين: الوحدات ثم المرافق.
                  SizedBox(width: 128, child: _buildTypesList()),
                  const VerticalDivider(width: 1, color: Color(0xFFE4EAE8)),
                  // اللوحة على اليسار: نموذج النوع المفتوح.
                  Expanded(child: _buildFormPanel()),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildTypesList() {
    Widget entry(String label, {required bool facility}) {
      final selected = _selected == label;
      final existingCount = facility
          ? (widget.existingAnnexes[label] ?? 0)
          : widget.existingUnits.where((u) => u.type == label).length;
      return InkWell(
        key: ValueKey('units-entry-type-$label'),
        onTap: () => setState(() => _selected = label),
        child: Container(
          color: selected
              ? const Color(0xFF0E7161).withValues(alpha: 0.08)
              : Colors.transparent,
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 11),
          child: Row(
            children: [
              Icon(
                facility
                    ? Icons.apartment_outlined
                    : _unitTypeIcon(label),
                size: 15,
                color: selected
                    ? const Color(0xFF0E7161)
                    : AppTheme.muted,
              ),
              const SizedBox(width: 6),
              Expanded(
                child: Text(
                  label,
                  maxLines: 4,
                  style: TextStyle(
                    fontSize: 10,
                    height: 1.25,
                    fontWeight: selected ? FontWeight.w900 : FontWeight.w700,
                    color: selected
                        ? const Color(0xFF0E7161)
                        : AppTheme.title,
                  ),
                ),
              ),
              if (existingCount > 0 || _savedTypes.contains(label))
                Text(
                  '$existingCount',
                  style: const TextStyle(
                    fontSize: 10,
                    fontWeight: FontWeight.w900,
                    color: Color(0xFF0E7161),
                  ),
                ),
            ],
          ),
        ),
      );
    }

    Widget header(String text) => Padding(
      padding: const EdgeInsets.fromLTRB(10, 12, 10, 4),
      child: Text(
        text,
        style: const TextStyle(
          fontSize: 10,
          fontWeight: FontWeight.w900,
          color: AppTheme.muted,
        ),
      ),
    );

    return ListView(
      padding: const EdgeInsets.only(bottom: 24),
      children: [
        if (!widget.facilitiesOnly) ...[
        header('الوحدات الإيجارية'),
        // نوع العقار معروف (العقارات الجديدة): وحداته المعتمدة فقط.
        for (final type in widget.propertyType.isNotEmpty
            ? _unitTypesForPropertyType(widget.propertyType)
            : const [
                _kUnitApartment,
                _kUnitStudio,
                _kUnitFullFloor,
                _kUnitOffice,
                _kUnitShop,
                _kUnitShowroom,
                _kUnitMezzanine,
                _kUnitWarehouse,
                _kUnitParking,
              ])
          entry(type, facility: false),
        const Divider(height: 16),
        ],
        header('المرافق العامة'),
        _facilitiesNotForRentNote(),
        for (final facility in _kFacilityLabels)
          entry(facility, facility: true),
      ],
    );
  }

  Widget _buildFormPanel() {
    final form = _form;
    final type = _selected;
    final facility = _isFacility;
    // موقف السيارات (كوحدة) والمرافق: العدد والملاحظات فقط.
    final countOnly = facility || type == _kUnitParking;
    final hasRooms = _unitTypeHasRooms(type);
    final residential = _unitTypeIsResidential(type);
    final showFull = type == _kUnitApartment || type == _kUnitFullFloor;

    Widget field(
      String label,
      TextEditingController controller, {
      bool number = true,
      int maxLines = 1,
      VoidCallback? onLive,
    }) {
      return Padding(
        padding: const EdgeInsets.only(bottom: 10),
        child: TextField(
          controller: controller,
          keyboardType: number ? TextInputType.number : TextInputType.text,
          maxLines: maxLines,
          textAlign: AppTr.alignEnd,
          onChanged: onLive == null
              ? null
              : (_) => setState(onLive),
          decoration: _propertyInputDecorationShared(label),
        ),
      );
    }

    final first = int.tryParse(form.firstNumber.text.trim()) ?? 1;
    final count = _rangeUnitCount(form);

    // الوحدات المضافة من هذا النوع (المحفوظة سابقًا + المضافة في هذه
    // الجلسة) — تظهر أسفل النموذج فيرى المستخدم ما أضافه مباشرة.
    final typeUnits = [
      ...widget.existingUnits.where((u) => u.type == type),
      ..._addedThisSession.where((u) => u.type == type),
    ];

    return ListView(
      key: ValueKey('units-entry-form-$type'),
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 28),
      children: [
        Row(
          children: [
            Icon(
              facility ? Icons.apartment_outlined : _unitTypeIcon(type),
              size: 18,
              color: const Color(0xFF0E7161),
            ),
            const SizedBox(width: 7),
            Expanded(
              child: Text(
                facility ? 'مرفق: $type' : 'إعدادات $type',
                style: const TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w900,
                  color: Color(0xFF022E2A),
                ),
              ),
            ),
          ],
        ),
        const SizedBox(height: 12),
        // شرح حقل العدد قبل ملئه.
        Padding(
          padding: const EdgeInsets.only(bottom: 10),
          child: Text(
            'اكتب العدد أولًا. إن كان أكبر من واحد يُفتح لك الترقيم '
            'التلقائي ليضيفها كلها دفعة واحدة، وإن كان واحدًا فلا ترقيم.',
            textAlign: TextAlign.right,
            style: const TextStyle(
              fontSize: 11,
              height: 1.5,
              fontWeight: FontWeight.w600,
              color: Color(0xFF5C6B68),
            ),
          ),
        ),
        field(
          facility ? 'العدد' : 'عدد ($type)',
          form.count,
          onLive: () => _syncCountToRange(form),
        ),
        if (!countOnly) ...[
          if (count > 1) ...[
            field(
              'رقم أول $type',
              form.firstNumber,
              onLive: () => _syncCountToRange(form),
            ),
            field(
              'إلى رقم (تسجيل تلقائي)',
              form.lastNumber,
              onLive: () => _syncRangeToCount(form),
            ),
            Padding(
              padding: const EdgeInsets.only(bottom: 10),
              child: Text(
                'الرقم من $first إلى ${first + count - 1} — سيتم تسجيل '
                'الوحدات تلقائيًا، وتستطيع تعديل البيانات بعد عملية الحفظ.',
                textAlign: TextAlign.right,
                style: const TextStyle(
                  fontSize: 11,
                  height: 1.5,
                  fontWeight: FontWeight.w700,
                  color: Color(0xFF5C6B68),
                ),
              ),
            ),
          ] else
            field(
              'رقم $type',
              form.firstNumber,
              onLive: () => _syncCountToRange(form),
            ),
          field('اسم $type *', form.name, number: false),
          field('مساحة كل وحدة (متر مربع)', form.area),
          if (hasRooms) field('عدد الغرف', form.rooms),
          if (hasRooms || showFull) field('عدد البلكونات', form.balconies),
          if (showFull) field('عدد الصالات', form.halls),
          if (residential) field('عدد الحمامات', form.bathrooms),
          // حُذف حقل "عدد مواقف السيارات" — المواقف تُضاف كنوع مستقل
          // "موقف خاص" من القائمة اليمنى.
        ],
        if (!facility && type != _kUnitParking) ...[
          ..._meterFieldsFor(form.meters),
          _meterBatchHint(),
        ],
        field('الملاحظات', form.notes, number: false, maxLines: 3),
        const SizedBox(height: 6),
        FilledButton.icon(
          key: ValueKey('units-entry-commit-$type'),
          onPressed: _commitSelected,
          icon: const Icon(Icons.check_rounded, size: 18),
          label: Text(facility ? 'إضافة المرفق' : 'إضافة $type'),
          style: FilledButton.styleFrom(
            backgroundColor: const Color(0xFF0E7161),
            foregroundColor: Colors.white,
            minimumSize: const Size.fromHeight(46),
            shape: RoundedRectangleBorder(
              borderRadius: BorderRadius.circular(AppTheme.rField),
            ),
          ),
        ),
        // ما أُضيف من هذا النوع يظهر هنا مباشرة تحت زر الإضافة.
        if (!facility && typeUnits.isNotEmpty) ...[
          const SizedBox(height: 14),
          Text(
            'المضاف من $type (${typeUnits.length})',
            textAlign: TextAlign.right,
            style: const TextStyle(
              fontSize: 12,
              fontWeight: FontWeight.w900,
              color: Color(0xFF2C3B38),
            ),
          ),
          const SizedBox(height: 6),
          for (final unit in typeUnits)
            Container(
              margin: const EdgeInsets.only(bottom: 6),
              padding: const EdgeInsets.symmetric(
                horizontal: 12,
                vertical: 9,
              ),
              decoration: BoxDecoration(
                color: AppTheme.surface,
                borderRadius: BorderRadius.circular(AppTheme.rField),
              ),
              child: Row(
                textDirection: AppTr.uiDir,
                children: [
                  Icon(
                    _unitTypeIcon(unit.type),
                    size: 15,
                    color: const Color(0xFF0E7161),
                  ),
                  const SizedBox(width: 8),
                  Expanded(
                    child: Text(
                      unit.name,
                      textAlign: TextAlign.right,
                      style: const TextStyle(
                        fontSize: 11,
                        fontWeight: FontWeight.w800,
                      ),
                    ),
                  ),
                  Text(
                    unit.area.isEmpty ? '' : '${unit.area} م²',
                    style: const TextStyle(
                      fontSize: 10,
                      fontWeight: FontWeight.w700,
                      color: Color(0xFF5C6B68),
                    ),
                  ),
                ],
              ),
            ),
        ],
      ],
    );
  }
}

/// زخرفة حقول شاشة إدخال الوحدات — حدود ظاهرة على نمط حقول العقارات.
/// نموذج الصيانة الموحَّد للبناية والوحدة: النوع، الوصف، المبلغ، الشركة
/// المنفّذة، رقم التواصل، تاريخ الطلب، التاريخ، ومن يتحمّلها، ومرفق.
/// يُعيد البند المحفوظ، أو null إن أُغلق بلا حفظ.
Future<Map<String, String>?> _showMaintenanceSheetShared(
  BuildContext context, {
  Map<String, String>? existing,
}) async {
    String fmtShort(DateTime d) =>
        '${d.day.toString().padLeft(2, '0')}/'
        '${d.month.toString().padLeft(2, '0')}/${d.year}';
    final kindCtrl = TextEditingController(text: existing?['الوصف'] ?? '');
    final amountCtrl = TextEditingController(text: existing?['المبلغ'] ?? '');
    final companyCtrl = TextEditingController(
      text: existing?['الشركة المنفذة'] ?? '',
    );
    // تاريخ بدء العمل اختياري: لا يُملأ تلقائيًا.
    var date = existing?['التاريخ'] ?? '';
    var kind = existing?['النوع'] ?? 'على المؤجر';
    final phoneCtrl = TextEditingController(text: existing?['رقم التواصل'] ?? '');
    final descCtrl = TextEditingController(
      text: existing?['وصف الصيانة'] ?? '',
    );
    var requestDate = existing?['تاريخ الطلب'] ?? '';
    var attachment = existing?['المرفق'] ?? '';
    // صيانة جديدة: «تحت الصيانة» حتى يُختار «انتهت — يعمل».
    var maintState =
        existing?[_kMaintStateKey] ??
        (existing == null ? _kMaintOpen : _kMaintDone);
    var impact = existing?[_kMaintImpactKey] ?? _kMaintKeepLease;
    Future<void> pickDate(
      BuildContext sheetContext,
      void Function(String value) onPicked,
    ) async {
      final picked = await showDatePicker(
        context: sheetContext,
        initialDate: DateTime.now(),
        firstDate: DateTime(2015),
        lastDate: DateTime(2100),
      );
      if (picked == null) return;
      onPicked(fmtShort(picked));
    }

    Widget dateBox(String text, VoidCallback onTap) => InkWell(
      onTap: onTap,
      borderRadius: BorderRadius.circular(AppTheme.rInner),
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 14),
        decoration: BoxDecoration(
          color: AppTheme.field,
          borderRadius: BorderRadius.circular(AppTheme.rInner),
          border: Border.all(color: AppTheme.line),
        ),
        child: Row(
          textDirection: AppTr.uiDir,
          children: [
            const Icon(
              Icons.calendar_today_rounded,
              size: 17,
              color: _kPropertyColor,
            ),
            const SizedBox(width: 8),
            Expanded(
              child: Text(
                text,
                textAlign: AppTr.alignEnd,
                style: const TextStyle(
                  fontSize: 12,
                  fontWeight: FontWeight.w800,
                  color: Color(0xFF022E2A),
                ),
              ),
            ),
          ],
        ),
      ),
    );
    final saved = await showModalBottomSheet<bool>(
      context: context,
      isScrollControlled: true,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(AppTheme.rCard),
        ),
      ),
      builder: (sheetContext) => StatefulBuilder(
        builder: (sheetContext, setSheetState) => Directionality(
          textDirection: AppTr.uiDir,
          child: Padding(
            padding: EdgeInsets.fromLTRB(
              16,
              14,
              16,
              MediaQuery.of(sheetContext).viewInsets.bottom + 16,
            ),
            child: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Text(
                    existing == null ? 'إضافة صيانة' : 'تعديل الصيانة',
                    textAlign: AppTr.alignEnd,
                    style: const TextStyle(
                      fontSize: 13,
                      fontWeight: FontWeight.w900,
                      color: Color(0xFF022E2A),
                    ),
                  ),
                  const SizedBox(height: 10),
                  // الحالة: «تحت الصيانة» = العقار/المركبة في صيانة، و«انتهت
                  // — يعمل» = يرجع شاغرًا أو مؤجرًا.
                  Wrap(
                    spacing: 8,
                    children: [
                      for (final option in const [_kMaintOpen, _kMaintDone])
                        ChoiceChip(
                          label: Text(
                            option,
                            style: const TextStyle(fontSize: 12),
                          ),
                          selected: maintState == option,
                          selectedColor: option == _kMaintOpen
                              ? AppTheme.dangerSoft
                              : AppTheme.brandSoft,
                          onSelected: (_) =>
                              setSheetState(() => maintState = option),
                        ),
                    ],
                  ),
                  const SizedBox(height: 10),
                  // أثر الصيانة على الإيجار: يستمر الإيجار، أو لا يمكن
                  // التأجير حتى «انتهاء الصيانة».
                  const Text(
                    'أثر الصيانة على الإيجار',
                    style: TextStyle(
                      fontSize: 11.5,
                      fontWeight: FontWeight.w800,
                      color: Color(0xFF5C6B68),
                    ),
                  ),
                  const SizedBox(height: 6),
                  Wrap(
                    spacing: 8,
                    children: [
                      for (final option in const [
                        _kMaintKeepLease,
                        _kMaintBlockLease,
                      ])
                        ChoiceChip(
                          label: Text(
                            option,
                            style: const TextStyle(fontSize: 12),
                          ),
                          selected: impact == option,
                          selectedColor: option == _kMaintBlockLease
                              ? AppTheme.dangerSoft
                              : AppTheme.brandSoft,
                          onSelected: (_) =>
                              setSheetState(() => impact = option),
                        ),
                    ],
                  ),
                  const SizedBox(height: 12),
                  TextField(
                    controller: kindCtrl,
                    textAlign: AppTr.alignEnd,
                    decoration: _propertyInputDecorationShared('نوع الصيانة *'),
                  ),
                  const SizedBox(height: 9),
                  TextField(
                    controller: descCtrl,
                    textAlign: AppTr.alignEnd,
                    maxLines: 2,
                    decoration: _propertyInputDecorationShared('وصف الصيانة'),
                  ),
                  const SizedBox(height: 9),
                  TextField(
                    controller: amountCtrl,
                    textAlign: AppTr.alignEnd,
                    keyboardType: const TextInputType.numberWithOptions(
                      decimal: true,
                    ),
                    decoration: _propertyInputDecorationShared('المبلغ'),
                  ),
                  const SizedBox(height: 9),
                  TextField(
                    controller: companyCtrl,
                    textAlign: AppTr.alignEnd,
                    decoration: _propertyInputDecorationShared(
                      'اسم الشركة المنفذة *',
                    ),
                  ),
                  const SizedBox(height: 9),
                  TextField(
                    controller: phoneCtrl,
                    textAlign: AppTr.alignEnd,
                    keyboardType: TextInputType.phone,
                    decoration: _propertyInputDecorationShared('رقم التواصل *'),
                  ),
                  const SizedBox(height: 9),
                  dateBox(
                    requestDate.isEmpty
                        ? 'تاريخ الطلب'
                        : 'تاريخ الطلب: $requestDate',
                    () => pickDate(
                      sheetContext,
                      (value) => setSheetState(() => requestDate = value),
                    ),
                  ),
                  const SizedBox(height: 9),
                  InkWell(
                    onTap: () async {
                      final picked = await showDatePicker(
                        context: sheetContext,
                        initialDate: DateTime.now(),
                        firstDate: DateTime(2015),
                        lastDate: DateTime(2100),
                      );
                      if (picked == null) return;
                      setSheetState(() => date = fmtShort(picked));
                    },
                    borderRadius: BorderRadius.circular(AppTheme.rInner),
                    child: Container(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 12,
                        vertical: 14,
                      ),
                      decoration: BoxDecoration(
                        color: AppTheme.field,
                        borderRadius: BorderRadius.circular(AppTheme.rInner),
                        border: Border.all(color: AppTheme.line),
                      ),
                      child: Row(
                        textDirection: AppTr.uiDir,
                        children: [
                          const Icon(
                            Icons.calendar_today_rounded,
                            size: 17,
                            color: _kPropertyColor,
                          ),
                          const SizedBox(width: 8),
                          Expanded(
                            child: Text(
                              date.isEmpty
                                  ? 'تاريخ بدء العمل (اختياري)'
                                  : 'تاريخ بدء العمل: $date',
                              textAlign: AppTr.alignEnd,
                              style: const TextStyle(
                                fontSize: 12,
                                fontWeight: FontWeight.w800,
                                color: Color(0xFF022E2A),
                              ),
                            ),
                          ),
                        ],
                      ),
                    ),
                  ),
                  const SizedBox(height: 9),
                  Row(
                    children: [
                      for (final option in const [
                        'على المؤجر',
                        'على المستأجر',
                      ]) ...[
                        Expanded(
                          child: InkWell(
                            onTap: () => setSheetState(() => kind = option),
                            borderRadius: BorderRadius.circular(AppTheme.rIcon),
                            child: Container(
                              margin: const EdgeInsets.only(left: 6),
                              padding: const EdgeInsets.symmetric(vertical: 11),
                              alignment: Alignment.center,
                              decoration: BoxDecoration(
                                color: kind == option
                                    ? _kPropertyColor
                                    : AppTheme.paper,
                                borderRadius: BorderRadius.circular(
                                  AppTheme.rIcon,
                                ),
                                border: Border.all(
                                  color: kind == option
                                      ? _kPropertyColor
                                      : AppTheme.hairline,
                                ),
                              ),
                              child: Text(
                                option,
                                style: TextStyle(
                                  fontSize: 12,
                                  fontWeight: FontWeight.w900,
                                  color: kind == option
                                      ? Colors.white
                                      : AppTheme.title,
                                ),
                              ),
                            ),
                          ),
                        ),
                      ],
                    ],
                  ),
                  const SizedBox(height: 9),
                  // إرفاق مستند: فاتورة الصيانة أو صورتها.
                  AppRemovableAttachment(
                    attached: attachment.isNotEmpty,
                    onRemove: () => setSheetState(() => attachment = ''),
                    child: OutlinedButton.icon(
                    onPressed: () async {
                      final path = await DocumentStore.pickAndStore(context: context);
                      if (path == null) return;
                      setSheetState(() => attachment = path);
                    },
                    style: OutlinedButton.styleFrom(
                      foregroundColor: _kPropertyColor,
                      minimumSize: const Size.fromHeight(46),
                    ),
                    icon: const Icon(Icons.attach_file_rounded, size: 18),
                    label: Text(
                      attachment.isEmpty
                          ? 'إرفاق مستند'
                          : DocumentStore.fileName(attachment),
                      maxLines: 3,
                    ),
                  ),
                  ),
                  const SizedBox(height: 14),
                  FilledButton(
                    onPressed: () async {
                      final missing = [
                        if (kindCtrl.text.trim().isEmpty) 'نوع الصيانة',
                        if (phoneCtrl.text.trim().isEmpty) 'رقم التواصل',
                        if (companyCtrl.text.trim().isEmpty)
                          'اسم الشركة المنفذة',
                      ];
                      if (missing.isNotEmpty) {
                        await showDialog<void>(
                          context: sheetContext,
                          builder: (dialogContext) => Directionality(
                            textDirection: AppTr.uiDir,
                            child: AlertDialog(
                              title: const Text('تنبيه'),
                              content: Text(
                                'أكمل: ${missing.join('، ')}',
                                textAlign: TextAlign.right,
                              ),
                              actions: [
                                FilledButton(
                                  onPressed: () =>
                                      Navigator.of(dialogContext).pop(),
                                  child: const Text('حسنًا'),
                                ),
                              ],
                            ),
                          ),
                        );
                        return;
                      }
                      if (!sheetContext.mounted) return;
                      // كل إجراء يُؤكَّد قبل تنفيذه.
                      final ok = await confirmAction(
                        sheetContext,
                        title: 'تأكيد الحفظ',
                        message: 'هل تريد حفظ الصيانة؟',
                      );
                      if (!ok) return;
                      if (sheetContext.mounted) {
                        Navigator.of(sheetContext).pop(true);
                      }
                    },
                    style: FilledButton.styleFrom(
                      backgroundColor: _kPropertyColor,
                      foregroundColor: Colors.white,
                      minimumSize: const Size.fromHeight(46),
                    ),
                    child: const Text('حفظ'),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
    // انتهت من النموذج نفسه: يُسجَّل وقت الانتهاء الآن إن لم يكن مسجَّلًا.
    final prevDoneAt = existing?[_kMaintDoneAtKey] ?? '';
    final wasOpen =
        existing == null || (existing[_kMaintStateKey] ?? '') == _kMaintOpen;
    final doneAt = maintState != _kMaintDone
        ? ''
        : prevDoneAt.isNotEmpty
        ? prevDoneAt
        : (wasOpen ? _maintStamp(DateTime.now()) : '');
    final row = <String, String>{
      'الوصف': kindCtrl.text.trim(),
      'وصف الصيانة': descCtrl.text.trim(),
      'المبلغ': amountCtrl.text.trim(),
      'الشركة المنفذة': companyCtrl.text.trim(),
      'رقم التواصل': phoneCtrl.text.trim(),
      'تاريخ الطلب': requestDate,
      'التاريخ': date,
      'النوع': kind,
      _kMaintStateKey: maintState,
      _kMaintImpactKey: impact,
      if (doneAt.isNotEmpty) _kMaintDoneAtKey: doneAt,
      if (maintState == _kMaintDone &&
          (existing?[_kMaintDoneNoteKey] ?? '').isNotEmpty)
        _kMaintDoneNoteKey: existing![_kMaintDoneNoteKey]!,
      if (attachment.isNotEmpty) 'المرفق': attachment,
    };
    kindCtrl.dispose();
    amountCtrl.dispose();
    companyCtrl.dispose();
    phoneCtrl.dispose();
    descCtrl.dispose();
    if (saved != true || row['الوصف']!.isEmpty) return null;
    return row;
}


