/// تفاصيل عنصر مع «تعديل» و«حذف» — نفسها في الوحدة والبناية.
Future<void> _showItemDetailsShared(
  BuildContext context, {
    required String title,
    required IconData icon,
    required Map<String, String> row,
    required VoidCallback onEdit,
    required VoidCallback onDelete,
    required void Function(String path) onOpenFile,
    Future<void> Function()? onFinishMaintenance,
  }) async {
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: AppTheme.page,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(
          top: Radius.circular(AppTheme.rCard),
        ),
      ),
      builder: (sheetContext) => Directionality(
        textDirection: AppTr.uiDir,
        child: SafeArea(
          top: false,
          child: Padding(
            padding: const EdgeInsets.fromLTRB(16, 14, 16, 18),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Row(
                  textDirection: AppTr.uiDir,
                  children: [
                    Icon(icon, size: 19, color: _kPropertyColor),
                    const SizedBox(width: 8),
                    Expanded(
                      child: Text(
                        title,
                        textAlign: AppTr.alignEnd,
                        style: const TextStyle(
                          fontSize: 13,
                          fontWeight: FontWeight.w900,
                          color: Color(0xFF022E2A),
                        ),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 10),
                for (final entry in row.entries)
                  if (entry.value.trim().isNotEmpty &&
                      entry.key != DocumentStore.kFileField)
                    _infoRowShared(
                      entry.key == 'التاريخ' && row.containsKey('وصف الصيانة')
                          ? 'تاريخ بدء العمل'
                          : entry.key,
                      entry.value,
                    ),
                if ((row[DocumentStore.kFileField] ?? '').trim().isNotEmpty) ...[
                  _infoRowShared(
                    'الملف المرفق',
                    DocumentStore.fileName(row[DocumentStore.kFileField]!),
                  ),
                  const SizedBox(height: 10),
                  FilledButton.icon(
                    style: FilledButton.styleFrom(
                      backgroundColor: _kPropertyColor,
                      foregroundColor: Colors.white,
                      minimumSize: const Size.fromHeight(44),
                    ),
                    onPressed: () {
                      Navigator.of(sheetContext).pop();
                      onOpenFile(row[DocumentStore.kFileField]!);
                    },
                    icon: const Icon(Icons.open_in_new_rounded, size: 18),
                    label: const Text('فتح المستند المحفوظ'),
                  ),
                ],
                const SizedBox(height: 14),
                // صيانة مفتوحة: «انتهاء الصيانة» يسجّل اليوم والوقت وملاحظة.
                if (onFinishMaintenance != null &&
                    (row[_kMaintStateKey] ?? '') == _kMaintOpen) ...[
                  FilledButton.icon(
                    style: FilledButton.styleFrom(
                      backgroundColor: const Color(0xFF0E7161),
                      foregroundColor: Colors.white,
                      minimumSize: const Size.fromHeight(44),
                    ),
                    onPressed: () {
                      Navigator.of(sheetContext).pop();
                      onFinishMaintenance();
                    },
                    icon: const Icon(Icons.task_alt_rounded, size: 18),
                    label: const Text('انتهاء الصيانة'),
                  ),
                  const SizedBox(height: 8),
                ],
                Row(
                  children: [
                    Expanded(
                      child: OutlinedButton.icon(
                        onPressed: () {
                          Navigator.of(sheetContext).pop();
                          onEdit();
                        },
                        icon: const Icon(Icons.edit_outlined, size: 18),
                        label: const Text('تعديل'),
                      ),
                    ),
                    const SizedBox(width: 8),
                    Expanded(
                      child: OutlinedButton.icon(
                        style: OutlinedButton.styleFrom(
                          foregroundColor: AppTheme.danger,
                        ),
                        onPressed: () async {
                          final ok = await confirmAction(
                            sheetContext,
                            title: 'حذف',
                            message: 'هل أنت متأكد من الحذف؟ لا يمكن التراجع.',
                            confirmLabel: 'حذف',
                            danger: true,
                          );
                          if (!ok || !sheetContext.mounted) return;
                          Navigator.of(sheetContext).pop();
                          onDelete();
                        },
                        icon: const Icon(Icons.delete_outline_rounded, size: 18),
                        label: const Text('حذف'),
                      ),
                    ),
                  ],
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }

/// سطر «عنوان: قيمة» في التفاصيل.
Widget _infoRowShared(String label, String value, {Color? valueColor}) {
    return Padding(
      padding: const EdgeInsets.symmetric(vertical: 5),
      child: Row(
        textDirection: AppTr.uiDir,
        children: [
          Expanded(
            child: Text(
              label,
              textAlign: TextAlign.right,
              style: const TextStyle(
                fontSize: 11,
                fontWeight: FontWeight.w600,
                color: Color(0xFF5C6B68),
              ),
            ),
          ),
          Text(
            value.isEmpty ? 'غير محدد' : value,
            style: TextStyle(
              fontSize: 12,
              fontWeight: FontWeight.w900,
              color: valueColor ?? const Color(0xFF022E2A),
            ),
          ),
        ],
      ),
    );
  }

InputDecoration _propertyInputDecorationShared(String label) {
  OutlineInputBorder border([Color? color]) => OutlineInputBorder(
    borderRadius: BorderRadius.circular(AppTheme.rField),
    borderSide: color == null
        ? BorderSide.none
        : BorderSide(color: color, width: 1.4),
  );
  // «الاسم *»: الحقل إلزامي، والنجمة حمراء.
  final trimmed = label.trim();
  final required = trimmed.endsWith('*');
  return InputDecoration(
    labelText: required ? null : AppTr.tr(label),
    label: required
        ? _requiredLabel(trimmed.substring(0, trimmed.length - 1).trim())
        : null,
    filled: true,
    fillColor: AppTheme.field,
    isDense: true,
    contentPadding: const EdgeInsets.symmetric(horizontal: 12, vertical: 12),
    border: border(),
    enabledBorder: border(),
    focusedBorder: border(const Color(0xFF0E7161)),
  );
}

// ============================================================
// «تعديل العقار» من الثلاث نقاط — نفس شكل «إضافة عقار»: على اليمين
// «بيانات العقار» ثم كل نوع وحدة أُدخل (شقة، دور كامل، غرفة...) ثم المرافق
// العامة، وعلى اليسار ما أُدخل لكل منها مملوءًا لتعديله.
// ============================================================

/// نتيجة التعديل: العقار بعد التعديل، والوحدات التي تغيّر اسمها
/// (مفتاحها ← اسمها الجديد) لتحديثه في عقودها.
class _PropertyEditResult {
  const _PropertyEditResult(this.item, this.renamed);
  final _AssetItem item;
  final Map<String, String> renamed;
}

/// متحكّمات حقول وحدة واحدة في شاشة التعديل.
class _UnitEditControllers {
  _UnitEditControllers(_PropertyUnit unit)
    : name = TextEditingController(text: unit.name),
      number = TextEditingController(text: unit.unitNumber),
      area = TextEditingController(text: unit.area),
      rooms = TextEditingController(text: _countText(unit.rooms)),
      halls = TextEditingController(text: _countText(unit.halls)),
      balconies = TextEditingController(text: _countText(unit.balconies)),
      bathrooms = TextEditingController(text: _countText(unit.bathrooms)),
      parking = TextEditingController(text: _countText(unit.parkingCount)),
      notes = TextEditingController(text: unit.notes),
      meters = _meterControllers(unit.extras);

  /// عدد عدادات الكهرباء والمياه وأرقامها لهذه الوحدة.
  final Map<String, TextEditingController> meters;

  static String _countText(int value) => value > 0 ? '$value' : '';

  final TextEditingController name;
  final TextEditingController number;
  final TextEditingController area;
  final TextEditingController rooms;
  final TextEditingController halls;
  final TextEditingController balconies;
  final TextEditingController bathrooms;
  final TextEditingController parking;
  final TextEditingController notes;

  void dispose() {
    for (final controller in [
      name,
      number,
      area,
      rooms,
      halls,
      balconies,
      bathrooms,
      parking,
      notes,
      ...meters.values,
    ]) {
      controller.dispose();
    }
  }
}

class _PropertyFullEditScreen extends StatefulWidget {
  const _PropertyFullEditScreen({required this.item, this.initialSelected});

  final _AssetItem item;

  /// يُفتح على هذا النوع (تعديل وحدة من صفحتها).
  final String? initialSelected;

  /// من صفحة وحدة: «تعديل وحدات» بلا «بيانات العقار».
  bool get unitsOnly => initialSelected != null;

  @override
  State<_PropertyFullEditScreen> createState() =>
      _PropertyFullEditScreenState();
}

class _PropertyFullEditScreenState extends State<_PropertyFullEditScreen> {
  static const _kData = '__بيانات العقار__';

  late String _selected = widget.initialSelected ?? _kData;

  late final TextEditingController _name = TextEditingController(
    text: widget.item.title,
  );
  late final TextEditingController _description = TextEditingController(
    text: widget.item.description,
  );
  late final TextEditingController _address = TextEditingController(
    text: widget.item.locationOrType == 'غير محدد'
        ? ''
        : widget.item.locationOrType,
  );
  late final TextEditingController _owner = TextEditingController(
    text: widget.item.owner == 'غير محدد' ? '' : widget.item.owner,
  );
  late final TextEditingController _mapLink = TextEditingController(
    text: widget.item.mapLink,
  );
  late final Map<String, TextEditingController> _meta = {
    for (final key in _kAddPropertyMetaKeys)
      key: TextEditingController(text: widget.item.propertyMeta[key] ?? ''),
  };

  /// متحكّمات كل وحدة بترتيبها في العقار.
  late final List<_UnitEditControllers> _units = [
    for (final unit in widget.item.units) _UnitEditControllers(unit),
  ];

  /// المرافق: القائمة الثابتة، وما أُدخل سابقًا باسم آخر.
  late final List<String> _facilityNames = [
    ..._kCommonFacilities,
    for (final key in widget.item.annexes.keys)
      if (!_kCommonFacilities.contains(key) && !key.startsWith('أخرى: '))
        key,
  ];

  late final Map<String, TextEditingController> _facilities = {
    for (final name in _facilityNames)
      name: TextEditingController(
        text: (widget.item.annexes[name] ?? 0) > 0
            ? '${widget.item.annexes[name]}'
            : '',
      ),
  };

  /// خيارات «النوع» حسب نوع العقار المحفوظ (موقف، مجمع، أرض).
  List<String> get _subTypeOptions => _propertySubTypeOptions(
    widget.item.propertyMeta[_kPropertyTypeKey] ?? '',
  );

  /// أنواع الوحدات المُدخلة في هذا العقار بترتيب ظهورها.
  List<String> get _unitTypes {
    final out = <String>[];
    for (final unit in widget.item.units) {
      if (!out.contains(unit.type)) out.add(unit.type);
    }
    return out;
  }

  @override
  void dispose() {
    for (final controller in [
      _name,
      _description,
      _address,
      _owner,
      _mapLink,
      ..._meta.values,
      ..._facilities.values,
    ]) {
      controller.dispose();
    }
    for (final unit in _units) {
      unit.dispose();
    }
    super.dispose();
  }

  int _n(TextEditingController controller) =>
      int.tryParse(controller.text.trim()) ?? 0;

  void _say(String message) {
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(content: Text(message), behavior: SnackBarBehavior.floating),
    );
  }

  void _save() {
    if (_name.text.trim().isEmpty) {
      setState(() => _selected = _kData);
      _say('أدخل اسم العقار');
      return;
    }
    final missingMeta = [
      if (!widget.unitsOnly)
        for (final key in _kRequiredPropertyMeta)
          if ((_meta[key]?.text ?? '').trim().isEmpty) key,
    ];
    if (missingMeta.isNotEmpty) {
      setState(() => _selected = _kData);
      _say('أكمل الحقول الإلزامية: ${missingMeta.join('، ')}');
      return;
    }
    final source = widget.item;
    for (var i = 0; i < source.units.length; i++) {
      if (_units[i].name.text.trim().isEmpty) {
        setState(() => _selected = source.units[i].type);
        _say('اكتب اسم كل وحدة — لا تُحفظ وحدة بلا اسم');
        return;
      }
    }
    final renamed = <String, String>{};
    final units = <_PropertyUnit>[];
    for (var i = 0; i < source.units.length; i++) {
      final unit = source.units[i];
      final c = _units[i];
      final type = unit.type;
      final hasRooms = _unitTypeHasRooms(type);
      final fullFloor = type == _kUnitFullFloor;
      final residential = _unitTypeIsResidential(type);
      final newName = c.name.text.trim();
      final newNumber = c.number.text.trim();
      var extras = unit.extras;
      // تغيّر الاسم أو الرقم: يُثبَّت مفتاح الوحدة الحالي فتبقى عقودها
      // ودفعاتها وحركاتها مربوطة بها.
      if (newName != unit.name || newNumber != unit.unitNumber) {
        extras = {...extras};
        if ((extras[_PropertyUnit.kPinnedKey] ?? '').trim().isEmpty) {
          extras[_PropertyUnit.kPinnedKey] = unit.unitKey;
        }
      }
      if (newName != unit.name) renamed[unit.unitKey] = newName;
      final parking = residential ? _n(c.parking) : unit.parkingCount;
      // عدادات الكهرباء والمياه داخل بيانات الوحدة.
      extras = {...extras};
      for (final m in _kMeterCountFields) {
        for (final key in [m.$1, m.$2]) {
          final value = c.meters[key]!.text;
          if (value.trim().isEmpty) {
            extras.remove(key);
          } else {
            extras[key] = value;
          }
        }
      }
      units.add(
        unit.copyWith(
          name: newName,
          unitNumber: newNumber,
          area: type == _kUnitParking ? unit.area : c.area.text.trim(),
          rooms: hasRooms ? _n(c.rooms) : unit.rooms,
          halls: fullFloor ? _n(c.halls) : unit.halls,
          balconies: (hasRooms || fullFloor) ? _n(c.balconies) : unit.balconies,
          bathrooms: residential ? _n(c.bathrooms) : unit.bathrooms,
          parkingCount: parking,
          hasParking: residential ? parking > 0 : unit.hasParking,
          notes: c.notes.text.trim(),
          extras: extras,
        ),
      );
    }
    final annexes = <String, int>{
      for (final entry in source.annexes.entries)
        if (entry.key.startsWith('أخرى: ')) entry.key: entry.value,
    };
    _facilities.forEach((name, controller) {
      final count = _n(controller);
      if (count > 0) annexes[name] = count;
    });
    final meta = Map<String, String>.of(source.propertyMeta);
    _meta.forEach((key, controller) {
      final value = controller.text.trim();
      if (value.isEmpty) {
        meta.remove(key);
      } else {
        meta[key] = value;
      }
    });
    final mapLink = _mapLink.text.trim();
    final coords = _parseLatLngFromMapLink(mapLink);
    final address = _address.text.trim();
    final owner = _owner.text.trim();
    Navigator.of(context).pop(
      _PropertyEditResult(
        source.copyWith(
          title: _name.text.trim(),
          description: _description.text.trim(),
          locationOrType: address.isEmpty ? 'غير محدد' : address,
          owner: owner.isEmpty ? 'غير محدد' : owner,
          mapLink: mapLink,
          latitude: coords?.$1 ?? source.latitude,
          longitude: coords?.$2 ?? source.longitude,
          annexes: annexes,
          units: units,
          propertyMeta: meta,
        ),
        renamed,
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: AppTheme.page,
      appBar: AppBar(
        toolbarHeight: 60,
        backgroundColor: Colors.white,
        surfaceTintColor: Colors.transparent,
        foregroundColor: const Color(0xFF0F1F1C),
        elevation: 0,
        centerTitle: true,
        title: Text(
          widget.unitsOnly ? 'تعديل وحدات' : 'تعديل عقار',
          style: const TextStyle(
            fontSize: 17,
            fontWeight: FontWeight.w900,
            color: Color(0xFF0F1F1C),
          ),
        ),
        leading: IconButton(
          tooltip: AppTr.tr('رجوع'),
          onPressed: () => Navigator.pop(context),
          icon: const Icon(Icons.arrow_back_ios_new_rounded, size: 20),
        ),
      ),
      body: Directionality(
        textDirection: AppTr.uiDir,
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            Expanded(
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  SizedBox(width: 132, child: _buildSidePane()),
                  const VerticalDivider(width: 1, color: Color(0xFFE4EAE8)),
                  Expanded(child: _buildFormPane()),
                ],
              ),
            ),
            Container(
              padding: const EdgeInsets.fromLTRB(14, 10, 14, 12),
              decoration: const BoxDecoration(
                color: Colors.white,
                border: Border(top: BorderSide(color: Color(0xFFE4EAE8))),
              ),
              child: SafeArea(
                top: false,
                child: FilledButton.icon(
                  onPressed: _save,
                  icon: const Icon(Icons.check_rounded, size: 19),
                  label: const Text(
                    'حفظ التعديل',
                    style: TextStyle(fontWeight: FontWeight.w900),
                  ),
                  style: FilledButton.styleFrom(
                    backgroundColor: _kPropertyColor,
                    foregroundColor: Colors.white,
                    minimumSize: const Size.fromHeight(48),
                  ),
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }

  Widget _buildSidePane() {
    Widget header(String text) => Padding(
      padding: const EdgeInsets.fromLTRB(10, 12, 10, 4),
      child: Text(
        text,
        style: const TextStyle(
          fontSize: 11,
          fontWeight: FontWeight.w900,
          color: AppTheme.muted,
        ),
      ),
    );

    Widget entry({
      required String keyValue,
      required String label,
      required IconData icon,
      int badge = 0,
    }) {
      final selected = _selected == keyValue;
      return InkWell(
        onTap: () => setState(() {
          _selected = keyValue;
          _unitQuery = '';
        }),
        child: Container(
          color: selected
              ? _kPropertyColor.withValues(alpha: 0.08)
              : Colors.transparent,
          padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 11),
          child: Row(
            children: [
              Icon(
                icon,
                size: 16,
                color: selected ? _kPropertyColor : AppTheme.muted,
              ),
              const SizedBox(width: 6),
              Expanded(
                child: Text(
                  label,
                  maxLines: 4,
                  style: TextStyle(
                    fontSize: 11,
                    height: 1.25,
                    fontWeight: selected ? FontWeight.w900 : FontWeight.w700,
                    color: selected ? _kPropertyColor : AppTheme.title,
                  ),
                ),
              ),
              if (badge > 0)
                Text(
                  '$badge',
                  style: const TextStyle(
                    fontSize: 10,
                    fontWeight: FontWeight.w900,
                    color: Color(0xFF0E7161),
                  ),
                ),
            ],
          ),
        ),
      );
    }

    return ListView(
      padding: const EdgeInsets.only(top: 8, bottom: 24),
      children: [
        // من صفحة وحدة: الوحدات فقط، بلا «بيانات العقار».
        if (!widget.unitsOnly)
          entry(
            keyValue: _kData,
            label: 'بيانات العقار',
            icon: Icons.edit_note_rounded,
          ),
        if (_unitTypes.isNotEmpty) ...[
          const Divider(height: 14),
          header('الوحدات الإيجارية'),
          for (final type in _unitTypes)
            entry(
              keyValue: type,
              label: type,
              icon: _unitTypeIcon(type),
              badge: widget.item.units.where((u) => u.type == type).length,
            ),
        ],
        const Divider(height: 14),
        header('المرافق العامة'),
        _facilitiesNotForRentNote(),
        for (final facility in _facilityNames)
          entry(
            // مسبوق بـ f: — «ميزانين» اسم وحدة واسم مرفق معًا.
            keyValue: 'f:$facility',
            label: facility,
            icon: Icons.apartment_outlined,
            badge: _n(_facilities[facility]!),
          ),
      ],
    );
  }

  Widget _buildFormPane() {
    if (_selected == _kData) return _buildDataForm();
    if (_selected.startsWith('f:')) {
      return _buildFacilityForm(_selected.substring(2));
    }
    return _buildUnitsForm(_selected);
  }

  Widget _field(
    String label,
    TextEditingController controller, {
    bool number = false,
    int maxLines = 1,
    VoidCallback? onChanged,
  }) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 10),
      child: TextField(
        controller: controller,
        textAlign: AppTr.alignEnd,
        maxLines: maxLines,
        keyboardType: number ? TextInputType.number : TextInputType.text,
        onChanged: onChanged == null ? null : (_) => setState(onChanged),
        decoration: _propertyInputDecorationShared(label),
      ),
    );
  }

  Widget _buildDataForm() {
    return ListView(
      key: const ValueKey('property-edit-data'),
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 28),
      children: [
        _field('اسم العقار', _name),
        _field('الوصف', _description, maxLines: 2),
        // الموقف والمجمع والأرض: سطر «النوع».
        if (_subTypeOptions.isNotEmpty)
          Padding(
            padding: const EdgeInsets.only(bottom: 10),
            child: DropdownButtonFormField<String>(
              initialValue: _subTypeOptions.contains(
                _meta[_kPropertySubTypeKey]!.text,
              )
                  ? _meta[_kPropertySubTypeKey]!.text
                  : null,
              isExpanded: true,
              decoration: _propertyInputDecorationShared('النوع'),
              items: [
                for (final option in _subTypeOptions)
                  DropdownMenuItem(
                    value: option,
                    child: Text(option, textAlign: AppTr.alignEnd),
                  ),
              ],
              onChanged: (value) => setState(
                () => _meta[_kPropertySubTypeKey]!.text = value ?? '',
              ),
            ),
          ),
        _field('العنوان / الموقع', _address),
        _field('المالك', _owner),
        _field('رابط الموقع على خرائط جوجل', _mapLink),
        const SizedBox(height: 6),
        _propertyFieldLabel('بيانات العقار الرسمية (تُستعمل في عقود الإيجار)'),
        const SizedBox(height: 8),
        for (final spec in LeaseContractData.propertyFields)
          if (_meta.containsKey(spec.key)) ...[
            if (spec.options.isNotEmpty)
              Padding(
                padding: const EdgeInsets.only(bottom: 10),
                child: DropdownButtonFormField<String>(
                  initialValue: spec.options.contains(_meta[spec.key]!.text)
                      ? _meta[spec.key]!.text
                      : null,
                  isExpanded: true,
                  decoration: _propertyInputDecorationShared(spec.label),
                  items: [
                    for (final option in spec.options)
                      DropdownMenuItem(
                        value: option,
                        child: Text(option, textAlign: AppTr.alignEnd),
                      ),
                  ],
                  onChanged: (value) =>
                      setState(() => _meta[spec.key]!.text = value ?? ''),
                ),
              )
            else
              _field(
                spec.label,
                _meta[spec.key]!,
                number: spec.numeric,
                maxLines: spec.multiline ? 2 : 1,
              ),
          ],
        for (final meter in _kMeterCountFields)
          _MeterCountField(
            countLabel: meter.$3,
            numberLabel: meter.$4,
            countController: _meta[meter.$1]!,
            numbersController: _meta[meter.$2]!,
            icon: meter.$5,
          ),
      ],
    );
  }

  /// بحث سريع بالاسم أو الرقم بين كل وحدات العقار.
  String _unitQuery = '';

  /// كل وحدات النوع المختار (أو نتائج البحث)، كل وحدة ببياناتها كما أُدخلت —
  /// الحقول تحت بعض بترتيب نموذج الإدخال: الرقم أولًا ثم الاسم.
  Widget _buildUnitsForm(String type) {
    final query = _unitQuery.trim();
    final indexes = [
      for (var i = 0; i < widget.item.units.length; i++)
        if (query.isEmpty
            ? widget.item.units[i].type == type
            : (_units[i].name.text.contains(query) ||
                  _units[i].number.text.contains(query)))
          i,
    ];
    return ListView(
      key: ValueKey('property-edit-units-$type'),
      padding: const EdgeInsets.fromLTRB(12, 12, 12, 28),
      children: [
        Padding(
          padding: const EdgeInsets.only(bottom: 12),
          child: TextField(
            textAlign: AppTr.alignEnd,
            onChanged: (value) => setState(() => _unitQuery = value),
            decoration: _propertyInputDecorationShared(
              'ابحث باسم الوحدة أو رقمها',
            ).copyWith(prefixIcon: const Icon(Icons.search_rounded)),
          ),
        ),
        if (indexes.isEmpty)
          const Padding(
            padding: EdgeInsets.symmetric(vertical: 20),
            child: Text(
              'لا توجد وحدة مطابقة',
              textAlign: TextAlign.center,
              style: TextStyle(
                fontSize: 12,
                fontWeight: FontWeight.w700,
                color: AppTheme.muted,
              ),
            ),
          ),
        for (final i in indexes) _unitEditCard(i),
      ],
    );
  }

  Widget _unitEditCard(int i) {
    final type = widget.item.units[i].type;
    final hasRooms = _unitTypeHasRooms(type);
    final fullFloor = type == _kUnitFullFloor;
    final residential = _unitTypeIsResidential(type);
    return Container(
      margin: const EdgeInsets.only(bottom: 12),
      padding: const EdgeInsets.fromLTRB(12, 12, 12, 2),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(AppTheme.rCard),
        border: Border.all(color: AppTheme.hairline),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Row(
            children: [
              Icon(_unitTypeIcon(type), size: 17, color: _kPropertyColor),
              const SizedBox(width: 6),
              Expanded(
                child: Text(
                  _units[i].name.text.trim().isEmpty
                      ? type
                      : '${_units[i].name.text.trim()} · $type',
                  maxLines: 3,
                  style: const TextStyle(
                    fontSize: 13,
                    fontWeight: FontWeight.w900,
                    color: Color(0xFF022E2A),
                  ),
                ),
              ),
              Text(
                widget.item.units[i].status,
                style: const TextStyle(
                  fontSize: 10.5,
                  fontWeight: FontWeight.w800,
                  color: AppTheme.muted,
                ),
              ),
            ],
          ),
          const SizedBox(height: 10),
          _field('رقم $type', _units[i].number),
          _field('اسم $type', _units[i].name, onChanged: () {}),
          if (type != _kUnitParking)
            _field('المساحة (متر مربع)', _units[i].area, number: true),
          if (hasRooms) _field('عدد الغرف', _units[i].rooms, number: true),
          if (hasRooms || fullFloor)
            _field('عدد البلكونات', _units[i].balconies, number: true),
          if (fullFloor)
            _field('عدد الصالات', _units[i].halls, number: true),
          if (residential)
            _field('عدد الحمامات', _units[i].bathrooms, number: true),
          if (residential)
            _field(
              'عدد مواقف السيارات الخاصة',
              _units[i].parking,
              number: true,
            ),
          if (type != _kUnitParking) ..._meterFieldsFor(_units[i].meters),
          _field('الملاحظات', _units[i].notes, maxLines: 2),
        ],
      ),
    );
  }

  Widget _buildFacilityForm(String facility) {
    return ListView(
      key: ValueKey('property-edit-facility-$facility'),
      padding: const EdgeInsets.fromLTRB(14, 14, 14, 28),
      children: [
        _propertyFieldLabel(facility),
        const SizedBox(height: 8),
        _field(
          'العدد (0 = غير موجود)',
          _facilities[facility]!,
          number: true,
          onChanged: () {},
        ),
      ],
    );
  }
}
